// ── Avatar fallback helper (called from onerror) ──────
// Standard-Profilbild: Farbverlauf pro Nutzer (immer gleich für denselben Namen) + Initiale
var NX_AVATAR_GRADS = [
  ['#a855f7','#6d28d9'], ['#ec4899','#be185d'], ['#f97316','#c2410c'], ['#f59e0b','#b45309'],
  ['#10b981','#047857'], ['#14b8a6','#0f766e'], ['#06b6d4','#0e7490'], ['#3b82f6','#1d4ed8'],
  ['#6366f1','#4338ca'], ['#8b5cf6','#5b21b6'], ['#f43f5e','#be123c'], ['#84cc16','#4d7c0f']
];
function nxAvatarGrad(seed) {
  var str = String(seed || '?'), h = 0;
  for (var i = 0; i < str.length; i++) h = (h * 31 + str.charCodeAt(i)) >>> 0;
  var g = NX_AVATAR_GRADS[h % NX_AVATAR_GRADS.length];
  return 'linear-gradient(135deg,' + g[0] + ' 0%,' + g[1] + ' 100%)';
}
function nxDefaultAvatarInner(initial, size, seed, isAnon) {
  var fs = Math.round(size * (isAnon ? 0.46 : 0.42));
  var content = isAnon ? '<i class="fa-solid fa-user" style="font-size:' + fs + 'px;transform:translateY(' + Math.round(size * 0.06) + 'px);opacity:.92"></i>' : initial;
  return '<span class="nx-dav" style="background:' + (isAnon ? 'linear-gradient(135deg,#3f3a4d,#25212e)' : nxAvatarGrad(seed)) + ';font-size:' + fs + 'px"><b>' + content + '</b></span>';
}
function _avatarErr(el, initial, size) {
  try {
    el.style.display = 'none';
    var wrap = document.createElement('span');
    wrap.innerHTML = nxDefaultAvatarInner(escHtml(initial || '?'), size || 36, el.dataset.seed || initial, false);
    if (el.parentNode) el.parentNode.appendChild(wrap.firstChild);
  } catch(e) {}
}

// ── Avatar + Frame Ring Helper ──────────────────────
// opts.click   – Funktion, die beim Klick läuft (seit v1.82 kein Inline-Code mehr)
// opts.noVideo – skip videoAvatar, show static image only (for grids, UI bars)
function buildAvatarHtml(user, size, opts) {
  size = size || 36;
  opts = opts || {};
  var clickHandler = typeof opts.click === 'function' ? ' ' + nxOn('click', opts.click) : '';
  var cursor = clickHandler ? 'cursor:pointer;' : '';
  var frameId = user && user.activeFrame;
  var frameObj = frameId ? SHOP_FRAMES.find(function(f){ return f.id === frameId; }) : null;
  var initial = escHtml(Array.from(decodeServerEntities((user && (user.displayName || user.username)) || '?'))[0].toUpperCase()); // maskiert: Namen mit " oder < am Anfang zerschossen sonst das Markup
  var isAnon = !user || !(user.displayName || user.username);
  var seed = user ? (user.id || user.username || user.displayName || '?') : '?';
  // noVideo: skip animated video avatar (thumbnails, bars, small UI)
  var vidAvatar = (!opts.noVideo) && user && user.videoAvatar ? user.videoAvatar : null;
  var img = user && user.avatar;

  var innerContent;
  if (vidAvatar) {
    innerContent = '<video src="' + escHtml(vidAvatar) + '" autoplay loop muted playsinline style="width:100%;height:100%;object-fit:cover;border-radius:50%;display:block"></video>';
  } else if (img) {
    innerContent = '<img alt="" src="' + escHtml(img) + '" data-initial="' + initial + '" data-seed="' + escHtml(String(seed)) + '" data-size="' + size + '" data-h-error="h_app__avatarErr_436" style="width:100%;height:100%;object-fit:cover;border-radius:50%;display:block">';
  } else {
    innerContent = nxDefaultAvatarInner(initial, size, seed, isAnon);
  }

  if (frameObj) {
    var pad = Math.max(2, Math.round(size * 0.07));
    var outer = size + pad * 2;
    // 3-layer: static wrapper -> rotating ring (absolute) -> static image (absolute, does NOT rotate)
    return '<div' + clickHandler + ' style="position:relative;width:' + outer + 'px;height:' + outer + 'px;border-radius:50%;flex-shrink:0;' + cursor + '">'
      + '<div style="position:absolute;inset:0;border-radius:50%;background:' + frameObj.css + ';animation:' + (frameObj.anim || 'rotate 3s linear infinite') + '"></div>'
      + '<div style="position:absolute;inset:' + pad + 'px;border-radius:50%;overflow:hidden;background:var(--bg-secondary);display:flex;align-items:center;justify-content:center">'
      + innerContent + '</div></div>';
  }

  if (vidAvatar || img) {
    return '<div' + clickHandler + ' style="width:' + size + 'px;height:' + size + 'px;border-radius:50%;overflow:hidden;flex-shrink:0;' + cursor + '">' + innerContent + '</div>';
  }
  return '<div class="comment-avatar nx-dav-wrap"' + clickHandler + ' style="width:' + size + 'px;height:' + size + 'px;flex-shrink:0;' + cursor + '">' + innerContent + '</div>';
}
