let _dashboardInterval = null;
// ─── Teil: client/app/020-norynex-animation-system.js ───

// ==================== NORYNEX ANIMATION SYSTEM ====================
const NXD = {
  // Audio removed in v55 – stub keeps existing call-sites working without errors
  play() {},

  // CSS Animations
  ripple(el, color='rgba(168,59,255,0.35)') {
    if (!el) return;
    const r = document.createElement('span');
    const rect = el.getBoundingClientRect();
    const size = Math.max(rect.width, rect.height) * 2;
    r.style.cssText = `position:absolute;width:${size}px;height:${size}px;border-radius:50%;
      background:${color};transform:scale(0);opacity:1;pointer-events:none;
      left:50%;top:50%;margin-left:-${size/2}px;margin-top:-${size/2}px;
      animation:nxd-ripple 0.5s ease-out forwards;`;
    el.style.position = 'relative'; el.style.overflow = 'hidden';
    el.appendChild(r);
    setTimeout(() => r.remove(), 600);
  },

  pulse(el) {
    if (!el) return;
    el.style.animation = 'none';
    el.offsetHeight; // reflow
    el.style.animation = 'nxd-pulse 0.35s ease-out';
    setTimeout(() => el.style.animation = '', 400);
  },

  pop(el) {
    if (!el) return;
    el.style.animation = 'none';
    el.offsetHeight;
    el.style.animation = 'nxd-pop 0.3s cubic-bezier(0.175,0.885,0.32,1.275)';
    setTimeout(() => el.style.animation = '', 350);
  },

  floatIcon(el, icon, color='#c77dff') {
    if (!el) return;
    const rect = el.getBoundingClientRect();
    const f = document.createElement('div');
    f.innerHTML = icon;
    f.style.cssText = `position:fixed;left:${rect.left + rect.width/2}px;top:${rect.top}px;
      color:${color};font-size:22px;pointer-events:none;z-index:99999;
      animation:nxd-float 0.9s ease-out forwards;`;
    document.body.appendChild(f);
    setTimeout(() => f.remove(), 950);
  },

  // Play/Pause overlay flash on video
  videoFlash(videoEl, isPause) {
    if (!videoEl) return;
    const wrap = videoEl.closest('.watch-player-wrapper') || videoEl.parentElement;
    if (!wrap) return;
    const f = document.createElement('div');
    const icon = isPause ? '<i class="fas fa-pause"></i>' : '<i class="fas fa-play" style="margin-left:4px"></i>';
    f.style.cssText = `position:absolute;inset:0;display:flex;align-items:center;justify-content:center;
      pointer-events:none;z-index:10;`;
    f.innerHTML = `<div style="width:72px;height:72px;background:rgba(0,0,0,0.55);border-radius:50%;
      display:flex;align-items:center;justify-content:center;font-size:30px;
      animation:nxd-video-flash 0.45s ease-out forwards;">${icon}</div>`;
    wrap.style.position = 'relative';
    wrap.appendChild(f);
    setTimeout(() => f.remove(), 500);
  }
};

// Inject animation keyframes into DOM
(function injectNXDStyles() {
  const style = document.createElement('style');
  style.textContent = `
    @keyframes nxd-ripple { to { transform: scale(1); opacity: 0; } }
    @keyframes nxd-pulse { 0%,100% { transform:scale(1); } 50% { transform:scale(1.18); } }
    @keyframes nxd-pop { 0% { transform:scale(1); } 50% { transform:scale(1.28); } 100% { transform:scale(1); } }
    @keyframes nxd-float { 0% { opacity:1; transform:translateY(0) scale(1); }
      100% { opacity:0; transform:translateY(-60px) scale(1.4); } }
    @keyframes nxd-video-flash { 0% { opacity:1; transform:scale(0.7); }
      60% { opacity:1; transform:scale(1.05); }
      100% { opacity:0; transform:scale(1.15); } }
  `;
  document.head.appendChild(style);
})();

