async function _confirmGoogleLogin() {
  const email = document.getElementById('google-email-input')?.value?.trim();
  const name = document.getElementById('google-name-input')?.value?.trim();
  const errEl = document.getElementById('google-login-error');
  if (!email || !email.includes('@')) { if (errEl) errEl.textContent = tr({en:'Please enter a valid email.',de:'Bitte gültige E-Mail eingeben.'}); return; }
  const btn = document.getElementById('google-confirm-btn');
  if (btn) { btn.disabled = true; btn.textContent = tr({en:'Logging in...',de:'Anmelden...'}); }
  const googleId = 'google_' + btoa(email).replace(/=/g,'');
  try {
    const data = await apiPost('/api/auth/google', { googleId, email, displayName: name || email.split('@')[0], avatar: `https://ui-avatars.com/api/?name=${encodeURIComponent(name||email)}&background=4285F4&color=fff` });
    localStorage.setItem('nxd_token', data.token);
    currentUser = data.user;
    localStorage.setItem('nxd_user', JSON.stringify(data.user));
    saveAccountToList(data.token, data.user);
    document.getElementById('google-login-overlay')?.remove();
    closeModal('auth-modal');
    renderAuthSection();
    if (socket) socket.emit('join_user', localStorage.getItem('nxd_token'));
    showToast(`${tr({en:'Welcome',de:'Willkommen'})}, ${currentUser.displayName}!`, 'success');
    refreshCurrentPage();
  } catch(e) {
    if (errEl) errEl.textContent = e.message || (tr({en:'Login failed.',de:'Anmeldung fehlgeschlagen.'}));
    if (btn) { btn.disabled = false; btn.textContent = tr({en:'Continue',de:'Weiter'}); }
  }
}

