// ==================== PASSWORD HELPERS ====================
function _togglePwVis(inputId, iconId) {
  const inp = document.getElementById(inputId);
  const ico = document.getElementById(iconId);
  if (!inp) return;
  if (inp.type === 'password') {
    inp.type = 'text';
    if (ico) { ico.classList.remove('fa-eye'); ico.classList.add('fa-eye-slash'); }
  } else {
    inp.type = 'password';
    if (ico) { ico.classList.remove('fa-eye-slash'); ico.classList.add('fa-eye'); }
  }
}

// Passwort-Regeln (gleich wie auf dem Server, server/lib/security.js → passwordProblem)
const NX_COMMON_PW = ['12345678','123456789','1234567890','123123123','11111111','00000000','87654321','password','password1','passwort','passwort1','qwertz123','qwerty123','qwertzui','qwertyui','asdfghjk','yxcvbnm1','iloveyou','sommer2026','sommer2027','winter2026','winter2027','hallo123','hallo1234','abc12345','abcd1234','abcdefgh','letmein1','welcome1','willkommen','fussball','fußball','schalke04','bvb09bvb','baller123','norynex','norynex1','norynex123','master12','dragon12','monkey12','football','baseball','superman','batman12','pokemon1','minecraft','fortnite','admin123','test1234','changeme','trustno1'];
function nxPwCheck(pw, ctx) {
  pw = pw || ''; ctx = ctx || {};
  const low = pw.toLowerCase();
  const rows = ['abcdefghijklmnopqrstuvwxyz','0123456789','qwertzuiopasdfghjklyxcvbnm','qwertyuiopasdfghjklzxcvbnm','1234567890'];
  const alnum = low.replace(/[^a-z0-9]/g, '');
  const seq = !!alnum && rows.some(r => r.includes(alnum) || r.split('').reverse().join('').includes(alnum));
  const common = NX_COMMON_PW.includes(low) || NX_COMMON_PW.includes(low.replace(/[0-9!.?_-]+$/, '')) || seq || (pw.length >= 1 && new Set(low).size < 4);
  const names = [ctx.username, (ctx.email || '').split('@')[0]].map(x => String(x || '').toLowerCase()).filter(x => x.length >= 4);
  const rules = [
    { ok: pw.length >= 8, label: tr({en:'At least 8 characters',de:'Mindestens 8 Zeichen'}) },
    { ok: /[a-zäöüß]/i.test(pw), label: tr({en:'At least one letter',de:'Mindestens ein Buchstabe'}) },
    { ok: /[0-9]/.test(pw) || /[^a-zA-Z0-9äöüÄÖÜß]/.test(pw), label: tr({en:'A number or special character',de:'Eine Zahl oder ein Sonderzeichen'}) },
    { ok: !!pw && !common && !names.some(n => low.includes(n)), label: tr({en:'Not easy to guess (no "12345678", no name)',de:'Nicht leicht zu erraten (kein „12345678“, nicht dein Name)'}) },
  ];
  const ok = rules.every(r => r.ok);
  let score = rules.filter(r => r.ok).length;
  if (ok) score = (pw.length >= 12 && /[A-Z]/.test(pw) && /[a-z]/.test(pw) && /[^a-zA-Z0-9]/.test(pw)) ? 4 : (pw.length >= 10 ? 3 : 2);
  else score = Math.min(1, score);
  const first = rules.find(r => !r.ok);
  return { ok, score, rules, msg: ok ? '' : tr({en:'Password too weak: ',de:'Passwort zu schwach: '}) + first.label + '.' };
}
function _updatePwStrength(pw, containerId, ctx) {
  const wrap = document.getElementById(containerId);
  if (!wrap) return;
  if (!pw) { wrap.style.display = 'none'; return; }
  wrap.style.display = 'block';
  const r = nxPwCheck(pw, ctx);
  const colors = ['#ef4444','#f97316','#eab308','#22c55e'];
  const labels = [tr({en:'Too weak',de:'Zu schwach'}), tr({en:'Okay',de:'In Ordnung'}), tr({en:'Good',de:'Gut'}), tr({en:'Strong',de:'Stark'})];
  const score = Math.max(1, r.score);
  wrap.querySelectorAll('.pw-bar').forEach((b, i) => { b.style.background = i < score ? colors[score-1] : ''; b.style.opacity = i < score ? '1' : '0.2'; });
  const lbl = wrap.querySelector('.pw-label');
  if (lbl) { lbl.textContent = labels[score-1] || ''; lbl.style.color = colors[score-1] || 'inherit'; }
  const list = wrap.querySelector('.pw-rules');
  if (list) list.innerHTML = r.rules.map(x => `<li class="${x.ok ? 'is-ok' : ''}"><i class="fas ${x.ok ? 'fa-circle-check' : 'fa-circle'}"></i>${x.label}</li>`).join('');
}
// Fügt unter einem Passwortfeld die Stärke-Anzeige ein (falls noch keine da ist)
function nxAttachPwMeter(inputId, ctxFn) {
  const inp = document.getElementById(inputId);
  if (!inp || inp.dataset.pwMeter) return;
  inp.dataset.pwMeter = '1';
  const box = document.createElement('div');
  box.id = inputId + '-meter';
  box.className = 'nx-pwm';
  box.style.display = 'none';
  box.innerHTML = '<div class="nx-pwm-bars"><span class="pw-bar"></span><span class="pw-bar"></span><span class="pw-bar"></span><span class="pw-bar"></span><b class="pw-label"></b></div><ul class="pw-rules"></ul>';
  const anchor = inp.closest('.form-group') || inp.parentElement;
  anchor.appendChild(box);
  inp.addEventListener('input', () => _updatePwStrength(inp.value, box.id, ctxFn ? ctxFn() : {}));
}

