// ==================== NAVIGATION ====================
function setupSidebar() {
  document.querySelectorAll('.nav-item[data-page]').forEach(item => {
    item.addEventListener('click', (e) => {
      e.preventDefault();
      navigateTo(item.dataset.page);
      if (window.innerWidth <= 960) {
        document.getElementById('sidebar').classList.remove('mobile-open');
        const bd = document.getElementById('sidebar-backdrop');
        if (bd) bd.classList.remove('active');
      }
    });
  });
}

function toggleSidebar() {
  const sidebar = document.getElementById('sidebar');
  const content = document.getElementById('main-content');
  const backdrop = document.getElementById('sidebar-backdrop');
  if (window.innerWidth <= 960) {
    const isOpen = sidebar.classList.toggle('mobile-open');
    if (backdrop) backdrop.classList.toggle('active', isOpen);
    NXD.play(isOpen ? 'menu_open' : 'menu_close');
  } else {
    sidebarOpen = !sidebarOpen;
    sidebar.classList.toggle('collapsed', !sidebarOpen);
    content.style.marginLeft = sidebarOpen ? 'var(--sidebar-w)' : 'var(--sidebar-collapsed-w)';
    NXD.play(sidebarOpen ? 'menu_open' : 'menu_close');
  }
}

// Schließt das mobile Sidebar-Menü inkl. des abgedunkelten/geblurten Overlays.
// Wichtig für Links, die in einem neuen Tab öffnen (target="_blank") oder die App
// verlassen (mailto:, Discord etc.) - ohne das hier bleibt sonst der Blur-Screen
// über der App "hängen", bis man ihn manuell wegtippt.
function closeMobileSidebar() {
  const sidebar = document.getElementById('sidebar');
  const backdrop = document.getElementById('sidebar-backdrop');
  if (sidebar) sidebar.classList.remove('mobile-open');
  if (backdrop) backdrop.classList.remove('active');
}

// Sicherheitsnetz: Falls die App (z.B. auf einem Touch-Gerät nach Rückkehr aus
// einem in einem neuen Tab geöffneten Link) in einem inkonsistenten Zustand
// wieder sichtbar wird - Backdrop aktiv, aber Sidebar eigentlich zu - räumen wir
// den Blur-Overlay automatisch auf, statt dass der Nutzer ihn wegwischen muss.
document.addEventListener('visibilitychange', () => {
  if (document.visibilityState !== 'visible') return;
  const sidebar = document.getElementById('sidebar');
  const backdrop = document.getElementById('sidebar-backdrop');
  if (backdrop && backdrop.classList.contains('active') && sidebar && !sidebar.classList.contains('mobile-open')) {
    backdrop.classList.remove('active');
  }
});

function navigateTo(page, param = null) {
  // Laufende Werbung (Ton!) beim Seitenwechsel sofort beenden
  if (typeof nxStopAllAds === 'function') nxStopAllAds();
  // Pause any playing video before navigating away
  const existingVideo = document.getElementById('main-video');
  if (existingVideo) {
    existingVideo.pause();
    // Bugfix: Bei HLS-Videos reicht "pause() + src=''" NICHT aus — die HLS.js-
    // Instanz (vid._hls) bleibt sonst aktiv am MediaSource-Objekt hängen und lädt/
    // spielt im Hintergrund weiter, obwohl man schon auf der Startseite ist (man
    // hört den Ton dann noch, ohne dass ein sichtbarer Player läuft). Deshalb muss
    // die HLS-Instanz hier explizit zerstört werden, bevor der <video>-Tag geleert wird.
    if (existingVideo._hls) { try { existingVideo._hls.destroy(); } catch(e) {} existingVideo._hls = null; }
    existingVideo.removeAttribute('src');
    existingVideo.src = '';
    existingVideo.load();
  }
  const existingStream = document.getElementById('stream-video');
  if (existingStream) {
    existingStream.pause();
    if (existingStream._hls) { try { existingStream._hls.destroy(); } catch(e) {} existingStream._hls = null; }
    if (typeof existingStream._liveCleanup === 'function') { try { existingStream._liveCleanup(); } catch(e) {} }
    existingStream.removeAttribute('src');
    existingStream.src = '';
    existingStream.load();
  }
  if (window._currentStreamUserId) { try { socket && socket.emit('leave_stream', window._currentStreamUserId); } catch {} window._currentStreamUserId = null; }
  // Hintergrundwiedergabe komplett stoppen, sonst spielt die alte Video-Referenz
  // beim nächsten Tab-Wechsel/Sperren weiter oder überlagert ein neu gestartetes Video.
  if (typeof _visibilityHandler !== 'undefined' && _visibilityHandler) {
    document.removeEventListener('visibilitychange', _visibilityHandler);
    _visibilityHandler = null;
  }
  if (typeof _wakeLock !== 'undefined' && _wakeLock) { _wakeLock.release().catch(() => {}); _wakeLock = null; }
  if (typeof _bgPlayVideoRef !== 'undefined' && _bgPlayVideoRef) { _bgPlayVideoRef.pause(); _bgPlayVideoRef = null; }
  if (typeof _bgPlayActive !== 'undefined') _bgPlayActive = false;
  // Echte Watchtime des verlassenen Videos noch sichern, bevor wir wegnavigieren
  stopRecommendationWatchTracking();
  // Cleanup shorts fullscreen mode when leaving
  if (page !== 'shorts' && _shortsCleanup) { _shortsCleanup(); _shortsCleanup = null; }
  // Stop all short videos
  document.querySelectorAll('.short-card video').forEach(v => { v.pause(); v.muted = true; });

  currentPage = page;
  document.querySelectorAll('.nav-item').forEach(n => n.classList.toggle('active', n.dataset.page === page));
  updateBottomNav(page);
  document.querySelectorAll('.page').forEach(p => p.style.display = 'none');
  const pageEl = document.getElementById(`page-${page}`);
  // Bugfix: nicht pauschal 'block' setzen — überschreibt sonst das per CSS
  // gesetzte 'display:flex' von #page-shorts (zentriert den Shorts-Player
  // wie bei YouTube) und klebt den Player links oben fest.
  if (pageEl) pageEl.style.display = (page === 'shorts') ? 'flex' : 'block';
  window.__pageParam = param;

  // Adresse aktualisieren (echte Pfade statt #, siehe 055-router.js), damit Neuladen,
  // Teilen und die Zurück-Taste funktionieren. Hat der Aufrufer schon eine Unterseite derselben
  // Seite gesetzt (z.B. history.replaceState(...,'#studio/channel') direkt vor
  // navigateTo('studio')), diese NICHT überschreiben, sonst geht der Unter-Tab verloren.
  window.__nxNavCount = (window.__nxNavCount || 0) + 1;
  const currentRoute = nxRoute();
  const alreadyOnSubRoute = (param === null || param === undefined) && (currentRoute === page || currentRoute.startsWith(`${page}/`));
  const newRoute = (param !== null && param !== undefined && param !== '') ? `${page}/${param}` : page;
  if (!alreadyOnSubRoute) nxCommitRoute(newRoute, true);
  else nxUpdateCanonical();
  if (NX_PAGE_TITLES[page]) nxSetMeta({ title: NX_PAGE_TITLES[page][0], description: NX_PAGE_TITLES[page][1] || NX_PAGE_TITLES.home[1] });

  switch(page) {
    case 'home': renderHomePage(); break;
    case 'shorts': if (param) window._shortsStartVideoId = param; renderShortsPage(); break;
    case 'subscriptions': renderSubscriptionsPage(); break;
    case 'live': renderLivePage(); break;
    case 'trending': renderCategoryPage('trending'); break;
    case 'gaming': renderCategoryPage('Gaming'); break;
    case 'music': renderCategoryPage('Music'); break;
    case 'sports': renderCategoryPage('Sports'); break;
    case 'comedy': renderCategoryPage('Comedy'); break;
    case 'history': renderHistoryPage(); break;
    case 'saved': renderSavedPage(); break;
    case 'posts': renderPostsPage(); break;
    case 'balance': navigateTo('shop', 'wallet'); return;
    case 'premium': renderPremiumPage(); break;
    case 'studio': renderStudioPage(); break;
    case 'settings': renderSettingsPage(param || undefined); break;
    case 'hashtag': renderHashtagPage(param); break;
    case 'messages': renderMessagesPage(param); break;
    case 'playlist': nxRenderPlaylistPage(param); break;
    case 'playlists': nxRenderMyPlaylistsPage(); break;
    case 'channel': renderChannelPage(param); break;
    case 'search': renderSearchPage(param); break;
    case 'watch': renderWatchPage(param); break;
    case 'stream': renderStreamPage(param); break;
    case 'nexa': renderNexaPage(); break;
    case 'vod': if (typeof renderVodPage === 'function') renderVodPage(param); break;
    case 'admin': renderAdminPage(); break;
    case 'shop': renderShopPage(param); break;
    case 'tasks': renderAufgabenPage(); break;
    case 'bugs': if (typeof renderBugsPage === 'function') renderBugsPage(param); break;
  }
}

// Aktuelle Seite neu zeichnen — ohne neuen Verlaufseintrag (Adresse bleibt, wie sie ist)
function refreshCurrentPage() {
  const was = _nxRouteRestoring; _nxRouteRestoring = true;
  try { navigateTo(currentPage, window.__pageParam); } finally { _nxRouteRestoring = was; }
}
// ─── Teil: client/app/070-home-page.js ───

// ==================== HOME PAGE ====================
// Kopf der Startseite: echte <h1> plus kurzer Text, was Norynex ist (wichtig für Google),
// dazu der Hinweis auf die Beta-Phase. Der Text lässt sich über das ✕ einklappen.
function nxHomeIntroHtml() {
  const collapsed = localStorage.getItem('nx_home_intro_collapsed') === '1';
  return `<section class="nx-home-intro${collapsed ? ' is-collapsed' : ''}" id="nx-home-intro">
    <div class="nx-home-intro-head">
      <h1>${tr({ en: 'Norynex – videos, shorts & livestreams', de: 'Norynex – Videos, Shorts & Livestreams' })}</h1>
      <span class="nx-beta-pill">BETA</span>
      <button class="nx-home-intro-toggle" data-h-click="h_app_nxToggleHomeIntro_2352" aria-label="${escHtml(tr({ en: 'Show or hide intro', de: 'Einleitung ein- oder ausblenden' }))}"><i class="fas ${collapsed ? 'fa-chevron-down' : 'fa-xmark'}"></i></button>
    </div>
    <div class="nx-home-intro-body">
      <p>${tr({ en: 'Norynex is a video platform for videos, shorts and livestreams. Discover creators, watch what\'s trending, chat live and upload your own videos – for free.',
               de: 'Norynex ist eine Video-Plattform für Videos, Shorts und Livestreams. Entdecke Creator, schau, was gerade angesagt ist, chatte live mit und lade kostenlos eigene Videos hoch.' })}</p>
      <p>${tr({ en: 'Norynex is currently in <b>beta</b> – everything is in the test phase. Found a bug? <a href="/bugs">Report it</a> and earn bug points you can redeem for Premium and shop items.',
               de: 'Norynex befindet sich gerade in der <b>Beta</b> – alles ist noch in der Testphase. Bug gefunden? <a href="/bugs">Melde ihn</a> und sammle Bug-Punkte, die du gegen Premium und Shop-Artikel eintauschen kannst.' })}</p>
    </div>
  </section>`;
}
function nxToggleHomeIntro() {
  const el = document.getElementById('nx-home-intro');
  if (!el) return;
  const c = el.classList.toggle('is-collapsed');
  try { localStorage.setItem('nx_home_intro_collapsed', c ? '1' : '0'); } catch {}
  const i = el.querySelector('.nx-home-intro-toggle i');
  if (i) i.className = 'fas ' + (c ? 'fa-chevron-down' : 'fa-xmark');
}
async function renderHomePage() {
  const el = document.getElementById('page-home');
  const renderToken = Date.now();
  el._renderToken = renderToken;
  el.innerHTML = nxHomeIntroHtml() + `
    <div class="spinner" style="margin:40px auto;display:block"></div>`;
  try {
    // Fetch recommended (returns { videos, shorts }) or fall back to flat array (legacy)
    let regVideos = [], shorts = [];
    if (currentUser) {
      const rec = await apiGet('/api/videos/recommended');
      if (Array.isArray(rec)) {
        // legacy flat response
        regVideos = rec.filter(v => !v.isShort);
        shorts    = rec.filter(v =>  v.isShort);
      } else {
        regVideos = rec.videos || [];
        shorts    = rec.shorts || [];
      }
      if (!regVideos.length && !shorts.length) {
        const all = await apiGet('/api/videos?sort=latest');
        regVideos = all.filter(v => !v.isShort);
        shorts    = all.filter(v =>  v.isShort);
      }
    } else {
      const rec = await apiGet('/api/videos/recommended');
      if (Array.isArray(rec)) {
        regVideos = rec.filter(v => !v.isShort);
        shorts    = rec.filter(v =>  v.isShort);
      } else {
        regVideos = rec.videos || [];
        shorts    = rec.shorts || [];
      }
    }
    if (el._renderToken !== renderToken) return;

    if (!regVideos.length && !shorts.length) {
      el.innerHTML = nxHomeIntroHtml() + emptyState('fa-film', t('no_videos_yet'), t('be_first_upload'));
      return;
    }

    // ── Build YouTube-style feed ─────────────────────────────────────
    // Pattern: 4 videos → 6 shorts → 4 videos → 6 shorts → rest videos (no more shorts)
    const VIDS_PER_ROW   = 4;
    const SHORTS_PER_ROW = window.innerWidth <= 640 ? 4 : 6;
    const PATTERN_CYCLES = 2; // how many video+shorts cycles before going endless-videos

    const container = document.createElement('div');
    container.style.cssText = 'display:flex;flex-direction:column;gap:32px';

    let vi = 0; // video index
    let si = 0; // shorts index

    function makeVideoRow(items) {
      const row = document.createElement('div');
      row.className = 'home-video-row';
      items.forEach(v => row.appendChild(createVideoCard(v)));
      return row;
    }

    function makeShortsRow(items) {
      const wrap = document.createElement('div');

      const header = document.createElement('div');
      header.className = 'feed-section-header';
      header.innerHTML = `<i class="fas fa-bolt feed-section-ic shorts"></i><span>${escHtml(t('nav_shorts'))}</span>`;
      wrap.appendChild(header);

      const row = document.createElement('div');
      row.className = 'home-shorts-row';
      items.forEach(v => {
        const card = createVideoCard(v);
        row.appendChild(card);
      });
      wrap.appendChild(row);
      return wrap;
    }

    // Section header for videos
    const vidHeader = document.createElement('div');
    vidHeader.className = 'feed-section-header';
    vidHeader.innerHTML = `
      <i class="fas fa-${currentUser ? 'magic' : 'fire'} feed-section-ic"></i>
      <span>${currentUser ? escHtml(tr({ en: 'Recommended for you', de: 'Für dich empfohlen' })) : escHtml(tr({ en: 'Trending', de: 'Trending' }))}</span>`;
    container.appendChild(vidHeader);

    // Cycles: videos then shorts
    for (let cycle = 0; cycle < PATTERN_CYCLES; cycle++) {
      // 4 videos
      const vChunk = regVideos.slice(vi, vi + VIDS_PER_ROW);
      vi += VIDS_PER_ROW;
      if (vChunk.length) container.appendChild(makeVideoRow(vChunk));

      // 6 shorts (only if we have some)
      if (shorts.length > si) {
        const sChunk = shorts.slice(si, si + SHORTS_PER_ROW);
        si += SHORTS_PER_ROW;
        if (sChunk.length) container.appendChild(makeShortsRow(sChunk));
      }
    }

    // Danach: weiterhin abwechselnd Video- und Shorts-Reihen, bis WIRKLICH alles gezeigt wurde.
    // Vorher wurden übrige Shorts nach den ersten 2 Zyklen komplett verworfen — dadurch fehlte
    // ein Großteil des Katalogs auf der Startseite, obwohl der Algorithmus sie korrekt geliefert hat.
    const VIDEO_ROWS_BETWEEN_SHORTS = 2; // alle 2 Video-Reihen kommt wieder eine Shorts-Reihe
    let videoRowsSinceShorts = 0;
    while (vi < regVideos.length || si < shorts.length) {
      if (vi < regVideos.length) {
        const chunk = regVideos.slice(vi, vi + VIDS_PER_ROW);
        vi += VIDS_PER_ROW;
        if (chunk.length) { container.appendChild(makeVideoRow(chunk)); videoRowsSinceShorts++; }
      }
      if (si < shorts.length && (videoRowsSinceShorts >= VIDEO_ROWS_BETWEEN_SHORTS || vi >= regVideos.length)) {
        const sChunk = shorts.slice(si, si + SHORTS_PER_ROW);
        si += SHORTS_PER_ROW;
        if (sChunk.length) container.appendChild(makeShortsRow(sChunk));
        videoRowsSinceShorts = 0;
      }
      // Sicherheitsnetz gegen Endlosschleife, falls beide Slices mal leer zurückkommen
      if (vi >= regVideos.length && si >= shorts.length) break;
    }

    el.innerHTML = nxHomeIntroHtml();
    el.appendChild(container);

  } catch(e) {
    console.error('renderHomePage error:', e);
    el.innerHTML = `<p style="color:var(--text-muted);padding:40px">${t('loading_error')}</p>`;
  }
}
