// ==================== VIDEO CARD ====================
function createVideoCard(v) {
  const card = document.createElement('div');
  card.className = 'video-card';
  const authorInitial = (v.author?.displayName || v.authorName || '?')[0].toUpperCase();
  // noVideo: grid thumbnails show static image only; video avatar only shown on click/watch
  const avatar = buildAvatarHtml(v.author, 36, { noVideo: true });
  const thumb = v.thumbnailPath
    ? `<img src="${v.thumbnailPath}" alt="${escHtml(v.title)}" loading="lazy" data-h-error="h_app_add_2512">`
    : `<div class="video-thumb-placeholder"><i class="fas fa-film"></i></div>`;
  const badges = [
    v.isShort ? `<span class="short-badge-thumb">SHORT</span>` : '',
    v.isPaid && !v.purchasedBy?.includes(currentUser?.id) ? `<span class="paid-badge">€${v.price}</span>` : '',
  ].join('');
  const views = formatViews(v.views);
  const time = timeAgo(v.createdAt);
  (window._nxCardVideos = window._nxCardVideos || {})[v.id] = { id: v.id, title: v.title || '', thumbnailPath: v.thumbnailPath || '', author: { displayName: v.author?.displayName || v.authorName || '' } };
  const inQ = typeof _queue !== 'undefined' && _queue.some(q => q.id === v.id);
  const queueBtn = !v.isShort
    ? `<button class="queue-add-btn${inQ ? ' is-in' : ''}" data-queue-id="${v.id}" title="${escHtml(tr({en:'Add to queue',de:'Zur Warteschlange hinzufügen'}))}" data-h-click="h_app_stopPropagation_2523" data-hv-click="${nxHv(String(v.id))}" aria-label="${escHtml(tr({en:'Add to queue',de:'Zur Warteschlange hinzufügen'}))}"><i class="fas ${inQ ? 'fa-check' : 'fa-list-ul'}"></i></button>`
    : '';
  const wheelBtn = (!v.isShort && localStorage.getItem('nxd_wheel_enabled') === 'true')
    ? `<button class="wheel-thumb-btn" title="${tr({en:'Add to Wheel',de:'Zum Glücksrad hinzufügen'})}" data-h-click="h_app_stopPropagation_2526" data-hv-click="${nxHv(String(v.id))}" aria-label="${tr({en:'Add to Wheel',de:'Zum Glücksrad hinzufügen'})}"><i class="fas fa-dharmachakra"></i></button>`
    : '';
  card.innerHTML = `
    <div class="video-thumb">${thumb}${badges}${wheelBtn}${queueBtn}${!v.isShort ? `<span class="video-duration">${formatDuration(v.duration)}</span>` : ''}</div>
    <div class="video-info">
      <div class="video-meta">
        <div class="video-channel-avatar-wrap">${avatar}</div>
        <div class="video-meta-text">
          <h3><a class="nx-card-link" href="${v.isShort ? '/shorts/' : '/watch/'}${encodeURIComponent(v.id)}">${escHtml(v.title)}</a></h3>
          <p>${escHtml(v.author?.displayName || v.authorName || t('label_unknown'))}${verifiedBadge(v.author)}</p>
          <p class="views-time">${views} ${t('views')} • ${time}</p>
        </div>
      </div>
    </div>`;
  if (v.isShort) {
    card.addEventListener('click', () => navigateTo('shorts', v.id));
  } else {
    card.addEventListener('click', () => navigateTo('watch', v.id));
  }
  return card;
}

// ── Chromecast / Remote Playback Button Setup ──────────────────────
// Nutzt primär die echte Google Cast Sender SDK (chrome.cast), da die
// browsereigene Remote Playback API auf vielen Chrome/Windows-Setups keine
// Chromecast-Geräte im Netzwerk findet (das war der Grund, warum "Casten"
// zuvor nie funktioniert hat, obwohl der Button klickbar war). Für Browser
// ohne Cast SDK (Firefox, Safari, mobil) fällt der Code auf die Remote
// Playback API zurück, sofern der Browser sie unterstützt.
let _castApiReady = false;
let _castSession = null;

// Initialisiert die Cast-SDK. Der eigentliche SDK-Callback (__onGCastApiAvailable) steht
// in index.html VOR dem SDK-Script und ruft diese Funktion auf — so geht der Callback nicht
// mehr verloren, wenn das SDK schneller lädt als app.js (Hauptgrund für "Cast geht nicht").
window.__nxCastInit = function (isAvailable) {
  if (_castApiReady || !isAvailable || typeof cast === 'undefined' || !cast.framework) return;
  try {
    const context = cast.framework.CastContext.getInstance();
    if (!window.__nxCastConfigured) {
      context.setOptions({
        receiverApplicationId: chrome.cast.media.DEFAULT_MEDIA_RECEIVER_APP_ID,
        autoJoinPolicy: chrome.cast.AutoJoinPolicy.ORIGIN_SCOPED,
        resumeSavedSession: true
      });
    }
    _castApiReady = true;
    context.addEventListener(cast.framework.CastContextEventType.SESSION_STATE_CHANGED, (e) => {
      _castSession = context.getCurrentSession();
      const on = e.sessionState === cast.framework.SessionState.SESSION_STARTED || e.sessionState === cast.framework.SessionState.SESSION_RESUMED;
      document.querySelectorAll('#nxd-cast-btn, .nxp-cast').forEach(b => b.classList.toggle('is-casting', on));
      // Sitzung wurde über die Chrome-Medien-Steuerung / das Chrome-Menü gestartet (nicht über
      // unseren Button) → das gerade laufende Video automatisch auf dem Fernseher starten,
      // genau wie bei YouTube.
      if (e.sessionState === cast.framework.SessionState.SESSION_STARTED && !window._nxCastLoading) {
        const el = _nxCurrentCastableVideo();
        if (el) _castCurrentVideoViaSDK(el).catch(err => { console.warn('[Cast] Laden fehlgeschlagen', err); if (typeof nxCastFailed === 'function') nxCastFailed(err); });
        else if (window._currentStreamUserId) nxCastLive(window._currentStreamUserId);
        else showToast(tr({en:'Connected to your TV – now open a video or live stream and it will play there.',de:'Mit dem Fernseher verbunden – öffne jetzt ein Video oder einen Livestream, er läuft dann dort.'}), 'info');
      }
      if (e.sessionState === cast.framework.SessionState.SESSION_ENDED) showToast(tr({en:'Casting stopped',de:'Übertragung zum Fernseher beendet'}), 'info');
    });
  } catch (err) {
    console.warn('[Norynex] Cast SDK konnte nicht initialisiert werden:', err);
  }
};
// Welches Video soll auf den Fernseher? Watch-Seite → Hauptvideo, Shorts → sichtbarer Short
function _nxCurrentCastableVideo() {
  const main = document.getElementById('main-video');
  if (main && document.body.contains(main)) return main;
  const feed = document.getElementById('shorts-feed');
  if (feed) {
    const top = feed.getBoundingClientRect().top;
    let best = null, bd = Infinity;
    feed.querySelectorAll('.short-card video').forEach(v => { const d = Math.abs(v.getBoundingClientRect().top - top); if (d < bd) { bd = d; best = v; } });
    return best;
  }
  return null;
}
if (window.__nxCastAvailable) window.__nxCastInit(true);

// Startet die Wiedergabe der aktuellen Video-URL auf dem gewählten Chromecast-Gerät.
async function _castCurrentVideoViaSDK(videoEl) {
  const context = cast.framework.CastContext.getInstance();
  window._nxCastLoading = true;
  try {
    if (!context.getCurrentSession()) await context.requestSession();
  } finally { setTimeout(() => { window._nxCastLoading = false; }, 500); }
  const session = context.getCurrentSession();
  if (!session) throw new Error('Keine Cast-Sitzung');

  // WICHTIG: Bei HLS-Videos ist videoEl.currentSrc eine blob:-URL von hls.js — die kann
  // ein Chromecast NICHT laden. Deshalb die echte Server-URL verwenden. Bevorzugt die
  // 720p-MP4 (H.264/AAC): spielt auf jedem Chromecast/Fire-TV-Receiver zuverlässig.
  const raw = videoEl.dataset.castSrc || videoEl.dataset.src || videoEl.getAttribute('src') || videoEl.currentSrc;
  if (!raw || raw.startsWith('blob:')) throw new Error('Keine castbare Video-URL');
  const srcUrl = new URL(raw, window.location.href).href;
  const isHls = /\.m3u8(\?|$)/.test(srcUrl);
  const mediaInfo = new chrome.cast.media.MediaInfo(srcUrl, isHls ? 'application/vnd.apple.mpegurl' : 'video/mp4');
  if (isHls && chrome.cast.media.HlsSegmentFormat) mediaInfo.hlsSegmentFormat = chrome.cast.media.HlsSegmentFormat.TS;
  mediaInfo.streamType = chrome.cast.media.StreamType.BUFFERED;
  mediaInfo.metadata = new chrome.cast.media.GenericMediaMetadata();
  const card = videoEl.closest('.short-card');
  mediaInfo.metadata.title = videoEl.dataset.castTitle || card?.querySelector('h4')?.textContent || document.title;
  mediaInfo.metadata.subtitle = videoEl.dataset.castAuthor || 'Norynex';
  const poster = videoEl.dataset.castPoster || videoEl.poster;
  if (poster) mediaInfo.metadata.images = [new chrome.cast.Image(new URL(poster, window.location.href).href)];

  const request = new chrome.cast.media.LoadRequest(mediaInfo);
  request.autoplay = true;
  request.currentTime = videoEl.currentTime || 0;
  try { await session.loadMedia(request); }
  catch (e) {
    // MP4 abgelehnt → HLS-Variante probieren
    const hls = videoEl.dataset.castHls;
    if (!isHls && hls) {
      const mi = new chrome.cast.media.MediaInfo(new URL(hls, location.href).href, 'application/vnd.apple.mpegurl');
      if (chrome.cast.media.HlsSegmentFormat) mi.hlsSegmentFormat = chrome.cast.media.HlsSegmentFormat.TS;
      mi.metadata = mediaInfo.metadata; mi.streamType = chrome.cast.media.StreamType.BUFFERED;
      const r2 = new chrome.cast.media.LoadRequest(mi); r2.autoplay = true; r2.currentTime = request.currentTime;
      await session.loadMedia(r2);
    } else throw e;
  }
  videoEl.pause();
  showToast(tr({en:'Playing on ',de:'Wird abgespielt auf '}) + (session.getCastDevice()?.friendlyName || 'TV'), 'success');
}

function _setupCastButtonFor(vid, attempt) {
  attempt = attempt || 0;
  const castBtn = document.getElementById('nxd-cast-btn');
  // Element noch nicht im DOM (innerHTML-Zuweisung lief noch nicht) → kurz erneut versuchen
  if (!castBtn || !vid || !document.body.contains(vid)) {
    if (attempt < 30) { setTimeout(() => _setupCastButtonFor(vid, attempt + 1), 150); }
    return;
  }

  castBtn.style.display = 'flex';

  castBtn.onclick = async (e) => {
    e.preventDefault();
    e.stopPropagation();
    const liveVid = document.getElementById('main-video') || vid;

    // 1) Bevorzugt: echte Google Cast SDK (findet Chromecast-Geräte zuverlässig)
    if (_castApiReady && typeof cast !== 'undefined' && typeof chrome !== 'undefined' && chrome.cast) {
      try {
        await _castCurrentVideoViaSDK(liveVid);
        return;
      } catch (err) {
        // Nutzer hat den Geräte-Auswahldialog selbst abgebrochen -> kein Fehler-Toast
        if (err && (err.code === 'cancel' || err === 'cancel' || err?.code === chrome.cast?.ErrorCode?.CANCEL)) return;
        console.warn('[Norynex] Cast SDK fehlgeschlagen, versuche Remote Playback API:', err);
        // Sitzung steht, aber der Fernseher konnte das Video nicht laden → echten Grund zeigen
        if (cast.framework.CastContext.getInstance().getCurrentSession()) { if (typeof nxCastFailed === 'function') nxCastFailed(err); return; }
      }
    }

    // 2) Fallback: browsereigene Remote Playback API (Safari/Firefox mit AirPlay o.ä.)
    if (liveVid && 'remote' in liveVid && typeof liveVid.remote?.prompt === 'function') {
      try {
        await liveVid.remote.prompt();
        return;
      } catch (err) {
        console.warn('[Norynex] Remote Playback fehlgeschlagen oder abgebrochen:', err);
        if (err && err.name === 'AbortError') return;
      }
    }

    if (!window.isSecureContext) {
      showToast(tr({en:'Casting needs HTTPS. Open Norynex via https:// to cast.',de:'Casten funktioniert nur über HTTPS. Öffne Norynex über https://, um zu streamen.'}), 'error');
    } else if (/^(localhost|127\.|192\.168\.|10\.)/.test(location.hostname)) {
      showToast(tr({en:'Your TV cannot reach a local address. Use the public domain to cast.',de:'Dein Fernseher kann eine lokale Adresse nicht erreichen. Nutze zum Casten die öffentliche Domain.'}), 'error');
    } else if (!_castApiReady) {
      showToast(tr({en:'Casting is only available in Chrome/Edge (Google Cast).',de:'Casten ist nur in Chrome/Edge verfügbar (Google Cast).'}), 'error');
    } else {
      if (typeof nxCastDiagnose === 'function') nxCastDiagnose(); else
      showToast(tr({en:'No cast devices found. Make sure your TV/Chromecast is on the same WiFi network.',de:'Keine Cast-Geräte gefunden. Stelle sicher, dass Fernseher/Chromecast im gleichen WLAN sind.'}), 'error');
    }
  };
}

// ── HLS-Wiedergabe (Videos) — für schwache Handys optimiert ──
// • capLevelToPlayerSize: ein Handy mit 400 px breitem Player bekommt nie 1080p
// • schwache Geräte (≤ 4 GB RAM oder ≤ 4 Kerne) werden auf max. 720p begrenzt
// • kleinerer Puffer auf Mobilgeräten (weniger Speicherdruck → keine Aussetzer)
// • Wiederherstellung bei Netzwerk-/Decoderfehlern, danach Rückfall auf die MP4-Datei
function nxIsLowEndDevice() {
  const mem = navigator.deviceMemory || 8, cores = navigator.hardwareConcurrency || 8;
  return mem <= 4 || cores <= 4 || !!(navigator.connection && (navigator.connection.saveData || /2g|3g/.test(navigator.connection.effectiveType || '')));
}
function nxAttachVodHls(vid, src, fallbackSrc, onReady) {
  const mobile = window.innerWidth <= 900 || /Android|iPhone|iPad|Mobile/i.test(navigator.userAgent);
  const lowEnd = nxIsLowEndDevice();
  const hls = new Hls({
    enableWorker: true,
    capLevelToPlayerSize: true,
    startLevel: -1,
    abrEwmaDefaultEstimate: lowEnd ? 600000 : 1500000,
    maxBufferLength: mobile ? 20 : 30,
    maxMaxBufferLength: mobile ? 40 : 60,
    maxBufferSize: (mobile ? 30 : 60) * 1000 * 1000,
    backBufferLength: mobile ? 15 : 30,
    maxBufferHole: 0.5,
    nudgeMaxRetry: 8,
    fragLoadingTimeOut: 20000, fragLoadingMaxRetry: 6, fragLoadingRetryDelay: 1000,
    manifestLoadingTimeOut: 10000, manifestLoadingMaxRetry: 4,
    levelLoadingTimeOut: 10000, levelLoadingMaxRetry: 4,
  });
  let mediaErrors = 0, netErrors = 0, gaveUp = false;
  const giveUp = () => {
    if (gaveUp) return; gaveUp = true;
    const t = vid.currentTime || 0, wasPlaying = !vid.paused;
    try { hls.destroy(); } catch {}
    vid._hls = null;
    if (!fallbackSrc) return;
    vid.src = fallbackSrc;
    vid.addEventListener('loadedmetadata', () => { try { vid.currentTime = t; } catch {} if (wasPlaying) vid.play().catch(() => {}); }, { once: true });
  };
  hls.loadSource(src);
  hls.attachMedia(vid);
  hls.on(Hls.Events.MANIFEST_PARSED, (e, data) => {
    if (lowEnd && data.levels && data.levels.length > 1) {
      const idx = data.levels.map((l, i) => ({ h: Math.min(l.height || 0, l.width || 0) || l.height, i })).filter(x => x.h && x.h <= 720).map(x => x.i).pop();
      if (idx !== undefined) hls.autoLevelCapping = idx;
    }
    onReady && onReady();
  });
  hls.on(Hls.Events.ERROR, (event, data) => {
    if (!data.fatal) return;
    if (data.type === Hls.ErrorTypes.NETWORK_ERROR && netErrors++ < 6) { setTimeout(() => { try { hls.startLoad(); } catch {} }, 1000 * netErrors); return; }
    if (data.type === Hls.ErrorTypes.MEDIA_ERROR && mediaErrors++ < 2) { try { mediaErrors === 1 ? hls.recoverMediaError() : (hls.swapAudioCodec(), hls.recoverMediaError()); } catch { giveUp(); } return; }
    giveUp();
  });
  // Hängt die Wiedergabe trotz Daten im Puffer (bekanntes Problem einiger Android-Decoder),
  // wird ein Stück weitergesprungen statt endlos zu warten.
  let lastT = -1, stuck = 0;
  const watchdog = setInterval(() => {
    if (!document.body.contains(vid)) { clearInterval(watchdog); return; }
    if (vid.paused || vid.seeking || vid.ended) { stuck = 0; lastT = vid.currentTime; return; }
    if (Math.abs(vid.currentTime - lastT) < 0.01) {
      stuck++;
      if (stuck >= 3) {
        stuck = 0;
        try {
          const b = vid.buffered;
          for (let i = 0; i < b.length; i++) if (b.start(i) > vid.currentTime && b.start(i) - vid.currentTime < 3) { vid.currentTime = b.start(i) + 0.05; return; }
          hls.recoverMediaError();
        } catch {}
      }
    } else stuck = 0;
    lastT = vid.currentTime;
  }, 1000);
  return hls;
}
