// ==================== WATCH PAGE ====================
async function renderWatchPage(videoId) {
  if (!videoId) return;
  window._currentVideoId = videoId;
  const el = document.getElementById('page-watch');
  el.innerHTML = `<div class="flex-center" style="height:300px"><div class="spinner"></div></div>`;
  try {
    const [video, comments] = await Promise.all([
      apiGet(`/api/videos/${videoId}`),
      apiGet(`/api/videos/${videoId}/comments`)
    ]);
    // Register view
    apiPost(`/api/videos/${videoId}/view`).catch(() => {});
    // Add to history
    if (currentUser) apiPost(`/api/videos/${videoId}/history`).catch(() => {});
    if (socket) socket.emit('join_video', videoId);

    const isShort = video.isShort;
    // Titel/Beschreibung/Canonical für Browser-Tab, Teilen und Suchmaschinen
    if (currentPage === 'watch' && window._currentVideoId === videoId) {
      nxSetMeta({ title: video.title || 'Video', description: video.description || video.title });
      if (isShort) { try { document.querySelector('link[rel="canonical"]').href = location.origin + '/shorts/' + encodeURIComponent(videoId); } catch {} }
    }
    const isPremium = currentUser?.isPremium;
    const isPaid = video.isPaid && !video.purchasedBy?.includes(currentUser?.id);
    const hasAccess = !isPaid;
    const isOwnChannel = currentUser && currentUser.id === video.author?.id;
    const isSubscribed = currentUser && (video.author?.isSubscribed || false);
    const isBellActive = false;
    const isLiked = currentUser && video.likes?.includes(currentUser.id);
    const isDisliked = currentUser && video.dislikes?.includes(currentUser.id);
    const isSaved = false;
    const authorInitial = (video.author?.displayName || video.authorName || '?')[0].toUpperCase();

    const adBanner = ''; // Static ad banner removed - ads are shown as video overlays only

    let playerHtml = '';
    if (!hasAccess) {
      playerHtml = `<div class="watch-player-wrapper" style="padding-top:${isShort ? '177%' : '56.25%'}">
        <div style="position:absolute;inset:0;background:#0d0d12 ${video.thumbnailPath ? `url('${video.thumbnailPath}') center/cover` : ''};"></div>
        <div style="position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;background:rgba(8,8,12,0.78);backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);color:#fff;text-align:center;padding:16px">
          <span style="width:52px;height:52px;border-radius:14px;display:flex;align-items:center;justify-content:center;background:rgba(255,255,255,0.08);border:1px solid rgba(255,255,255,0.12)"><i class="fas fa-lock" style="font-size:20px"></i></span>
          <p style="font-size:17px;font-weight:700;margin:0">${t('paid_video')}</p>
          <p style="color:rgba(255,255,255,0.65);margin:0;font-size:14px">${t('price_label')}: ${Number(video.price||0).toFixed(2).replace('.', ',')} €</p>
          <button class="btn-primary" data-action="purchaseVideo" data-args="${nxA(String(video.id), (Number(video.price)||0), nxS(video.title||''))}">${t('buy_video')}</button>
        </div>
      </div>`;
    } else {
      const subtitleTracks = (video.subtitles || []).map(s =>
        `<track kind="subtitles" src="${s.path}" srclang="${s.language}" label="${escHtml(s.label || s.language)}">`
      ).join('');
      // Always set src inline so the player never shows blank/poster-only
      const _hlsSrc     = video.hlsPath  || null;
      const _directSrc  = video.playPath || video.videoPath || '';
      const _posterAttr = video.thumbnailPath ? `poster="${video.thumbnailPath}"` : '';
      // Wenn HLS vorhanden ist, KEIN direktes src setzen — sonst lädt das Handy parallel die
      // große Originaldatei (doppelte Datenmenge, auf schwachen Geräten Ruckeln/Hänger).
      const _canHls = !!_hlsSrc && ((typeof Hls !== 'undefined' && Hls.isSupported()) || !!document.createElement('video').canPlayType('application/vnd.apple.mpegurl'));
      const _inlineSrc  = (!_canHls && _directSrc) ? `src="${_directSrc}"` : '';
      const _wrapClass  = isShort ? 'short-player-wrapper' : 'watch-player-wrapper';
      const _wrapStyle  = isShort ? '' : 'padding-top:56.25%';
      // Video-Wasserzeichen des Creators – kleines, dezentes Overlay unten rechts (wie bei YouTube).
      // Gestaltung in css/v175.css (.nx-wm): klein, halbtransparent, rutscht über die Steuerleiste.
      const _watermarkHtml = video.author?.watermark
        ? `<img class="nx-wm${isShort ? ' nx-wm--short' : ''}" src="${escHtml(video.author.watermark)}" alt="" draggable="false" loading="lazy">`
        : '';
      playerHtml = `<div class="${_wrapClass}" style="${_wrapStyle}">
        <video id="main-video" data-video-id="${escHtml(video.id)}" controls playsinline webkit-playsinline preload="metadata" x-webkit-airplay="allow" controlsList="nodownload noplaybackrate nofullscreen" ${_inlineSrc} ${_posterAttr} style="object-fit:contain;background:#000" data-description="${escHtml(video.description||'')}" data-cast-src="${escHtml(video.playPath || video.videoPath || video.hlsPath || '')}" data-cast-hls="${escHtml(video.hlsPath || '')}" data-cast-poster="${escHtml(video.thumbnailPath || '')}" data-cast-title="${escHtml(video.title||'')}" data-cast-author="${escHtml(video.author?.displayName || video.authorName || '')}">
          ${subtitleTracks}
        </video>
        <button id="nxd-cast-btn" class="nxd-cast-btn" type="button" title="Auf Fernseher streamen" aria-label="Auf Fernseher streamen" style="display:flex">
          <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="20" height="20" fill="currentColor">
            <path d="M1 18v3h3c0-1.66-1.34-3-3-3zm0-4v2c2.76 0 5 2.24 5 5h2c0-3.87-3.13-7-7-7zm18-7H5v1.63c3.96 1.28 7.09 4.41 8.37 8.37H19V7zM1 10v2c4.97 0 9 4.03 9 9h2c0-6.08-4.92-11-11-11zm20-7H3c-1.1 0-2 .9-2 2v3h2V5h18v14h-7v2h7c1.1 0 2-.9 2-2V5c0-1.1-.9-2-2-2z"/>
          </svg>
        </button>
        ${_watermarkHtml}
      </div>`;
      // Attach HLS.js for hlsPath videos, fallback to direct src
      setTimeout(() => {
        const vid = document.getElementById('main-video');
        if (!vid) return;

        // ── Chromecast / Remote Playback Button ───────────────────────
        // Wird robust separat initialisiert (siehe _setupCastButtonFor weiter unten),
        // da dieser setTimeout-Block schneller feuern kann, als das <video>-Element
        // tatsächlich im DOM eingefügt wurde (der eigentliche Fix für den nicht
        // klickbaren Cast-Button: vorher lief document.getElementById('nxd-cast-btn')
        // hier oft ins Leere, weil el.innerHTML = ... erst NACH diesem Timer ausgeführt
        // wurde, wenn buildRelatedVideos() länger als 300ms brauchte).
        if (typeof nxEnhancePlayer === 'function') nxEnhancePlayer(vid);
        _setupCastButtonFor(vid);

        // Bugfix: Wenn evtl. eine Pre-Roll-Werbung gezeigt wird (nicht-Premium, kein Short,
        // Zugriff vorhanden), darf das Hauptvideo hier NICHT sofort automatisch starten.
        // Vorher lief das Video schon hörbar mit Ton, während im Hintergrund erst per API
        // geprüft/geladen wurde, ob eine Werbung kommt — dadurch hörte man kurz die Video-Audio,
        // obwohl gleich danach (oder sogar noch während) die Werbung eingeblendet wurde.
        // Die eigentliche Wiedergabe übernimmt jetzt ausschließlich der Ad-Flow weiter unten
        // (maybeShowPreRollAd), der entweder die Werbung zeigt oder das Video selbst startet.
        const _adFlowControlsPlayback = !isPremium && !isShort && hasAccess;

        // ── HLS Player Setup ──────────────────────────────────────────
        const hlsSrc = video.hlsPath ? video.hlsPath : null;
        const fallbackSrc = video.playPath || video.videoPath;

        if (hlsSrc && typeof Hls !== 'undefined' && Hls.isSupported()) {
          vid._hls = nxAttachVodHls(vid, hlsSrc, fallbackSrc, () => {
            if (window.innerWidth > 640 && !_adFlowControlsPlayback) vid.play().catch(() => {});
          });
        } else if (hlsSrc && vid.canPlayType('application/vnd.apple.mpegurl')) {
          // iPhone/iPad (Safari): natives HLS
          vid.src = hlsSrc;
          vid.addEventListener('error', () => { if (fallbackSrc && !vid.src.includes(fallbackSrc)) { vid.src = fallbackSrc; } }, { once: true });
        } else {
          // No HLS — src already set inline, autoplay only on desktop
          // (übersprungen, falls der Ad-Flow gleich selbst entscheidet, siehe oben)
          if (window.innerWidth > 640 && !_adFlowControlsPlayback) vid.play().catch(() => {});
        }

        let firstPlay = true;
        vid.addEventListener('play', () => {
          if (firstPlay) { firstPlay = false; return; } // skip autoplay
          NXD.play('video_play');
          NXD.videoFlash(vid, false);
        });
        vid.addEventListener('pause', () => {
          NXD.play('video_pause');
          NXD.videoFlash(vid, true);
        });
        // Track XP every 10 full minutes of watching
        let _watchXpTimer = null;
        let _watchXpSeconds = 0;
        const _startWatchXpTimer = () => {
          if (_watchXpTimer) return;
          _watchXpTimer = setInterval(() => {
            if (!vid.paused && !vid.ended) {
              _watchXpSeconds += 1;
              if (_watchXpSeconds >= 600) { // 10 minutes = 600 seconds
                _watchXpSeconds = 0;
                xpTrack('watch', videoId);
              }
            }
          }, 1000);
        };
        const _stopWatchXpTimer = () => { if (_watchXpTimer) { clearInterval(_watchXpTimer); _watchXpTimer = null; } };
        vid.addEventListener('play', _startWatchXpTimer);
        vid.addEventListener('pause', () => { /* keep timer, just don't count paused seconds */ });
        vid.addEventListener('ended', () => {
          _stopWatchXpTimer();
          onVideoEnded();
        });

        // ── Echtes Watchtime-Tracking für den lernenden Empfehlungsalgorithmus ──
        // Sendet alle 5s die tatsächlich geschaute Zeit an den Server, damit das Interessensprofil
        // (Kategorie/Kanal) wirklich aus echtem Sehverhalten lernt, nicht nur aus Klicks.
        startRecommendationWatchTracking(vid, video.id);

        // ── Hintergrundwiedergabe (nur Premium) ──
        _setupBackgroundPlayback(vid, video);
      }, 300);
      setTimeout(initDescriptionToggle, 100);
    }

    const relatedSection = await buildRelatedVideos(video);

    el.innerHTML = `
      ${adBanner}
      <div class="watch-layout${isShort ? ' watch-layout--short' : ''}">
        <div class="watch-player-section">
          ${playerHtml}
          <div class="watch-info">
            <h1 class="watch-title">${linkifyText(video.title)}</h1>
            <div class="watch-meta">
              <span class="watch-views" id="view-count">${formatViews(video.views)} ${t('views')} • ${timeAgo(video.createdAt)}</span>
              <div class="watch-actions">
                <button class="action-btn ${isLiked ? 'active' : ''}" id="like-btn-${video.id}" data-action="toggleLike" data-args="${nxA(String(video.id))}">
                  <i class="fas fa-thumbs-up"></i> <span id="like-count-${video.id}">${video.likes?.length || 0}</span>
                </button>
                <button class="action-btn ${isDisliked ? 'active' : ''}" id="dislike-btn-${video.id}" data-action="toggleDislike" data-args="${nxA(String(video.id))}">
                  <i class="fas fa-thumbs-down"></i> <span>${video.dislikes?.length || 0}</span>
                </button>
                <button class="action-btn" data-action="shareVideo" data-args="${nxA(String(video.id), nxS(video.title))}">
                  <i class="fas fa-share"></i> ${t('share')}
                </button>
                ${(() => { const _sv = !!(currentUser && Array.isArray(currentUser.saved) && currentUser.saved.includes(video.id)); return `<button class="action-btn nx-save-btn ${_sv ? 'active' : ''}" id="save-btn-${video.id}" data-action="saveVideo" data-args="${nxA(String(video.id))}" aria-pressed="${_sv}">
                  <i class="${_sv ? 'fas' : 'far'} fa-bookmark"></i> <span>${_sv ? tr({en:'Saved',de:'Gespeichert'}) : t('save')}</span>
                </button>`; })()}

                <!-- ── Mehr-Menü (ausgeklappt) ── -->
                <div class="watch-more-wrap" id="watch-more-wrap-${video.id}">
                  <button class="action-btn watch-more-toggle" data-action="toggleWatchMore" data-args="${nxA(String(video.id))}" id="watch-more-btn-${video.id}">
                    <i class="fas fa-ellipsis-h"></i> <span class="watch-more-label">${escHtml(t('watch_more_label'))}</span> <i class="fas fa-chevron-down" id="watch-more-arrow-${video.id}" style="font-size:10px;transition:transform 0.2s"></i>
                  </button>
                  <div class="watch-more-dropdown" id="watch-more-drop-${video.id}">
                    <button class="watch-more-item" data-action="toggleWatchMore|nxOpenAddToPlaylist" data-args="${nxA([String(video.id)], [String(video.id)])}"><i class="fas fa-folder-plus"></i> ${tr({en:'Save to playlist',de:'Zu Playlist hinzufügen'})}</button>
                    ${(() => { (window._nxCardVideos = window._nxCardVideos || {})[video.id] = { id: video.id, title: video.title || '', thumbnailPath: video.thumbnailPath || '', author: { displayName: video.author?.displayName || '' } }; const _inQ = _queue.some(q => q.id === video.id); return `<button class="watch-more-item" data-watch-queue="${video.id}" data-action="nxQueueToggleFromCard|toggleWatchMore" data-args="${nxA([String(video.id)], [String(video.id)])}">${_inQ ? `<i class="fas fa-check"></i> ${tr({en:'In queue',de:'In der Warteschlange'})}` : `<i class="fas fa-list-ul"></i> ${tr({en:'Add to queue',de:'Zur Warteschlange'})}`}</button>`; })()}
                    <button class="watch-more-item" data-action="startOrJoinParty|toggleWatchMore" data-args="${nxA([String(video.id), nxS(video.playPath || video.videoPath || ''), nxS(video.title)], [String(video.id)])}" style="color:#c77dff">
                      <i class="fas fa-users"></i> ${tr({en:'Watch Party',de:'Watch Party'})}
                    </button>
                    <button class="watch-more-item" data-action="openClipEditor|toggleWatchMore" data-args="${nxA([String(video.id), nxS(video.title)], [String(video.id)])}" style="color:#a83bff">
                      <i class="fas fa-scissors"></i> ${tr({en:'Create Clip',de:'Clip erstellen'})}
                    </button>
                    <button class="watch-more-item" data-action="openRemixModal|toggleWatchMore" data-args="${nxA([String(video.id), nxS(video.title), nxS(video.playPath||video.videoPath||"")], [String(video.id)])}" style="color:#f59e0b">
                      <i class="fas fa-sliders-h"></i> Remix
                    </button>
                    <button class="watch-more-item" data-action="downloadVideoPremium|toggleWatchMore" data-args="${nxA([String(video.id)], [String(video.id)])}" style="color:#22c55e">
                      <i class="fas fa-download"></i> ${t('download_btn')}
                      ${(currentUser && (currentUser.isPremium || currentUser.isAdmin)) ? '' : '<i class="fas fa-crown" style="color:#f59e0b;font-size:10px;margin-left:auto"></i>'}
                    </button>
                    ${currentUser && currentUser.id === video.author?.id
                      ? `<button class="watch-more-item" style="display:none;pointer-events:none" aria-hidden="true" tabindex="-1"><i class="fas fa-bullhorn"></i> ${t('promote')}</button>`
                      : `<button class="watch-more-item" style="color:#ef4444" data-action="openReportModal|toggleWatchMore" data-args="${nxA(['video', String(video.id), nxS(video.title)], [String(video.id)])}"><i class="fas fa-flag"></i> ${t('report')}</button>`}
                    <div style="height:1px;background:var(--border-light);margin:4px 8px"></div>
                    <button class="watch-more-item" id="bg-play-btn" data-action="toggleBackgroundPlay" style="color:var(--text-muted)">
                      <i class="fas fa-mobile-alt"></i> ${tr({en:'Background Play',de:'Hintergrundwiedergabe'})}
                    </button>
                    <button class="watch-more-item" id="pip-btn" data-action="togglePictureInPicture" style="color:var(--text-muted)">
                      <i class="fas fa-compress-alt"></i> Picture-in-Picture
                    </button>
                  </div>
                </div>
              </div>
            </div>
            <!-- Legacy speed/subtitle row (now inside the player bar) -->
            <div class="legacy-speed-row" style="display:none">
              <div style="display:flex;align-items:center;gap:6px">
                <i class="fas fa-tachometer-alt" style="color:var(--text-muted);font-size:13px"></i>
                <span style="font-size:12px;color:var(--text-muted)">${t('speed_label')}:</span>
                <div style="display:flex;gap:4px" id="speed-btns">
                  ${([0.25,0.5,0.75,1,1.25,1.5,1.75,2,2.5,3,3.5,4]).map(s => {
                    const locked = s > 2 && !(currentUser && (currentUser.isPremium || currentUser.isAdmin));
                    return locked
                      ? `<button data-action="showToast" data-args="${nxA(tr({en:'Speeds above 2x are a Premium feature.',de:'Geschwindigkeiten über 2x sind ein Premium-Feature.'}), 'info')}" data-speed="${s}" class="speed-btn" style="padding:3px 7px;font-size:11px;border-radius:4px;border:1px solid var(--border);background:var(--bg-secondary);color:var(--text-muted);cursor:pointer;opacity:0.6">${s}x <i class="fas fa-crown" style="color:#f59e0b;font-size:9px"></i></button>`
                      : `<button data-action="setVideoSpeed" data-args="${nxA((s))}" data-speed="${s}" class="speed-btn${s===1?' active':''}" style="padding:3px 7px;font-size:11px;border-radius:4px;border:1px solid var(--border);background:${s===1?'var(--purple-main)':'var(--bg-secondary)'};color:${s===1?'white':'var(--text-secondary)'};cursor:pointer">${s}x</button>`;
                  }).join('')}
                </div>
              </div>
              <button id="subtitle-btn" data-action="toggleSubtitles" style="padding:4px 10px;font-size:12px;border-radius:4px;border:1px solid var(--border);background:var(--bg-secondary);color:var(--text-secondary);cursor:pointer"><i class="fas fa-closed-captioning"></i> ${t('subtitles_btn')}</button>
            </div>
          </div>
          <div class="watch-channel">
            <div style="cursor:pointer;flex-shrink:0" data-action="navigateTo" data-args="${nxA('channel', String(video.author?.id))}">
              ${buildAvatarHtml(video.author, 44, { click: () => navigateTo('channel', video.author?.id) })}
            </div>
            <div class="watch-channel-info">
              <a class="watch-channel-name" style="display:block;color:inherit;text-decoration:none" href="/channel/${encodeURIComponent(video.author?.username || video.author?.id || '')}" data-action="navigateTo" data-args="${nxA('channel', String(video.author?.id))}">${escHtml(video.author?.displayName || video.authorName || t('label_unknown'))}${verifiedBadge(video.author)}</a>
              <div class="watch-channel-subs">${formatViews(video.author?.subscriberCount || 0)} ${t('subscribers_label')}</div>
            </div>
            <div style="display:flex;gap:8px;align-items:center">
              ${isOwnChannel
                ? `<button class="btn-secondary" data-action="nxSetHash|navigateTo" data-args="[[&quot;#studio/videos&quot;], [&quot;studio&quot;]]"><i class="fas fa-tools"></i> ${t('studio_btn')}</button>`
                : `<button class="subscribe-btn ${isSubscribed ? 'subscribed' : ''}" id="sub-btn-${video.author?.id}" data-action="toggleSubscribe" data-args="${nxA(String(video.author?.id))}">
                ${isSubscribed ? t('subscribed') : t('subscribe')}
              </button>
              <button class="bell-btn" id="bell-btn" data-action="toggleBell" data-args="${nxA(String(video.author?.id))}" aria-label="Benachrichtigungen">
                <i class="fas fa-bell"></i>
              </button>`}
            </div>
          </div>
          ${(video.description || video.tags?.length) ? `
          <div class="watch-description" id="watch-desc" data-h-click="h_app_if_3041">
            ${renderDescriptionWithChapters(video.description || '')}
            ${video.tags?.length ? `<div style="margin-top:8px">${video.tags.filter(Boolean).map(tag => `<a class="nx-hashtag" href="/hashtag/${encodeURIComponent(String(tag).replace(/^#/,'').toLowerCase())}" data-action="navigateTo" data-args="${nxA('hashtag', nxS(String(tag).replace(/^#/,'').toLowerCase()))}" data-prevent data-stop style="margin-right:8px">#${escHtml(String(tag).replace(/^#/,''))}</a>`).join('')}</div>` : ''}
          </div>` : ''}
          ${buildChapterBar(video)}
          <div class="comments-section">
            <h3 id="comments-count">${t('comments_title')} (${comments.length})</h3>
            <div class="comment-input">
              <div style="flex-shrink:0">${currentUser ? buildAvatarHtml(currentUser, 36, {}) : '<div class="comment-avatar">?</div>'}</div>
              <div style="flex:1;position:relative">
                <textarea id="comment-text-input" placeholder="${currentUser ? t('comment_placeholder') : t('login_to_comment')}" ${!currentUser ? 'readonly data-h-click="h_app_openAuthModal_3052"' : 'data-h-input="h_app_handleMentionInput_3052" data-h-keydown="h_app_handleMentionKeydown_3052"'}></textarea>
                ${currentUser ? `<div class="comment-compose-bar">
                  <button class="comment-sticker-btn" type="button" data-action="nxOpenStickerPicker" data-args="[&quot;$el&quot;]" title="Sticker" aria-label="Sticker"><i class="far fa-face-smile"></i></button>
                  <span id="nx-sticker-chip" class="nx-sticker-chip" style="display:none"></span>
                  <span style="flex:1"></span>
                  <button class="btn-secondary" data-h-click="h_app_getElementById_3053">${t('btn_cancel')}</button>
                  <button class="btn-primary" data-action="submitComment" data-args="${nxA(String(video.id))}">${t('post_comment_btn')}</button>
                </div>` : ''}
              </div>
            </div>
            <div id="comments-list"></div>
          </div>
        </div>
        <div class="related-videos">
          <h3>${t('more_videos')}</h3>
          ${relatedSection}
        </div>
      </div>`;

    // Render comments
    const commentsList = document.getElementById('comments-list');
    comments.forEach(c => commentsList.appendChild(createCommentEl(c)));

    // Werbung wird allen Nicht-Premium-Nutzern angezeigt (Premium-Nutzer sehen keine Werbung)
    if (!isPremium && !isShort && hasAccess) {
      const mainVideo = document.getElementById('main-video');
      if (mainVideo) {
        // Pre-roll ad (shown before video starts, ~65% chance)
        mainVideo.addEventListener('canplay', async function onCanPlay() {
          mainVideo.removeEventListener('canplay', onCanPlay);
          await maybeShowPreRollAd(mainVideo);
        }, { once: true });
        // Mid-roll ads for longer videos
        setupMidRollAds(mainVideo);
      }
    }

  } catch(e) {
    const kidsMsg = /Kindermodus|kids mode/i.test(e?.message || '');
    el.innerHTML = kidsMsg
      ? emptyState('fa-child-reaching', tr({en:'Not available in kids mode',de:'Im Kindermodus nicht verfügbar'}), tr({en:'This video is not marked as made for kids.',de:'Dieses Video ist nicht als „Für Kinder“ gekennzeichnet.'})) + `<div style="text-align:center;margin-top:-20px"><button class="btn-primary" data-action="navigateTo" data-args="[&quot;home&quot;]">${t('page_home')}</button></div>`
      : `<p style="color:var(--text-muted);padding:40px">${escHtml(e?.message && e.message !== 'Fehler' ? e.message : 'Video nicht gefunden')}</p>`;
  }
}

async function buildRelatedVideos(currentVideo) {
  try {
    const sortMode = currentUser ? 'personalized' : 'latest';
    const all = await apiGet(`/api/videos?sort=${sortMode}`);
    let filtered = all.filter(v => v.id !== currentVideo.id);
    // Videos aus der gleichen Kategorie wie das aktuell geschaute Video leicht nach vorne ziehen —
    // zusätzlich zum gelernten Gesamtprofil, damit der direkte thematische Bezug nie verloren geht.
    if (currentVideo.category) {
      const sameCat = filtered.filter(v => v.category === currentVideo.category);
      const rest = filtered.filter(v => v.category !== currentVideo.category);
      filtered = [...sameCat, ...rest];
    }
    filtered = filtered.slice(0, 15);
    if (!filtered.length) return `<p style="color:var(--text-muted);font-size:13px">${t('no_more_videos')}</p>`;
    return filtered.map(v => {
      const thumb = v.thumbnailPath ? `<img src="${v.thumbnailPath}" alt="" data-h-error="h_app_h_3112">` : `<div class="related-thumb-placeholder"><i class="fas fa-film"></i></div>`;
      return `<div class="related-video-item" data-vid-id="${v.id}" data-action="navigateTo" data-args="${nxA('watch', String(v.id))}">
        <div class="related-thumb" style="position:relative">${thumb}
          <button class="queue-add-btn" data-h-click="h_app_stopPropagation_3114" data-hv-click="${nxHv(String(v.id), String(escHtml(JSON.stringify(v.title))), String(v.thumbnailPath||''), String(escHtml(JSON.stringify(v.author?.displayName||v.authorName||''))))}" title="Zur Queue hinzufügen" aria-label="Zur Queue hinzufügen">
            <i class="fas fa-plus"></i>
          </button>
        </div>
        <div class="related-info">
          <h4>${escHtml(v.title)}</h4>
          <p>${escHtml(v.author?.displayName || v.authorName || '')}</p>
          <p>${formatViews(v.views)} ${t('view_count')}</p>
        </div>
      </div>`;
    }).join('');
  } catch { return ''; }
}

// Simple heuristic language detection (DE vs EN) — no server round-trip needed.
// Used to auto-pick the right language variant of a creator's quick reply.
function detectCommentLang(text) {
  if (!text) return 'de';
  const t = text.toLowerCase();
  if (/[äöüß]/.test(t)) return 'de'; // Umlaute sind ein starkes DE-Signal
  const deWords = ['der','die','das','und','ist','nicht','ich','du','wir','sehr','schön','gut','danke','warum','wie','was','wo'];
  const enWords = ['the','and','is','not','you','we','very','nice','good','thanks','why','how','what','where','this','that'];
  const words = t.replace(/[^a-zäöüß\s]/g, ' ').split(/\s+/).filter(Boolean);
  let deScore = 0, enScore = 0;
  for (const w of words) {
    if (deWords.includes(w)) deScore++;
    if (enWords.includes(w)) enScore++;
  }
  return enScore > deScore ? 'en' : 'de';
}

// Renders quick-reply chips for the video owner inside a reply box.
// Clicking a chip fills the textarea with the DE/EN variant matching the original comment's language.
function renderQuickReplyChips(parentId, originalText) {
  if (!currentUser || !Array.isArray(currentUser.quickReplies) || !currentUser.quickReplies.length) return '';
  const lang = detectCommentLang(originalText);
  const chips = currentUser.quickReplies.map(qr => {
    const label = lang === 'en' ? (qr.textEn || qr.textDe) : (qr.textDe || qr.textEn);
    return `<span class="quick-reply-chip" style="display:inline-block;background:var(--bg-secondary);border:1px solid var(--border);border-radius:14px;padding:4px 10px;font-size:12px;cursor:pointer;margin:2px 4px 2px 0" data-action="fillQuickReply" data-args="${nxA(nxS(parentId), nxS(label))}">${escHtml(label)}</span>`;
  }).join('');
  return `<div class="quick-reply-chips" style="margin-bottom:6px">${chips}</div>`;
}

function fillQuickReply(parentId, text) {
  const textarea = document.querySelector('#reply-input-' + parentId + ' textarea');
  if (textarea) { textarea.value = text; textarea.focus(); }
}

function createCommentEl(c) {
  const div = document.createElement('div');
  div.className = 'comment-item';
  div.id = `comment-${c.id}`;
  const initial = (c.author?.displayName || c.author?.username || '?')[0].toUpperCase();
  const avatar = buildAvatarHtml(c.author, 36, { click: () => navigateTo('channel', c.author?.id || '') });
  const repliesHtml = c.replies?.length
    ? `<div style="margin-top:12px;padding-left:12px;border-left:2px solid var(--border)">${c.replies.map(r => {
        const ri = (r.author?.displayName || r.author?.username || '?')[0].toUpperCase();
        const ra = buildAvatarHtml(r.author, 28, {});
        return `<div class="comment-item" id="comment-${r.id}" style="margin-bottom:8px">${ra}<div class="comment-body${nxBubbleClass(r.author)}"><span class="comment-author">${nxNameHtml(r.author)}</span><span class="comment-time">${timeAgo(r.createdAt)}</span>${r.sticker ? `<div class="comment-sticker">${nxStickerHtml(r.sticker)}</div>` : ''}${r.text ? `<p class="comment-text" id="comment-text-${r.id}" data-original="${escHtml(r.text)}">${linkifyText(r.text)}</p>` : ''}${renderTranslateAction(r.id, r.text)}</div></div>`;
      }).join('')}</div>` : '';

  // Show delete button if own comment or own video
  const isOwnComment = currentUser && c.author?.id === currentUser.id;
  const deleteBtn = isOwnComment ? `<span class="comment-action" style="color:#ef4444" data-action="deleteComment" data-args="${nxA(String(c.id))}"><i class="fas fa-trash"></i></span>` : '';
  const reportBtn = !isOwnComment && currentUser ? `<span class="comment-action" style="color:var(--text-muted)" data-action="openReportModal" data-args="${nxA('comment', String(c.id), nxS((c.text || '').slice(0,40)))}"><i class="fas fa-flag"></i></span>` : '';

  div.innerHTML = `${avatar}
    <div class="comment-body${nxBubbleClass(c.author)}" style="flex:1">
      <span class="comment-author">${nxNameHtml(c.author)}</span>
      <span class="comment-time">${timeAgo(c.createdAt)}</span>
      ${c.sticker ? `<div class="comment-sticker">${nxStickerHtml(c.sticker)}</div>` : ''}
      ${c.text ? `<p class="comment-text" id="comment-text-${c.id}" data-original="${escHtml(c.text)}">${linkifyText(c.text)}</p>` : ''}
      <div class="comment-actions">
        <span class="comment-action" data-action="likeComment" data-args="${nxA(String(c.id), '$el')}"><i class="fas fa-thumbs-up"></i> ${c.likes?.length || 0}</span>
        <span class="comment-action" data-action="replyToComment" data-args="${nxA(String(c.id), nxD(c.text||''))}"><i class="fas fa-reply"></i> Antworten</span>
        ${renderTranslateAction(c.id, c.text)}
        ${deleteBtn}${reportBtn}
      </div>
      ${repliesHtml}
    </div>`;
  return div;
}

// Ein-Klick-Übersetzung: rendert den "Übersetzen"-Link für einen Kommentar
// (Video-Kommentar oder Reply). Der eigentliche Text wird per API on-demand
// geholt (siehe translateComment()) — keine Vorab-Übersetzung, um den
// Übersetzungsdienst nicht unnötig zu belasten.
function renderTranslateAction(commentId, text) {
  if (!text || !text.trim()) return '';
  return `<span class="comment-action translate-action" id="translate-btn-${commentId}" data-action="translateComment" data-args="${nxA(String(commentId))}"><i class="fas fa-language"></i> ${t('translate_comment')}</span>`;
}

async function translateComment(commentId) {
  const textEl = document.getElementById(`comment-text-${commentId}`);
  const btn = document.getElementById(`translate-btn-${commentId}`);
  if (!textEl || !btn) return;

  // Zweiter Klick: zurück zum Original wechseln, kein neuer API-Call nötig.
  if (textEl.dataset.showingTranslation === '1') {
    textEl.innerHTML = linkifyText(textEl.dataset.original || '');
    textEl.dataset.showingTranslation = '0';
    btn.innerHTML = `<i class="fas fa-language"></i> ${t('translate_comment')}`;
    return;
  }

  // Bereits übersetzt vorliegend (z.B. nach Sprachwechsel zurück) → aus Cache anzeigen
  if (textEl.dataset.translated) {
    textEl.innerHTML = linkifyText(textEl.dataset.translated) + `<span class="translated-badge" style="display:block;font-size:11px;color:var(--text-muted);margin-top:2px"><i class="fas fa-language"></i> ${t('translated_label')}</span>`;
    textEl.dataset.showingTranslation = '1';
    btn.innerHTML = `<i class="fas fa-undo"></i> ${t('translate_show_original')}`;
    return;
  }

  const original = textEl.dataset.original || '';
  btn.innerHTML = `<i class="fas fa-spinner fa-spin"></i> ${t('translating')}`;
  try {
    const data = await apiPost('/api/translate', { text: original, targetLang: getLang() });
    textEl.dataset.translated = data.translated;
    textEl.innerHTML = linkifyText(data.translated) + `<span class="translated-badge" style="display:block;font-size:11px;color:var(--text-muted);margin-top:2px"><i class="fas fa-language"></i> ${t('translated_label')}</span>`;
    textEl.dataset.showingTranslation = '1';
    btn.innerHTML = `<i class="fas fa-undo"></i> ${t('translate_show_original')}`;
  } catch (e) {
    btn.innerHTML = `<i class="fas fa-language"></i> ${t('translate_comment')}`;
    showToast(e.message || t('translate_failed'), 'error');
  }
}

function prependComment(comment, list) {
  const el = createCommentEl(comment);
  list.insertBefore(el, list.firstChild);
}

async function submitComment(videoId) {
  if (!currentUser) { openAuthModal('login'); return; }
  const input = document.getElementById('comment-text-input');
  const text = input.value.trim();
  const sticker = window._nxPendingSticker || null;
  if (!text && !sticker) return;
  try {
    const c = await apiPost(`/api/videos/${videoId}/comments`, { text, sticker });
    window._nxPendingSticker = null;
    if (typeof nxRenderStickerChip === 'function') nxRenderStickerChip();
    if (c && c.id) xpTrack('comment', c.id);
    NXD.play('comment');
    input.value = '';
  } catch(e) { showToast(e.message, 'error'); }
}
