function shareVideo(id, title, isShort = false) {
  const url = isShort
    ? window.location.origin + '/shorts/' + id
    : window.location.origin + '/watch/' + id;
  const existing = document.getElementById('share-menu-overlay');
  if (existing) existing.remove();
  const overlay = document.createElement('div');
  overlay.id = 'share-menu-overlay';
  overlay.style.cssText = 'position:fixed;inset:0;z-index:9999;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,0.6)';
  const encodedUrl = encodeURIComponent(url);
  const encodedTitle = encodeURIComponent(title);
  overlay.innerHTML = `
    <div style="background:var(--bg-card);border-radius:var(--radius-lg);padding:24px;min-width:320px;max-width:90vw;box-shadow:0 20px 60px rgba(0,0,0,0.5);border:1px solid var(--border-light)">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:20px">
        <h3 style="margin:0;font-size:18px"><i class="fas fa-share-alt" style="color:var(--purple-light);margin-right:8px"></i>${t('share_title')}</h3>
        <button id="share-close-btn" style="background:none;border:none;color:var(--text-muted);font-size:20px;cursor:pointer" aria-label="Schließen"><i class="fas fa-times"></i></button>
      </div>
      <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:20px">
        <a href="https://wa.me/?text=${encodedTitle}%20${encodedUrl}" target="_blank" class="share-btn-item">
          <i class="fab fa-whatsapp" style="font-size:24px;color:#25D366"></i><span>${t('share_whatsapp')}</span>
        </a>
        <a href="https://twitter.com/intent/tweet?text=${encodedTitle}&url=${encodedUrl}" target="_blank" class="share-btn-item">
          <i class="fab fa-twitter" style="font-size:24px;color:#1DA1F2"></i><span>X / Twitter</span>
        </a>
        <a href="https://www.facebook.com/sharer/sharer.php?u=${encodedUrl}" target="_blank" class="share-btn-item">
          <i class="fab fa-facebook" style="font-size:24px;color:#1877F2"></i><span>${t('share_facebook')}</span>
        </a>
        <a href="mailto:?subject=${encodedTitle}&body=${encodeURIComponent(t('share_email_body')+' '+url)}" class="share-btn-item">
          <i class="fas fa-envelope" style="font-size:24px;color:#ea4335"></i><span>E-Mail</span>
        </a>
        <a href="https://t.me/share/url?url=${encodedUrl}&text=${encodedTitle}" target="_blank" class="share-btn-item">
          <i class="fab fa-telegram" style="font-size:24px;color:#0088cc"></i><span>${t('share_telegram')}</span>
        </a>
        <button id="share-copy-btn" class="share-btn-item" style="font-family:inherit">
          <i class="fas fa-link" style="font-size:24px;color:var(--purple-light)"></i><span>${t('share_copy_link')}</span>
        </button>
      </div>
      <div style="display:flex;gap:8px;background:var(--bg-secondary);border-radius:8px;padding:8px;border:1px solid var(--border-light)">
        <input id="share-url-input" type="text" value="${escHtml(url)}" readonly style="flex:1;background:none;border:none;color:var(--text-secondary);font-size:12px;outline:none">
        <button id="share-copy-btn2" style="background:var(--purple-main);border:none;color:white;padding:6px 12px;border-radius:6px;cursor:pointer;font-size:12px;font-weight:600" aria-label="Kopieren"><i class="fas fa-copy"></i></button>
      </div>
    </div>`;
  overlay.addEventListener('click', (e) => { if (e.target === overlay) overlay.remove(); });
  document.body.appendChild(overlay);
  document.getElementById('share-close-btn').addEventListener('click', () => overlay.remove());
  document.getElementById('share-copy-btn').addEventListener('click', () => { navigator.clipboard.writeText(url); showToast('Link kopiert!','success'); xpTrack('share', id); overlay.remove(); });
  document.getElementById('share-copy-btn2').addEventListener('click', () => { navigator.clipboard.writeText(url); showToast('Link kopiert!','success'); xpTrack('share', id); });
  document.querySelectorAll('.share-btn-item').forEach(el => {
    el.style.cssText += ';display:flex;flex-direction:column;align-items:center;gap:8px;padding:14px;background:var(--bg-secondary);border-radius:12px;text-decoration:none;color:var(--text-primary);border:1px solid var(--border-light);cursor:pointer;transition:all 0.2s;font-size:12px;font-weight:600';
  });
}
