// ==================== SHORTS – TikTok-Style Engine ====================
let _shortsCleanup = null;

// ── Shorts: nur das aktuelle Video + direkte Nachbarn laden ──
// Vorher hatten die ersten 3 Shorts gleichzeitig preload="auto" mit der ORIGINALDATEI.
// Schwache Handys haben nur wenige Hardware-Decoder: mehrere gleichzeitig geladene Videos
// führten dazu, dass das sichtbare Video nach ~1 s stehen blieb. Jetzt: aktuelles Video
// lädt voll, das nächste nur Metadaten, alles weiter Entfernte wird entladen (Decoder frei).
function nxShortsLoadAround(feed, currentCard) {
  const cards = Array.from(feed.querySelectorAll('.short-card'));
  const ci = cards.indexOf(currentCard);
  const lowEnd = typeof nxIsLowEndDevice === 'function' && nxIsLowEndDevice();
  cards.forEach((c, i) => {
    const v = c.querySelector('video');
    if (!v) return;
    const d = i - ci;
    const src = v.dataset.src || '';
    if (!src) return;
    if (d === 0 || d === 1 || (!lowEnd && d === -1)) {
      if (v.getAttribute('src') !== src) { v.setAttribute('src', src); }
      v.preload = d === 0 ? 'auto' : 'metadata';
      if (d !== 0 && !v.paused) v.pause();
    } else if (v.getAttribute('src')) {
      v.pause();
      v.removeAttribute('src');
      try { v.load(); } catch {}
    }
  });
}

// Mehr-Menü eines Shorts (Melden, Link kopieren, Kanal ansehen)
function nxOpenShortMenu(v) {
  document.getElementById('nx-short-menu')?.remove();
  const own = currentUser && v.author?.id === currentUser.id;
  const ov = document.createElement('div');
  ov.id = 'nx-short-menu';
  ov.className = 'nx-sheet-overlay';
  ov.innerHTML = `<div class="nx-sheet" role="dialog" aria-modal="true">
      <div class="nx-sheet-grip"></div>
      <button class="nx-sheet-item" data-act="link"><i class="fas fa-link"></i> ${tr({en:'Copy link',de:'Link kopieren'})}</button>
      <button class="nx-sheet-item" data-act="channel"><i class="fas fa-user"></i> ${tr({en:'Go to channel',de:'Zum Kanal'})}</button>
      <button class="nx-sheet-item" data-act="cast"><i class="fab fa-chromecast"></i> ${tr({en:'Cast to TV',de:'Auf Fernseher streamen'})}</button>
      ${own ? '' : `<button class="nx-sheet-item is-danger" data-act="report"><i class="fas fa-flag"></i> ${tr({en:'Report',de:'Melden'})}</button>`}
      <button class="nx-sheet-item nx-sheet-cancel" data-act="close">${t('btn_cancel')}</button>
    </div>`;
  const close = () => { ov.classList.remove('is-open'); setTimeout(() => ov.remove(), 200); };
  ov.addEventListener('click', (e) => {
    if (e.target === ov) return close();
    const b = e.target.closest('[data-act]'); if (!b) return;
    const a = b.dataset.act; close();
    if (a === 'link') { const url = `${location.origin}/shorts/${v.id}`; (navigator.clipboard?.writeText(url) || Promise.reject()).then(() => showToast(tr({en:'Link copied',de:'Link kopiert'}), 'success')).catch(() => prompt('Link', url)); }
    else if (a === 'channel') navigateTo('channel', v.author?.id);
    else if (a === 'cast') {
      const vid = document.querySelector(`.short-card[data-video-id="${v.id}"] video`);
      if (_castApiReady && vid) _castCurrentVideoViaSDK(vid).catch(err => { if (!(err && (err === 'cancel' || err.code === 'cancel'))) showToast(tr({en:'Casting failed',de:'Streamen fehlgeschlagen'}), 'error'); });
      else showToast(_nxCastHint(), 'info');
    }
    else if (a === 'report') { if (!currentUser) { openAuthModal('login'); return; } openReportModal('video', v.id, v.title || 'Short'); }
  });
  document.body.appendChild(ov);
  requestAnimationFrame(() => ov.classList.add('is-open'));
}

async function renderShortsPage() {
  const el = document.getElementById('page-shorts');
  el.innerHTML = `<div class="flex-center" style="height:300px"><div class="spinner"></div></div>`;

  // Cleanup previous instance
  if (_shortsCleanup) { _shortsCleanup(); _shortsCleanup = null; }

  try {
    const recData = await apiGet('/api/videos/recommended');
    let allShorts = recData.shorts || [];
    // Direktaufruf /shorts/<id> (z. B. aus Google oder einem geteilten Link): Short laden,
    // auch wenn er nicht in den Empfehlungen ist
    const _startId = window._shortsStartVideoId;
    if (_startId && !allShorts.some(s => s.id === _startId)) {
      try { const sv = await apiGet(`/api/videos/${encodeURIComponent(_startId)}`); if (sv && sv.id) allShorts.unshift(sv); } catch {}
    }
    if (!allShorts.length) {
      el.innerHTML = emptyState('fa-film', t('empty_shorts_title'), t('empty_shorts_desc'));
      return;
    }

    // Server liefert bereits personalisiert vorsortiert (gelerntes Interessensprofil).
    // Client-seitig: Engagement-Feintuning + Reload-Shuffle, damit bei jedem F5
    // die Reihenfolge spürbar wechselt — aber bevorzugte Kategorien bleiben vorne.
    const _shortsSeed = Math.random() * 100000;
    function seededRandShorts(i) {
      const x = Math.sin(_shortsSeed + i * 9301 + 49297) * 233280;
      return x - Math.floor(x);
    }
    function scoreShort(v, idx) {
      const likes    = v.likes?.length    || 0;
      const comments = v.comments?.length || 0;
      const views    = v.views            || 0;
      const age      = Date.now() - new Date(v.createdAt || 0).getTime();
      const hourAge  = age / 3_600_000;
      const decay    = Math.pow(0.5, hourAge / 48);
      const isSubbed = currentUser && (v.author?.isSubscribed || false);
      // Reload-Rauschen: groß genug für sichtbare Variation, aber kleiner als subBoost/engagement
      const noise    = seededRandShorts(idx) * 8;
      return (likes * 3 + comments * 5 + views * 0.1) * decay + (isSubbed ? 50 : 0) + noise;
    }
    // Tier-Shuffle: 3 Tiers nach Score, innerhalb jedes Tiers echter Shuffle
    const _rawScored = [...allShorts].map((v, i) => ({ v, s: scoreShort(v, i) }));
    _rawScored.sort((a, b) => b.s - a.s);
    const _t = Math.ceil(_rawScored.length / 3);
    function _shuffleTier(arr) {
      const a = [...arr];
      for (let i = a.length - 1; i > 0; i--) {
        const j = Math.floor(seededRandShorts(i + (a[0]?.v?.id?.charCodeAt(0) || 0)) * (i + 1));
        [a[i], a[j]] = [a[j], a[i]];
      }
      return a;
    }
    const shorts = [
      ..._shuffleTier(_rawScored.slice(0, _t)),
      ..._shuffleTier(_rawScored.slice(_t, _t * 2)),
      ..._shuffleTier(_rawScored.slice(_t * 2)),
    ].map(x => x.v);

    // === BUILD SHORTS UI (YouTube-style: sidebar+header visible) ===
    el.innerHTML = `
      <div class="shorts-container" id="shorts-feed"></div>
      <div class="shorts-progress" id="shorts-progress"></div>`;

    const feed     = document.getElementById('shorts-feed');
    const progress = document.getElementById('shorts-progress');
    let currentIdx = 0;
    const observers = [];

    // Build progress dots (max 12 visible)
    const MAX_DOTS = 12;
    const dotCount = Math.min(shorts.length, MAX_DOTS);
    for (let i = 0; i < dotCount; i++) {
      const d = document.createElement('div');
      d.className = 'shorts-dot' + (i === 0 ? ' active' : '');
      progress.appendChild(d);
    }

    function updateDots(idx) {
      const dots = progress.querySelectorAll('.shorts-dot');
      dots.forEach((d, i) => d.classList.toggle('active', i === Math.min(idx, MAX_DOTS - 1)));
    }

    function goToIndex(idx) {
      if (idx < 0 || idx >= shorts.length) return;
      // .short-ad-card zählt nicht als regulärer Short-Index, daher nur echte Shorts berücksichtigen
      const cards = feed.querySelectorAll('.short-card:not(.short-ad-card)');
      if (cards[idx]) {
        cards[idx].scrollIntoView({ behavior: 'smooth', block: 'start' });
      }
    }

    // Keyboard navigation only

    // Pfeiltasten gehen Karte für Karte (inkl. Werbe-Shorts), damit Werbung nicht per
    // Tastatur einfach übersprungen wird, ohne sie je zu sehen.
    const keyHandler = (e) => {
      if (e.key !== 'ArrowDown' && e.key !== 'ArrowUp') return;
      const allCards = Array.from(feed.querySelectorAll('.short-card'));
      const top = feed.getBoundingClientRect().top;
      let cur = 0, best = Infinity;
      allCards.forEach((c, i) => { const d = Math.abs(c.getBoundingClientRect().top - top); if (d < best) { best = d; cur = i; } });
      const next = allCards[cur + (e.key === 'ArrowDown' ? 1 : -1)];
      if (next) { e.preventDefault(); next.scrollIntoView({ behavior: 'smooth', block: 'start' }); }
    };
    document.addEventListener('keydown', keyHandler);

    // Build cards (mit eingestreuter Werbe-Short, wie bei TikTok/YouTube — alle SHORT_AD_INTERVAL
    // Shorts eine Werbung, nur für Nutzer ohne Premium). Die Werbe-Shorts haben KEINEN Countdown,
    // man kann sie sofort wegscrollen.
    const showShortAds = !currentUser?.isPremium && !currentUser?.isAdmin;
    const SHORT_AD_INTERVAL = 5;
    let adCounter = 0;
    // Alle benötigten Werbungen parallel vorladen (vorher: pro Werbung ein await mitten im
    // Aufbau -> Feed baute sich spürbar langsamer auf). Impressionen werden erst gezählt,
    // wenn die Werbe-Karte wirklich sichtbar wird (track=0).
    const _adSlots = showShortAds ? Math.floor((shorts.length - 1) / SHORT_AD_INTERVAL) : 0;
    const _prefetchedAds = _adSlots > 0
      ? (await Promise.all(Array.from({ length: _adSlots }, () =>
          apiGet('/api/ads/random?type=short').catch(() => null)))).filter(a => a && a.videoPath)
      : [];
    let _adPtr = 0;
    for (const [idx, v] of shorts.entries()) {
      // Nach jedem SHORT_AD_INTERVAL-ten Short eine Werbung einstreuen (nie ganz am Anfang)
      if (showShortAds && idx > 0 && idx % SHORT_AD_INTERVAL === 0) {
        const shortAd = _prefetchedAds.length ? _prefetchedAds[_adPtr++ % _prefetchedAds.length] : null;
        if (shortAd) {
          const adCard = buildShortAdCard(shortAd, `shortad-${adCounter++}`);
          feed.appendChild(adCard.el);
          observers.push(adCard.observer);
        }
      }
      const sc = document.createElement('div');
      sc.className = 'short-card';
      sc.dataset.videoId = v.id;
      sc.dataset.idx = idx;
      const isLiked = currentUser && v.likes?.includes(currentUser.id);

      sc.innerHTML = `
        <video data-src="${escHtml(v.playPath || v.videoPath || '')}" ${v.thumbnailPath ? `poster="${escHtml(v.thumbnailPath)}"` : ''} loop muted playsinline webkit-playsinline preload="none"></video>
        <div class="short-pause-overlay" id="short-pause-icon-${v.id}" style="position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);font-size:64px;color:white;opacity:0;transition:opacity 0.25s;pointer-events:none;z-index:10;text-shadow:0 2px 20px rgba(0,0,0,0.8)"><i class="fas fa-play"></i></div>
        <div class="short-overlay">
          <div class="short-side-actions">
            <div class="short-action${isLiked ? ' active' : ''}" id="short-like-${v.id}" data-liked="${isLiked ? '1' : '0'}">
              <i class="fas fa-heart" style="color:${isLiked ? '#a83bff' : 'white'}"></i>
              <span>${v.likes?.length || 0}</span>
            </div>
            <div class="short-action" id="short-comment-${v.id}">
              <i class="fas fa-comment"></i><span>${v.comments?.length || 0}</span>
            </div>
            <div class="short-action" id="short-share-${v.id}">
              <i class="fas fa-share"></i><span>${t('share')}</span>
            </div>
            <div class="short-action short-more" id="short-more-${v.id}" role="button" aria-label="${tr({en:'More',de:'Mehr'})}">
              <i class="fas fa-ellipsis"></i><span>${tr({en:'More',de:'Mehr'})}</span>
            </div>
          </div>
          <div class="short-info">
            <div style="display:flex;align-items:center;gap:8px;margin-bottom:8px">
              <div style="cursor:pointer;flex-shrink:0" id="short-avatar-${v.id}">
                ${buildAvatarHtml(v.author, 38, { click: () => navigateTo('channel', v.author?.id) })}
              </div>
              <span style="font-weight:700;color:white">${escHtml(v.author?.displayName || v.authorName || '')}</span>
              ${currentUser && v.author?.id !== currentUser.id ? `<button class="short-follow-btn" id="short-follow-${v.id}">${t('follow')}</button>` : ''}
            </div>
            <h4>${nxHashtagify(escHtml(v.title))}</h4>
            <p>${nxHashtagify(escHtml(v.description?.slice(0, 100) || ''))}</p>
          </div>
        </div>`;

      // Events
      sc.querySelector(`#short-like-${v.id}`).addEventListener('click', async () => {
        if (!currentUser) { openAuthModal('login'); return; }
        const btn = sc.querySelector(`#short-like-${v.id}`);
        const icon = btn.querySelector('i');
        const countEl = btn.querySelector('span');
        try {
          const data = await toggleLikeShort(v.id);
          btn.dataset.liked = data.liked ? '1' : '0';
          btn.classList.toggle('active', data.liked);
          icon.style.color = data.liked ? '#a83bff' : 'white';
          countEl.textContent = data.likes;
        } catch {}
      });
      sc.querySelector(`#short-comment-${v.id}`).addEventListener('click', () => toggleCommentPanel(v.id));
      sc.querySelector(`#short-share-${v.id}`).addEventListener('click', () => shareVideo(v.id, v.title, true));
      sc.querySelector(`#short-avatar-${v.id}`).addEventListener('click', () => navigateTo('channel', v.author?.id));
      sc.querySelector(`#short-more-${v.id}`).addEventListener('click', (e) => { e.stopPropagation(); nxOpenShortMenu(v); });

      const followBtn = sc.querySelector(`#short-follow-${v.id}`);
      if (followBtn) {
        const isSubbed = currentUser && (v.author?.isSubscribed || false);
        if (isSubbed) { followBtn.textContent = 'Abonniert'; followBtn.classList.add('is-subscribed'); }
        followBtn.addEventListener('click', async () => {
          if (!currentUser) { openAuthModal('login'); return; }
          try {
            const data = await apiPost(`/api/users/${v.author?.id}/subscribe`);
            if (data.subscribed) {
              followBtn.textContent = 'Abonniert';
              followBtn.classList.add('is-subscribed');
              showToast('Abonniert!', 'success');
            } else {
              followBtn.textContent = t('follow');
              followBtn.classList.remove('is-subscribed');
              showToast('Abo entfernt', 'info');
            }
          } catch(e) { showToast('Fehler', 'error'); }
        });
      }

      // Video click = pause/play
      const video = sc.querySelector('video');
      const pauseIcon = sc.querySelector(`#short-pause-icon-${v.id}`);
      const togglePlay = () => {
        if (video.paused) {
          video.play().catch(() => {});
          pauseIcon.querySelector('i').className = 'fas fa-play';
          pauseIcon.style.opacity = '1';
          setTimeout(() => { pauseIcon.style.opacity = '0'; }, 500);
        } else {
          video.pause();
          pauseIcon.querySelector('i').className = 'fas fa-pause';
          pauseIcon.style.opacity = '1';
          setTimeout(() => { pauseIcon.style.opacity = '0'; }, 800);
        }
      };
      video.addEventListener('click', togglePlay);
      sc.querySelector('.short-overlay').addEventListener('click', (e) => {
        if (e.target.closest('.short-side-actions') || e.target.closest('.short-info')) return;
        togglePlay();
      });

      // IntersectionObserver: autoplay + track current index + update dots + echte Watchtime
      const obs = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            currentIdx = idx;
            // Adresse mitführen (/shorts/<id>), damit Teilen und Neuladen den richtigen Short zeigen
            if (currentPage === 'shorts') { nxReplaceRoute('shorts/' + v.id); nxSetMeta({ title: v.title || 'Short', description: v.description || v.title }); }
            nxShortsLoadAround(feed, sc);
            try {
              if ('mediaSession' in navigator) {
                navigator.mediaSession.metadata = new MediaMetadata({ title: v.title || 'Short', artist: v.author?.displayName || v.authorName || 'Norynex', album: 'Norynex Shorts',
                  artwork: v.thumbnailPath ? [{ src: new URL(v.thumbnailPath, location.href).href, sizes: '360x640' }] : [{ src: '/assets/icon-512.png', sizes: '512x512', type: 'image/png' }] });
                navigator.mediaSession.setActionHandler('play', () => video.play().catch(() => {}));
                navigator.mediaSession.setActionHandler('pause', () => video.pause());
                navigator.mediaSession.setActionHandler('nexttrack', () => { const n = sc.nextElementSibling; if (n) n.scrollIntoView({ behavior: 'smooth', block: 'start' }); });
                navigator.mediaSession.setActionHandler('previoustrack', () => { const p = sc.previousElementSibling; if (p) p.scrollIntoView({ behavior: 'smooth', block: 'start' }); });
              }
            } catch {}
            video.muted = localStorage.getItem('nxd_shorts_sound') === 'false';
            video.play().catch(() => { video.muted = true; video.play().catch(() => {}); });
            updateDots(idx);
            startRecommendationWatchTracking(video, v.id);
            // View zählen — bisher passierte das nur auf der normalen Watch-Seite, wodurch
            // Shorts, die man im FYP-Feed einfach vorbeiscrollt/ansieht, nie mitgezählt wurden.
            if (!sc.dataset.viewTracked) {
              sc.dataset.viewTracked = '1';
              apiPost(`/api/videos/${v.id}/view`).catch(() => {});
              xpTrack('short', v.id);
            }
            // Short angesehen -> verschwindet danach von der Startseite/Shorts-Feed (wie reguläre Videos)
            if (currentUser && !sc.dataset.historyTracked) {
              sc.dataset.historyTracked = '1';
              apiPost(`/api/videos/${v.id}/history`).catch(() => {});
            }
          } else {
            video.pause();
            video.muted = true;
            stopRecommendationWatchTracking();
          }
        });
      }, { threshold: 0.6, root: feed });
      obs.observe(sc);
      observers.push(obs);

      feed.appendChild(sc);
    }

    // Scroll to startVideoId if set (when coming from home page shorts)
    if (window._shortsStartVideoId) {
      const startId = window._shortsStartVideoId;
      window._shortsStartVideoId = null;
      requestAnimationFrame(() => {
        const targetCard = feed.querySelector(`.short-card[data-video-id="${startId}"]`);
        if (targetCard) targetCard.scrollIntoView({ behavior: 'instant', block: 'start' });
      });
    }

    // Cleanup fn
    _shortsCleanup = () => {
      document.removeEventListener('keydown', keyHandler);
      observers.forEach(o => o.disconnect());
      stopRecommendationWatchTracking();
      feed.querySelectorAll('video').forEach(v => { v.pause(); v.removeAttribute('src'); try { v.load(); } catch {} });
    };

  } catch(e) { el.innerHTML = emptyState('fa-film', 'Fehler', e.message); }
}
