// ── Live-Wiedergabe (HLS) mit Wartebildschirm, Neuverbindung und Ende-Erkennung ──
function nxAttachLiveHls(video, userId) {
  if (typeof video._liveCleanup === 'function') video._liveCleanup();
  const src = `/api/live/${encodeURIComponent(userId)}/index.m3u8`;
  let hls = null, stopped = false, pollT = null, tries = 0;
  const cleanup = () => { stopped = true; clearTimeout(pollT); if (hls) { try { hls.destroy(); } catch {} hls = null; } video._liveCleanup = null; };
  video._liveCleanup = cleanup;
  const ended = () => { cleanup(); nxShowLoading(tr({en:'The stream has ended.',de:'Der Stream wurde beendet.'})); };
  const attach = () => {
    if (stopped || !document.body.contains(video)) return cleanup();
    nxHideLoading();
    if (typeof Hls !== 'undefined' && Hls.isSupported()) {
      hls = new Hls({
        enableWorker: true, lowLatencyMode: false,
        liveSyncDurationCount: 2, liveMaxLatencyDurationCount: 5, maxLiveSyncPlaybackRate: 1.1,
        backBufferLength: 10, maxBufferLength: 12, capLevelToPlayerSize: true,
        manifestLoadingMaxRetry: 10, manifestLoadingRetryDelay: 1000, levelLoadingMaxRetry: 10, fragLoadingMaxRetry: 10,
      });
      hls.loadSource(src);
      hls.attachMedia(video);
      hls.on(Hls.Events.MANIFEST_PARSED, () => { video.play().catch(() => { video.muted = true; video.play().catch(() => {}); }); });
      let netErr = 0;
      hls.on(Hls.Events.FRAG_LOADED, () => { netErr = 0; });
      hls.on(Hls.Events.ERROR, (e, data) => {
        if (!data.fatal) return;
        if (data.type === Hls.ErrorTypes.MEDIA_ERROR) { try { hls.recoverMediaError(); } catch {} return; }
        if (++netErr > 8) { cleanup(); stopped = false; video._liveCleanup = cleanup; nxShowLoading(tr({en:'Reconnecting…',de:'Verbinde neu …'})); pollT = setTimeout(waitReady, 3000); return; }
        setTimeout(() => { try { hls && hls.startLoad(); } catch {} }, 1500);
      });
    } else if (video.canPlayType('application/vnd.apple.mpegurl')) {
      video.src = src;
      video.addEventListener('loadedmetadata', () => video.play().catch(() => {}), { once: true });
    } else {
      nxShowLoading(tr({en:'Your browser cannot play live streams.',de:'Dein Browser kann keine Livestreams abspielen.'}));
    }
  };
  const waitReady = async () => {
    if (stopped || !document.body.contains(video)) return cleanup();
    try {
      const st = await fetch(`/api/live/${encodeURIComponent(userId)}/status`, { cache: 'no-store' }).then(r => r.json());
      if (!st.live) return ended();
      if (st.ready) return attach();
    } catch {}
    nxShowLoading(++tries < 4 ? tr({en:'Connecting to live stream…',de:'Verbinde mit dem Livestream …'}) : tr({en:'Waiting for the streamer… the stream starts in a few seconds.',de:'Warte auf den Streamer … der Stream startet in wenigen Sekunden.'}));
    pollT = setTimeout(waitReady, 2000);
  };
  if (socket) {
    const onEnd = (d) => { if (d && d.userId === userId) { socket.off('stream_broadcast_ended', onEnd); ended(); } };
    socket.on('stream_broadcast_ended', onEnd);
  }
  waitReady();
}
