// ==================== EIGENE PLAYER-CONTROLS (statt native Browser-Controls) ====================
function nxHideLoading() {
  const el = document.getElementById('nx-player-loading');
  if (el) el.classList.add('nx-hidden');
}
function nxShowLoading(text) {
  const el = document.getElementById('nx-player-loading');
  if (!el) return;
  if (text) { const span = el.querySelector('span'); if (span) span.textContent = text; }
  el.classList.remove('nx-hidden');
}
function nxInitPlayerControls(video) {
  if (!video) return;
  video.addEventListener('playing', nxHideLoading);
  video.addEventListener('waiting', () => nxShowLoading(tr({en:'Buffering…',de:'Puffert …'})));
  video.addEventListener('play', () => {
    const btn = document.getElementById('nx-play-btn');
    if (btn) btn.innerHTML = '<i class="fas fa-pause"></i>';
  });
  video.addEventListener('pause', () => {
    const btn = document.getElementById('nx-play-btn');
    if (btn) btn.innerHTML = '<i class="fas fa-play"></i>';
  });
  // Auto-hide der Controls nach Inaktivität, wie bei modernen Streaming-Playern
  const wrap = document.getElementById('stream-video-container');
  if (wrap) {
    let hideTimer = null;
    const showCtrls = () => {
      wrap.classList.add('nx-controls-visible');
      clearTimeout(hideTimer);
      hideTimer = setTimeout(() => wrap.classList.remove('nx-controls-visible'), 3000);
    };
    wrap.addEventListener('mousemove', showCtrls);
    wrap.addEventListener('mouseleave', () => { clearTimeout(hideTimer); wrap.classList.remove('nx-controls-visible'); });
    wrap.addEventListener('click', (e) => { if (e.target === video) nxTogglePlay(); });
    showCtrls();
  }
}
function nxTogglePlay() {
  const video = document.getElementById('stream-video');
  if (!video) return;
  if (video.paused) video.play().catch(() => {}); else video.pause();
}
function nxToggleMute() {
  const video = document.getElementById('stream-video');
  const btn = document.getElementById('nx-mute-btn');
  if (!video) return;
  video.muted = !video.muted;
  if (btn) btn.innerHTML = video.muted ? '<i class="fas fa-volume-xmark"></i>' : '<i class="fas fa-volume-high"></i>';
}
function nxSetVolume(val) {
  const video = document.getElementById('stream-video');
  const btn = document.getElementById('nx-mute-btn');
  if (!video) return;
  video.volume = parseFloat(val);
  video.muted = video.volume === 0;
  if (btn) btn.innerHTML = video.muted ? '<i class="fas fa-volume-xmark"></i>' : '<i class="fas fa-volume-high"></i>';
}
function nxTogglePip() {
  const video = document.getElementById('stream-video');
  if (!video || !document.pictureInPictureEnabled) return;
  if (document.pictureInPictureElement) document.exitPictureInPicture().catch(() => {});
  else video.requestPictureInPicture().catch(() => {});
}
function nxToggleFullscreen() {
  const wrap = document.getElementById('stream-video-container');
  if (!wrap) return;
  if (document.fullscreenElement) document.exitFullscreen().catch(() => {});
  else wrap.requestFullscreen().catch(() => {});
}

