function sendChatMsg(streamerId) {
  if (!currentUser) { openAuthModal('login'); return; }
  const input = document.getElementById('chat-input');
  const msg = input.value.trim();
  if (!msg) return;
  const isStreamer = currentUser.id === streamerId;
  socket.emit('stream_chat', { streamerId, message: msg, username: currentUser.displayName || currentUser.username, isStreamer });
  input.value = '';
}

function _handleStreamChatBlocked(data) {
  const reasons = {
    disabled: tr({en:'The chat is currently disabled.',de:'Der Chat ist gerade deaktiviert.'}),
    followers_only: tr({en:'Chat is followers-only right now.',de:'Der Chat ist gerade nur für Follower.'}),
    slow_mode: (tr({en:`Slow mode: wait ${Math.ceil((data.waitMs||0)/1000)}s`,de:`Zeitlupe: warte noch ${Math.ceil((data.waitMs||0)/1000)}s`})),
    moderation: tr({en:'Your message was flagged as inappropriate and not sent.',de:'Deine Nachricht wurde als unangemessen erkannt und nicht gesendet.'}),
  };
  showToast(reasons[data.reason] || (tr({en:'Message not sent',de:'Nachricht nicht gesendet'})), 'error');
}

function getUsernameColor(id) {
  const colors = ['#c77dff','#60a5fa','#34d399','#fb923c','#f472b6','#facc15','#38bdf8','#4ade80','#f87171','#c084fc'];
  let hash = 0;
  for (let i = 0; i < (id||'').length; i++) hash = (hash * 31 + id.charCodeAt(i)) & 0xffffffff;
  return colors[Math.abs(hash) % colors.length];
}

function toggleModPanel(streamerId) {
  const panel = document.getElementById('mod-panel');
  if (panel) panel.style.display = panel.style.display === 'none' ? 'block' : 'none';
}

async function doStreamMod(streamerId, action) {
  const input = document.getElementById('mod-target-user');
  const val = input ? input.value.trim() : '';
  if (!val) { showToast('Bitte Username oder User-ID eingeben', 'error'); return; }
  let duration = 300;
  if (action === 'timeout') {
    const d = prompt('Timeout-Dauer in Sekunden (Standard: 300):', '300');
    duration = parseInt(d) || 300;
  }
  try {
    // Find user id by username if needed
    let targetUserId = val;
    if (!val.includes('-')) {
      try { const u = await apiGet('/api/users/' + val); targetUserId = u.id; } catch {}
    }
    await apiPost('/api/users/' + streamerId + '/stream/mod', { targetUserId, action, duration });
    const labels = { addmod: t('mod_give'), timeout: t('mod_timeout'), ban: t('mod_ban'), removemod: t('mod_remove') };
    showToast((labels[action] || action), 'success');
    if (input) input.value = '';
  } catch(e) { showToast(e.message || 'Fehler', 'error'); }
}

function showChatModMenu(msg, div, streamerId) {
  document.getElementById('chat-mod-ctx')?.remove();
  const menu = document.createElement('div');
  menu.id = 'chat-mod-ctx';
  menu.style.cssText = 'position:fixed;background:var(--bg-card);border:1px solid var(--border);border-radius:8px;z-index:9999;padding:6px;min-width:160px;box-shadow:0 8px 24px rgba(0,0,0,0.4)';
  const rect = div.getBoundingClientRect();
  menu.style.top = Math.min(rect.bottom + 4, window.innerHeight - 150) + 'px';
  menu.style.left = Math.min(rect.left, window.innerWidth - 170) + 'px';
  menu.innerHTML = `
    <div style="padding:4px 10px;font-size:11px;color:var(--text-muted);font-weight:700">@${escHtml(msg.username)}</div>
    <button class="ctx-btn" data-h-click="h_app_streamModAction_4343" data-hv-click="${nxHv(String(streamerId), String(msg.msgId))}"><i class="fas fa-trash"></i> ${t('mod_delete_msg')}</button>
    <button class="ctx-btn" data-h-click="h_app_streamModAction_4344" data-hv-click="${nxHv(String(streamerId), String(msg.userId))}"><i class="fas fa-stopwatch"></i> ${t('mod_timeout')} (5 Min)</button>
    <button class="ctx-btn" data-h-click="h_app_streamModAction_4345" data-hv-click="${nxHv(String(streamerId), String(msg.userId))}">${t('mod_ban')}</button>
    <button class="ctx-btn" data-h-click="h_app_streamModAction_4346" data-hv-click="${nxHv(String(streamerId), String(msg.userId))}"><i class="fas fa-shield-halved"></i> ${t('mod_give')}</button>`;
  document.body.appendChild(menu);
  setTimeout(() => document.addEventListener('click', () => menu.remove(), { once: true }), 50);
}

async function streamModAction(action, streamerId, msgId, targetUserId) {
  document.getElementById('chat-mod-ctx')?.remove();
  try {
    const body = { action, targetUserId, msgId, duration: 300 };
    await apiPost('/api/users/' + streamerId + '/stream/mod', body);
    const labels = { deletemsg: t('mod_delete_msg'), timeout: t('mod_timeout'), ban: t('mod_ban'), addmod: t('mod_give') };
    showToast(labels[action] || t('done'), 'success');
  } catch(e) { showToast(e.message || 'Fehler', 'error'); }
}

// Einheitliche Fehleranzeige für Feed-Seiten (ersetzt hartkodiertes "Fehler: ..." auf Deutsch).
function feedErrorHtml(e) {
  return `<div class="an-error"><i class="fas fa-triangle-exclamation"></i><p>${escHtml(t('loading_error'))}${e?.message ? ': ' + escHtml(e.message) : ''}</p></div>`;
}
