// ==================== CATEGORY PAGES ====================
async function renderCategoryPage(category) {
  const page = category === 'trending' ? 'trending' : category.toLowerCase();
  const el = document.getElementById(`page-${page}`);
  const catMeta = {
    trending: { icon: 'fa-fire', label: t('page_trending') },
    Gaming: { icon: 'fa-gamepad', label: t('page_gaming') },
    Music: { icon: 'fa-music', label: t('page_music') },
    Sports: { icon: 'fa-football-ball', label: t('page_sports') },
    Comedy: { icon: 'fa-laugh', label: t('page_comedy') },
  }[category] || { icon: 'fa-tag', label: category };
  const header = `<div class="page-header"><h2><i class="fas ${catMeta.icon}" style="color:var(--purple-main);margin-right:10px;font-size:.85em"></i>${escHtml(catMeta.label)}</h2></div>`;
  el.innerHTML = header + `<div class="spinner" style="margin:40px auto;display:block"></div>`;
  try {
    const params = category === 'trending' ? '?sort=trending' : `?category=${category}`;
    const videos = await apiGet('/api/videos' + params);
    if (!videos.length) {
      el.innerHTML = header + emptyState('fa-film', t('empty_cat_title'), t('empty_cat_desc'));
      return;
    }
    el.innerHTML = header + `<div class="video-grid" id="${page}-grid"></div>`;
    const grid = document.getElementById(`${page}-grid`);
    videos.forEach(v => grid.appendChild(createVideoCard(v)));
  } catch(e) { el.innerHTML = header + feedErrorHtml(e); }
}

