// ==================== HISTORY ====================
// Verlauf mit Steuerung: pausieren/fortsetzen, einzelne Videos entfernen, alles löschen, suchen.
async function renderHistoryPage() {
  const el = document.getElementById('page-history');
  if (!currentUser) {
    el.innerHTML = `<div class="page-header"><h2>${t('page_history')}</h2></div>` + emptyState('fa-sign-in-alt', t('login_required'), t('login_required_history')) + `<div style="text-align:center;margin-top:-20px"><button class="btn-primary" data-h-click="h_app_openAuthModal_4419">${t('btn_login')}</button></div>`;
    return;
  }
  el.innerHTML = `<div class="page-header"><h2>${t('page_history')}</h2></div><div class="spinner" style="margin:40px auto;display:block"></div>`;
  let videos = [];
  try { videos = await apiGet('/api/users/me/history'); } catch(e) { el.innerHTML = feedErrorHtml(e); return; }
  const paused = !!currentUser.privacySettings?.historyPaused;
  el.innerHTML = `
    <div class="hist-layout">
      <div class="hist-main">
        <div class="page-header" style="margin-bottom:12px"><h2>${t('page_history')}</h2></div>
        ${paused ? `<div class="hist-paused-banner"><i class="fas fa-pause-circle"></i><div><strong>${tr({en:'Watch history is paused',de:'Verlauf ist pausiert'})}</strong><span>${tr({en:'Videos you watch are not saved right now.',de:'Angesehene Videos werden gerade nicht gespeichert.'})}</span></div></div>` : ''}
        <div id="hist-list" class="hist-list"></div>
      </div>
      <aside class="hist-side">
        <div class="hist-search"><i class="fas fa-search"></i><input id="hist-search" type="search" placeholder="${escHtml(tr({en:'Search watch history',de:'Verlauf durchsuchen'}))}"></div>
        <button class="hist-action" data-h-click="h_app_historyClearAll_4434"><i class="fas fa-trash"></i> ${tr({en:'Clear all watch history',de:'Gesamten Verlauf löschen'})}</button>
        <button class="hist-action" id="hist-pause-btn" data-h-click="h_app_historyTogglePause_4435"><i class="fas ${paused ? 'fa-play' : 'fa-pause'}"></i> ${paused ? tr({en:'Turn on watch history',de:'Verlauf wieder aktivieren'}) : tr({en:'Pause watch history',de:'Verlauf pausieren'})}</button>
        <p class="hist-note">${tr({en:'Your history helps improve recommendations. Pausing it means new videos are not added.',de:'Dein Verlauf verbessert deine Empfehlungen. Wenn er pausiert ist, werden neue Videos nicht hinzugefügt.'})}</p>
      </aside>
    </div>`;
  const listEl = document.getElementById('hist-list');
  const draw = (q = '') => {
    const needle = q.trim().toLowerCase();
    const shown = needle ? videos.filter(v => (v.title || '').toLowerCase().includes(needle) || (v.author?.displayName || '').toLowerCase().includes(needle)) : videos;
    if (!shown.length) {
      listEl.innerHTML = emptyState('fa-history', needle ? tr({en:'No matches',de:'Keine Treffer'}) : t('empty_history_title'), needle ? tr({en:'Try another search term.',de:'Versuche einen anderen Suchbegriff.'}) : t('empty_history_desc'));
      return;
    }
    listEl.innerHTML = shown.map(v => `<div class="history-item" data-id="${v.id}" data-h-click="h_app_navigateTo_4448" data-hv-click="${nxHv(String(v.id))}">
        <div class="history-thumb">${v.thumbnailPath ? `<img src="${v.thumbnailPath}" alt="" loading="lazy" data-h-error="h_app_h_4449">` : `<div style="width:100%;height:100%;display:flex;align-items:center;justify-content:center;color:var(--text-muted)"><i class="fas fa-film"></i></div>`}</div>
        <div class="history-info">
          <h4>${escHtml(v.title)}</h4>
          <p>${escHtml(v.author?.displayName || v.authorName || '')}</p>
          <p>${formatViews(v.views)} ${t('view_count')} • ${timeAgo(v.createdAt)}</p>
        </div>
        <button class="hist-remove" title="${escHtml(tr({en:'Remove from watch history',de:'Aus Verlauf entfernen'}))}" data-h-click="h_app_stopPropagation_4455" data-hv-click="${nxHv(String(v.id))}" aria-label="${escHtml(tr({en:'Remove from watch history',de:'Aus Verlauf entfernen'}))}"><i class="fas fa-xmark"></i></button>
      </div>`).join('');
  };
  draw();
  document.getElementById('hist-search').addEventListener('input', e => draw(e.target.value));
  window._histVideos = videos;
  window._histDraw = () => { videos = window._histVideos; draw(document.getElementById('hist-search')?.value || ''); };
}

async function historyRemove(videoId) {
  try {
    await apiDel('/api/users/me/history/' + encodeURIComponent(videoId));
    window._histVideos = (window._histVideos || []).filter(v => v.id !== videoId);
    window._histDraw?.();
    showToast(tr({en:'Removed from watch history',de:'Aus dem Verlauf entfernt'}), 'success');
  } catch(e) { showToast(e.message, 'error'); }
}

async function historyClearAll() {
  if (!confirm(tr({en:'Clear your entire watch history? This cannot be undone.',de:'Gesamten Verlauf löschen? Das kann nicht rückgängig gemacht werden.'}))) return;
  try {
    await apiDel('/api/users/me/history');
    window._histVideos = [];
    window._histDraw?.();
    showToast(tr({en:'Watch history cleared',de:'Verlauf gelöscht'}), 'success');
  } catch(e) { showToast(e.message, 'error'); }
}

async function historyTogglePause(forceValue) {
  if (!currentUser) return;
  const next = typeof forceValue === 'boolean' ? forceValue : !currentUser.privacySettings?.historyPaused;
  try {
    const r = await apiPost('/api/users/me/history/pause', { paused: next });
    currentUser.privacySettings = { ...(currentUser.privacySettings || {}), historyPaused: r.historyPaused };
    try { localStorage.setItem('nxd_user', JSON.stringify(currentUser)); } catch {}
    showToast(r.historyPaused ? tr({en:'Watch history paused',de:'Verlauf pausiert'}) : tr({en:'Watch history turned on',de:'Verlauf aktiviert'}), 'success');
    if (document.getElementById('page-history')?.style.display !== 'none' && document.getElementById('hist-list')) renderHistoryPage();
    return r.historyPaused;
  } catch(e) { showToast(e.message, 'error'); }
}
