// ==================== POSTS PAGE ====================
async function renderPostsPage() {
  const el = document.getElementById('page-posts');
  el.innerHTML = `<div class="page-header"><h2>${t('page_posts')}</h2></div>
    <div class="feed-container">
      ${currentUser ? `<div class="create-post-bar" data-h-click="h_app_openModal_4522">
        <div style="cursor:default;flex-shrink:0;display:flex;align-items:center">
          ${buildAvatarHtml(currentUser, 40, {})}
        </div>
        <input type="text" placeholder="${t('post_share_placeholder')}" readonly style="cursor:pointer">
      </div>` : ''}
      <div id="posts-feed"><div class="spinner" style="margin:40px auto;display:block"></div></div>
    </div>`;
  try {
    const posts = await apiGet('/api/posts');
    const feed = document.getElementById('posts-feed');
    if (!posts.length) { feed.innerHTML = emptyState('fa-images', t('empty_posts_title'), t('empty_posts_desc')); return; }
    // Algorithm: score posts by engagement + recency
    function scorePost(p) {
      const likes    = p.likes?.length    || 0;
      const comments = p.commentCount     || p.comments?.length || 0;
      const age      = Date.now() - new Date(p.createdAt || 0).getTime();
      const hourAge  = age / 3_600_000;
      const decay    = Math.pow(0.5, hourAge / 24); // half-life 24h
      const isSubbed = currentUser && (p.author?.isSubscribed || false);
      return (likes * 3 + comments * 5) * decay + (isSubbed ? 30 : 0);
    }
    const sorted = [...posts].sort((a, b) => scorePost(b) - scorePost(a));
    feed.innerHTML = '';
    sorted.forEach(p => feed.appendChild(createPostCard(p)));
  } catch {}
}

function createPostCard(p) {
  const div = document.createElement('div');
  div.className = 'post-card';
  const authorInitial = (p.author?.displayName || p.author?.username || '?')[0].toUpperCase();
  const isLiked = currentUser && p.likes?.includes(currentUser.id);
  const imgGrid = p.images?.length ? `<div class="post-images ${['','one','two','three'][Math.min(p.images.length, 3)]}">${p.images.slice(0,4).map(img => `<img src="${img}" alt="" loading="lazy">`).join('')}</div>` : '';
  div.innerHTML = `
    <div class="post-header">
      <div style="cursor:pointer;display:flex;align-items:center;gap:8px" data-h-click="h_app_navigateTo_4556" data-hv-click="${nxHv(String(p.author?.id))}">
        ${buildAvatarHtml(p.author, 44, { click: () => navigateTo('channel', p.author?.id) })}
        <div>
          <div class="post-author-name">${escHtml(p.author?.displayName || p.author?.username || t('label_unknown'))}</div>
          <div class="post-time">${timeAgo(p.createdAt)}</div>
        </div>
      </div>
    </div>
    ${p.text ? `<p class="post-text">${escHtml(p.text)}</p>` : ''}
    ${imgGrid}
    ${p.poll ? buildPollCard(p) : ''}
    <div class="post-actions" style="margin-top:12px">
      <span class="post-action ${isLiked ? 'active' : ''}" data-h-click="h_app_likePost_4570" data-hv-click="${nxHv(String(p.id))}">
        <i class="fas fa-heart"></i> <span class="like-count">${p.likes?.length || 0}</span>
      </span>
      <span class="post-action" data-h-click="h_app_togglePostComments_4571" data-hv-click="${nxHv(String(p.id))}">
        <i class="fas fa-comment"></i> ${t('post_comment_btn')}
      </span>
      <span class="post-action" data-h-click="h_app_sharePost_4574" data-hv-click="${nxHv(String(p.id), String(escJs(p.text||'Norynex Beitrag')))}">
        <i class="fas fa-share"></i> ${t('share')}
      </span>
    </div>
    <div class="post-comments-section" id="post-comments-${p.id}" style="display:none;margin-top:12px;border-top:1px solid var(--border-light);padding-top:12px"></div>`;
  return div;
}

async function likePost(postId, el) {
  if (!currentUser) { openAuthModal('login'); return; }
  try {
    const data = await apiPost(`/api/posts/${postId}/like`);
    el.classList.toggle('active', data.liked);
    el.querySelector('.like-count').textContent = data.count;
  } catch {}
}

async function togglePostComments(postId, postCard) {
  const section = postCard.querySelector(`#post-comments-${postId}`);
  if (!section) return;
  const isOpen = section.style.display !== 'none';
  section.style.display = isOpen ? 'none' : 'block';
  if (!isOpen) {
    section.innerHTML = `<div class="spinner" style="display:block;margin:12px auto"></div>`;
    try {
      const comments = await apiGet(`/api/posts/${postId}/comments`);
      section.innerHTML = `
        <div id="post-comment-list-${postId}" style="display:flex;flex-direction:column;gap:8px;margin-bottom:12px">
          ${comments.length ? comments.map(c => `
            <div style="display:flex;gap:8px;align-items:flex-start" id="post-cmt-${c.id}">
              <div style="flex-shrink:0;cursor:pointer" data-h-click="h_app_navigateTo_4605" data-hv-click="${nxHv(String(c.authorId))}">${buildAvatarHtml({ id: c.authorId, avatar: c.authorAvatar, displayName: c.authorName }, 30, { noVideo: true })}</div>
              <div style="flex:1;background:var(--bg-secondary);border-radius:10px;padding:8px 12px">
                <div style="display:flex;align-items:center;justify-content:space-between">
                  <span style="font-weight:600;font-size:12px;cursor:pointer" data-h-click="h_app_navigateTo_4606" data-hv-click="${nxHv(String(c.authorId))}">${escHtml(c.authorName||t('label_anonymous'))}</span>
                  <div style="display:flex;align-items:center;gap:6px">
                    <span style="font-size:11px;color:var(--text-muted)">${timeAgo(c.createdAt)}</span>
                    ${(currentUser && (currentUser.id === c.authorId || currentUser.isAdmin)) ? `<button data-h-click="h_app_deletePostComment_4612" data-hv-click="${nxHv(String(postId), String(c.id))}" style="background:none;border:none;color:var(--text-muted);cursor:pointer;padding:2px 4px;border-radius:4px;font-size:11px;transition:color 0.15s" data-h-mouseover="h_app_h_4612" data-h-mouseout="h_app_var_4612" aria-label="Löschen"><i class="fas fa-trash"></i></button>` : ''}
                  </div>
                </div>
                <p style="margin:4px 0 0;font-size:13px">${linkifyText(c.text||c.content||'')}</p>
              </div>
            </div>`).join('') : `<p style="font-size:13px;color:var(--text-muted);text-align:center">${t('no_comments')}</p>`}
        </div>
        <div style="display:flex;gap:8px;align-items:center;position:relative">
          <input type="text" id="post-comment-input-${postId}" placeholder="${currentUser ? t('comment_placeholder') : t('login_to_comment')}" ${!currentUser ? 'readonly data-h-click="h_app_openAuthModal_4620"' : 'data-h-input="h_app_handleMentionInput_4620" data-h-keydown="h_app_handleMentionKeydown_4620"'}
            style="flex:1;background:var(--bg-secondary);border:1px solid var(--border);border-radius:20px;padding:8px 14px;color:var(--text-primary);font-size:13px;outline:none">
          <button data-h-click="h_app_submitPostComment_4620" data-hv-click="${nxHv(String(postId))}" style="width:34px;height:34px;border-radius:50%;background:var(--purple-main);border:none;color:white;cursor:pointer;flex-shrink:0" aria-label="Senden"><i class="fas fa-paper-plane" style="font-size:12px"></i></button>
        </div>`;
      // Enter key
      section.querySelector(`#post-comment-input-${postId}`)?.addEventListener('keydown', e => {
        if (e.key === 'Enter' && !document.getElementById('mention-dropdown')) submitPostComment(postId);
      });
    } catch(e) { section.innerHTML = `<p style="color:var(--text-muted);font-size:13px">${t('loading_error')}</p>`; }
  }
}

async function submitPostComment(postId) {
  if (!currentUser) { openAuthModal('login'); return; }
  const input = document.getElementById(`post-comment-input-${postId}`);
  const text = input?.value.trim();
  if (!text) return;
  try {
    await apiPost(`/api/posts/${postId}/comments`, { text });
    input.value = '';
    // Reload comments inline without closing
    const section = document.getElementById(`post-comments-${postId}`);
    if (section) {
      const postCard = section.closest('.post-card');
      if (postCard) {
        // Close and reopen to reload
        section.style.display = 'none';
        await togglePostComments(postId, postCard);
      }
    }
  } catch(e) { showToast(e.message, 'error'); }
}

async function deletePostComment(postId, commentId) {
  if (!currentUser) return;
  try {
    await apiDel(`/api/posts/${postId}/comments/${commentId}`);
    // Remove comment from DOM immediately
    const el = document.getElementById(`post-cmt-${commentId}`);
    if (el) { el.style.opacity='0'; el.style.transition='opacity 0.2s'; setTimeout(()=>el.remove(),200); }
    showToast(t('comment_deleted'), 'success');
  } catch(e) { showToast(e.message||t('error_generic'), 'error'); }
}

function sharePost(postId, text) {
  const url = window.location.origin + '/?post=' + postId;
  const existing = document.getElementById('share-menu-overlay');
  if (existing) existing.remove();
  const overlay = document.createElement('div');
  overlay.id = 'share-menu-overlay';
  overlay.style.cssText = 'position:fixed;inset:0;z-index:9999;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,0.6)';
  const encodedUrl = encodeURIComponent(url);
  const encodedTitle = encodeURIComponent(text.slice(0,80));
  overlay.innerHTML = `
    <div style="background:var(--bg-card);border-radius:var(--radius-lg);padding:24px;min-width:320px;max-width:90vw;box-shadow:0 20px 60px rgba(0,0,0,0.5);border:1px solid var(--border-light)">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:20px">
        <h3 style="margin:0;font-size:18px"><i class="fas fa-share-alt" style="color:var(--purple-light);margin-right:8px"></i>${t('share_title')}</h3>
        <button id="share-close-btn" style="background:none;border:none;color:var(--text-muted);font-size:20px;cursor:pointer" aria-label="Schließen"><i class="fas fa-times"></i></button>
      </div>
      <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:20px">
        <a href="https://wa.me/?text=${encodedTitle}%20${encodedUrl}" target="_blank" class="share-btn-item" style="display:flex;flex-direction:column;align-items:center;gap:8px;padding:14px;background:var(--bg-secondary);border-radius:12px;text-decoration:none;color:var(--text-primary);border:1px solid var(--border-light);cursor:pointer;font-size:12px;font-weight:600">
          <i class="fab fa-whatsapp" style="font-size:24px;color:#25D366"></i><span>WhatsApp</span>
        </a>
        <a href="https://twitter.com/intent/tweet?text=${encodedTitle}&url=${encodedUrl}" target="_blank" class="share-btn-item" style="display:flex;flex-direction:column;align-items:center;gap:8px;padding:14px;background:var(--bg-secondary);border-radius:12px;text-decoration:none;color:var(--text-primary);border:1px solid var(--border-light);cursor:pointer;font-size:12px;font-weight:600">
          <i class="fab fa-twitter" style="font-size:24px;color:#1DA1F2"></i><span>X / Twitter</span>
        </a>
        <button id="share-copy-btn" class="share-btn-item" style="display:flex;flex-direction:column;align-items:center;gap:8px;padding:14px;background:var(--bg-secondary);border-radius:12px;border:1px solid var(--border-light);cursor:pointer;font-size:12px;font-weight:600;color:var(--text-primary);font-family:inherit">
          <i class="fas fa-link" style="font-size:24px;color:var(--purple-light)"></i><span>${t('share_copy_link')}</span>
        </button>
      </div>
      <div style="display:flex;gap:8px;background:var(--bg-secondary);border-radius:8px;padding:8px;border:1px solid var(--border-light)">
        <input type="text" value="${escHtml(url)}" readonly style="flex:1;background:none;border:none;color:var(--text-secondary);font-size:12px;outline:none">
        <button id="share-copy-btn2" style="background:var(--purple-main);border:none;color:white;padding:6px 12px;border-radius:6px;cursor:pointer;font-size:12px;font-weight:600" aria-label="Kopieren"><i class="fas fa-copy"></i></button>
      </div>
    </div>`;
  overlay.addEventListener('click', e => { if (e.target === overlay) overlay.remove(); });
  document.body.appendChild(overlay);
  document.getElementById('share-close-btn').addEventListener('click', () => overlay.remove());
  document.getElementById('share-copy-btn').addEventListener('click', () => { navigator.clipboard.writeText(url); showToast('Link kopiert!','success'); overlay.remove(); });
  document.getElementById('share-copy-btn2').addEventListener('click', () => { navigator.clipboard.writeText(url); showToast('Link kopiert!','success'); });
}
