async function settingsLogoutAll() {
  if (!confirm(tr({en:'Sign out on all other devices?',de:'Auf allen anderen Geräten abmelden?'}))) return;
  try {
    const r = await apiPost('/api/users/me/logout-all', {});
    if (r.token) {
      localStorage.setItem('nxd_token', r.token);
      try { saveAccountToList(r.token, currentUser); } catch {}
    }
    showToast(tr({en:'Signed out on all other devices',de:'Auf allen anderen Geräten abgemeldet'}), 'success');
  } catch(e) { showToast(e.message, 'error'); }
}

async function settingsDownloadData(btn) {
  if (btn) { btn.disabled = true; btn.textContent = '…'; }
  try {
    const res = await fetch(API + '/api/users/me/data-export', { headers: { Authorization: 'Bearer ' + localStorage.getItem('nxd_token') } });
    if (!res.ok) throw new Error((await res.json().catch(() => ({}))).error || 'Fehler');
    const blob = await res.blob();
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = `norynex-daten-${currentUser?.username || 'export'}.json`;
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(() => URL.revokeObjectURL(a.href), 2000);
  } catch(e) { showToast(e.message, 'error'); }
  finally { if (btn) { btn.disabled = false; btn.textContent = tr({en:'Download',de:'Herunterladen'}); } }
}

async function settingsClearCache() {
  try {
    if (window.caches) { const keys = await caches.keys(); await Promise.all(keys.map(k => caches.delete(k))); }
    if (navigator.serviceWorker) { const regs = await navigator.serviceWorker.getRegistrations(); await Promise.all(regs.map(r => r.update().catch(() => {}))); }
    Object.keys(localStorage).filter(k => k.startsWith('nxd_locale_')).forEach(k => localStorage.removeItem(k));
    showToast(tr({en:'Cache cleared – reloading…',de:'Cache geleert – lade neu…'}), 'success');
    setTimeout(() => location.reload(), 800);
  } catch(e) { showToast(e.message, 'error'); }
}

// Setzt den Push-Toggle-Schalter auf den tatsächlichen Browser-Abo-Status statt
// nur auf einen gespeicherten Wunsch – falls der Nutzer die Berechtigung z.B.
// direkt im Browser widerrufen hat, zeigt der Schalter das korrekt an.
async function _refreshPushToggleUI() {
  const toggle = document.getElementById('push-notif-toggle');
  if (!toggle) return;
  const status = await getPushSubscriptionStatus();
  if (status === 'unsupported') {
    // settingRow-Zeile ausblenden statt einen nutzlosen Schalter zu zeigen
    // (z.B. iOS Safari außerhalb des Homescreens)
    const row = toggle.closest('.st-row') || toggle.closest('div[style*="justify-content:space-between"]');
    if (row) row.style.display = 'none';
    return;
  }
  toggle.checked = status === 'subscribed';
  updateToggleStyle(toggle);
}
