// Load balance in settings
async function loadSettingsBalance() {
  const el = document.getElementById('settings-balance-display');
  if (!el || !currentUser) return;
  try {
    const { balance } = await apiGet('/api/balance');
    el.textContent = '€' + balance.toFixed(2) + ' ' + (tr({en:'available',de:'verfügbar'}));
  } catch { el.textContent = ''; }
}
