// ==================== CHANNEL PAGE ====================
async function renderChannelPage(userId) {
  const el = document.getElementById('page-channel');
  if (!userId) return;
  el.innerHTML = `<div class="flex-center" style="height:300px"><div class="spinner"></div></div>`;
  try {
    // userId may be an actual ID, a username, or a channelUrl (e.g. from #@handle links) —
    // resolve the user first, then use their real ID for the videos/posts lookups.
    const user = await apiGet(`/api/users/${userId}`);
    // Adresse auf den lesbaren Kanalnamen umstellen (/channel/<username> statt interner ID)
    if (currentPage === 'channel' && user && user.username) {
      nxReplaceRoute('channel/' + user.username);
      nxSetMeta({ title: user.displayName || user.username, description: user.bio || `Videos und Shorts von ${user.displayName || user.username} auf Norynex.` });
    }
    const [videos, posts] = await Promise.all([
      apiGet(`/api/videos?authorId=${user.id}`),
      apiGet(`/api/posts?authorId=${user.id}`)
    ]);
    const isSubscribed = currentUser && (user.isSubscribed || false);
    const authorInitial = (user.displayName || user.username)[0].toUpperCase();
    const isMe = currentUser?.id === user.id;
    el.innerHTML = `
      <div class="channel-banner">
        ${user.videoBanner
          ? `<video src="${user.videoBanner}" autoplay loop muted playsinline style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;display:block"></video>`
          : (user.banner ? `<img src="${user.banner}" alt="">` : '')}
      </div>
      <div class="channel-header">
        <div class="channel-avatar-wrap" style="position:relative;display:inline-block">
          ${buildAvatarHtml(user, 92, {})}
        </div>
        <div class="channel-info" style="flex:1">
          <div class="channel-name">${escHtml(user.displayName || user.username)}${verifiedBadge(user, 18)}</div>
          <div class="channel-handle">@${escHtml(user.channelUrl || user.username)}</div>
          <div style="margin-top:4px"><a href="${window.location.origin}/channel/${encodeURIComponent(user.username)}" target="_blank" style="font-size:12px;color:var(--purple-light);text-decoration:none">${window.location.host}/channel/${escHtml(user.username)} <i class="fas fa-external-link-alt" style="font-size:10px"></i></a></div>
          <div class="channel-stats">${formatViews(user.subscriberCount || 0)} ${t('subscribers_label')} • ${user.videoCount || videos.length} ${t('stat_uploads')}</div>
          ${user.bio ? `<p style="font-size:13px;color:var(--text-secondary);margin-top:8px;max-width:500px">${escHtml(user.bio)}</p>` : ''}
        </div>
        <div style="display:flex;gap:8px;align-items:center;padding-bottom:8px">
          ${isMe
            ? `<button class="btn-secondary" data-action="nxSetHash|navigateTo" data-args="[[&quot;#studio/channel&quot;], [&quot;studio&quot;]]"><i class="fas fa-tools"></i> Studio</button>`
            : `<button class="subscribe-btn ${isSubscribed ? 'subscribed' : ''}" id="sub-btn-${user.id}" data-action="toggleSubscribe" data-args="${nxA(String(user.id))}">${isSubscribed ? 'Abonniert' : 'Abonnieren'}</button>
               <button class="bell-btn" data-action="toggleBell" data-args="${nxA(String(user.id))}" aria-label="Benachrichtigungen"><i class="fas fa-bell"></i></button>
               ${currentUser ? `
                 <!-- NORYNEX: gift premium hidden -->
                 ${_getPrivacySetting(user, 'allowMessages') !== false && user.canDM !== false && !currentUser.under16 && !nxIsBlocked(user.id) ? `<button class="ch-msg-btn" data-action="openMessageModal" data-args="${nxA(String(user.id))}"><i class="far fa-paper-plane"></i> ${tr({en:'Message',de:'Nachricht'})}</button>` : ''}
                 <button class="ch-more-btn" data-action="nxChannelMenu" data-args="${nxA('$el', String(user.id), nxS(user.displayName || user.username))}" aria-label="${escHtml(tr({en:'More',de:'Mehr'}))}"><i class="fas fa-ellipsis"></i></button>
               ` : ''}`}
          ${user.isLive ? `<a href="#" data-action="navigateTo" data-args="${nxA('stream', String(user.id))}" class="btn-primary" style="font-size:13px"><span class="live-badge" style="position:relative;top:0;left:0">LIVE</span></a>` : ''}
        </div>
      </div>
      ${currentUser && !isMe && nxIsBlocked(user.id) ? `<div class="nx-blocked-banner"><i class="fas fa-ban"></i><div><strong>${tr({en:'You blocked this channel',de:'Du hast diesen Kanal blockiert'})}</strong><span>${tr({en:'Their videos, comments and messages are hidden for you.',de:'Videos, Kommentare und Nachrichten dieser Person werden dir nicht angezeigt.'})}</span></div><button class="st-btn" data-action="nxToggleBlock" data-args="${nxA(String(user.id), false)}">${tr({en:'Unblock',de:'Blockierung aufheben'})}</button></div>` : ''}
      ${user.contentHidden ? `<div class="ag-note" style="margin:16px"><i class="fas fa-lock"></i><div><b>${tr({en:'This account is private',de:'Dieses Konto ist privat'})}</b><span>${tr({en:'Only people this account follows can see its content.',de:'Nur Personen, denen dieses Konto folgt, sehen die Inhalte.'})}</span></div></div>` : ''}
      <div class="channel-tabs">
        <button class="channel-tab active" data-ctab="videos" data-action="switchChannelTab" data-args="[&quot;videos&quot;]">Videos (${videos.filter(v=>!v.isShort).length})</button>
        <button class="channel-tab" data-ctab="shorts" data-action="switchChannelTab" data-args="[&quot;shorts&quot;]">Shorts (${videos.filter(v=>v.isShort).length})</button>
        <button class="channel-tab" data-ctab="posts" data-action="switchChannelTab" data-args="[&quot;posts&quot;]">${t('tab_posts')} (${posts.length})</button>
        <button class="channel-tab" data-ctab="playlists" data-action="switchChannelTab" data-args="[&quot;playlists&quot;]">Playlists</button>
        <button class="channel-tab" data-ctab="about" data-action="switchChannelTab" data-args="[&quot;about&quot;]">Info</button>
      </div>
      ${(() => {
        if (!user.trailerVideoId) return '';
        const trailer = videos.find(v => v.id === user.trailerVideoId);
        if (!trailer) return '';
        return `<div class="channel-trailer-wrap" id="channel-trailer-${trailer.id}" data-action="navigateTo" data-args="${nxA('watch', String(trailer.id))}">
          <div class="channel-trailer-thumb">
            ${trailer.thumbnailPath
              ? `<img src="${trailer.thumbnailPath}" alt="${escHtml(trailer.title)}" data-h-error="h_app_h_5643">`
              : `<video src="${trailer.videoPath}" preload="metadata" muted></video>`}
            <div class="trailer-play-btn"><i class="fas fa-play"></i></div>
          </div>
          <div class="channel-trailer-info">
            <div class="channel-trailer-label"><i class="fas fa-play-circle"></i> Kanal-Trailer</div>
            <div class="channel-trailer-title">${escHtml(trailer.title)}</div>
            ${trailer.description ? `<div class="channel-trailer-desc">${escHtml(trailer.description.slice(0,120))}${trailer.description.length>120?'…':''}</div>` : ''}
          </div>
          <div class="channel-trailer-arrow"><i class="fas fa-chevron-right"></i></div>
        </div>`;
      })()}
      <div id="channel-tab-content"></div>`;

    window.__channelVideos = videos;
    window.__channelPosts = posts;
    window.__channelUser = user;
    switchChannelTab('videos');
  } catch(e) { el.innerHTML = `<p style="padding:40px;color:var(--text-muted)">${t('channel_not_found')}</p>`; }
}

function switchChannelTab(tab) {
  document.querySelectorAll('.channel-tab').forEach(t => t.classList.toggle('active', t.dataset.ctab === tab));
  const content = document.getElementById('channel-tab-content');
  const videos = window.__channelVideos || [];
  const posts = window.__channelPosts || [];
  const user = window.__channelUser || {};
  if (tab === 'videos') {
    const vids = videos.filter(v => !v.isShort);
    if (!vids.length) { content.innerHTML = emptyState('fa-film', tr({en:'No Videos',de:'Keine Videos'}), ''); return; }
    content.innerHTML = '<div class="video-grid"></div>';
    vids.forEach(v => content.querySelector('.video-grid').appendChild(createVideoCard(v)));
  } else if (tab === 'shorts') {
    const shorts = videos.filter(v => v.isShort);
    if (!shorts.length) { content.innerHTML = emptyState('fa-film', tr({en:'No Shorts',de:'Keine Shorts'}), ''); return; }
    content.innerHTML = '<div class="video-grid"></div>';
    shorts.forEach(v => content.querySelector('.video-grid').appendChild(createVideoCard(v)));
  } else if (tab === 'posts') {
    if (!posts.length) { content.innerHTML = emptyState('fa-images', t('empty_posts_title'), ''); return; }
    content.innerHTML = '<div class="feed-container" style="max-width:680px;margin:0 auto"></div>';
    const feed = content.querySelector('.feed-container');
    posts.forEach(p => feed.appendChild(createPostCard(p)));
  } else if (tab === 'playlists') {
    if (typeof nxRenderChannelPlaylists === 'function') nxRenderChannelPlaylists(content, user);
  } else if (tab === 'about') {
    content.innerHTML = `<div style="max-width:600px;padding:20px 0">
      <div style="background:var(--bg-card);border-radius:var(--radius-lg);padding:24px">
        ${user.bio ? `<div style="margin-bottom:20px"><h4 style="margin-bottom:8px;color:var(--text-muted);font-size:12px;text-transform:uppercase">${t('ch_description')}</h4><p style="color:var(--text-secondary)">${escHtml(user.bio)}</p></div>` : ''}
        ${user.pronouns ? `<div style="margin-bottom:16px"><h4 style="margin-bottom:4px;color:var(--text-muted);font-size:12px;text-transform:uppercase">${t('ch_pronouns')}</h4><p>${escHtml(user.pronouns)}</p></div>` : ''}
        ${user.links?.length ? `<div style="margin-bottom:16px"><h4 style="margin-bottom:8px;color:var(--text-muted);font-size:12px;text-transform:uppercase">Links</h4>${user.links.map(l => `<a href="#" data-action="openExternalLink" data-args="${nxA(nxS(l))}" data-prevent style="color:var(--purple-light);display:block;margin-bottom:4px;cursor:pointer"><i class="fas fa-external-link-alt" style="font-size:11px;margin-right:6px"></i>${escHtml(l)}</a>`).join('')}</div>` : ''}
        <div><h4 style="margin-bottom:4px;color:var(--text-muted);font-size:12px;text-transform:uppercase">${t('member_since')}</h4><p>${new Date(user.createdAt).toLocaleDateString(cl()==='de'?'de-DE':'en-US', {year:'numeric',month:'long'})}</p></div>
      </div>
    </div>`;
  }
}

// ==================== CREATOR CODE HELPERS ====================
function _creatorCodeApplyFormHtml(lang) {
  return `
    <div style="background:var(--bg-card);border:1px solid var(--border-light);border-radius:16px;padding:22px">
      <h4 style="margin:0 0 14px;font-size:14px;font-weight:700">${tr({en:'Apply for a Creator Code',de:'Creator-Code beantragen'})}</h4>
      <div class="form-group">
        <label>${tr({en:'Desired code (optional)',de:'Gewünschter Code (optional)'})}</label>
        <input type="text" id="cc-apply-code" placeholder="${tr({en:'e.g. YOURNAME10',de:'z.B. DEINNAME10'})}" maxlength="20" style="width:100%;text-transform:uppercase;font-family:monospace">
      </div>
      <div class="form-group">
        <label>${tr({en:'Message to the team (optional)',de:'Nachricht an das Team (optional)'})}</label>
        <textarea id="cc-apply-message" rows="3" maxlength="500" placeholder="${tr({en:'Tell us a bit about your channel and audience...',de:'Erzähl uns etwas über deinen Kanal und deine Community...'})}" style="width:100%;resize:vertical"></textarea>
      </div>
      <button data-action="submitCreatorCodeApplication" class="btn-primary" style="width:100%;margin-top:6px"><i class="fas fa-paper-plane"></i> ${tr({en:'Submit application',de:'Antrag absenden'})}</button>
    </div>`;
}

async function submitCreatorCodeApplication() {
  const requestedCode = document.getElementById('cc-apply-code')?.value.trim().toUpperCase() || '';
  const message = document.getElementById('cc-apply-message')?.value.trim() || '';
  try {
    await apiPost('/api/creator-codes/apply', { requestedCode, message });
    showToast(tr({en:'Application submitted!',de:'Antrag eingereicht!'}), 'success');
    switchStudio('creator-code', document.querySelector('.studio-nav a[data-studio="creator-code"]'));
  } catch(e) { showToast(e.message, 'error'); }
}

async function requestCreatorPayout() {
  const amount = document.getElementById('creator-payout-amount')?.value;
  const method = document.getElementById('creator-payout-method')?.value;
  const account = document.getElementById('creator-payout-account')?.value.trim();
  const note = document.getElementById('creator-payout-note')?.value.trim();
  if (!amount || parseFloat(amount) <= 0) { showToast(t('valid_amount') || 'Bitte gültigen Betrag angeben', 'error'); return; }
  if (!account) { showToast(tr({en:'Please enter a payout account',de:'Bitte Auszahlungskonto angeben'}), 'error'); return; }
  try {
    await apiPost('/api/creator-codes/payout-request', { amount: parseFloat(amount), method, account, note });
    showToast(tr({en:'Payout request sent!',de:'Auszahlungsantrag gesendet!'}), 'success');
    switchStudio('creator-code', document.querySelector('.studio-nav a[data-studio="creator-code"]'));
  } catch(e) { showToast(e.message, 'error'); }
}
