// ==================== CREATOR STUDIO ====================
async function renderStudioPage() {
  const el = document.getElementById('page-studio');
  if (!currentUser) {
    el.innerHTML = emptyState('fa-sign-in-alt', t('login_required'), '') + `<div style="text-align:center;margin-top:-20px"><button class="btn-primary" data-h-click="h_app_openAuthModal_5745">${t('login_btn')}</button></div>`;
    return;
  }
  el.innerHTML = `
    <div class="page-header"><h2><i class="fas fa-tools" style="color:var(--purple-light)"></i> ${t('studio_title')}</h2></div>
    <div class="studio-layout">
      <nav class="studio-nav">
        ${(() => {
          const groups = [
            ['studio_overview', [['dashboard','fa-gauge-high','studio_dashboard'],['analytics','fa-chart-line','studio_analytics']]],
            ['studio_group_content', [['videos','fa-film','studio_videos'],['content','fa-pen-to-square','studio_editor'],['subtitles','fa-closed-captioning','studio_subtitles'],['playlists','fa-list','studio_playlists'],['community','fa-newspaper','studio_community']]],
            ['studio_group_audience', [['comments','fa-comments','studio_comments'],['subscribers','fa-users','studio_subscribers']]],
            ['studio_group_channel', [['channel','fa-user-pen','studio_channel'],['stream','fa-broadcast-tower','studio_stream'],['notif-settings','fa-bell','studio_notif_settings']]],
            ['studio_group_earn', [['monetize','fa-coins','studio_monetize'],['creator-code','fa-user-tag','studio_creator_code']]],
            ['studio_group_help', [['nexa-help','fa-wand-magic-sparkles','studio_nexa_help'],['ads','fa-bullhorn','studio_ads']]],
          ];
          return groups.map(([gk, items]) => `<div class="studio-nav-group">${escHtml(t(gk))}</div>` +
            items.map(([id, icon, key]) => `<a href="#" data-studio="${id}" data-h-click="h_app_preventDefault_5762" data-hv-click="${nxHv(String(id))}"><i class="fas ${icon}"></i><span>${escHtml(t(key))}</span></a>`).join('')).join('');
        })()}
      </nav>
      <div class="studio-content" id="studio-panel"></div>
    </div>`;
  // Restore studio sub-tab from hash if present
  const studioHash = nxHash().replace('#', '');
  const studioMatch = studioHash.match(/^studio\/(.+)$/);
  const studioTab = studioMatch ? studioMatch[1].split('/')[0] : 'dashboard';
  const tabLink = el.querySelector(`.studio-nav a[data-studio="${studioTab}"]`) || el.querySelector('.studio-nav a');
  switchStudio(studioTab, tabLink);
}
