// ==================== STUDIO: Kommentar-Untertabs (Liste / Blockliste / Schnellantworten) ====================
async function switchCommentsSubtab(tab) {
  document.querySelectorAll('.comment-subtab').forEach(b => {
    const active = b.dataset.subtab === tab;
    b.style.background = active ? 'var(--purple-main)' : '';
    b.style.color = active ? '#fff' : '';
  });
  const box = document.getElementById('comments-subtab-content');
  if (!box) return;
  box.innerHTML = `<div class="spinner" style="margin:40px auto;display:block"></div>`;

  if (tab === 'list') {
    try {
      const myVideos = await apiGet(`/api/videos?authorId=${currentUser.id}`);
      let allComments = [];
      for (const v of myVideos.slice(0,20)) {
        try {
          const comments = await apiGet(`/api/videos/${v.id}/comments`);
          for (const c of (comments||[])) allComments.push({...c, videoTitle: v.title, videoId: v.id});
        } catch {}
      }
      allComments.sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));
      box.innerHTML = `
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:20px">
          <h3>${t('studio_comments')} (${allComments.length})</h3>
          <div style="font-size:13px;color:var(--text-muted)">${t('latest_first')}</div>
        </div>
        ${!allComments.length ? `<div style="text-align:center;padding:40px;color:var(--text-muted)"><i class="fas fa-comments" style="font-size:48px;margin-bottom:16px;display:block;opacity:0.3"></i><p>${t('studio_no_comments')}</p></div>` :
        allComments.map(c => `
          <div style="background:var(--bg-secondary);border-radius:12px;padding:14px;margin-bottom:10px">
            <div style="display:flex;gap:10px;align-items:flex-start">
              <div style="flex-shrink:0">${buildAvatarHtml({ id: c.authorId, avatar: c.authorAvatar, displayName: c.authorName }, 36, { noVideo: true })}</div>
              <div style="flex:1;min-width:0">
                <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px">
                  <div>
                    <span style="font-weight:600;font-size:13px">${escHtml(c.authorName||t('label_anonymous'))}</span>
                    <span style="font-size:11px;color:var(--text-muted);margin-left:8px">${new Date(c.createdAt).toLocaleDateString(cl()==='de'?'de-DE':'en-US')}</span>
                  </div>
                  <button data-h-click="h_app_deleteStudioComment_6666" data-hv-click="${nxHv(String(c.videoId), String(c.id))}" style="background:none;border:none;color:#ef4444;cursor:pointer;padding:4px 8px;border-radius:6px;font-size:12px" title="${t('studio_delete_comment')}" aria-label="${t('studio_delete_comment')}"><i class="fas fa-trash"></i></button>
                </div>
                <div style="font-size:14px;color:var(--text-secondary);margin-bottom:6px">${escHtml(c.text||c.content||'')}</div>
                <div style="font-size:11px;color:var(--text-muted)">
                  <i class="fas fa-film" style="margin-right:4px"></i>
                  <span style="cursor:pointer;color:var(--purple-light)" data-h-click="h_app_navigateTo_6670" data-hv-click="${nxHv(String(c.videoId))}">${escHtml(c.videoTitle)}</span>
                </div>
              </div>
            </div>
          </div>`).join('')}`;
    } catch { box.innerHTML = `<p style="color:var(--text-muted);padding:20px">${t('loading_error')}</p>`; }

  } else if (tab === 'blocklist') {
    try {
      const keywords = await apiGet('/api/users/me/blocked-keywords');
      const isEn = cl() === 'en';
      box.innerHTML = `
        <h3 style="margin-bottom:8px">${isEn?'Your blocked words':'Deine Blockierliste'}</h3>
        <p style="font-size:13px;color:var(--text-muted);margin-bottom:16px">${isEn?'Comments on your videos and posts containing these words are automatically rejected.':'Kommentare unter deinen Videos und Beiträgen mit diesen Wörtern werden automatisch abgelehnt.'}</p>
        <div style="display:flex;gap:8px;margin-bottom:16px">
          <input id="new-keyword-input" type="text" maxlength="100" placeholder="${isEn?'Add a word…':'Begriff hinzufügen…'}" style="flex:1;background:var(--bg-secondary);border:1px solid var(--border);border-radius:8px;padding:10px 12px;color:var(--text-primary);font-size:13px" data-h-keydown="h_app_if_6688">
          <button class="btn-primary" data-h-click="h_app_addCreatorKeyword_6688"><i class="fas fa-plus"></i> ${isEn?'Add':'Hinzufügen'}</button>
        </div>
        <div id="keyword-chip-list" style="display:flex;flex-wrap:wrap;gap:8px">
          ${!keywords.length ? `<p style="color:var(--text-muted);font-size:13px">${isEn?'No words blocked yet.':'Noch keine Begriffe gesperrt.'}</p>` :
          keywords.map(kw => `<span style="display:inline-flex;align-items:center;gap:6px;background:var(--bg-secondary);border:1px solid var(--border);border-radius:20px;padding:6px 8px 6px 14px;font-size:13px">${escHtml(kw)}<button data-h-click="h_app_removeCreatorKeyword_6693" data-hv-click="${nxHv(String(encodeURIComponent(kw)))}" style="background:none;border:none;color:#ef4444;cursor:pointer;padding:2px 6px" aria-label="Schließen"><i class="fas fa-times"></i></button></span>`).join('')}
        </div>`;
    } catch { box.innerHTML = `<p style="color:var(--text-muted);padding:20px">${t('loading_error')}</p>`; }

  } else if (tab === 'quickreplies') {
    try {
      const replies = await apiGet('/api/users/me/quick-replies');
      const isEn = cl() === 'en';
      box.innerHTML = `
        <h3 style="margin-bottom:8px">${isEn?'Quick replies':'Schnellantworten'}</h3>
        <p style="font-size:13px;color:var(--text-muted);margin-bottom:16px">${isEn?'Save one-click reply templates. Provide both language variants — the right one is picked automatically based on the comment language.':'Hinterlege Standardantworten für einen Klick. Beide Sprachvarianten angeben — die passende wird automatisch anhand der Kommentarsprache vorgeschlagen.'}</p>
        <div style="background:var(--bg-secondary);border-radius:12px;padding:14px;margin-bottom:20px">
          <div style="display:flex;gap:8px;flex-wrap:wrap">
            <input id="new-qr-de" type="text" maxlength="300" placeholder="${isEn?'German variant (e.g. "Danke!")':'Deutsche Variante (z.B. „Danke!“)'}" style="flex:1;min-width:180px;background:var(--bg-primary);border:1px solid var(--border);border-radius:8px;padding:10px 12px;color:var(--text-primary);font-size:13px">
            <input id="new-qr-en" type="text" maxlength="300" placeholder="${isEn?'English variant (e.g. "Thanks!")':'Englische Variante (z.B. „Thanks!“)'}" style="flex:1;min-width:180px;background:var(--bg-primary);border:1px solid var(--border);border-radius:8px;padding:10px 12px;color:var(--text-primary);font-size:13px">
          </div>
          <button class="btn-primary" style="margin-top:10px" data-h-click="h_app_addQuickReply_6707"><i class="fas fa-plus"></i> ${isEn?'Add':'Hinzufügen'}</button>
        </div>
        <div id="qr-list">
          ${!replies.length ? `<p style="color:var(--text-muted);font-size:13px">${isEn?'No quick replies yet.':'Noch keine Schnellantworten hinterlegt.'}</p>` :
          replies.map(r => `
            <div style="display:flex;gap:10px;align-items:center;background:var(--bg-secondary);border-radius:10px;padding:10px 14px;margin-bottom:8px">
              <div style="flex:1;min-width:0">
                <div style="font-size:13px"><span style="color:var(--text-muted);font-size:11px;text-transform:uppercase">DE</span> ${escHtml(r.textDe)}</div>
                <div style="font-size:13px;margin-top:2px"><span style="color:var(--text-muted);font-size:11px;text-transform:uppercase">EN</span> ${escHtml(r.textEn)}</div>
              </div>
              <button data-h-click="h_app_removeQuickReply_6717" data-hv-click="${nxHv(String(r.id))}" style="background:none;border:none;color:#ef4444;cursor:pointer;padding:4px 8px" aria-label="Löschen"><i class="fas fa-trash"></i></button>
            </div>`).join('')}
        </div>`;
    } catch { box.innerHTML = `<p style="color:var(--text-muted);padding:20px">${t('loading_error')}</p>`; }
  }
}

async function addCreatorKeyword() {
  const input = document.getElementById('new-keyword-input');
  const keyword = input?.value.trim();
  if (!keyword) return;
  try {
    await apiPost('/api/users/me/blocked-keywords', { keyword });
    input.value = '';
    switchCommentsSubtab('blocklist');
  } catch(e) { showToast(e.message, 'error'); }
}
async function removeCreatorKeyword(encodedKw) {
  try {
    await apiDel(`/api/users/me/blocked-keywords/${encodedKw}`);
    switchCommentsSubtab('blocklist');
  } catch(e) { showToast(e.message, 'error'); }
}

async function addQuickReply() {
  const textDe = document.getElementById('new-qr-de')?.value.trim();
  const textEn = document.getElementById('new-qr-en')?.value.trim();
  if (!textDe && !textEn) { showToast(tr({en:'Enter at least one variant',de:'Mindestens eine Variante eingeben'}), 'error'); return; }
  try {
    const data = await apiPost('/api/users/me/quick-replies', { textDe, textEn });
    currentUser.quickReplies = data.quickReplies;
    localStorage.setItem('nxd_user', JSON.stringify(currentUser));
    switchCommentsSubtab('quickreplies');
  } catch(e) { showToast(e.message, 'error'); }
}
async function removeQuickReply(id) {
  try {
    const data = await apiDel(`/api/users/me/quick-replies/${id}`);
    currentUser.quickReplies = data.quickReplies;
    localStorage.setItem('nxd_user', JSON.stringify(currentUser));
    switchCommentsSubtab('quickreplies');
  } catch(e) { showToast(e.message, 'error'); }
}

async function saveChannelSettings(e) {
  e.preventDefault();
  const form = new FormData();
  const fields = {
    displayName: 's-displayname',
    alias: 's-alias',
    bio: 's-bio',
    pronouns: 's-pronouns',
    channelUrl: 's-channelurl'
  };
  for (const [key, id] of Object.entries(fields)) {
    const el = document.getElementById(id);
    if (el) form.append(key, el.value);
  }
  const linksEl = document.getElementById('s-links');
  if (linksEl) {
    const links = linksEl.value.split('\n').filter(l => l.trim());
    form.append('links', JSON.stringify(links));
  }
  const avatarInput = document.getElementById('s-avatar');
  const bannerInput = document.getElementById('s-banner');
  if (avatarInput && avatarInput.files[0]) form.append('avatar', avatarInput.files[0]);
  if (bannerInput && bannerInput.files[0]) form.append('banner', bannerInput.files[0]);

  const btn = e.target.querySelector('button[type="submit"]');
  if (btn) { btn.disabled = true; btn.innerHTML = `<i class="fas fa-spinner fa-spin"></i> ${t('saving')}...`; }

  try {
    const token = localStorage.getItem('nxd_token');
    const res = await fetch('/api/users/me', {
      method: 'PUT',
      headers: { 'Authorization': `Bearer ${token}` },
      body: form
    });
    const data = await res.json();
    if (!res.ok) throw new Error(data.error || 'Fehler beim Speichern');
    // Kanal-Trailer wird jetzt über denselben Speichern-Knopf mitgespeichert (kein eigener Knopf mehr)
    const trailerSel = document.getElementById('trailer-video-select');
    if (trailerSel && trailerSel.value !== (trailerSel.dataset.initial || '')) {
      const tr_ = await apiPut('/api/users/me/trailer', { videoId: trailerSel.value || null });
      data.trailerVideoId = tr_.trailerVideoId;
    }
    currentUser = data;
    localStorage.setItem('nxd_user', JSON.stringify(data));
    renderAuthSection();
    showToast(''+t('channel_saved'), 'success');
    // Reload the channel settings panel to show updated data
    switchStudio('channel', document.querySelector('[data-studio="channel"]'));
  } catch(err) {
    showToast(err.message, 'error');
    if (btn) { btn.disabled = false; btn.innerHTML = `<i class="fas fa-save"></i> ${t('btn_save')}`; }
  }
}
// ─── Teil: client/app/240-sprach-auswahl.js ───


// ==================== SPRACH-AUSWAHL (ein Overlay für die ganze App) ====================
// Warum ein Overlay statt Dropdown: Die Einstellungs-Karten haben overflow:hidden → ein absolut
// positioniertes Menü wurde abgeschnitten. Flaggen-Emojis werden unter Windows als Buchstaben
// („DE") dargestellt und sind daher bewusst nicht mehr im Einsatz – stattdessen Sprachcode + Name.
function langMeta(code) {
  const list = (typeof SUPPORTED_LANGS !== 'undefined') ? SUPPORTED_LANGS : [];
  return list.find(l => l.code === code) || { code: code || 'de', name: code || 'Deutsch' };
}

function openLangPicker() {
  closeLangPicker();
  const cur = cl();
  const list = (typeof SUPPORTED_LANGS !== 'undefined') ? SUPPORTED_LANGS : [{ code: 'de', name: 'Deutsch' }, { code: 'en', name: 'English' }];
  const wrap = document.createElement('div');
  wrap.id = 'lang-picker';
  wrap.className = 'lang-picker-overlay';
  wrap.setAttribute('role', 'dialog');
  wrap.setAttribute('aria-modal', 'true');
  wrap.innerHTML = `
    <div class="lang-picker-panel">
      <div class="lang-picker-head">
        <strong>${escHtml(t('lang_pick'))}</strong>
        <button class="lang-picker-close" data-h-click="h_app_closeLangPicker_6840" aria-label="Close"><i class="fas fa-times"></i></button>
      </div>
      <div class="lang-picker-search"><i class="fas fa-search"></i><input id="lang-picker-input" type="text" autocomplete="off" placeholder="${escHtml(t('lang_search'))}" data-h-input="h_app_filterLangPicker_6843"></div>
      <p style="margin:0 14px 8px;font-size:12px;opacity:.7">${escHtml(tr({ en: 'Norynex is fully available in German and English. Other languages are partly translated (beta) – some texts appear in English.', de: 'Norynex gibt es vollständig auf Deutsch und Englisch. Andere Sprachen sind teilweise übersetzt (Beta) – manche Texte erscheinen auf Englisch.' }))}</p>
      <div class="lang-picker-list" id="lang-picker-list">
        ${list.map(l => `
          <button class="lang-item${l.code === cur ? ' active' : ''}" data-code="${l.code}" data-name="${escHtml(l.name.toLowerCase())}" data-h-click="h_app_pickLanguage_6847" data-hv-click="${nxHv(String(l.code))}" ${l.rtl ? 'dir="rtl"' : ''}>
            <span class="lang-code">${l.code.toUpperCase()}</span>
            <span class="lang-name">${escHtml(l.name)}${l.code !== 'de' && l.code !== 'en' ? ` <small class="lang-partial" style="opacity:.6;font-size:11px">${escHtml(tr({ en: 'partly translated', de: 'teilweise übersetzt' }))}</small>` : ''}</span>
            ${l.code === cur ? '<i class="fas fa-check lang-check"></i>' : ''}
          </button>`).join('')}
      </div>
    </div>`;
  wrap.addEventListener('pointerdown', e => { if (e.target === wrap) closeLangPicker(); });
  document.body.appendChild(wrap);
  document.body.classList.add('lang-picker-open');
  document.addEventListener('keydown', _langPickerKey);
  // Auf Touch-Geräten keinen Auto-Fokus (öffnet sonst sofort die Tastatur und verdeckt die Liste)
  if (!(typeof isTouchDevice === 'function' && isTouchDevice())) setTimeout(() => document.getElementById('lang-picker-input')?.focus(), 30);
  // Aktive Sprache in Sichtweite scrollen
  setTimeout(() => wrap.querySelector('.lang-item.active')?.scrollIntoView({ block: 'center' }), 40);
}

function _langPickerKey(e) { if (e.key === 'Escape') closeLangPicker(); }

function closeLangPicker() {
  document.getElementById('lang-picker')?.remove();
  document.body.classList.remove('lang-picker-open');
  document.removeEventListener('keydown', _langPickerKey);
}

function filterLangPicker(q) {
  q = (q || '').trim().toLowerCase();
  document.querySelectorAll('#lang-picker-list .lang-item').forEach(b => {
    b.style.display = (!q || b.dataset.name.includes(q) || b.dataset.code.includes(q)) ? '' : 'none';
  });
}

async function pickLanguage(code) {
  closeLangPicker();
  await applyAppLang(code);
}

function saveAppSetting(key, value) {
  localStorage.setItem(key, String(value));
  showToast("Einstellung gespeichert", "success");
  // Feed neu rendern, damit die Glücksrad-Buttons auf den Thumbnails sofort erscheinen/verschwinden
  if (key === 'nxd_wheel_enabled') {
    if (!value) { _wheelSelectedIds = []; _updateWheelBar(); }
    refreshCurrentPage();
  }
}

// ==================== GLÜCKSRAD (WHEEL OF FORTUNE) ====================
let _wheelSelectedIds = []; // manuell ausgewählte Video-IDs (Reihenfolge = Auswahlreihenfolge)
let _wheelSelectedCache = {}; // id -> video-Objekt (für die Leiste/das Rad, ohne erneuten Fetch)

function _wheelMaxManualPicks() {
  return (currentUser && (currentUser.isPremium || currentUser.isAdmin)) ? Infinity : 3;
}

// Klick auf den Glücksrad-Button einer Thumbnail-Kachel: Video zur manuellen Auswahl hinzufügen/entfernen
function toggleWheelPick(videoId, btnEl) {
  if (!currentUser) { openAuthModal('login'); return; }
  const idx = _wheelSelectedIds.indexOf(videoId);
  if (idx !== -1) {
    _wheelSelectedIds.splice(idx, 1);
    delete _wheelSelectedCache[videoId];
    if (btnEl) btnEl.classList.remove('active');
  } else {
    const max = _wheelMaxManualPicks();
    if (_wheelSelectedIds.length >= max) {
      showToast(tr({en:`You can pick up to ${max} videos (Premium: unlimited).`,de:`Du kannst bis zu ${max} Videos auswählen (Premium: unbegrenzt).`}), 'info');
      return;
    }
    _wheelSelectedIds.push(videoId);
    // Video-Daten für später merken: Karte aus dem DOM ableiten (Titel/Thumbnail liegen bereits im Feed vor)
    const card = btnEl ? btnEl.closest('.video-card') : null;
    if (card) {
      _wheelSelectedCache[videoId] = {
        id: videoId,
        title: card.querySelector('.video-meta-text h3')?.textContent || '',
        thumbnailPath: card.querySelector('.video-thumb img')?.getAttribute('src') || ''
      };
    } else {
      _wheelSelectedCache[videoId] = { id: videoId };
    }
    if (btnEl) btnEl.classList.add('active');
  }
  _updateWheelBar();
}

// Schwebende Leiste unten, die erscheint sobald mindestens 1 Video manuell gewählt wurde
function _updateWheelBar() {
  let bar = document.getElementById('wheel-float-bar');
  if (!_wheelSelectedIds.length) {
    if (bar) bar.remove();
    return;
  }
  if (!bar) {
    bar = document.createElement('div');
    bar.id = 'wheel-float-bar';
    bar.className = 'wheel-float-bar';
    document.body.appendChild(bar);
  }
  const max = _wheelMaxManualPicks();
  bar.innerHTML = `
    <div class="wheel-float-bar-inner">
      <div class="wheel-float-bar-count"><i class="fas fa-dharmachakra"></i> ${_wheelSelectedIds.length}${max === Infinity ? ' ∞' : '/' + max}</div>
      <button class="btn-secondary" data-h-click="h_app_clearWheelSelection_6949">${tr({en:'Clear',de:'Zurücksetzen'})}</button>
      <button class="btn-primary" data-h-click="h_app_openWheelModal_6950"><i class="fas fa-sync-alt"></i> ${tr({en:'Spin',de:'Drehen'})}</button>
    </div>`;
}

function clearWheelSelection() {
  document.querySelectorAll('.wheel-thumb-btn.active').forEach(b => b.classList.remove('active'));
  _wheelSelectedIds = [];
  _wheelSelectedCache = {};
  _updateWheelBar();
}

// Entfernt ein Video aus der manuellen Auswahl heraus aus dem Wheel-Modal (Liste dort neu rendern)
function removeWheelPickFromModal(videoId) {
  const idx = _wheelSelectedIds.indexOf(videoId);
  if (idx !== -1) _wheelSelectedIds.splice(idx, 1);
  delete _wheelSelectedCache[videoId];
  // Falls die zugehörige Thumbnail-Kachel noch im Feed sichtbar ist, Button-Zustand zurücksetzen
  document.querySelectorAll('.wheel-thumb-btn.active').forEach(b => {
    if ((b.getAttribute('data-hv-click') || '').includes(JSON.stringify(String(videoId)))) b.classList.remove('active');
  });
  _updateWheelBar();
  if (document.getElementById('wheel-modal')) switchWheelTab('manual');
}

// Öffnet den Auswahl-Dialog mit den drei Modi. defaultTab: 'manual' | 'subs' | 'recommended'
function openWheelModal(defaultTab) {
  if (!currentUser) { openAuthModal('login'); return; }
  document.getElementById('wheel-modal')?.remove();
  const isPremium = !!(currentUser.isPremium || currentUser.isAdmin);
  const tab = defaultTab || (_wheelSelectedIds.length ? 'manual' : 'subs');

  const overlay = document.createElement('div');
  overlay.id = 'wheel-modal';
  overlay.className = 'nxv-overlay';
  overlay.innerHTML = `
    <div class="nx-modal wh-modal" role="dialog" aria-modal="true" aria-labelledby="wh-title">
      <div class="nx-modal-head">
        <div>
          <h3 id="wh-title">${tr({en:'Wheel of Fortune',de:'Glücksrad'})}</h3>
          <p>${tr({en:'Choose where the videos come from, then spin.',de:'Wähle, woher die Videos kommen, und dreh das Rad.'})}</p>
        </div>
        <button class="nx-modal-x" data-h-click="h_app_getElementById_6990" aria-label="${escHtml(tr({en:'Close',de:'Schließen'}))}"><i class="fas fa-xmark"></i></button>
      </div>
      <div class="wh-tabs" id="wheel-tabs" role="tablist">
        <button class="wheel-tab-btn" data-wtab="manual" data-h-click="h_app_switchWheelTab_6992"><i class="fas fa-hand-pointer"></i> ${tr({en:'My picks',de:'Meine Auswahl'})}<span class="wh-count" id="wh-count-manual">${_wheelSelectedIds.length || ''}</span></button>
        <button class="wheel-tab-btn" data-wtab="subs" data-h-click="h_app_switchWheelTab_6995"><i class="fas fa-users"></i> ${tr({en:'Subscriptions',de:'Abos'})}</button>
        <button class="wheel-tab-btn" data-wtab="recommended" data-h-click="h_app_switchWheelTab_6996"><i class="fas fa-wand-magic-sparkles"></i> ${tr({en:'For you',de:'Für dich'})}${!isPremium ? ' <i class="fas fa-crown wh-crown"></i>' : ''}</button>
      </div>
      <div id="wheel-tab-content" class="wh-body"></div>
      <div class="nx-modal-foot">
        <span class="wh-foot-info" id="wh-foot-info"></span>
        <button class="st-btn" data-h-click="h_app_getElementById_6997">${t('btn_cancel')}</button>
        <button class="st-btn st-btn-primary" id="wheel-spin-trigger" data-h-click="h_app_startWheelSpinFromModal_7002"><i class="fas fa-rotate"></i> ${tr({en:'Spin',de:'Drehen'})}</button>
      </div>
    </div>`;
  document.body.appendChild(overlay);
  overlay.addEventListener('click', e => { if (e.target === overlay) overlay.remove(); });
  const onEsc = e => { if (e.key === 'Escape') { overlay.remove(); document.removeEventListener('keydown', onEsc); } };
  document.addEventListener('keydown', onEsc);
  switchWheelTab(tab);
}

let _wheelActiveTab = 'manual';
let _wheelTabVideos = { manual: [], subs: null, recommended: null };

function _wheelListHtml(list, removable) {
  return `<div class="wheel-pick-list">${list.map((v, i) => `
    <div class="wheel-pick-item">
      <span class="wh-idx">${i + 1}</span>
      <div class="wh-thumb">${v.thumbnailPath ? `<img src="${escHtml(v.thumbnailPath)}" alt="" loading="lazy" data-h-error="h_app_remove_7020">` : '<i class="fas fa-film"></i>'}</div>
      <span class="wh-title">${escHtml(v.title || '')}</span>
      ${removable ? `<button data-h-click="h_app_removeWheelPickFromModal_7022" data-hv-click="${nxHv(String(v.id))}" aria-label="${escHtml(tr({en:'Remove',de:'Entfernen'}))}"><i class="fas fa-xmark"></i></button>` : ''}
    </div>`).join('')}</div>`;
}
function _wheelEmpty(icon, title, text, action = '') {
  return `<div class="wh-empty"><div class="wh-empty-icon"><i class="fas ${icon}"></i></div><strong>${title}</strong><p>${text}</p>${action}</div>`;
}
function _wheelSetFoot(n) {
  const info = document.getElementById('wh-foot-info');
  const btn = document.getElementById('wheel-spin-trigger');
  if (info) info.textContent = n ? (n + ' ' + (n === 1 ? tr({en:'video',de:'Video'}) : tr({en:'videos',de:'Videos'}))) : '';
  if (btn) btn.disabled = !n;
}

async function switchWheelTab(tabName) {
  _wheelActiveTab = tabName;
  document.querySelectorAll('.wheel-tab-btn').forEach(b => b.classList.toggle('active', b.dataset.wtab === tabName));
  const content = document.getElementById('wheel-tab-content');
  if (!content) return;
  const isPremium = !!(currentUser?.isPremium || currentUser?.isAdmin);
  const cnt = document.getElementById('wh-count-manual'); if (cnt) cnt.textContent = _wheelSelectedIds.length || '';

  if (tabName === 'manual') {
    if (!_wheelSelectedIds.length) {
      content.innerHTML = _wheelEmpty('fa-dharmachakra', tr({en:'No videos picked yet',de:'Noch keine Videos ausgewählt'}), tr({en:'Tap the wheel icon on any video thumbnail to add it here.',de:'Tippe auf das Glücksrad-Symbol auf einer Video-Thumbnail, um es hier hinzuzufügen.'}));
      _wheelSetFoot(0);
      return;
    }
    const max = _wheelMaxManualPicks();
    const list = _wheelSelectedIds.map(id => _wheelSelectedCache[id] || { id });
    content.innerHTML = `<div class="wh-info">${tr({en:`Picked ${list.length}${max === Infinity ? '' : ' of ' + max}`,de:`${list.length}${max === Infinity ? '' : ' von ' + max} ausgewählt`})}${list.length === 1 ? ' · ' + tr({en:'add at least one more to make it exciting',de:'füge noch mindestens eins hinzu, damit es spannend wird'}) : ''}</div>` + _wheelListHtml(list, true);
    _wheelSetFoot(list.length);
    return;
  }

  const loading = () => { content.innerHTML = `<div class="wh-empty"><i class="fas fa-circle-notch fa-spin" style="font-size:20px;color:var(--text-muted)"></i></div>`; _wheelSetFoot(0); };

  if (tabName === 'subs') {
    loading();
    try {
      const data = await apiGet('/api/wheel/subscriptions');
      _wheelTabVideos.subs = data.videos || [];
      if (_wheelActiveTab !== 'subs') return;
      if (!_wheelTabVideos.subs.length) {
        content.innerHTML = _wheelEmpty('fa-users', tr({en:'Nothing new',de:'Nichts Neues'}), tr({en:'No new videos from your subscriptions in the last 48 hours.',de:'Keine neuen Videos deiner Abos in den letzten 48 Stunden.'}));
        return;
      }
      content.innerHTML = `<div class="wh-info">${tr({en:`Random videos from the last 48 h of your subscriptions (max ${isPremium?15:3})`,de:`Zufällige Videos aus den letzten 48 h deiner Abos (max. ${isPremium?15:3})`})}</div>` + _wheelListHtml(_wheelTabVideos.subs, false);
      _wheelSetFoot(_wheelTabVideos.subs.length);
    } catch(e) {
      content.innerHTML = _wheelEmpty('fa-triangle-exclamation', tr({en:'Could not load',de:'Konnte nicht geladen werden'}), escHtml(e.message));
    }
    return;
  }

  if (tabName === 'recommended') {
    if (!isPremium) {
      content.innerHTML = _wheelEmpty('fa-crown', tr({en:'Premium feature',de:'Premium-Funktion'}), tr({en:'Picks videos from the creators you watch the most.',de:'Wählt Videos von den Creatorn, die du am meisten schaust.'}), `<button class="st-btn st-btn-primary" data-h-click="h_app_getElementById_7078">${t('prem_activate')}</button>`);
      _wheelSetFoot(0);
      return;
    }
    loading();
    try {
      const data = await apiGet('/api/wheel/recommended');
      _wheelTabVideos.recommended = data.videos || [];
      if (_wheelActiveTab !== 'recommended') return;
      if (!_wheelTabVideos.recommended.length) {
        content.innerHTML = _wheelEmpty('fa-clock-rotate-left', tr({en:'Not enough history',de:'Noch zu wenig Verlauf'}), tr({en:'Watch a few more videos first.',de:'Schau dir zuerst noch ein paar Videos an.'}));
        return;
      }
      content.innerHTML = `<div class="wh-info">${tr({en:'Based on the creators you watch the most',de:'Basierend auf den Creatorn, die du am meisten schaust'})}</div>` + _wheelListHtml(_wheelTabVideos.recommended, false);
      _wheelSetFoot(_wheelTabVideos.recommended.length);
    } catch(e) {
      content.innerHTML = _wheelEmpty('fa-triangle-exclamation', tr({en:'Could not load',de:'Konnte nicht geladen werden'}), escHtml(e.message));
    }
  }
}

function startWheelSpinFromModal() {
  let list = [];
  if (_wheelActiveTab === 'manual') list = _wheelSelectedIds.map(id => _wheelSelectedCache[id]).filter(Boolean);
  else if (_wheelActiveTab === 'subs') list = _wheelTabVideos.subs || [];
  else if (_wheelActiveTab === 'recommended') list = _wheelTabVideos.recommended || [];

  if (!list.length) {
    showToast(tr({en:'No videos to spin yet.',de:'Noch keine Videos zum Drehen vorhanden.'}), 'error');
    return;
  }
  document.getElementById('wheel-modal')?.remove();
  runWheelSpin(list);
}

// ── Dreh-Sound: synthetischer "Tick"-Effekt per Web Audio API (im Projekt sind keine
// Audiodateien mehr eingebunden), leicht beschleunigend während des Drehens. ──
let _wheelAudioCtx = null;
function _wheelTick() {
  try {
    if (!_wheelAudioCtx) _wheelAudioCtx = new (window.AudioContext || window.webkitAudioContext)();
    const ctx = _wheelAudioCtx;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = 'square';
    osc.frequency.value = 320;
    gain.gain.setValueAtTime(0.08, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.08);
    osc.connect(gain); gain.connect(ctx.destination);
    osc.start(); osc.stop(ctx.currentTime + 0.08);
  } catch(e) {}
}

// Baut das Rad als SVG mit einem Segment pro Video (Thumbnail + Nummer), dreht 5-6 s
// mit Tick-Sound und zeigt danach das Ergebnis mit "Ansehen" / "Nochmal drehen".
function _wheelSvg(list, size) {
  const n = list.length, c = size / 2;
  const rimR = c - 2, r = c - 22;            // Außenring mit Lichtern, darin das Rad
  const slice = 360 / n;
  const palette = [['#a855f7','#7c3aed'], ['#ec4899','#be185d'], ['#3b82f6','#1d4ed8'], ['#f59e0b','#d97706'],
                   ['#10b981','#047857'], ['#f43f5e','#be123c'], ['#06b6d4','#0e7490'], ['#8b5cf6','#5b21b6']];
  const col = (i) => palette[(n % palette.length === 1 && i === n - 1 && n > 1) ? (i + 2) % palette.length : i % palette.length];
  const pt = (deg, rad) => { const a = (deg - 90) * Math.PI / 180; return [c + rad * Math.cos(a), c + rad * Math.sin(a)]; };
  let defs = `<radialGradient id="wh-shade" cx="50%" cy="50%" r="50%"><stop offset="0.35" stop-color="#000" stop-opacity="0"/><stop offset="1" stop-color="#000" stop-opacity="0.45"/></radialGradient>
    <linearGradient id="wh-rim" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#2a2238"/><stop offset="1" stop-color="#120e1a"/></linearGradient>`;
  let body = `<circle cx="${c}" cy="${c}" r="${rimR}" fill="url(#wh-rim)"/><circle cx="${c}" cy="${c}" r="${rimR - 1}" fill="none" stroke="rgba(255,255,255,0.12)" stroke-width="2"/>`;
  list.forEach((v, i) => {
    const a0 = i * slice, a1 = (i + 1) * slice, mid = a0 + slice / 2;
    const [x0, y0] = pt(a0, r), [x1, y1] = pt(a1, r);
    const d = n === 1 ? `M ${c} ${c - r} A ${r} ${r} 0 1 1 ${c - 0.01} ${c - r} Z` : `M ${c} ${c} L ${x0} ${y0} A ${r} ${r} 0 ${slice > 180 ? 1 : 0} 1 ${x1} ${y1} Z`;
    const [g0, g1] = col(i);
    defs += `<clipPath id="whc-${i}"><path d="${d}"/></clipPath><linearGradient id="whg-${i}" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="${g0}"/><stop offset="1" stop-color="${g1}"/></linearGradient>`;
    const [cx, cy] = n === 1 ? [c, c] : pt(mid, r * 0.56);
    const iw = n === 1 ? r * 2 : Math.max(r * 1.15, 150), ih = iw * 0.5625;
    body += `<g clip-path="url(#whc-${i})">
      <rect x="0" y="0" width="${size}" height="${size}" fill="url(#whg-${i})"/>
      ${v.thumbnailPath ? `<image href="${escHtml(v.thumbnailPath)}" x="${cx - iw / 2}" y="${cy - ih / 2}" width="${iw}" height="${ih}" preserveAspectRatio="xMidYMid slice" transform="rotate(${n === 1 ? 0 : mid} ${cx} ${cy})"/>
      <rect x="0" y="0" width="${size}" height="${size}" fill="url(#whg-${i})" opacity="0.28"/>` : ''}
    </g>`;
  });
  body += `<circle cx="${c}" cy="${c}" r="${r}" fill="url(#wh-shade)"/>`;
  if (n > 1) list.forEach((_, i) => { const [x, y] = pt(i * slice, r); body += `<line x1="${c}" y1="${c}" x2="${x}" y2="${y}" stroke="#fff" stroke-opacity="0.9" stroke-width="2.5" stroke-linecap="round"/>`; });
  body += `<circle cx="${c}" cy="${c}" r="${r}" fill="none" stroke="#fff" stroke-opacity="0.9" stroke-width="3"/>`;
  // Nummern als Plakette am Rand
  if (n <= 24) list.forEach((_, i) => {
    const [tx, ty] = n === 1 ? [c, c - r * 0.7] : pt(i * slice + slice / 2, r * 0.82);
    const rr = n > 12 ? 10 : 13;
    body += `<g transform="translate(${tx} ${ty})"><circle r="${rr}" fill="#fff"/><text text-anchor="middle" dominant-baseline="central" font-size="${n > 12 ? 11 : 13}" font-weight="900" fill="${col(i)[1]}" font-family="Outfit, system-ui, sans-serif">${i + 1}</text></g>`;
  });
  // Lichter im Außenring (blinken per CSS)
  const bulbs = Math.max(12, Math.min(28, n * 4));
  for (let k = 0; k < bulbs; k++) { const [bx, by] = pt(k * 360 / bulbs, c - 12); body += `<circle class="wh-bulb ${k % 2 ? 'b' : 'a'}" cx="${bx}" cy="${by}" r="3.6"/>`; }
  return `<svg viewBox="0 0 ${size} ${size}" width="100%" height="100%" aria-hidden="true"><defs>${defs}</defs>${body}</svg>`;
}

function runWheelSpin(videoList) {
  document.getElementById('wheel-spin-overlay')?.remove();
  const n = videoList.length;
  const winnerIndex = Math.floor(Math.random() * n);
  const reduce = document.documentElement.classList.contains('nx-reduce-motion');
  const spinDuration = reduce ? 600 : 5200 + Math.random() * 900;
  const slice = 360 / n;

  const overlay = document.createElement('div');
  overlay.id = 'wheel-spin-overlay';
  overlay.className = 'wh-spin-overlay';
  overlay.innerHTML = `
    <button class="nx-modal-x wh-spin-x" aria-label="${escHtml(tr({en:'Close',de:'Schließen'}))}"><i class="fas fa-xmark"></i></button>
    <div class="wh-spin-head">
      <span class="wh-spin-kicker">${tr({en:'Wheel of Fortune',de:'Glücksrad'})}</span>
      <h3 id="wh-spin-status">${tr({en:'Spinning…',de:'Wird gedreht…'})}</h3>
    </div>
    <div class="wh-stage">
      <div class="wh-pointer"><svg viewBox="0 0 40 52" width="40" height="52" aria-hidden="true"><defs><linearGradient id="wh-ptr" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#ffffff"/><stop offset="1" stop-color="#e9ddff"/></linearGradient></defs><path d="M5 8 Q5 3 10 3 H30 Q35 3 35 8 V17 Q35 20 33.5 22.5 L22.5 46 Q20 50 17.5 46 L6.5 22.5 Q5 20 5 17 Z" fill="url(#wh-ptr)" stroke="#7c3aed" stroke-width="2.5" stroke-linejoin="round"/><circle cx="20" cy="14" r="5" fill="#a855f7"/></svg></div>
      <div class="wh-disc" id="wheel-disc" style="transition:transform ${spinDuration}ms cubic-bezier(0.12,0.8,0.18,1)">${_wheelSvg(videoList, 400)}</div>
      <div class="wh-hub"><img src="/assets/icon-96.png" alt="" data-h-error="h_app_replaceWith_7192"></div>
    </div>
    <div class="wh-result" id="wh-result" hidden></div>
    <p class="wh-pool">${n} ${n === 1 ? tr({en:'video in the pool',de:'Video im Topf'}) : tr({en:'videos in the pool',de:'Videos im Topf'})}</p>`;
  document.body.appendChild(overlay);

  let done = false, timers = [];
  const close = () => { done = true; timers.forEach(clearTimeout); overlay.remove(); document.removeEventListener('keydown', onEsc); };
  const onEsc = e => { if (e.key === 'Escape') close(); };
  document.addEventListener('keydown', onEsc);
  overlay.querySelector('.wh-spin-x').addEventListener('click', close);

  const disc = document.getElementById('wheel-disc');
  const jitter = (Math.random() - 0.5) * slice * 0.6; // nicht immer exakt die Segmentmitte
  const target = winnerIndex * slice + slice / 2 + (n > 1 ? jitter : 0);
  const fullSpins = reduce ? 1 : 6 + Math.floor(Math.random() * 3);
  const finalRotation = fullSpins * 360 + (360 - target);
  requestAnimationFrame(() => requestAnimationFrame(() => { disc.style.transform = `rotate(${finalRotation}deg)`; }));

  // Tick-Sound, synchron zu den Segmentgrenzen (liest die echte Drehung aus)
  if (!reduce && n > 1) {
    let lastSeg = -1;
    const tickLoop = () => {
      if (done) return;
      const m = getComputedStyle(disc).transform;
      if (m && m !== 'none') {
        const [a, b] = m.slice(7, -1).split(',').map(Number);
        const deg = (Math.atan2(b, a) * 180 / Math.PI + 360) % 360;
        const seg = Math.floor(deg / slice);
        if (seg !== lastSeg) { if (lastSeg !== -1) _wheelTick(); lastSeg = seg; }
      }
      requestAnimationFrame(tickLoop);
    };
    requestAnimationFrame(tickLoop);
  }

  timers.push(setTimeout(() => {
    done = true;
    const winner = videoList[winnerIndex];
    document.getElementById('wh-spin-status').textContent = tr({en:'Your pick',de:'Dein Treffer'});
    overlay.classList.add('is-done');
    const res = document.getElementById('wh-result');
    res.hidden = false;
    res.innerHTML = `
      <div class="wh-result-thumb">${winner.thumbnailPath ? `<img src="${escHtml(winner.thumbnailPath)}" alt="">` : '<i class="fas fa-film"></i>'}<span>#${winnerIndex + 1}</span></div>
      <div class="wh-result-title">${escHtml(winner.title || '')}</div>
      <div class="wh-result-actions">
        ${n > 1 ? `<button class="st-btn" id="wh-again"><i class="fas fa-rotate"></i> ${tr({en:'Spin again',de:'Nochmal drehen'})}</button>` : ''}
        <button class="st-btn st-btn-primary" id="wh-watch"><i class="fas fa-play"></i> ${tr({en:'Watch now',de:'Jetzt ansehen'})}</button>
      </div>`;
    res.querySelector('#wh-watch').addEventListener('click', () => { close(); clearWheelSelection(); if (winner?.id) navigateTo('watch', winner.id); });
    res.querySelector('#wh-again')?.addEventListener('click', () => { close(); runWheelSpin(videoList); });
  }, spinDuration + 200));
}

