function checkDeleteConfirm(input) {
  const btn = document.getElementById("delete-confirm-btn");
  const err = document.getElementById("delete-error");
  const match = input.value.trim() === (currentUser?.username || "");
  if (btn) { btn.disabled = !match; btn.style.opacity = match ? "1" : "0.5"; btn.style.cursor = match ? "pointer" : "not-allowed"; }
  if (err) err.textContent = input.value && !match ? "Benutzername stimmt nicht \u00fcberein." : "";
}

async function doDeleteAccount() {
  if (!currentUser) return;
  const input = document.getElementById("delete-confirm-input");
  if (input?.value.trim() !== currentUser.username) return;
  const btn = document.getElementById("delete-confirm-btn");
  if (btn) { btn.disabled = true; btn.innerHTML = "<i class=\"fas fa-spinner fa-spin\"></i> Wird gel\u00f6scht..."; }
  try {
    const deletedId = currentUser.id;
    const _tk = localStorage.getItem('nxd_token');
    const _r = await fetch(API + '/api/users/me', { method: 'DELETE', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${_tk}` }, body: JSON.stringify({ confirmUsername: input.value.trim(), password: document.getElementById('delete-confirm-pw')?.value || '' }) });
    const _d = await _r.json().catch(() => ({}));
    if (!_r.ok) throw new Error(_d.error || 'Fehler beim Löschen');
    document.getElementById("delete-account-overlay")?.remove();
    localStorage.removeItem("nxd_token");
    localStorage.removeItem("nxd_user");
    // Remove from account switcher list
    removeAccountFromList(deletedId);
    currentUser = null;
    renderAuthSection();
    navigateTo("home");
    showToast("Konto wurde dauerhaft gelöscht.", "success");
  } catch(e) {
    showToast(e.message || "Fehler beim L\u00f6schen", "error");
    if (btn) { btn.disabled = false; btn.textContent = "Konto l\u00f6schen"; }
  }
}

