async function doChangePassword() {
  const isEn = cl() === 'en';
  const err = document.getElementById("cp-error");
  const btn = document.getElementById("cp-confirm-btn");
  const currentPassword = document.getElementById("cp-current")?.value || "";
  const newPassword = document.getElementById("cp-new")?.value || "";
  const newPassword2 = document.getElementById("cp-new2")?.value || "";
  if (err) err.textContent = "";
  if (!currentPassword || !newPassword || !newPassword2) {
    if (err) err.textContent = isEn ? "Please fill in all fields." : "Bitte alle Felder ausf\u00fcllen.";
    return;
  }
  { const c = nxPwCheck(newPassword, { username: currentUser?.username, email: currentUser?.email });
    if (!c.ok) { if (err) err.textContent = c.msg; return; } }
  if (newPassword !== newPassword2) {
    if (err) err.textContent = isEn ? "New passwords do not match." : "Die neuen Passw\u00f6rter stimmen nicht \u00fcberein.";
    return;
  }
  if (btn) { btn.disabled = true; btn.innerHTML = `<i class="fas fa-spinner fa-spin"></i> ${isEn ? 'Saving...' : 'Wird gespeichert...'}`; }
  try {
    const _cp = await apiPost("/api/auth/change-password", { currentPassword, newPassword });
    if (_cp?.token) { localStorage.setItem('nxd_token', _cp.token); try { saveAccountToList(_cp.token, currentUser); } catch {} }
    document.getElementById("change-password-overlay")?.remove();
    showToast(isEn ? "Password changed successfully." : "Passwort erfolgreich ge\u00e4ndert.", "success");
  } catch(e) {
    if (err) err.textContent = e.message || (isEn ? "Error changing password" : "Fehler beim \u00c4ndern des Passworts");
    if (btn) { btn.disabled = false; btn.textContent = isEn ? "Change password" : "Passwort \u00e4ndern"; }
  }
}

function applyAppTheme(theme) {
  if (typeof setTheme === 'function') setTheme(theme);
  // Re-render the settings page so the switch thumb, active state and the
  // row icon (moon/sun) all stay in sync with the new theme.
  if (typeof renderSettingsPage === 'function' && document.getElementById('page-settings')) renderSettingsPage();
  if (typeof showToast === 'function') showToast(typeof t === 'function' ? t('settings_saved') : 'Gespeichert!', 'success');
}

async function applyAppLang(lang) {
  // setLanguage() lädt die Sprachdatei zuerst und schaltet erst dann um → kein Mischtext.
  const ok = (typeof setLanguage === 'function') ? await setLanguage(lang) : false;
  if (ok === false) { showToast(t('lang_load_failed'), 'error'); return; }
  const m = langMeta(lang);
  const code = document.getElementById('lang-selected-code'); if (code) code.textContent = m.code.toUpperCase();
  const label = document.getElementById('lang-selected-label'); if (label) label.textContent = m.name;
}

