async function startStream(title) {
  if (!currentUser) { openAuthModal('login'); return false; }
  const me = await apiGet('/api/auth/me');
  let cfg = { minSubscribers: 50, limitEnabled: true };
  try { cfg = await apiGet('/api/streams/config'); } catch {}
  const subCount = (me.subscribers || []).length;
  if (cfg.limitEnabled && subCount < cfg.minSubscribers && !me.isAdmin) {
    showToast(`Du brauchst mindestens ${cfg.minSubscribers} Abonnenten um live zu gehen. Du hast ${subCount}/${cfg.minSubscribers}.`, 'error');
    return false;
  }
  try {
    let streamKey = '';
    try { streamKey = (await apiGet('/api/users/me/streamkey')).streamKey; } catch {}
    await apiPost('/api/streams/start', { title: title || '', key: streamKey });
    return true;
  } catch(e) { showToast(e.message, 'error'); return false; }
}
