// ==================== UPLOAD ====================
let videoFile = null;
let thumbnailFile = null;
let postImages = [];

function setupUploadModal() {
  // Upload tab switching
  document.querySelectorAll('.upload-tab').forEach(tab => {
    tab.addEventListener('click', () => switchUploadTab(tab.dataset.upload));
  });
  document.querySelectorAll('.utab').forEach(tab => {
    tab.addEventListener('click', () => switchUtab(tab.dataset.utab));
  });

  // Video drop zone
  const dz = document.getElementById('video-drop-zone');
  const fi = document.getElementById('video-file-input');
  if (dz && fi) {
    dz.addEventListener('click', () => fi.click());
    dz.addEventListener('dragover', (e) => { e.preventDefault(); dz.classList.add('dragover'); });
    dz.addEventListener('dragleave', () => dz.classList.remove('dragover'));
    dz.addEventListener('drop', (e) => { e.preventDefault(); dz.classList.remove('dragover'); if (e.dataTransfer.files[0]) handleVideoFile(e.dataTransfer.files[0]); });
    fi.addEventListener('change', () => { if (fi.files[0]) handleVideoFile(fi.files[0]); });
  }

  // Thumbnail
  const td = document.getElementById('thumb-drop');
  const ti = document.getElementById('thumb-input');
  if (td && ti) {
    td.addEventListener('click', () => ti.click());
    ti.addEventListener('change', () => {
      if (ti.files[0]) {
        thumbnailFile = ti.files[0];
        const reader = new FileReader();
        reader.onload = (e) => {
          const img = document.getElementById('thumb-preview-img');
          img.src = e.target.result; img.style.display = 'block';
          document.getElementById('thumb-placeholder').style.display = 'none';
        };
        reader.readAsDataURL(thumbnailFile);
      }
    });
  }

  // Post images
  const pd = document.getElementById('post-image-drop');
  const pi = document.getElementById('post-images-input');
  if (pd && pi) {
    pd.addEventListener('click', () => pi.click());
    pi.addEventListener('change', () => {
      postImages = Array.from(pi.files);
      const preview = document.getElementById('post-images-preview');
      preview.innerHTML = '';
      postImages.forEach(f => {
        const reader = new FileReader();
        reader.onload = e => { const img = document.createElement('img'); img.src = e.target.result; preview.appendChild(img); };
        reader.readAsDataURL(f);
      });
    });
  }
}

// Maximale Länge für Shorts: 3 Minuten (180 Sekunden)
const SHORTS_MAX_DURATION = 180;

function handleVideoFile(file) {
  videoFile = file;
  const dz = document.getElementById('video-drop-zone');
  dz.style.display = 'none';
  const prevSection = document.getElementById('video-preview-section');
  prevSection.style.display = 'block';
  const prevVideo = document.getElementById('video-preview');
  prevVideo.src = URL.createObjectURL(file);

  // Short-Erkennung: Hochformat (9:16-artig) UND innerhalb der Short-Höchstlänge (3 Minuten).
  // Ein Hochformat-Video über 3 Minuten wird nicht mehr automatisch als Short markiert.
  prevVideo.addEventListener('loadedmetadata', () => {
    const isPortrait = prevVideo.videoWidth > 0 && prevVideo.videoWidth < prevVideo.videoHeight;
    const withinShortLength = !prevVideo.duration || prevVideo.duration <= SHORTS_MAX_DURATION;
    const isShort = isPortrait && withinShortLength;
    const shortBadge = document.getElementById('short-badge');
    if (shortBadge) shortBadge.style.display = isShort ? 'inline-block' : 'none';

    // Auto-capture thumbnail if none selected yet
    if (!thumbnailFile) {
      // Seek to 10% into video for a good frame
      prevVideo.currentTime = Math.min(prevVideo.duration * 0.1, 5);
    }
  });
  
  prevVideo.addEventListener('seeked', () => {
    if (thumbnailFile) return; // user already chose a thumbnail
    try {
      const canvas = document.createElement('canvas');
      canvas.width = prevVideo.videoWidth || 1280;
      canvas.height = prevVideo.videoHeight || 720;
      const ctx = canvas.getContext('2d');
      ctx.drawImage(prevVideo, 0, 0, canvas.width, canvas.height);
      canvas.toBlob((blob) => {
        if (!blob) return;
        thumbnailFile = new File([blob], 'auto-thumbnail.jpg', { type: 'image/jpeg' });
        const img = document.getElementById('thumb-preview-img');
        if (img) { img.src = canvas.toDataURL('image/jpeg'); img.style.display = 'block'; }
        const placeholder = document.getElementById('thumb-placeholder');
        if (placeholder) placeholder.style.display = 'none';
      }, 'image/jpeg', 0.85);
    } catch(e) {}
  }, { once: false });
}



// ==================== MOBILE CAMERA RECORDING ====================
let _camStream = null;
let _camRecorder = null;
let _camChunks = [];
let _camFacingMode = 'user'; // front camera default
let _camFilter = 'none';
let _camTimerInterval = null;
let _camSeconds = 0;

function switchUploadSource(src) {
  const fileBtn = document.getElementById('src-file-btn');
  const camBtn = document.getElementById('src-camera-btn');
  const dropZone = document.getElementById('video-drop-zone');
  const previewSection = document.getElementById('video-preview-section');
  const camUI = document.getElementById('camera-record-ui');

  if (src === 'camera') {
    if (fileBtn) { fileBtn.style.background = 'var(--bg-secondary)'; fileBtn.style.border = '1px solid var(--border)'; fileBtn.style.color = 'var(--text-primary)'; fileBtn.className = 'btn-secondary'; }
    if (camBtn) { camBtn.style.background = 'var(--purple-main)'; camBtn.style.color = 'white'; camBtn.style.border = 'none'; }
    if (dropZone) dropZone.style.display = 'none';
    if (previewSection) previewSection.style.display = 'none';
    if (camUI) camUI.style.display = 'block';
    startCameraPreview();
  } else {
    if (fileBtn) { fileBtn.className = 'btn-primary'; fileBtn.style.cssText = ''; }
    if (camBtn) { camBtn.style.background = 'var(--bg-secondary)'; camBtn.style.color = 'var(--text-primary)'; camBtn.style.border = '1px solid var(--border)'; }
    if (dropZone) dropZone.style.display = '';
    if (camUI) camUI.style.display = 'none';
    stopCameraPreview();
  }
}

async function startCameraPreview() {
  try {
    if (_camStream) stopCameraPreview();
    _camStream = await navigator.mediaDevices.getUserMedia({
      video: { facingMode: _camFacingMode, width: { ideal: 1080 }, height: { ideal: 1920 } },
      audio: true
    });
    const preview = document.getElementById('camera-preview');
    if (preview) { preview.srcObject = _camStream; preview.style.filter = _camFilter === 'none' ? '' : _camFilter; }
  } catch(e) {
    showToast('Kamera konnte nicht gestartet werden: ' + e.message, 'error');
    switchUploadSource('file');
  }
}

function stopCameraPreview() {
  if (_camStream) { _camStream.getTracks().forEach(t => t.stop()); _camStream = null; }
  const preview = document.getElementById('camera-preview');
  if (preview) preview.srcObject = null;
}

async function flipCamera() {
  _camFacingMode = _camFacingMode === 'user' ? 'environment' : 'user';
  NXD.play('click');
  const btn = document.querySelector('[data-action="flipCamera"]');
  if (btn) NXD.pop(btn);
  await startCameraPreview();
}

function applyCameraFilter(filter) {
  _camFilter = filter;
  const preview = document.getElementById('camera-preview');
  if (preview) preview.style.filter = filter === 'none' ? '' : filter;
  // Update filter button styles
  document.querySelectorAll('.filter-btn').forEach(b => {
    const isActive = b.getAttribute('onclick').includes(filter === 'none' ? "'none'" : filter.replace(/[()%]/g, s => '\\' + s));
    b.style.background = isActive ? 'var(--purple-subtle)' : 'var(--bg-secondary)';
    b.style.borderColor = isActive ? 'var(--purple-main)' : 'var(--border)';
    b.style.color = isActive ? 'var(--purple-light)' : 'var(--text-secondary)';
  });
  NXD.play('click');
}

function toggleCameraRecording() {
  if (_camRecorder && _camRecorder.state === 'recording') {
    stopCameraRecording();
  } else {
    startCameraRecording();
  }
}

function startCameraRecording() {
  if (!_camStream) return;
  _camChunks = [];
  try {
    // Mit Audiospur einen Audio-Codec mit angeben – sonst fehlt der Ton in der Aufnahme
    const m = _bseGetMimeType(_camStream);
    const opts = m ? { mimeType: m } : {};
    _camRecorder = new MediaRecorder(_camStream, opts);
  } catch(e) { _camRecorder = new MediaRecorder(_camStream); }

  _camRecorder.ondataavailable = e => { if (e.data.size > 0) _camChunks.push(e.data); };
  _camRecorder.onstop = finalizeCameraRecording;
  _camRecorder.start(100);

  // UI update
  const btn = document.getElementById('record-btn');
  const icon = document.getElementById('record-icon');
  const status = document.getElementById('record-status');
  const timer = document.getElementById('record-timer');
  if (btn) { btn.style.background = 'linear-gradient(#dc2626,#dc2626)'; btn.style.transform = 'scale(1.1)'; }
  if (icon) { icon.className = 'fas fa-stop'; }
  if (status) status.textContent = 'Aufnahme läuft – tippe zum Stoppen';
  if (timer) { timer.style.display = 'block'; }
  NXD.play('mic_start');

  _camSeconds = 0;
  _camTimerInterval = setInterval(() => {
    _camSeconds++;
    const m = String(Math.floor(_camSeconds/60)).padStart(2,'0');
    const s = String(_camSeconds%60).padStart(2,'0');
    const t = document.getElementById('record-timer');
    if (t) t.innerHTML = `<i class="fas fa-circle" style="font-size:9px;animation:pulse 1s infinite"></i> ${m}:${s}`;
  }, 1000);
}

function stopCameraRecording() {
  if (_camRecorder) _camRecorder.stop();
  clearInterval(_camTimerInterval);
  const btn = document.getElementById('record-btn');
  const icon = document.getElementById('record-icon');
  const status = document.getElementById('record-status');
  const timer = document.getElementById('record-timer');
  if (btn) { btn.style.background = 'linear-gradient(#ef4444,#ef4444)'; btn.style.transform = ''; }
  if (icon) icon.className = 'fas fa-circle';
  if (status) status.textContent = 'Video wird vorbereitet...';
  if (timer) timer.style.display = 'none';
  NXD.play('mic_stop');
}

function finalizeCameraRecording() {
  const mimeType = _camRecorder?.mimeType || 'video/webm';
  const blob = new Blob(_camChunks, { type: mimeType });
  const ext = mimeType.includes('mp4') ? 'mp4' : 'webm';
  const file = new File([blob], `aufnahme_${Date.now()}.${ext}`, { type: mimeType });

  // Apply CSS filter to canvas for thumbnail if filter active
  handleVideoFile(file);

  // Switch back to file upload UI so user can see the video + fill in details
  const camUI = document.getElementById('camera-record-ui');
  const dropZone = document.getElementById('video-drop-zone');
  if (camUI) camUI.style.display = 'none';
  if (dropZone) dropZone.style.display = 'none'; // keep hidden, video preview shows

  const status = document.getElementById('record-status');
  if (status) status.textContent = 'Tippe den roten Knopf zum Aufnehmen';

  // Stop preview stream after recording done
  stopCameraPreview();
  showToast('Aufnahme fertig! Titel eingeben und hochladen.', 'success');
  NXD.play('upload');
}

// Stop camera when upload modal closes - hook via event
document.addEventListener('click', (e) => {
  if (e.target.closest('[onclick*="closeModal(\'upload-modal\')"]') || 
      (e.target.closest('.modal-close') && e.target.closest('.upload-modal-box'))) {
    stopCameraPreview();
  }
});

function switchUploadTab(tab) {
  document.querySelectorAll('.upload-tab').forEach(t => t.classList.toggle('active', t.dataset.upload === tab));
  document.getElementById('video-upload-form').style.display = tab === 'video' ? 'block' : 'none';
  document.getElementById('post-upload-form').style.display = tab === 'post' ? 'block' : 'none';
}

function switchUtab(tab) {
  document.querySelectorAll('.utab').forEach(t => t.classList.toggle('active', t.dataset.utab === tab));
  document.querySelectorAll('.utab-content').forEach(c => c.style.display = 'none');
  const el = document.getElementById(`utab-${tab}`);
  if (el) el.style.display = 'block';
}

function togglePaidPrice() {
  const cb = document.getElementById('vid-paid');
  const group = document.getElementById('paid-price-group');
  if (group) group.style.display = cb?.checked ? 'block' : 'none';
}

function toggleScheduleField() {
  const checked = document.getElementById('vid-schedule-toggle')?.checked;
  const wrap = document.getElementById('schedule-datetime-wrap');
  const label = document.getElementById('submit-video-label');
  if (wrap) wrap.style.display = checked ? 'block' : 'none';
  if (label) label.textContent = checked ? 'Termin planen' : 'Video hochladen';
  // Set minimum datetime to now
  if (checked) {
    const input = document.getElementById('vid-scheduled-at');
    if (input && !input.value) {
      const now = new Date(Date.now() + 60 * 60 * 1000); // +1 Stunde als Default
      input.value = now.toISOString().slice(0, 16);
    }
    input.min = new Date().toISOString().slice(0, 16);
  }
}

async function submitVideo() {
  if (!currentUser) { openModal('auth-modal'); return; }
  if (!videoFile) { showToast('Bitte wähle ein Video aus', 'error'); return; }
  const titleEl = document.getElementById('vid-title');
  const title = titleEl ? titleEl.value.trim() : '';
  if (!title) { showToast('Bitte gib einen Titel ein', 'error'); return; }

  const prevVideo = document.getElementById('video-preview');
  const isPortraitVid = prevVideo && prevVideo.videoWidth > 0 && prevVideo.videoWidth < prevVideo.videoHeight;
  const isShort = isPortraitVid && (!prevVideo.duration || prevVideo.duration <= SHORTS_MAX_DURATION);

  const form = new FormData();
  form.append('video', videoFile);
  if (thumbnailFile) form.append('thumbnail', thumbnailFile);
  form.append('title', title);
  form.append('description', document.getElementById('vid-desc')?.value || '');
  form.append('tags', document.getElementById('vid-tags')?.value || '');
  form.append('category', document.getElementById('vid-category')?.value || 'General');
  form.append('playlist', document.getElementById('vid-playlist')?.value || '');
  const visibility = document.getElementById('vid-visibility')?.value || 'public';
  form.append('isKidsSafe', String(document.getElementById('vid-kids')?.value === 'true'));
  form.append('isPrivate', String(visibility === 'private'));
  form.append('isUnlisted', String(visibility === 'unlisted'));
  form.append('isPaid', String(document.getElementById('vid-paid')?.checked || false));
  form.append('price', document.getElementById('vid-price')?.value || '0');
  form.append('isShort', String(isShort));

  // Geplante Veröffentlichung
  const scheduleToggle = document.getElementById('vid-schedule-toggle');
  const scheduledAtInput = document.getElementById('vid-scheduled-at');
  if (scheduleToggle?.checked && scheduledAtInput?.value) {
    form.append('scheduledAt', new Date(scheduledAtInput.value).toISOString());
  }

  document.getElementById('upload-progress').style.display = 'block';
  document.getElementById('submit-video-btn').disabled = true;
  document.getElementById('upload-status-text').textContent = 'Wird hochgeladen...';
  document.getElementById('upload-pct-label').textContent = '0%';
  document.getElementById('upload-speed-label').textContent = '';
  document.getElementById('upload-eta-label').textContent = '';
  document.getElementById('upload-phase-block').style.display = 'block';
  document.getElementById('transcode-phase-block').style.display = 'none';
  NXD.play('upload_start');

  // Show floating upload button
  window._bgUploadTitle = title;
  const floatBtn = document.getElementById('upload-float-btn');
  if (floatBtn) { floatBtn.style.display = 'flex'; floatBtn.style.cssText += ';display:flex'; }


  let uploadStartTime = Date.now();
  let lastLoaded = 0;
  let lastTime = uploadStartTime;
  let speedAvg = 0;

  const onProgress = (loaded, total) => {
    const pct = Math.min(100, Math.floor((loaded / total) * 100));
    const fill = document.getElementById('upload-progress-fill');
    if (fill) fill.style.width = pct + '%';
    const pctEl = document.getElementById('upload-pct-label'); if (pctEl) pctEl.textContent = pct + '%';
    const bgFill = document.getElementById('bg-upload-fill');
    const bgPct = document.getElementById('bg-upload-pct');
    const bgTitle = document.getElementById('bg-upload-title');
    const floatPct = document.getElementById('upload-float-pct');
    if (bgFill) bgFill.style.width = pct + '%';
    if (bgPct) bgPct.textContent = pct + '%';
    if (bgTitle && window._bgUploadTitle) bgTitle.textContent = window._bgUploadTitle;
    if (floatPct) floatPct.textContent = pct + '%';
    const now = Date.now();
    const dt = (now - lastTime) / 1000;
    if (dt >= 0.7) {
      const speed = Math.max(0, (loaded - lastLoaded) / dt);
      speedAvg = speedAvg ? speedAvg * 0.7 + speed * 0.3 : speed; // geglättet, springt nicht so
      lastLoaded = loaded; lastTime = now;
      const fmtSpeed = speedAvg > 1024 * 1024 ? (speedAvg / (1024 * 1024)).toFixed(1) + ' MB/s' : (speedAvg / 1024).toFixed(0) + ' KB/s';
      const etaSec = speedAvg > 0 ? Math.round((total - loaded) / speedAvg) : 0;
      const etaStr = etaSec >= 60 ? Math.floor(etaSec / 60) + ' min ' + (etaSec % 60) + ' s' : etaSec + ' s';
      const sp = document.getElementById('upload-speed-label'); if (sp) sp.textContent = fmtSpeed;
      const eta = document.getElementById('upload-eta-label'); if (eta) eta.textContent = pct < 100 ? (tr({en:'~',de:'noch ca. '}) + etaStr) : '';
    }
    const st = document.getElementById('upload-status-text');
    if (st) st.textContent = pct < 100 ? tr({en:'Uploading…',de:'Wird hochgeladen …'}) : tr({en:'Upload complete – checking video…',de:'Hochgeladen – Video wird geprüft …'});
    if (pct >= 100) { const sp = document.getElementById('upload-speed-label'); if (sp) sp.textContent = ''; const eta = document.getElementById('upload-eta-label'); if (eta) eta.textContent = ''; }
  };
  const onFail = (msg) => {
    document.getElementById('submit-video-btn').disabled = false;
    document.getElementById('upload-progress').style.display = 'none';
    showToast(msg || tr({en:'Upload failed',de:'Upload fehlgeschlagen'}), 'error');
    const bgBar = document.getElementById('bg-upload-bar'); if (bgBar) bgBar.style.display = 'none';
    const fb = document.getElementById('upload-float-btn'); if (fb) fb.style.display = 'none';
    window.removeEventListener('beforeunload', _nxUploadUnloadGuard);
  };
  const onDone = (v) => {
    window.removeEventListener('beforeunload', _nxUploadUnloadGuard);
    document.getElementById('submit-video-btn').disabled = false;
    NXD.play('upload_complete');
    if (v && v.id) setTimeout(() => xpTrack('upload', v.id), 1500);
    showToast(tr({en:'Video uploaded! It is being optimised for all devices.',de:'Video hochgeladen! Es wird jetzt für alle Geräte optimiert.'}), 'success');
    document.getElementById('upload-phase-block').style.display = 'none';
    document.getElementById('transcode-phase-block').style.display = 'block';
    document.getElementById('submit-video-btn').style.display = 'none';
    const bgStatus = document.getElementById('bg-upload-status'); if (bgStatus) bgStatus.textContent = tr({en:'Processing…',de:'Wird verarbeitet …'});
    if (v && v.id) window._uploadingVideoId = v.id;
    window._uploadModalFallbackTimer = setTimeout(() => { _finishUploadModal(); }, 30000);
  };
  window.addEventListener('beforeunload', _nxUploadUnloadGuard);
  onProgress(0, videoFile.size || 1);

  try {
    const v = await nxChunkedUpload(videoFile, form, onProgress);
    onDone(v);
  } catch (e) {
    onFail(e && e.message);
  }
}

function _nxUploadUnloadGuard(e) { e.preventDefault(); e.returnValue = ''; return ''; }
// ─── Teil: client/app/280-upload-2.js ───

// Lädt eine Videodatei in 16-MB-Stücken hoch (siehe Server: /api/videos/upload/init|chunk|complete).
// Jedes Stück wird bei Netzwerkfehlern bis zu 6x automatisch wiederholt.
async function nxChunkedUpload(file, form, onProgress) {
  const token = localStorage.getItem('nxd_token');
  const auth = { Authorization: `Bearer ${token}` };
  const init = await fetch('/api/videos/upload/init', { method: 'POST', headers: { ...auth, 'Content-Type': 'application/json' }, body: JSON.stringify({ size: file.size, name: file.name || 'video.mp4', type: file.type || '' }) });
  const initData = await init.json().catch(() => ({}));
  if (!init.ok) throw new Error(initData.error || tr({en:'Upload could not be started',de:'Upload konnte nicht gestartet werden'}));
  const { uploadId } = initData;
  const chunkSize = initData.chunkSize || 16 * 1024 * 1024;
  const total = Math.max(1, Math.ceil(file.size / chunkSize));
  let doneBytes = 0;
  for (let i = 0; i < total; i++) {
    const start = i * chunkSize, end = Math.min(file.size, start + chunkSize);
    const blob = file.slice(start, end);
    let attempt = 0;
    for (;;) {
      try {
        const r = await new Promise((resolve, reject) => {
          const xhr = new XMLHttpRequest();
          xhr.open('PUT', `/api/videos/upload/chunk/${uploadId}/${i}`);
          xhr.setRequestHeader('Authorization', `Bearer ${token}`);
          xhr.setRequestHeader('Content-Type', 'application/octet-stream');
          xhr.timeout = 180000;
          xhr.upload.onprogress = (e) => { if (e.lengthComputable) onProgress(doneBytes + Math.min(e.loaded, blob.size), file.size); };
          xhr.onload = () => { let d = {}; try { d = JSON.parse(xhr.responseText || '{}'); } catch {} resolve({ status: xhr.status, data: d }); };
          xhr.onerror = () => reject(new Error('network'));
          xhr.ontimeout = () => reject(new Error('timeout'));
          xhr.send(blob);
        });
        if (r.status === 200) break;
        if (r.status === 409 && typeof r.data.expected === 'number' && r.data.expected > i) break; // Server hat das Stück schon
        if (r.status >= 400 && r.status < 500 && r.status !== 408 && r.status !== 429) throw Object.assign(new Error(r.data.error || 'Upload fehlgeschlagen'), { fatal: true });
        throw new Error(r.data.error || 'HTTP ' + r.status);
      } catch (e) {
        if (e.fatal || ++attempt > 6) throw new Error(e.fatal ? e.message : tr({en:'Connection lost during upload. Please try again.',de:'Verbindung beim Hochladen abgebrochen. Bitte erneut versuchen.'}));
        const st = document.getElementById('upload-status-text');
        if (st) st.textContent = tr({en:`Connection unstable – retrying (${attempt}/6)…`,de:`Verbindung instabil – neuer Versuch (${attempt}/6) …`});
        await new Promise(r => setTimeout(r, Math.min(15000, 1000 * 2 ** attempt)));
      }
    }
    doneBytes = end;
    onProgress(doneBytes, file.size);
  }
  // Abschluss: Metadaten (+ optionales Vorschaubild) senden
  const meta = new FormData();
  for (const [k, v] of form.entries()) if (k !== 'video') meta.append(k, v);
  const st = document.getElementById('upload-status-text');
  if (st) st.textContent = tr({en:'Upload complete – checking video…',de:'Hochgeladen – Video wird geprüft …'});
  const fin = await fetch(`/api/videos/upload/complete/${uploadId}`, { method: 'POST', headers: auth, body: meta });
  const finData = await fin.json().catch(() => ({}));
  if (!fin.ok) throw new Error(finData.error || tr({en:'Upload failed',de:'Upload fehlgeschlagen'}));
  return finData;
}

// Toggle background upload bar visibility
function toggleUploadBar() {
  const bar = document.getElementById('bg-upload-bar');
  const floatBtn = document.getElementById('upload-float-btn');
  if (!bar) return;
  const isVisible = bar.style.display !== 'none' && bar.style.display !== '';
  bar.style.display = isVisible ? 'none' : 'block';
  if (floatBtn) floatBtn.style.bottom = isVisible ? '70px' : '210px';
}

// Minimize upload modal to background bar
function minimizeUpload() {
  const bgBar = document.getElementById('bg-upload-bar');
  const floatBtn = document.getElementById('upload-float-btn');
  if (bgBar) bgBar.style.display = 'block';
  if (floatBtn) { floatBtn.style.display = 'flex'; floatBtn.style.cssText += ';display:flex'; floatBtn.style.bottom = '220px'; }
  closeModal('upload-modal');
}

// Re-open upload modal from background
function reopenUploadModal() {
  document.getElementById('bg-upload-bar').style.display = 'none';
  openModal('upload-modal');
}

function _finishUploadModal() {
  clearTimeout(window._uploadModalFallbackTimer);
  closeModal('upload-modal');
  videoFile = null; thumbnailFile = null;
  document.getElementById('upload-progress').style.display = 'none';
  document.getElementById('upload-progress-fill').style.width = '0%';
  document.getElementById('upload-pct-label').textContent = '0%';
  document.getElementById('submit-video-btn').style.display = '';
  document.getElementById('submit-video-btn').disabled = false;
  window._uploadingVideoId = null;
  // Hide background bar
  const bgBar = document.getElementById('bg-upload-bar');
  if (bgBar) bgBar.style.display = 'none';
  const floatBtn = document.getElementById('upload-float-btn');
  if (floatBtn) floatBtn.style.display = 'none';
  navigateTo('home');
}

function setPostTab(tab) {
  const isMedia = tab === 'media';
  document.getElementById('post-media-section').style.display = isMedia ? 'block' : 'none';
  document.getElementById('post-poll-section').style.display = isMedia ? 'none' : 'block';
  const mBtn = document.getElementById('post-tab-media');
  const pBtn = document.getElementById('post-tab-poll');
  if (mBtn) { mBtn.style.background = isMedia ? 'var(--purple-subtle)' : 'var(--bg-secondary)'; mBtn.style.borderColor = isMedia ? 'var(--purple-main)' : 'var(--border)'; mBtn.style.color = isMedia ? 'var(--purple-light)' : 'var(--text-muted)'; }
  if (pBtn) { pBtn.style.background = !isMedia ? 'var(--purple-subtle)' : 'var(--bg-secondary)'; pBtn.style.borderColor = !isMedia ? 'var(--purple-main)' : 'var(--border)'; pBtn.style.color = !isMedia ? 'var(--purple-light)' : 'var(--text-muted)'; }
}

function addPollOption() {
  const list = document.getElementById('poll-options-list');
  if (!list) return;
  const count = list.querySelectorAll('.poll-option-row').length;
  if (count >= 6) { showToast('Max. 6 Optionen', 'info'); return; }
  const row = document.createElement('div');
  row.className = 'poll-option-row';
  row.style.display = 'flex'; row.style.gap = '6px'; row.style.alignItems = 'center';
  row.innerHTML = `<input type="text" placeholder="Option ${count+1}" maxlength="100" class="poll-opt-input" style="flex:1;padding:8px 12px;background:var(--bg-secondary);border:1px solid var(--border);border-radius:8px;color:var(--text-primary);font-size:13px">
    <button type="button" data-h-click="h_app_remove_8463" style="width:30px;height:30px;border-radius:50%;background:rgba(239,68,68,0.15);border:none;color:#ef4444;cursor:pointer;font-size:14px;flex-shrink:0">&times;</button>`;
  list.appendChild(row);
}

async function submitPost() {
  if (!currentUser) { openAuthModal('login'); return; }
  const text = document.getElementById('post-text').value.trim();
  const isPollTab = document.getElementById('post-poll-section')?.style.display !== 'none';

  let poll = null;
  if (isPollTab) {
    const question = document.getElementById('poll-question')?.value?.trim();
    const opts = Array.from(document.querySelectorAll('.poll-opt-input')).map(i => i.value.trim()).filter(Boolean);
    if (!question) { showToast('Bitte gib eine Frage ein', 'error'); return; }
    if (opts.length < 2) { showToast('Mindestens 2 Optionen benötigt', 'error'); return; }
    const days = parseInt(document.getElementById('poll-duration')?.value || '3');
    poll = { question, options: opts, endsAt: days > 0 ? new Date(Date.now() + days * 86400000).toISOString() : null };
  } else {
    if (!text && postImages.length === 0) { showToast('Bitte schreibe etwas oder lade ein Bild hoch', 'error'); return; }
  }

  const form = new FormData();
  form.append('text', text);
  if (poll) form.append('poll', JSON.stringify(poll));
  postImages.forEach(img => form.append('images', img));
  const token = localStorage.getItem('nxd_token');
  try {
    const res = await fetch('/api/posts', { method: 'POST', headers: { 'Authorization': `Bearer ${token}` }, body: form });
    const data = await res.json();
    if (!res.ok) throw new Error(data.error);
    showToast(poll ? 'Umfrage veröffentlicht!' : 'Beitrag veröffentlicht!', 'success');
    if (data && data.id) xpTrack('post', data.id);
    closeModal('upload-modal');
    postImages = [];
    navigateTo('posts');
  } catch(e) { showToast(e.message, 'error'); }
}
