// ==================== NOTIFICATIONS ====================
function toggleNotificationsPanel() {
  const panel = document.getElementById('notifications-panel');
  if (panel.style.display === 'none') {
    panel.style.display = 'flex';
    panel.style.flexDirection = 'column';
    loadNotifications();
    if (currentUser) {
      apiPost('/api/users/me/notifications/read').catch(()=>{});
      // Check for unread messages
      apiGet('/api/dm/unread').then(({ unread }) => {
        const badge = document.getElementById('msg-badge');
        if (badge) { badge.textContent = unread; badge.style.display = unread > 0 ? 'inline-block' : 'none'; }
      }).catch(()=>{});
    }
    document.getElementById('notif-count').style.display = 'none';
  } else {
    panel.style.display = 'none';
  }
}
function closeNotificationsPanel() { document.getElementById('notifications-panel').style.display = 'none'; }

function switchNotifTab(tab) {
  const isNotifs = tab === 'notifs';
  document.getElementById('notif-tab-btn-notifs').style.cssText = `flex:1;padding:10px;border:none;background:${isNotifs?'var(--purple-subtle)':'transparent'};color:${isNotifs?'var(--purple-light)':'var(--text-muted)'};font-size:13px;font-weight:${isNotifs?'700':'600'};cursor:pointer;border-bottom:2px solid ${isNotifs?'var(--purple-main)':'transparent'}`;
  document.getElementById('notif-tab-btn-messages').style.cssText = `flex:1;padding:10px;border:none;background:${!isNotifs?'var(--purple-subtle)':'transparent'};color:${!isNotifs?'var(--purple-light)':'var(--text-muted)'};font-size:13px;font-weight:${!isNotifs?'700':'600'};cursor:pointer;border-bottom:2px solid ${!isNotifs?'var(--purple-main)':'transparent'};position:relative`;
  if (isNotifs) loadNotifications(); else loadMessages();
}

async function loadMessages() {
  const list = document.getElementById('notifications-list');
  if (!currentUser) { list.innerHTML = `<div style="padding:20px;color:var(--text-muted);text-align:center">${tr({en:'Login required',de:'Anmeldung erforderlich'})}</div>`; return; }
  list.innerHTML = `<div style="padding:20px;text-align:center"><div class="spinner"></div></div>`;
  try {
    const convs = await apiGet('/api/dm/conversations');
    const badge = document.getElementById('msg-badge'); if (badge) badge.style.display = 'none';
    const openAll = `<button class="dm-panel-all" data-h-click="h_app_closeNotificationsPanel_8539">${tr({en:'Open messages',de:'Alle Nachrichten öffnen'})} <i class="fas fa-arrow-right"></i></button>`;
    if (!convs.length) {
      list.innerHTML = `<div style="padding:36px 20px;color:var(--text-muted);text-align:center"><i class="far fa-paper-plane" style="font-size:30px;margin-bottom:12px;display:block;opacity:0.5"></i>${tr({en:'No messages yet',de:'Noch keine Nachrichten'})}</div>` + openAll;
      return;
    }
    list.innerHTML = convs.slice(0, 15).map(c => `
      <div class="notif-item${c.unread ? ' unread' : ''}" style="cursor:pointer" data-h-click="h_app_closeNotificationsPanel_8545" data-hv-click="${nxHv(String(c.partner.id))}">
        <div style="flex-shrink:0">${buildAvatarHtml(c.partner, 36, { noVideo: true })}</div>
        <div style="flex:1;min-width:0">
          <div class="notif-text" style="display:flex;justify-content:space-between;gap:8px"><strong style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${escHtml(c.partner.displayName || c.partner.username)}</strong><span style="font-size:11px;color:var(--text-muted);flex-shrink:0">${_dmTime(c.last.createdAt)}</span></div>
          <div style="font-size:12.5px;color:var(--text-secondary);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin-top:2px">${c.last.fromMe ? tr({en:'You: ',de:'Du: '}) : ''}${escHtml(c.last.text.slice(0, 80))}</div>
        </div>
        ${c.unread ? `<span class="dm-conv-unread" style="align-self:center">${c.unread}</span>` : ''}
      </div>`).join('') + openAll;
  } catch(e) { list.innerHTML = `<div style="padding:20px;color:var(--text-muted)">${tr({en:'Loading error',de:'Fehler beim Laden'})}</div>`; }
}

async function loadNotifications() {
  const list = document.getElementById('notifications-list');
  if (!currentUser) { list.innerHTML = `<div style="padding:20px;color:var(--text-muted);text-align:center">Anmeldung erforderlich</div>`; return; }
  try {
    const notifs = await apiGet('/api/users/me/notifications');
    if (!notifs.length) {
      list.innerHTML = `<div style="padding:20px;color:var(--text-muted);text-align:center"><i class="fas fa-bell-slash" style="font-size:32px;margin-bottom:8px;display:block"></i>${t('notifications_empty')}</div>`;
      return;
    }
    list.innerHTML = '';
    notifs.forEach(n => {
      const div = document.createElement('div');
      div.className = `notif-item${n.read ? '' : ' unread'}`;
      const icons = { new_video: 'fa-film', comment: 'fa-comment', like: 'fa-heart', subscribe: 'fa-user-plus', new_post: 'fa-images', mention: 'fa-at', support_reply: 'fa-headset', report_status: 'fa-flag', announcement: 'fa-bullhorn', strike: 'fa-triangle-exclamation', takedown: 'fa-eye-slash', verified: 'fa-circle-check', unverified: 'fa-circle-xmark', live: 'fa-tower-broadcast', channel_sub: 'fa-star', gift_sub: 'fa-gift', live_gift: 'fa-gem' };
      if (n.type === 'strike' || n.type === 'takedown') div.classList.add('notif-item--alert');
      const icon = icons[n.type] || 'fa-bell';
      const texts = {
        new_video: `<strong>${escHtml(n.fromName)}</strong> ${t('notif_new_video')} <em>${escHtml(n.videoTitle)}</em>`,
        comment: `<strong>${escHtml(n.fromName)}</strong> ${t('notif_comment')} <em>"${escHtml(n.commentText)}"</em>`,
        like: `<strong>${escHtml(n.fromName)}</strong> ${t('notif_like')} <em>${escHtml(n.videoTitle)}</em>`,
        subscribe: `<strong>${escHtml(n.fromName)}</strong> ${t('notif_subscribed')}`,
        new_post: `<strong>${escHtml(n.fromName)}</strong> ${t('notif_new_post')}`,
        mention: `<strong>${escHtml(n.fromName)}</strong> ${t('notif_mention')}: <em>"${escHtml(n.commentText)}"</em>`,
        support_reply: `<strong>${t('notif_support_reply')}</strong>: <em>"${escHtml(n.commentText)}"</em>`,
        report_status: escHtml(n.commentText),
        announcement: `<strong><i class="fas fa-bullhorn"></i> ${escHtml(n.title || 'Norynex')}</strong>: ${escHtml(n.commentText)}`,
        strike: n.banned
          ? `<strong>${tr({en:'Your account was suspended',de:'Dein Konto wurde gesperrt'})}</strong>: ${escHtml(n.reason || '')}`
          : `<strong>${tr({en:'You received a strike',de:'Du hast eine Verwarnung erhalten'})}${n.strikeCount ? ` (${n.strikeCount}/3)` : ''}</strong>: ${escHtml(n.reason || '')}`,
        takedown: `<strong>${tr({en:'Content removed',de:'Inhalt entfernt'})}</strong>: „${escHtml(n.contentTitle || '')}“ – ${escHtml(n.reason || '')}`,
        verified: `<strong>${tr({en:'Your channel is now verified',de:'Dein Kanal ist jetzt verifiziert'})}</strong> <i class="fas fa-circle-check" style="color:#3b82f6"></i>`,
        unverified: tr({en:'Your verification badge was removed.',de:'Dein Verifizierungs-Abzeichen wurde entfernt.'}),
        live: `<i class="fas fa-circle" style="color:#ef4444;font-size:9px;vertical-align:middle"></i> <strong>${escHtml(n.fromName)}</strong> ${tr({en:'is live now',de:'ist jetzt live'})}${n.liveTitle ? `: <em>${escHtml(n.liveTitle)}</em>` : ''}`,
        channel_sub: n.gifted ? `<i class="fas fa-gift"></i> <strong>${escHtml(n.fromName)}</strong> ${tr({en:`gifted ${n.gifted} live sub(s) in your channel`,de:`hat ${n.gifted} Live-Abo(s) in deinem Kanal verschenkt`})}` : `<i class="fas fa-star"></i> <strong>${escHtml(n.fromName)}</strong> ${tr({en:'subscribed to your channel',de:'hat ein Live-Abo für deinen Kanal abgeschlossen'})} (${tr({en:'Tier',de:'Stufe'})} ${n.tier}${n.months > 1 ? `, ${n.months} ${tr({en:'months',de:'Monate'})}` : ''})`,
        gift_sub: `<i class="fas fa-gift"></i> <strong>${escHtml(n.fromName)}</strong> ${tr({en:'gifted you a live sub for',de:'hat dir ein Live-Abo geschenkt für'})} <strong>${escHtml(n.channelName || '')}</strong>`,
        live_gift: `<i class="fas fa-gem"></i> <strong>${escHtml(n.fromName)}</strong> ${tr({en:'sent you',de:'hat dir geschickt:'})} ${escHtml(n.gift || '')}`
      };
      div.innerHTML = `
        <div class="notif-icon"><i class="fas ${icon}"></i></div>
        <div style="flex:1">
          <div class="notif-text">${texts[n.type] || t('notif_new')}</div>
          <div class="notif-time">${timeAgo(n.createdAt)}</div>
        </div>`;
      if (n.videoId) div.style.cursor = 'pointer', div.addEventListener('click', () => { navigateTo('watch', n.videoId); closeNotificationsPanel(); });
      else if (n.type === 'live' && n.fromId) div.style.cursor = 'pointer', div.addEventListener('click', () => { closeNotificationsPanel(); navigateTo('stream', n.fromId); });
      else if (n.type === 'gift_sub' && n.channelId) div.style.cursor = 'pointer', div.addEventListener('click', () => { closeNotificationsPanel(); navigateTo('stream', n.channelId); });
      else if (n.type === 'channel_sub' || n.type === 'live_gift') div.style.cursor = 'pointer', div.addEventListener('click', () => { closeNotificationsPanel(); history.replaceState(null,'','#studio/stream/money'); navigateTo('studio'); });
      else if (n.type === 'support_reply') div.style.cursor = 'pointer', div.addEventListener('click', () => { openSupportChatWidget(); closeNotificationsPanel(); });
      else if (n.type === 'report_status') div.style.cursor = 'pointer', div.addEventListener('click', () => { openMyReportsModal(); closeNotificationsPanel(); });
      else if (n.type === 'strike' || n.type === 'takedown') div.style.cursor = 'pointer', div.addEventListener('click', () => { closeNotificationsPanel(); if (typeof nxOpenMyStrikes === 'function') nxOpenMyStrikes(); });
      else if (n.type === 'announcement' && n.link) div.style.cursor = 'pointer', div.addEventListener('click', () => { closeNotificationsPanel(); if (/^https?:/.test(n.link)) window.open(n.link, '_blank', 'noopener'); else location.href = n.link; });
      list.appendChild(div);
    });
  } catch(e) { list.innerHTML = `<div style="padding:20px;color:var(--text-muted)">${t('loading_error')}</div>`; }
}

// ==================== SUPPORT-CHAT (Nutzerseite) ====================
let _supportChatId = null;
let _supportChatSocketJoined = false;

function openSupportChatWidget() {
  if (!currentUser) { openAuthModal('login'); return; }
  closeNotificationsPanel();
  document.getElementById('support-chat-panel').style.display = 'flex';
  loadSupportChat();
}

function closeSupportChatWidget() {
  document.getElementById('support-chat-panel').style.display = 'none';
}

async function loadSupportChat() {
  const box = document.getElementById('support-chat-messages');
  box.innerHTML = `<div class="spinner" style="margin:20px auto;display:block"></div>`;
  try {
    const chat = await apiGet('/api/support/chat');
    _supportChatId = chat.id || null;
    renderSupportChatMessages(chat.messages || []);
    if (_supportChatId && socket && !_supportChatSocketJoined) {
      socket.emit('join_support_chat', _supportChatId);
      _supportChatSocketJoined = true;
    }
    apiPost('/api/support/chat/read').catch(() => {});
  } catch (e) {
    box.innerHTML = `<p style="color:var(--text-muted);text-align:center;padding:20px">${t('loading_error')}</p>`;
  }
}

function renderSupportChatMessages(messages) {
  const box = document.getElementById('support-chat-messages');
  if (!messages.length) {
    box.innerHTML = `<div style="text-align:center;color:var(--text-muted);font-size:13px;padding:30px 10px">
      <i class="fas fa-headset" style="font-size:32px;margin-bottom:10px;display:block;opacity:0.5"></i>
      ${t('support_chat_intro')}
    </div>`;
    return;
  }
  box.innerHTML = messages.map(m => supportMessageBubbleHtml(m)).join('');
  box.scrollTop = box.scrollHeight;
}

function supportMessageBubbleHtml(m) {
  if (m.from === 'nexa') return nexaMessageBubbleHtml(m);
  const isUser = m.from === 'user';
  return `<div style="align-self:${isUser ? 'flex-end' : 'flex-start'};max-width:80%;display:flex;flex-direction:column;gap:2px">
    ${!isUser ? `<span style="font-size:11px;color:var(--purple-light);font-weight:700;margin-left:4px"><i class="fas fa-headset"></i> ${escHtml(m.adminName || 'Support')}</span>` : ''}
    <div style="background:${isUser ? 'var(--purple-main)' : 'var(--bg-secondary)'};color:${isUser ? 'white' : 'var(--text-primary)'};padding:9px 13px;border-radius:14px;${isUser ? 'border-bottom-right-radius:4px' : 'border-bottom-left-radius:4px'};font-size:13px;word-break:break-word">${linkifyText(m.text)}</div>
    <span style="font-size:10px;color:var(--text-muted);${isUser ? 'text-align:right;margin-right:4px' : 'margin-left:4px'}">${timeAgo(m.createdAt)}</span>
  </div>`;
}

async function sendSupportChatMessage() {
  const input = document.getElementById('support-chat-input');
  const text = input.value.trim();
  if (!text) return;
  input.value = '';
  const askNexaToo = document.getElementById('support-ask-nexa')?.checked;
  const box = document.getElementById('support-chat-messages');

  try {
    if (askNexaToo) {
      // Nexa beantwortet direkt im Support-Chat (Nachricht + Antwort werden serverseitig gespeichert).
      // Server sendet beide Nachrichten zusätzlich per Socket (support_message) an den Chat-Raum.
      // Ist der Socket beim Absenden bereits im Raum (Normalfall ab der 2. Nachricht), würde ein
      // zusätzliches manuelles Einfügen hier zu doppelt angezeigten Nachrichten führen — deshalb wird
      // die Nachricht nur dann sofort lokal gerendert, wenn der Socket (noch) nicht im Raum ist; in dem
      // Fall bekäme der Nutzer die Live-Broadcasts sonst gar nicht mit.
      const willReceiveViaSocket = !!(socket && _supportChatSocketJoined);
      if (box.querySelector('.fa-headset')) box.innerHTML = '';
      if (!willReceiveViaSocket) {
        box.insertAdjacentHTML('beforeend', supportMessageBubbleHtml({ from: 'user', text, createdAt: new Date().toISOString() }));
        box.scrollTop = box.scrollHeight;
      }
      const thinkingId = 'nexa-thinking-' + Date.now();
      box.insertAdjacentHTML('beforeend', `<div id="${thinkingId}" class="nexa-thinking"><div class="nexa-avatar nexa-avatar--sm"><img src="/assets/nexa-logo.svg" alt="Nexa"></div><span class="nexa-thinking-dots"><span></span><span></span><span></span></span></div>`);
      box.scrollTop = box.scrollHeight;
      try {
        const result = await apiPost('/api/nexa/support', { question: text });
        document.getElementById(thinkingId)?.remove();
        if (!_supportChatId) {
          const chat = await apiGet('/api/support/chat');
          _supportChatId = chat.id;
          if (socket && !_supportChatSocketJoined) { socket.emit('join_support_chat', _supportChatId); _supportChatSocketJoined = true; }
        }
        // Nur lokal rendern, wenn der Socket die Nachricht nicht sowieso schon (oder gleich) liefert.
        if (!willReceiveViaSocket && result.nexaMessage) box.insertAdjacentHTML('beforeend', nexaMessageBubbleHtml(result.nexaMessage));
        box.scrollTop = box.scrollHeight;
      } catch (nexaErr) {
        document.getElementById(thinkingId)?.remove();
        const msg = nexaErr.name === 'AbortError'
          ? tr({en:'Nexa is taking too long to answer. Your message was still sent.',de:'Nexa braucht zu lange für eine Antwort. Deine Nachricht wurde trotzdem gesendet.'})
          : (nexaErr.message || tr({en:'Nexa could not answer right now.',de:'Nexa konnte gerade nicht antworten.'}));
        box.insertAdjacentHTML('beforeend', `<div style="align-self:flex-start;color:#ef4444;font-size:12px;padding:4px">${escHtml(msg)}</div>`);
        box.scrollTop = box.scrollHeight;
      }
      return;
    }
    // Server broadcastet die Nachricht per Socket an den Chat-Raum (support_message). War der Socket
    // beim Senden bereits im Raum, kommt sie darüber an — dann hier nicht zusätzlich manuell einfügen,
    // sonst erscheint die Nachricht doppelt.
    const willReceiveViaSocket = !!(socket && _supportChatSocketJoined);
    const msg = await apiPost('/api/support/chat/messages', { text });
    if (!_supportChatId) {
      // Erster Chat-Kontakt: jetzt existiert eine Chat-ID, dem Socket-Raum beitreten
      const chat = await apiGet('/api/support/chat');
      _supportChatId = chat.id;
      if (socket && !_supportChatSocketJoined) { socket.emit('join_support_chat', _supportChatId); _supportChatSocketJoined = true; }
    }
    if (!willReceiveViaSocket) {
      if (box.querySelector('.fa-headset')) box.innerHTML = ''; // Intro-Text entfernen
      box.insertAdjacentHTML('beforeend', supportMessageBubbleHtml(msg));
      box.scrollTop = box.scrollHeight;
    }
  } catch (e) {
    showToast(e.message, 'error');
    input.value = text;
  }
}

function nexaMessageBubbleHtml(m) {
  return `<div class="nexa-row nexa-row--assistant">
    <div class="nexa-avatar nexa-avatar--sm"><img src="/assets/nexa-logo.svg" alt="Nexa"></div>
    <div>
      <div class="nexa-name">Nexa</div>
      <div class="nexa-bubble nexa-bubble--assistant">${linkifyText(m.text)}</div>
      <div class="nexa-meta">${timeAgo(m.createdAt)}</div>
    </div>
  </div>`;
}
