// ==================== NEXA HELP (Creator Studio) ====================
// → siehe public/js/nexa-pro.js (Nexa Studio v2)

// ==================== EXTERNAL LINK CONFIRMATION ====================
function openExternalLink(url) {
  // Nur http(s) – verhindert javascript:/data:-Links aus Profilen
  url = String(url || '').trim();
  if (!/^https?:\/\//i.test(url)) url = 'https://' + url.replace(/^[a-z]+:/i, '');
  try { const u = new URL(url); if (!/^https?:$/.test(u.protocol)) return; } catch { return; }
  const overlay = document.createElement('div');
  overlay.style.cssText = 'position:fixed;inset:0;z-index:9999;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,0.7)';
  overlay.innerHTML = `
    <div style="background:var(--bg-card);border-radius:var(--radius-lg);padding:28px;max-width:400px;width:90%;border:1px solid var(--border-light)">
      <div style="text-align:center;margin-bottom:20px">
        <i class="fas fa-external-link-alt" style="font-size:36px;color:var(--purple-light);margin-bottom:12px;display:block"></i>
        <h3 style="margin:0 0 8px">Norynex verlassen?</h3>
        <p style="color:var(--text-muted);font-size:13px;margin:0">Du wirst zu einer externen Seite weitergeleitet:</p>
        <p style="color:var(--purple-light);font-size:12px;word-break:break-all;margin:8px 0 0;background:var(--bg-secondary);padding:8px;border-radius:8px">${escHtml(url)}</p>
      </div>
      <div style="display:flex;gap:10px">
        <button id="ext-cancel" class="btn-secondary" style="flex:1">${t('btn_cancel')}</button>
        <button id="ext-confirm" class="btn-primary" style="flex:1"><i class="fas fa-external-link-alt"></i> Besuchen</button>
      </div>
    </div>`;
  document.body.appendChild(overlay);
  document.getElementById('ext-cancel').addEventListener('click', () => overlay.remove());
  document.getElementById('ext-confirm').addEventListener('click', () => { window.open(url, '_blank', 'noopener,noreferrer'); overlay.remove(); });
  overlay.addEventListener('click', e => { if (e.target === overlay) overlay.remove(); });
}

// ==================== REPORT ====================
function openReportModal(type, targetId, targetName) {
  const isEn = cl() === 'en';
  const REPORT_REASONS = [
    { id:'inappropriate', icon:'fa-triangle-exclamation', de:'Unangemessene Inhalte',      en:'Inappropriate content' },
    { id:'hate',          icon:'fa-face-angry',            de:'Hassrede / Diskriminierung', en:'Hate speech / discrimination' },
    { id:'spam',          icon:'fa-ban',                   de:'Spam',                       en:'Spam' },
    { id:'copyright',     icon:'fa-copyright',             de:'Urheberrechtsverletzung',    en:'Copyright infringement' },
    { id:'misinfo',       icon:'fa-circle-question',       de:'Falsche Informationen',      en:'Misinformation' },
    { id:'harassment',    icon:'fa-user-slash',            de:'Belästigung',                en:'Harassment' },
    { id:'violence',      icon:'fa-hand-fist',             de:'Gewalt',                     en:'Violence' },
    { id:'underage',      icon:'fa-child',                 de:'Vermutlich zu jung',         en:'Probably underage' },
    { id:'other',         icon:'fa-ellipsis',              de:'Sonstiges',                  en:'Other' },
  ];
  const overlay = document.createElement('div');
  overlay.id = 'report-modal';
  overlay.className = 'nx-modal-overlay';
  overlay.innerHTML = `
    <div class="nx-report-card">
      <div class="nx-report-head">
        <div class="nx-report-head-icon"><i class="fas fa-flag"></i></div>
        <div>
          <h3>${type === 'video' ? t('report_modal_video') : type === 'comment' ? t('report_modal_comment') : type === 'message' ? tr({en:'Report message',de:'Nachricht melden'}) : type === 'stream' ? tr({en:'Report live stream',de:'Livestream melden'}) : type === 'livechat' ? tr({en:'Report chat message',de:'Chat-Nachricht melden'}) : t('report_modal_channel')}</h3>
          <p>${tr({en:`Why do you want to report "${escHtml(targetName)}"?`, de:`Warum möchtest du „${escHtml(targetName)}" melden?`})}</p>
        </div>
        <button class="nx-report-close" id="report-close" aria-label="${tr({en:'Close',de:'Schließen'})}"><i class="fas fa-xmark"></i></button>
      </div>
      <div class="nx-report-reasons" id="report-reasons">
        ${REPORT_REASONS.map(r => `
          <div class="nx-report-reason" data-reason-id="${r.id}">
            <label>
              <input type="radio" name="report-reason" value="${isEn ? r.en : r.de}" data-reason-id="${r.id}">
              <span class="nx-report-reason-icon"><i class="fas ${r.icon}"></i></span>
              <span class="nx-report-reason-label">${isEn ? r.en : r.de}</span>
              <span class="nx-report-reason-check"><i class="fas fa-check"></i></span>
            </label>
            <div class="nx-report-reason-detail" id="report-detail-${r.id}">
              <textarea maxlength="500" placeholder="${tr({en:'Add details (optional)…',de:'Details hinzufügen (optional)…'})}"></textarea>
            </div>
          </div>`
        ).join('')}
      </div>
      ${type === 'message' ? `<label class="gs-check" style="margin:4px 4px 12px"><input type="checkbox" id="report-also-block" checked><span>${tr({en:'Also block this person',de:'Diese Person auch blockieren'})}</span></label>` : ''}
      <div class="nx-report-actions">
        <button id="report-cancel" class="btn-secondary" style="flex:1">${t('btn_cancel')}</button>
        <button id="report-submit" class="nx-report-submit" style="flex:1.4" disabled><i class="fas fa-flag"></i> ${tr({en:'Report',de:'Melden'})}</button>
      </div>
    </div>`;
  document.body.appendChild(overlay);
  requestAnimationFrame(() => overlay.classList.add('is-open'));

  const close = () => { overlay.classList.remove('is-open'); setTimeout(() => overlay.remove(), 200); };
  document.getElementById('report-close').addEventListener('click', close);
  document.getElementById('report-cancel').addEventListener('click', close);
  overlay.addEventListener('click', e => { if (e.target === overlay) close(); });

  const submitBtn = document.getElementById('report-submit');
  overlay.querySelectorAll('input[name="report-reason"]').forEach(input => {
    input.addEventListener('change', () => {
      overlay.querySelectorAll('.nx-report-reason').forEach(row => row.classList.toggle('is-selected', row.dataset.reasonId === input.dataset.reasonId));
      submitBtn.disabled = false;
    });
  });

  submitBtn.addEventListener('click', async () => {
    if (!currentUser) { openAuthModal('login'); close(); return; }
    const checked = document.querySelector('input[name="report-reason"]:checked');
    const reason = checked?.value;
    if (!reason) { showToast(tr({en:'Please select a reason',de:'Bitte wähle einen Grund aus'}), 'error'); return; }
    const detailEl = document.getElementById(`report-detail-${checked.dataset.reasonId}`)?.querySelector('textarea');
    const details = detailEl ? detailEl.value.trim() : '';
    submitBtn.disabled = true;
    submitBtn.innerHTML = `<i class="fas fa-spinner fa-spin"></i> ${tr({en:'Sending…',de:'Wird gesendet…'})}`;
    try {
      const alsoBlock = type === 'message' && !!document.getElementById('report-also-block')?.checked;
      await apiPost('/api/report', { type, targetId, reason, reasonCode: checked.dataset.reasonId, details: details || undefined, alsoBlock, channelId: type === 'livechat' ? window._currentStreamerId : undefined });
      if (alsoBlock && typeof nxAfterBlockChange === 'function') nxAfterBlockChange();
      close();
      showToast(tr({en:'Reported! We\u2019re reviewing the content.',de:'Gemeldet! Wir prüfen den Inhalt.'}), 'success');
    } catch(e) {
      submitBtn.disabled = false;
      submitBtn.innerHTML = `<i class="fas fa-flag"></i> ${tr({en:'Report',de:'Melden'})}`;
      showToast(e.message, 'error');
    }
  });
}

// ==================== OBS TAB (Stream-Key + RTMP-URL für externe Encoder) ====================
function renderObsSetupHtml(me) {
  const key = me.streamKey || '';
  const cfg = window._nxStreamCfg || {};
  const rtmpUrl = (cfg.rtmp && cfg.rtmp.url) || `rtmp://${window.location.hostname}:1935/live`;
  if (!window._nxStreamCfg) apiGet('/api/streams/config').then(c => { window._nxStreamCfg = c; const el = document.getElementById('obs-rtmp-url'); if (el && c.rtmp?.url) el.textContent = c.rtmp.url; }).catch(() => {});
  return `
    <div class="nx-setup-grid">
      <div class="nx-setup-card">
        <h4><i class="fas fa-satellite-dish"></i> ${tr({en:'OBS / External Encoder',de:'OBS / Externer Encoder'})}</h4>
        <div class="nx-setup-row-desc" style="margin-bottom:14px">${tr({en:'Use these values in OBS Studio (or any RTMP-compatible encoder) under "Stream" → "Custom...".',de:'Trage diese Werte in OBS Studio (oder einem beliebigen RTMP-fähigen Encoder) unter „Stream" → „Benutzerdefiniert..." ein.'})}</div>

        <div class="nx-setup-row">
          <div style="flex:1;min-width:0">
            <div class="nx-setup-row-label">${tr({en:'Server (RTMP URL)',de:'Server (RTMP-URL)'})}</div>
            <div class="nx-key-value" id="obs-rtmp-url">${rtmpUrl}</div>
          </div>
          <button class="nx-copy-btn" data-h-click="h_app_writeText_8879" data-hv-click="${nxHv(String(rtmpUrl), String(tr({en:'RTMP URL copied!',de:'RTMP-URL kopiert!'})))}" aria-label="Kopieren"><i class="fas fa-copy"></i></button>
        </div>

        <div class="nx-setup-row">
          <div style="flex:1;min-width:0">
            <div class="nx-setup-row-label">${tr({en:'Stream Key',de:'Stream-Key'})}</div>
            <div class="nx-key-value" id="skey-display">${key.replace(/./g, '•')}</div>
          </div>
          <button class="nx-copy-btn" data-h-click="h_app_toggleStreamKey_8887" data-hv-click="${nxHv(String(key))}" aria-label="Anzeigen"><i class="fas fa-eye"></i></button>
          <button class="nx-copy-btn" data-h-click="h_app_copyStreamKey_8889" data-hv-click="${nxHv(String(key))}" aria-label="Kopieren"><i class="fas fa-copy"></i></button>
        </div>

        <button class="nx-regen-btn" data-h-click="h_app_regenerateStreamKey_8890"><i class="fas fa-rotate"></i> ${tr({en:'Regenerate key',de:'Key neu generieren'})}</button>

        <div class="nx-obs-tips">
          <b>${tr({en:'Recommended OBS settings',de:'Empfohlene OBS-Einstellungen'})}</b>
          <ul>
            <li>${tr({en:'Output → Encoder: x264 or NVENC/QuickSync (H.264)',de:'Ausgabe → Encoder: x264 oder NVENC/QuickSync (H.264)'})}</li>
            <li>${tr({en:'Rate control CBR, bitrate 2500–4500 kbps',de:'Qualitätsregelung CBR, Bitrate 2500–4500 kbit/s'})}</li>
            <li><b>${tr({en:'Keyframe interval: 2 s',de:'Keyframe-Intervall: 2 s'})}</b> ${tr({en:'(important for smooth playback)',de:'(wichtig für flüssige Wiedergabe)'})}</li>
            <li>${tr({en:'Profile: main · Audio: AAC 160 kbps, 48 kHz',de:'Profil: main · Audio: AAC 160 kbit/s, 48 kHz'})}</li>
          </ul>
        </div>
        <div class="nx-setup-note"><i class="fas fa-info-circle" style="margin-top:1px"></i><span>${tr({en:'OBS connects on port 1935. If the site runs through Cloudflare, OBS must use the server IP (the admin sets RTMP_PUBLIC_URL). No OBS? Use the "Phone" or "PC Studio" tab – that works everywhere.',de:'OBS verbindet sich über Port 1935. Läuft die Seite über Cloudflare, muss OBS die Server-IP nutzen (der Admin trägt dafür RTMP_PUBLIC_URL ein). Kein OBS? Nutze den Tab „Handy“ oder „PC Studio“ – das funktioniert überall.'})}</span></div>
      </div>
    </div>`;
}
