async function nxLoadStreamModeration() {
  if (!currentUser) return;
  try {
    const data = await apiGet(`/api/users/${currentUser.id}/stream/moderation`);
    _streamSetupState.mods = data.mods || [];
    _streamSetupState.banned = data.banned || [];
    nxRenderModLists();
  } catch(e) {
    const modList = document.getElementById('nx-mod-list');
    const bannedList = document.getElementById('nx-banned-list');
    if (modList) modList.innerHTML = `<div style="font-size:12px;color:var(--text-muted);padding:8px">${tr({en:'Could not load',de:'Konnte nicht geladen werden'})}</div>`;
    if (bannedList) bannedList.innerHTML = '';
  }
}
function nxRenderModLists() {
  const modList = document.getElementById('nx-mod-list');
  const bannedList = document.getElementById('nx-banned-list');
  if (modList) {
    modList.innerHTML = _streamSetupState.mods.length
      ? _streamSetupState.mods.map(u => `
        <div class="nx-mod-list-item">
          ${buildAvatarHtml(u, 22, {})}
          <span class="nx-mli-name">${escHtml(u.displayName || u.username)}</span>
          <button class="nx-mli-remove" data-h-click="h_app_nxRemoveModFromSetup_8992" data-hv-click="${nxHv(String(u.id))}" title="${tr({en:'Remove',de:'Entfernen'})}" aria-label="${tr({en:'Remove',de:'Entfernen'})}"><i class="fas fa-times"></i></button>
        </div>`).join('')
      : `<div style="font-size:12px;color:var(--text-muted);padding:8px">${tr({en:'No moderators yet',de:'Noch keine Moderatoren'})}</div>`;
  }
  if (bannedList) {
    bannedList.innerHTML = _streamSetupState.banned.length
      ? _streamSetupState.banned.map(u => `
        <div class="nx-mod-list-item">
          ${buildAvatarHtml(u, 22, {})}
          <span class="nx-mli-name">${escHtml(u.displayName || u.username)}</span>
          <button class="nx-mli-remove" data-h-click="h_app_nxUnbanFromSetup_9002" data-hv-click="${nxHv(String(u.id))}" title="${tr({en:'Unban',de:'Bann aufheben'})}" aria-label="${tr({en:'Unban',de:'Bann aufheben'})}"><i class="fas fa-undo"></i></button>
        </div>`).join('')
      : `<div style="font-size:12px;color:var(--text-muted);padding:8px">${tr({en:'No one banned',de:'Niemand gebannt'})}</div>`;
  }
}
async function nxAddModFromSetup() {
  const input = document.getElementById('nx-add-mod-input');
  const val = input ? input.value.trim() : '';
  if (!val) return;
  try {
    let targetUserId = val;
    if (!val.includes('-')) { const u = await apiGet('/api/users/' + val); targetUserId = u.id; }
    const res = await apiPost(`/api/users/${currentUser.id}/stream/mod`, { targetUserId, action: 'addmod' });
    showToast(tr({en:'Moderator added',de:'Moderator hinzugefügt'}), 'success');
    if (input) input.value = '';
    nxLoadStreamModeration();
  } catch(e) { showToast(e.message || 'Fehler', 'error'); }
}
async function nxRemoveModFromSetup(userId) {
  try {
    await apiPost(`/api/users/${currentUser.id}/stream/mod`, { targetUserId: userId, action: 'removemod' });
    nxLoadStreamModeration();
  } catch(e) { showToast(e.message || 'Fehler', 'error'); }
}
async function nxUnbanFromSetup(userId) {
  try {
    await apiPost(`/api/users/${currentUser.id}/stream/mod`, { targetUserId: userId, action: 'unban' });
    nxLoadStreamModeration();
  } catch(e) { showToast(e.message || 'Fehler', 'error'); }
}
async function nxSaveChatSettings() {
  const chatEnabled = document.getElementById('nx-chat-enabled')?.checked;
  const followersOnly = document.getElementById('nx-chat-followers')?.checked;
  const slowModeSeconds = parseInt(document.getElementById('nx-chat-slowmode')?.value || '0');
  try {
    await apiPost(`/api/users/${currentUser.id}/stream/chat-settings`, { chatEnabled, followersOnly, slowModeSeconds });
    showToast(tr({en:'Chat settings saved',de:'Chat-Einstellungen gespeichert'}), 'success');
  } catch(e) { showToast(e.message || 'Fehler', 'error'); }
}


// Gemeinsamer Kern: nimmt einen fertigen MediaStream (Kamera direkt ODER Canvas-Kompositing
// bei Desktop) und schickt ihn per MediaRecorder + Socket.io-Chunks an den Server, der die
// Chunks an alle Zuschauer im gleichen "stream_<userId>"-Raum weiterleitet.
const _bse = {
  outputStream: null,     // finaler MediaStream, der tatsächlich gesendet wird
  recorder: null,
  live: false,
  mode: null,             // 'mobile' | 'desktop'
};

function _bseGetMimeType(stream) {
  // Ohne Audiospur darf kein Audio-Codec angegeben werden, sonst lehnt MSE beim
  // Zuschauer das Segment ab ("expected audio track missing").
  const hasAudio = !stream || stream.getAudioTracks().length > 0;
  // H.264 zuerst: wird auf fast allen Geräten per Hardware kodiert (schont Akku/CPU beim Streamer)
  const candidates = hasAudio
    ? ['video/webm;codecs=h264,opus', 'video/webm;codecs=vp8,opus', 'video/webm;codecs=vp9,opus', 'video/mp4;codecs=avc1,mp4a', 'video/webm', 'video/mp4']
    : ['video/webm;codecs=h264', 'video/webm;codecs=vp8', 'video/webm;codecs=vp9', 'video/mp4;codecs=avc1', 'video/webm', 'video/mp4'];
  for (const m of candidates) { if (MediaRecorder.isTypeSupported(m)) return m; }
  return '';
}

async function _bseStartBroadcast(outputStream, title) {
  if (!currentUser) { openAuthModal('login'); return false; }
  const started = await startStream(title);
  if (!started) return false;
  const me = await apiGet('/api/auth/me').catch(() => null);
  if (!me) { showToast('Fehler beim Starten', 'error'); return false; }

  _bse.outputStream = outputStream;
  const mimeType = _bseGetMimeType(outputStream);
  const videoBitsPerSecond = _bse.pendingBitrate || 2_500_000;
  // Segment-basiertes Streaming: jeder MediaRecorder-Durchlauf erzeugt eine VOLLSTÄNDIGE,
  // eigenständige WebM-Datei (Header + Keyframe). Zuschauer können dadurch jederzeit
  // einsteigen und erholen sich nach Fehlern beim nächsten Segment von selbst — vorher
  // wurden Teil-Chunks eines einzigen Recorders verschickt, die für später beitretende
  // Zuschauer nicht dekodierbar waren (endloses "Puffert …").
  const segMs = ({ 250: 1000, 500: 2000, 1000: 3000 })[_bse.pendingChunkMs || 500] || 2000;
  const recOpts = mimeType ? { mimeType, videoBitsPerSecond } : { videoBitsPerSecond };
  try { new MediaRecorder(outputStream, recOpts); } catch (e) {
    showToast('Aufnahme konnte nicht gestartet werden: ' + e.message, 'error');
    return false;
  }
  _bse.userId = me.id; _bse.streamKey = me.streamKey; _bse.seq = 0;
  _bse.mimeType = mimeType || 'video/webm';

  // Der Streamer tritt nur noch dem Chat-Raum bei. Die Videodaten laufen per HTTPS
  // (/api/live/ingest) — unabhängig davon, ob der Socket gerade verbunden ist.
  // (Vorher: Anmeldung als "Broadcaster" über den Socket mit dem Stream-Key aus /api/auth/me —
  // der dort gar nicht enthalten ist → Server meldete "Ungültiger Stream-Key" und der Stream
  // wurde sofort wieder beendet.)
  const joinChat = () => { try { socket && socket.emit('join_stream', me.id); } catch {} };
  joinChat();
  _bse._onReconnect = () => { if (_bse.live) joinChat(); };
  if (socket) socket.on('connect', _bse._onReconnect);

  // ── Ein durchgehender Recorder, jede Sekunde ein Stück per HTTPS an den Server ──
  // (vorher: alle 2 s ein neuer Recorder + Versand über den Socket → Lücken, und über
  // Cloudflare/Proxys kamen die großen Socket-Nachrichten oft gar nicht an)
  const startRun = () => {
    if (!_bse.live || !_bse.outputStream) return;
    let rec;
    try { rec = new MediaRecorder(_bse.outputStream, recOpts); } catch (e) { console.warn('[stream] recorder', e); showToast(tr({en:'Recording failed: ',de:'Aufnahme fehlgeschlagen: '}) + e.message, 'error'); return; }
    const run = (crypto.randomUUID ? crypto.randomUUID() : String(Date.now()) + Math.random().toString(36).slice(2)).replace(/[^\w-]/g, '');
    let seq = 0;
    _bse.run = run;
    rec.ondataavailable = (ev) => { if (ev.data && ev.data.size && _bse.run === run) _bseQueue(run, seq++, ev.data); };
    rec.onerror = (ev) => { console.warn('[stream] recorder error', ev.error); if (_bse.live) setTimeout(startRun, 1000); };
    rec.start(1000);
    _bse.recorder = rec;
  };
  _bse.live = true;
  _bse.queue = []; _bse.sending = false; _bse.failStreak = 0;
  startRun();
  // Bildschirm wieder aktiv / Netz zurück → falls der Recorder gestoppt wurde, neu starten
  _bse._onVis = () => { if (_bse.live && _bse.recorder && _bse.recorder.state === 'inactive') startRun(); };
  document.addEventListener('visibilitychange', _bse._onVis);
  return true;
}

// Sende-Warteschlange: Stücke strikt in Reihenfolge, mit Wiederholung bei Netzfehlern
function _bseQueue(run, seq, blob) {
  _bse.queue.push({ run, seq, blob, tries: 0 });
  // Hängt die Leitung zu weit hinterher (> 20 s), alte Stücke verwerfen statt ewig nachzuliefern
  if (_bse.queue.length > 20) { _bse.queue.splice(0, _bse.queue.length - 20); }
  _bseSend();
}
async function _bseSend() {
  if (_bse.sending) return;
  _bse.sending = true;
  const token = localStorage.getItem('nxd_token');
  while (_bse.live && _bse.queue.length) {
    const item = _bse.queue[0];
    try {
      const r = await fetch(`/api/live/ingest?run=${encodeURIComponent(item.run)}&seq=${item.seq}`, { method: 'POST', headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/octet-stream' }, body: item.blob });
      if (r.ok) { _bse.queue.shift(); _bse.failStreak = 0; _bseStatus('ok'); continue; }
      if (r.status === 409) { _bseStatus('ended'); _bse.queue = []; break; } // Stream wurde serverseitig beendet
      if (r.status === 403 || r.status === 401) { const d = await r.json().catch(() => ({})); showToast(d.error || tr({en:'Live stream not allowed',de:'Livestream nicht erlaubt'}), 'error'); _bseStopBroadcast(); break; }
      throw new Error('HTTP ' + r.status);
    } catch (e) {
      _bse.failStreak++;
      _bseStatus('retry');
      if (++item.tries > 8) _bse.queue.shift();
      await new Promise(res => setTimeout(res, Math.min(4000, 400 * _bse.failStreak)));
    }
  }
  _bse.sending = false;
}
function _bseStatus(st) {
  // Statusanzeige in den sichtbaren Studio-Tab einsetzen (Handy oder PC)
  let el = document.getElementById('nx-live-net');
  if (!el) {
    const slot = [...document.querySelectorAll('.nx-live-net-slot')].find(x => x.offsetParent !== null) || document.querySelector('.nx-live-net-slot');
    if (!slot) return;
    el = document.createElement('span'); el.id = 'nx-live-net'; slot.appendChild(el);
  }
  if (el.dataset.state === st && el.innerHTML) return;
  el.dataset.state = st;
  el.innerHTML = st === 'ok' ? `<i class="fas fa-circle"></i> ${tr({en:'Live – connection good',de:'Live – Verbindung gut'})}`
    : st === 'retry' ? `<i class="fas fa-triangle-exclamation"></i> ${tr({en:'Connection unstable – reconnecting…',de:'Verbindung instabil – verbinde neu …'})}`
    : `<i class="fas fa-stop"></i> ${tr({en:'Stream ended',de:'Stream beendet'})}`;
}

async function _bseStopBroadcast() {
  _bse.live = false;
  _bse.run = null; _bse.queue = [];
  if (_bse._onVis) { document.removeEventListener('visibilitychange', _bse._onVis); _bse._onVis = null; }
  clearTimeout(_bse.segTimer);
  if (_bse.recorder && _bse.recorder.state !== 'inactive') {
    try { _bse.recorder.ondataavailable = null; _bse.recorder.onstop = null; _bse.recorder.stop(); } catch(e) {}
  }
  _bse.recorder = null;
  if (_bse._onReconnect) { socket.off('connect', _bse._onReconnect); _bse._onReconnect = null; }
  if (_bse._onBroadcastError) { socket.off('stream_broadcast_error', _bse._onBroadcastError); _bse._onBroadcastError = null; }
  _bse.live = false;
  await apiPost('/api/streams/stop').catch(() => {});
}

// ── MOBILE TAB ──────────────────────────────────────────────
let _mstreamCamStream = null;
let _mstreamFacing = 'user';

async function _mstreamEnsurePreview() {
  try {
    if (_mstreamCamStream) { _mstreamCamStream.getTracks().forEach(t => t.stop()); }
    _mstreamCamStream = await navigator.mediaDevices.getUserMedia({
      video: { facingMode: _mstreamFacing, width: { ideal: 1280 }, height: { ideal: 720 } },
      audio: true
    });
    const video = document.getElementById('mstream-preview');
    const placeholder = document.getElementById('mstream-placeholder');
    if (video) {
      video.srcObject = _mstreamCamStream;
      try { await video.play(); } catch(e) {}
    }
    if (placeholder) placeholder.style.display = 'none';
    return true;
  } catch(e) {
    showToast('Kamera/Mikrofon-Zugriff verweigert: ' + e.message, 'error');
    return false;
  }
}

async function mobileStreamFlipCamera() {
  _mstreamFacing = _mstreamFacing === 'user' ? 'environment' : 'user';
  if (_mstreamCamStream) await _mstreamEnsurePreview();
}

async function mobileStreamToggle() {
  const btn = document.getElementById('mstream-go-btn');
  if (_bse.live) {
    await _bseStopBroadcast();
    if (_mstreamCamStream) { _mstreamCamStream.getTracks().forEach(t => t.stop()); _mstreamCamStream = null; }
    if (btn) btn.innerHTML = `<i class="fas fa-broadcast-tower"></i> ${t('btn_go_live')}`;
    refreshCurrentPage();
    return;
  }
  if (!_mstreamCamStream) {
    const ok = await _mstreamEnsurePreview();
    if (!ok) return;
  }
  const title = document.getElementById('mstream-title')?.value || '';
  if (btn) { btn.disabled = true; btn.innerHTML = `<i class="fas fa-spinner fa-spin"></i> ...`; }
  const ok = await _bseStartBroadcast(_mstreamCamStream, title);
  if (btn) btn.disabled = false;
  if (ok) {
    showToast('Du bist jetzt live!', 'success');
    if (btn) btn.innerHTML = `<i class="fas fa-stop"></i> ${t('btn_end_stream')}`;
    switchStudio('stream', document.querySelector('[data-studio="stream"]'));
  } else if (btn) {
    btn.innerHTML = `<i class="fas fa-broadcast-tower"></i> ${t('btn_go_live')}`;
  }
}

