// Kompositing läuft über <canvas> + requestAnimationFrame: Bildschirm/Kamera werden
// gezeichnet, canvas.captureStream() liefert daraus den finalen MediaStream.
const _dstudio = {
  camStream: null,
  screenStream: null,
  canvas: null,
  ctx: null,
  raf: null,
  scene: 'cam',       // 'cam' | 'screen' | 'screen+cam'
  camRect: { x: 0.68, y: 0.66, w: 0.28, h: 0.28 }, // relative Position/Größe der Kamera-Bubble im Overlay
  dragging: false,
  audioCtx: null,
};

