function dstudioInitCanvas() {
  _dstudio.canvas = document.getElementById('dstudio-canvas');
  if (!_dstudio.canvas) return;
  _dstudio.ctx = _dstudio.canvas.getContext('2d');
  // Drag-Handling für die Kamera-Bubble im "screen+cam"-Modus
  let dragOffset = null;
  const getPos = (ev) => {
    const rect = _dstudio.canvas.getBoundingClientRect();
    const clientX = ev.touches ? ev.touches[0].clientX : ev.clientX;
    const clientY = ev.touches ? ev.touches[0].clientY : ev.clientY;
    return { x: (clientX - rect.left) / rect.width, y: (clientY - rect.top) / rect.height };
  };
  const onDown = (ev) => {
    if (_dstudio.scene !== 'screen+cam') return;
    const p = getPos(ev);
    const r = _dstudio.camRect;
    if (p.x >= r.x && p.x <= r.x + r.w && p.y >= r.y && p.y <= r.y + r.h) {
      _dstudio.dragging = true;
      dragOffset = { dx: p.x - r.x, dy: p.y - r.y };
      ev.preventDefault();
    }
  };
  const onMove = (ev) => {
    if (!_dstudio.dragging) return;
    const p = getPos(ev);
    _dstudio.camRect.x = Math.min(1 - _dstudio.camRect.w, Math.max(0, p.x - dragOffset.dx));
    _dstudio.camRect.y = Math.min(1 - _dstudio.camRect.h, Math.max(0, p.y - dragOffset.dy));
    ev.preventDefault();
  };
  const onUp = () => { _dstudio.dragging = false; };
  _dstudio.canvas.addEventListener('mousedown', onDown);
  _dstudio.canvas.addEventListener('mousemove', onMove);
  window.addEventListener('mouseup', onUp);
  _dstudio.canvas.addEventListener('touchstart', onDown, { passive: false });
  _dstudio.canvas.addEventListener('touchmove', onMove, { passive: false });
  window.addEventListener('touchend', onUp);
}

function dstudioDrawLoop() {
  const { ctx, canvas } = _dstudio;
  if (!ctx) return;
  ctx.fillStyle = '#000';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  const drawCover = (videoEl, x, y, w, h) => {
    if (!videoEl || !videoEl.videoWidth) return;
    const vRatio = videoEl.videoWidth / videoEl.videoHeight;
    const tRatio = w / h;
    let sx = 0, sy = 0, sw = videoEl.videoWidth, sh = videoEl.videoHeight;
    if (vRatio > tRatio) { sw = sh * tRatio; sx = (videoEl.videoWidth - sw) / 2; }
    else { sh = sw / tRatio; sy = (videoEl.videoHeight - sh) / 2; }
    ctx.drawImage(videoEl, sx, sy, sw, sh, x, y, w, h);
  };

  if (_dstudio.scene === 'cam' && _dstudio._camVideoEl) {
    drawCover(_dstudio._camVideoEl, 0, 0, canvas.width, canvas.height);
  } else if (_dstudio.scene === 'screen' && _dstudio._screenVideoEl) {
    drawCover(_dstudio._screenVideoEl, 0, 0, canvas.width, canvas.height);
  } else if (_dstudio.scene === 'screen+cam') {
    if (_dstudio._screenVideoEl) drawCover(_dstudio._screenVideoEl, 0, 0, canvas.width, canvas.height);
    if (_dstudio._camVideoEl) {
      const r = _dstudio.camRect;
      const bx = r.x * canvas.width, by = r.y * canvas.height, bw = r.w * canvas.width, bh = r.h * canvas.height;
      ctx.save();
      ctx.beginPath();
      const rad = 14;
      ctx.moveTo(bx + rad, by);
      ctx.arcTo(bx + bw, by, bx + bw, by + bh, rad);
      ctx.arcTo(bx + bw, by + bh, bx, by + bh, rad);
      ctx.arcTo(bx, by + bh, bx, by, rad);
      ctx.arcTo(bx, by, bx + bw, by, rad);
      ctx.closePath();
      ctx.clip();
      drawCover(_dstudio._camVideoEl, bx, by, bw, bh);
      ctx.restore();
      ctx.strokeStyle = '#a83bff';
      ctx.lineWidth = 3;
      ctx.stroke();
    }
  }
  _dstudio.raf = requestAnimationFrame(dstudioDrawLoop);
}

function _dstudioHidePlaceholder() {
  const ph = document.getElementById('dstudio-placeholder');
  if (ph) ph.style.display = 'none';
  if (!_dstudio.raf) { dstudioInitCanvas(); dstudioDrawLoop(); }
}
// ─── Teil: client/app/320-video-bewerben.js ───

async function dstudioToggleCam() {
  const btn = document.getElementById('dsrc-cam-btn');
  if (_dstudio.camStream) {
    _dstudio.camStream.getTracks().forEach(t => t.stop());
    _dstudio.camStream = null; _dstudio._camVideoEl = null;
    if (btn) btn.innerHTML = `<i class="fas fa-video"></i> Kamera aktivieren`;
    return;
  }
  try {
    _dstudio.camStream = await navigator.mediaDevices.getUserMedia({ video: { width: { ideal: 1280 }, height: { ideal: 720 } }, audio: true });
    const v = document.createElement('video');
    v.srcObject = _dstudio.camStream; v.muted = true; v.playsInline = true;
    await v.play().catch(()=>{});
    _dstudio._camVideoEl = v;
    if (btn) btn.innerHTML = `<i class="fas fa-check"></i> Kamera aktiv`;
    _dstudioHidePlaceholder();
  } catch(e) { showToast('Kamera-Zugriff verweigert: ' + e.message, 'error'); }
}

async function dstudioToggleScreen() {
  const btn = document.getElementById('dsrc-screen-btn');
  if (_dstudio.screenStream) {
    _dstudio.screenStream.getTracks().forEach(t => t.stop());
    _dstudio.screenStream = null; _dstudio._screenVideoEl = null;
    if (btn) btn.innerHTML = `<i class="fas fa-desktop"></i> Bildschirm teilen`;
    return;
  }
  try {
    _dstudio.screenStream = await navigator.mediaDevices.getDisplayMedia({ video: true, audio: true });
    const v = document.createElement('video');
    v.srcObject = _dstudio.screenStream; v.muted = true; v.playsInline = true;
    await v.play().catch(()=>{});
    _dstudio._screenVideoEl = v;
    if (btn) btn.innerHTML = `<i class="fas fa-check"></i> Bildschirm aktiv`;
    // Wenn der Nutzer die Freigabe über die Browser-eigene Leiste beendet:
    _dstudio.screenStream.getVideoTracks()[0].addEventListener('ended', () => {
      _dstudio.screenStream = null; _dstudio._screenVideoEl = null;
      if (btn) btn.innerHTML = `<i class="fas fa-desktop"></i> Bildschirm teilen`;
    });
    _dstudioHidePlaceholder();
  } catch(e) { showToast('Bildschirmfreigabe abgebrochen', 'error'); }
}

function dstudioSetScene(scene) {
  _dstudio.scene = scene;
  ['cam','screen','screen+cam'].forEach(s => {
    const b = document.getElementById('dscene-' + s);
    if (b) b.classList.toggle('active', s === scene);
  });
  _dstudioHidePlaceholder();
}

async function dstudioToggleLive() {
  const btn = document.getElementById('dstudio-go-btn');
  if (_bse.live) {
    await _bseStopBroadcast();
    if (btn) btn.innerHTML = `<i class="fas fa-broadcast-tower"></i> ${t('btn_go_live')}`;
    refreshCurrentPage();
    return;
  }
  if (!_dstudio._camVideoEl && !_dstudio._screenVideoEl) {
    showToast('Aktiviere zuerst Kamera und/oder Bildschirm', 'error');
    return;
  }
  if (!_dstudio.canvas) dstudioInitCanvas();
  if (!_dstudio.raf) dstudioDrawLoop();

  const canvasStream = _dstudio.canvas.captureStream(30);
  // Ton: bevorzugt Kamera-Mikrofon, sonst Bildschirm-Audio (falls geteilt)
  const audioTrack = (_dstudio.camStream && _dstudio.camStream.getAudioTracks()[0]) ||
                      (_dstudio.screenStream && _dstudio.screenStream.getAudioTracks()[0]);
  const finalStream = new MediaStream([...canvasStream.getVideoTracks(), ...(audioTrack ? [audioTrack] : [])]);

  const title = document.getElementById('dstream-title')?.value || '';
  if (btn) { btn.disabled = true; btn.innerHTML = `<i class="fas fa-spinner fa-spin"></i> ...`; }
  const ok = await _bseStartBroadcast(finalStream, title);
  if (btn) btn.disabled = false;
  if (ok) {
    showToast('Du bist jetzt live!', 'success');
    if (btn) btn.innerHTML = `<i class="fas fa-stop"></i> ${t('btn_end_stream')}`;
    switchStudio('stream', document.querySelector('[data-studio="stream"]'));
  } else if (btn) {
    btn.innerHTML = `<i class="fas fa-broadcast-tower"></i> ${t('btn_go_live')}`;
  }
}

