// ==================== AD SYSTEM ====================
// ==================== AD SYSTEM ====================
window._adActive = false;

async function shouldShowAd() {
  if (currentUser?.isPremium || currentUser?.isAdmin) return false; // Premium users never get ads
  // ~65% chance to show ad (YouTube-like balance)
  return Math.random() < 0.65;
}

// Stoppt JEDE laufende Werbung sofort (Video-Werbung, Werbeblock im Livestream, Shorts-Werbung).
// Bugfix: Beim Wechsel auf eine andere Seite lief der Ton der Werbung weiter, weil das
// Werbe-<video> im (nur versteckten) Player hing und nie angehalten wurde.
function nxStopAllAds() {
  try { if (typeof window._nxAdAbort === 'function') window._nxAdAbort(); } catch (e) {}
  window._nxAdAbort = null;
  document.querySelectorAll('#nxd-ad-overlay video, #lv-ad video, video[data-nx-ad]').forEach(v => {
    try { v.pause(); v.muted = true; v.removeAttribute('src'); v.load(); } catch (e) {}
  });
  document.getElementById('nxd-ad-overlay')?.remove();
  const lvAd = document.getElementById('lv-ad');
  if (lvAd) { lvAd.hidden = true; lvAd.innerHTML = ''; }
  window._adActive = false;
}

function _nxAdFmt(sec) { sec = Math.max(0, Math.ceil(sec || 0)); return Math.floor(sec / 60) + ':' + String(sec % 60).padStart(2, '0'); }

// Holt einen Werbeblock: 1 Werbung, oder 2–3 kurze hintereinander (wie bei YouTube)
async function _nxFetchAdPod() {
  let list = [];
  try { const pod = await apiGet('/api/ads/pod'); list = (pod && pod.ads || []).filter(a => a && a.videoPath); } catch (e) {}
  if (!list.length) { try { const a = await apiGet('/api/ads/random'); if (a && a.videoPath) list = [a]; } catch (e) {} }
  return list;
}

async function showVideoAd(videoEl, position = 'pre') {
  if (window._adActive) return;
  if (!videoEl) return;
  if (currentUser?.isPremium || currentUser?.isAdmin) return;
  window._adActive = true; // sofort sperren, damit kein zweiter Block parallel startet

  const pod = await _nxFetchAdPod();
  // Kein Ad verfügbar -> Video MUSS trotzdem weiterlaufen.
  // Inzwischen weg-navigiert? -> nichts mehr anzeigen.
  if (!pod.length || !videoEl.isConnected || document.getElementById('main-video') !== videoEl) {
    window._adActive = false;
    if (videoEl.isConnected) videoEl.play().catch(() => {});
    return;
  }

  videoEl.pause();
  // On mobile, climb up to find a properly sized container
  const wrapper = videoEl.closest('.watch-player-wrapper') || videoEl.closest('[class*="player"]') || videoEl.parentElement;
  if (!wrapper) { window._adActive = false; videoEl.play().catch(() => {}); return; }
  wrapper.style.position = 'relative';
  wrapper.style.overflow = 'hidden';
  document.getElementById('nxd-ad-overlay')?.remove();

  const multi = pod.length > 1;
  const podTotal = pod.reduce((s, a) => s + (a.duration || 0), 0);
  const overlay = document.createElement('div');
  overlay.id = 'nxd-ad-overlay';
  overlay.className = 'nx-ad';
  overlay.innerHTML = `
    <video id="nxd-ad-video" data-nx-ad="1" playsinline muted></video>
    <div class="nx-ad-click" id="nxd-ad-clickzone"></div>
    <div class="nx-ad-top">
      <span class="nx-ad-badge"><i class="fas fa-rectangle-ad"></i> <span id="nxd-ad-label">${tr({en:'Ad',de:'Werbung'})}</span></span>
      <button class="nx-ad-premium" type="button" id="nxd-ad-premium"><i class="fas fa-crown"></i> ${tr({en:'Go ad-free',de:'Werbefrei werden'})}</button>
    </div>
    <div class="nx-ad-bottom">
      <div class="nx-ad-info">
        <div class="nx-ad-kicker" id="nxd-ad-kicker"></div>
        <div class="nx-ad-title" id="nxd-ad-title"></div>
        <a class="nx-ad-visit" id="nxd-ad-visit" target="_blank" rel="noopener noreferrer sponsored" hidden>${tr({en:'Visit website',de:'Website besuchen'})} <i class="fas fa-arrow-up-right-from-square"></i></a>
      </div>
      <div class="nx-ad-ctrl">
        <span class="nx-ad-count" id="nxd-ad-countdown"></span>
        <button class="nx-ad-skip" id="nxd-ad-skip-btn" type="button" hidden>${tr({en:'Skip',de:'Überspringen'})} <i class="fas fa-forward-step"></i></button>
      </div>
    </div>
    <div class="nx-ad-progress">${pod.map((_, i) => `<span style="flex:${multi && podTotal ? Math.max(1, pod[i].duration || 1) : 1}"><i id="nxd-ad-seg-${i}"></i></span>`).join('')}</div>`;
  wrapper.appendChild(overlay);

  const adVideo = overlay.querySelector('#nxd-ad-video');
  const countdown = overlay.querySelector('#nxd-ad-countdown');
  const skipBtn = overlay.querySelector('#nxd-ad-skip-btn');
  const visit = overlay.querySelector('#nxd-ad-visit');
  let idx = -1, aborted = false, podDone = false;
  let cur = null, started = false, ended = false, elapsed = 0, ticker = null, watchdog = null, safety = null;

  const clearTimers = () => { clearInterval(ticker); clearTimeout(watchdog); clearTimeout(safety); };
  const teardown = () => {
    clearTimers();
    try { adVideo.pause(); adVideo.removeAttribute('src'); adVideo.load(); } catch (e) {}
    overlay.remove();
    window._adActive = false;
    if (window._nxAdAbort === abort) window._nxAdAbort = null;
  };
  const finishPod = () => {
    if (podDone) return; podDone = true;
    teardown();
    // Nur weiterspielen, wenn man noch auf DIESEM Video ist
    if (!aborted && videoEl.isConnected && document.getElementById('main-video') === videoEl) videoEl.play().catch(() => {});
  };
  function abort() { aborted = true; podDone = true; teardown(); }
  window._nxAdAbort = abort;

  const endAd = (skipped) => {
    if (ended || !cur) return; ended = true;
    clearTimers();
    const seg = document.getElementById('nxd-ad-seg-' + idx); if (seg) seg.style.width = '100%';
    apiPost('/api/ads/' + cur.id + (skipped ? '/skip' : '/complete'), { impToken: cur.impToken }).catch(() => {});
    playNext();
  };

  function playNext() {
    if (aborted) return;
    idx++;
    if (idx >= pod.length) return finishPod();
    cur = pod[idx]; started = false; ended = false; elapsed = 0;
    const skipAfter = cur.skipAfter || 5;
    // sehr kurze Werbung (≤ Skip-Zeit + 1 s) ist – wie bei YouTube – nicht überspringbar
    const skippable = !(cur.duration && cur.duration <= skipAfter + 1);
    overlay.querySelector('#nxd-ad-label').textContent = multi ? tr({en:`Ad ${idx + 1} of ${pod.length}`,de:`Werbung ${idx + 1} von ${pod.length}`}) : tr({en:'Ad',de:'Werbung'});
    overlay.querySelector('#nxd-ad-kicker').textContent = cur.promotedByName ? tr({en:'Sponsored · ',de:'Gesponsert · '}) + cur.promotedByName : tr({en:'Sponsored',de:'Gesponsert'});
    overlay.querySelector('#nxd-ad-title').textContent = decodeServerEntities(cur.title || '');
    if (cur.clickUrl) { visit.href = cur.clickUrl; visit.hidden = false; } else { visit.hidden = true; visit.removeAttribute('href'); }
    skipBtn.hidden = true;
    countdown.hidden = false;
    countdown.textContent = skippable ? skipInLabel(skipAfter) : '';
    window._adClickUrl = cur.clickUrl || null;

    adVideo.src = cur.videoPath;
    adVideo.muted = false;
    adVideo.play().catch(() => { adVideo.muted = true; adVideo.play().catch(() => {}); });

    ticker = setInterval(() => {
      if (!started || adVideo.paused) return;
      elapsed++;
      const left = (adVideo.duration || cur.duration || 0) - adVideo.currentTime;
      if (skippable && elapsed >= skipAfter) { countdown.hidden = true; skipBtn.hidden = false; }
      else if (skippable) countdown.textContent = skipInLabel(Math.max(0, skipAfter - elapsed));
      else countdown.textContent = _nxAdFmt(left);
    }, 1000);
    // Werbung startet nicht (hängender Stream) -> nach 15 s weiter, statt schwarzem Bild
    watchdog = setTimeout(() => { if (!started && adVideo.readyState < 2) endAd(true); }, 15000);
    safety = setTimeout(() => endAd(true), 180000);
  }

  adVideo.addEventListener('playing', () => {
    if (!cur || started) return;
    started = true;
    // Einblendung erst zählen (und abrechnen), wenn die Werbung tatsächlich läuft
    apiPost('/api/ads/' + cur.id + '/impression', { impToken: cur.impToken }).catch(() => {});
  });
  adVideo.addEventListener('timeupdate', () => {
    if (adVideo.currentTime > 0) started = true;
    const seg = document.getElementById('nxd-ad-seg-' + idx);
    if (seg && adVideo.duration > 0) seg.style.width = Math.min(100, adVideo.currentTime / adVideo.duration * 100) + '%';
  });
  adVideo.addEventListener('ended', () => endAd(false));
  // Werbedatei kaputt -> überspringen, Hauptvideo läuft weiter
  adVideo.addEventListener('error', () => { if (adVideo.getAttribute('src')) endAd(true); });
  skipBtn.addEventListener('click', (e) => { e.stopPropagation(); endAd(true); });
  overlay.querySelector('#nxd-ad-premium').addEventListener('click', (e) => { e.stopPropagation(); abort(); navigateTo('premium'); });
  visit.addEventListener('click', (e) => { e.stopPropagation(); if (cur) apiPost('/api/ads/' + cur.id + '/click').catch(() => {}); });
  overlay.querySelector('#nxd-ad-clickzone').addEventListener('click', () => {
    if (cur && cur.clickUrl) { apiPost('/api/ads/' + cur.id + '/click').catch(() => {}); window.open(cur.clickUrl, '_blank', 'noopener'); }
    else if (adVideo.paused) adVideo.play().catch(() => {}); else adVideo.pause();
  });

  playNext();
}

async function maybeShowPreRollAd(videoEl) {
  if (!videoEl) return;
  // Premium/Admin: keine Werbung, aber Video trotzdem starten (der Ad-Flow hat den Autoplay übernommen)
  if (currentUser?.isPremium || currentUser?.isAdmin) { videoEl.play().catch(()=>{}); return; }
  if (await shouldShowAd()) {
    await showVideoAd(videoEl, 'pre');
  } else {
    videoEl.play().catch(()=>{});
  }
}

// Mid-Rolls: kurze Videos (1–8 Min.) höchstens eine Werbepause in der Mitte,
// lange Videos (ab 8 Min.) etwa alle 7–9 Minuten eine (wie bei YouTube).
function setupMidRollAds(videoEl) {
  if (!videoEl) return;
  if (currentUser?.isPremium || currentUser?.isAdmin) return;
  let points = null;
  const plan = (dur) => {
    if (!dur || !isFinite(dur) || dur < 60) return [];
    if (dur < 480) return Math.random() < 0.4 ? [dur * (0.4 + Math.random() * 0.2)] : [];
    const list = [];
    for (let t = 360 + Math.random() * 120; t < dur - 60; t += 420 + Math.random() * 120) {
      if (Math.random() < 0.55) list.push(t);
    }
    return list;
  };
  videoEl.addEventListener('timeupdate', async () => {
    if (window._adActive) return;
    if (!points) { if (!videoEl.duration) return; points = plan(videoEl.duration); }
    if (!points.length) return;
    const now = videoEl.currentTime;
    const due = points.filter(p => now >= p);
    if (!due.length) return;
    // Beim Vorspulen über mehrere Punkte nur EINE Werbepause zeigen
    points = points.filter(p => now < p);
    if (now - due[due.length - 1] > 15 && videoEl.seeking) return;
    videoEl.pause();
    await showVideoAd(videoEl, 'mid');
  });
}
