// ==================== MONETARISIERUNG BEANTRAGEN ====================
async function checkMonetizationEligibility() {
  if (!currentUser) return false;
  try {
    // v1.80: Werte kommen vom Server (echte Watchtime angemeldeter, bestätigter Zuschauer der
    // letzten 100 Tage) statt einer Schätzung aus Aufrufen × 3 Minuten
    const st = await apiGet('/api/users/me/monetization/stats');
    const { recentViews, watchTimeHours, hasViews, hasWatchTime } = st;
    return { eligible: hasViews || hasWatchTime, hasViews, hasWatchTime, recentViews, watchTimeHours: Math.round(watchTimeHours * 10) / 10 };
  } catch { return false; }
}

// ==================== VIDEO CONTROLS ====================
function setVideoSpeed(speed) {
  if (speed > 2 && !(currentUser && (currentUser.isPremium || currentUser.isAdmin))) {
    showToast(tr({en:'Speeds above 2x are a Premium feature.',de:'Geschwindigkeiten über 2x sind ein Premium-Feature.'}), 'info');
    return;
  }
  const v = document.getElementById('main-video');
  if (v) v.playbackRate = speed;
  document.querySelectorAll('.speed-btn').forEach(btn => {
    const isActive = parseFloat(btn.dataset.speed) === speed;
    btn.style.background = isActive ? 'var(--purple-main)' : 'var(--bg-secondary)';
    btn.style.color = isActive ? 'white' : 'var(--text-secondary)';
    btn.classList.toggle('active', isActive);
  });
}

function toggleSubtitles() {
  const v = document.getElementById('main-video');
  if (!v) return;
  const btn = document.getElementById('subtitle-btn');
  const tracks = Array.from(v.textTracks);
  const active = tracks.find(t => t.mode === 'showing');
  if (active) {
    // Cycle: off
    tracks.forEach(t => t.mode = 'hidden');
    btn.style.background = 'var(--bg-secondary)'; btn.style.color = 'var(--text-secondary)';
    btn.innerHTML = '<i class="fas fa-closed-captioning"></i> CC';
    showToast('Untertitel aus', 'info');
    return;
  }
  if (tracks.length > 1) {
    // Show picker
    showSubtitlePicker(v, btn, tracks);
    return;
  }
  if (tracks.length === 1) {
    tracks[0].mode = 'showing';
    btn.style.background = 'var(--purple-main)'; btn.style.color = 'white';
    btn.innerHTML = `<i class="fas fa-closed-captioning"></i> ${escHtml(tracks[0].label || 'CC')}`;
    return;
  }
  showToast(tr({en:'No subtitles available. Go to Studio → Subtitles to generate.',de:'Keine Untertitel verfügbar. Im Studio → Untertitel generieren.'}), 'info');
}

function showSubtitlePicker(vid, btn, tracks) {
  document.getElementById('sub-picker')?.remove();
  const picker = document.createElement('div');
  picker.id = 'sub-picker';
  picker.style.cssText = 'position:absolute;z-index:200;background:var(--bg-card);border:1px solid var(--border);border-radius:10px;box-shadow:0 8px 24px rgba(0,0,0,0.5);overflow:hidden;min-width:140px';
  const btnRect = btn.getBoundingClientRect();
  picker.style.top = (btnRect.bottom + 6) + 'px';
  picker.style.left = btnRect.left + 'px';
  picker.innerHTML = Array.from(tracks).map(tr => `
    <div data-h-click="h_app_setSubtitleTrack_9862" data-hv-click="${nxHv(String(escHtml(escJs(tr.language||tr.label))))}"
         style="padding:9px 14px;font-size:13px;cursor:pointer;display:flex;align-items:center;gap:8px;transition:background 0.1s">
      <i class="fas fa-language" style="color:var(--purple-light)"></i> ${escHtml(tr.label || tr.language)}
    </div>`).join('');
  document.body.appendChild(picker);
  setTimeout(() => document.addEventListener('click', () => picker.remove(), { once: true }), 0);
}

function setSubtitleTrack(langOrLabel) {
  const vid = document.getElementById('main-video');
  const btn = document.getElementById('subtitle-btn');
  if (!vid) return;
  Array.from(vid.textTracks).forEach(t => {
    t.mode = (t.language === langOrLabel || t.label === langOrLabel) ? 'showing' : 'hidden';
  });
  const active = Array.from(vid.textTracks).find(t => t.mode === 'showing');
  if (btn && active) { btn.style.background = 'var(--purple-main)'; btn.style.color = 'white'; btn.innerHTML = `<i class="fas fa-closed-captioning"></i> ${escHtml(active.label || active.language)}`; }
}

