// ==================== PREMIUM PAYMENT FLOW (Real PayPal + Klarna) ====================

let _paypalSDKLoaded = false;
let _paypalLoadedClientId = null;

async function loadPaypalSDK(clientId) {
  if (!clientId || clientId === 'YOUR_PAYPAL_CLIENT_ID') return;
  if (_paypalSDKLoaded && _paypalLoadedClientId === clientId) return;
  if (_paypalSDKLoaded && _paypalLoadedClientId !== clientId) {
    document.querySelector('script[src*="paypal.com/sdk"]')?.remove();
    if (window.paypal) try { delete window.paypal; } catch {}
    _paypalSDKLoaded = false;
  }
  return new Promise((resolve) => {
    const s = document.createElement('script');
    s.src = 'https://www.paypal.com/sdk/js?client-id=' + clientId + '&currency=EUR&components=buttons';
    s.onload = () => { _paypalSDKLoaded = true; _paypalLoadedClientId = clientId; resolve(); };
    s.onerror = () => resolve();
    document.head.appendChild(s);
  });
}

