// _openPaymentModal → siehe public/js/shop-pro.js


async function _payWithGooglePay(type, videoId, videoTitle, amount) {
  // FIX K-GPAY: Server verifiziert Google-Pay-Zahlungen (noch) nicht echt und lehnt
  // diese Routen serverseitig ab. Statt einen falschen Erfolg vorzutäuschen, weisen
  // wir direkt auf PayPal/Klarna hin.
  showToast(tr({en:'Google Pay is available in the normal checkout (when payments are enabled).',de:'Google Pay gibt es in der normalen Kasse (sobald Zahlungen aktiv sind).'}), 'error');
  return;
  try {
    const paymentRequest = {
      apiVersion: 2, apiVersionMinor: 0,
      allowedPaymentMethods: [{
        type: 'CARD',
        parameters: { allowedAuthMethods: ['PAN_ONLY','CRYPTOGRAM_3DS'], allowedCardNetworks: ['MASTERCARD','VISA'] },
        tokenizationSpecification: { type: 'PAYMENT_GATEWAY', parameters: { gateway: 'example', gatewayMerchantId: 'norynex' } }
      }],
      merchantInfo: { merchantId: '01234567890123456789', merchantName: 'Norynex' },
      transactionInfo: { totalPriceStatus: 'FINAL', totalPriceLabel: 'Gesamt', totalPrice: (amount||3.99).toFixed(2), currencyCode: 'EUR', countryCode: 'DE' }
    };
    if (!window.google?.payments?.api) {
      await new Promise((res, rej) => {
        const s = document.createElement('script');
        s.src = 'https://pay.google.com/gp/p/js/pay.js';
        s.onload = res; s.onerror = rej;
        document.head.appendChild(s);
      });
    }
    const client = new window.google.payments.api.PaymentsClient({ environment: 'TEST' });
    const isReady = await client.isReadyToPay({ apiVersion: 2, apiVersionMinor: 0, allowedPaymentMethods: paymentRequest.allowedPaymentMethods });
    if (!isReady.result) { showToast('Google Pay ist auf diesem Gerät nicht verfügbar', 'error'); return; }
    const paymentData = await client.loadPaymentData(paymentRequest);
    // Process
    if (type === 'balance') {
      await apiPost('/api/balance/topup', { amount });
      showToast('€' + (amount||0).toFixed(2) + (tr({en:' added to your balance!',de:' Guthaben aufgeladen!'})), 'success');
      renderBalancePage();
    } else {
      await apiPost('/api/payment/googlepay/process', { type, videoId, videoTitle, amount, paymentToken: paymentData.paymentMethodData.tokenizationData.token });
      document.getElementById('norynex-payment-modal')?.remove();
      if (type === 'premium') { currentUser.isPremium = true; localStorage.setItem('nxd_user', JSON.stringify(currentUser)); renderAuthSection(); renderPremiumPage(); }
      showToast('Zahlung erfolgreich!', 'success');
    }
  } catch(e) {
    if (e.statusCode === 'CANCELED') return;
    showToast('Google Pay: ' + (e.message||'Fehler'), 'error');
  }
}

async function _payWithApplePay(type, videoId, videoTitle, amount) {
  // FIX K-APAY: Server verifiziert Apple-Pay-Zahlungen (noch) nicht echt und lehnt
  // diese Routen serverseitig ab. Statt einen falschen Erfolg vorzutäuschen, weisen
  // wir direkt auf PayPal/Klarna hin.
  showToast(tr({en:'Apple Pay is available in the normal checkout (when payments are enabled).',de:'Apple Pay gibt es in der normalen Kasse (sobald Zahlungen aktiv sind).'}), 'error');
  return;
  if (!window.ApplePaySession || !window.ApplePaySession.canMakePayments()) {
    showToast('Apple Pay ist nur auf Apple-Geräten mit Safari verfügbar', 'error'); return;
  }
  try {
    const request = {
      countryCode: 'DE', currencyCode: 'EUR',
      supportedNetworks: ['visa','masterCard','amex'],
      merchantCapabilities: ['supports3DS'],
      total: { label: type === 'premium' ? 'Norynex Premium' : 'Norynex Werbung', amount: (amount||3.99).toFixed(2) }
    };
    const session = new window.ApplePaySession(3, request);
    session.onvalidatemerchant = async (e) => {
      try {
        const merchantSession = await apiPost('/api/payment/applepay/validate', { validationURL: e.validationURL });
        session.completeMerchantValidation(merchantSession);
      } catch { session.abort(); }
    };
    session.onpaymentauthorized = async (e) => {
      try {
        if (type === 'balance') {
          await apiPost('/api/balance/topup', { amount });
          session.completePayment(window.ApplePaySession.STATUS_SUCCESS);
          showToast('€' + (amount||0).toFixed(2) + (tr({en:' added to your balance!',de:' Guthaben aufgeladen!'})), 'success');
          renderBalancePage();
        } else {
          await apiPost('/api/payment/applepay/process', { type, videoId, videoTitle, amount, token: e.payment.token });
          session.completePayment(window.ApplePaySession.STATUS_SUCCESS);
          document.getElementById('norynex-payment-modal')?.remove();
          if (type === 'premium') { currentUser.isPremium = true; localStorage.setItem('nxd_user', JSON.stringify(currentUser)); renderAuthSection(); renderPremiumPage(); }
          showToast('Apple Pay Zahlung erfolgreich!', 'success');
        }
      } catch { session.completePayment(window.ApplePaySession.STATUS_FAILURE); showToast('Apple Pay Fehler', 'error'); }
    };
    session.begin();
  } catch(e) { showToast('Apple Pay: ' + (e.message||'Fehler'), 'error'); }
}

async function _payWithKlarna(type, videoId, videoTitle, adBudget) {
  const btn = document.getElementById('klarna-pay-btn');
  if (btn) { btn.disabled = true; btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Klarna...'; }
  const planKey = window._selectedPremiumPlan || 'monthly';
  try {
    const session = await apiPost('/api/payment/klarna/create-session', { type, plan: planKey, videoId, adBudget });
    if (!window.Klarna) {
      await new Promise((resolve, reject) => {
        const s = document.createElement('script');
        s.src = 'https://x.klarnacdn.net/kp/lib/v1/api.js';
        s.onload = resolve; s.onerror = reject;
        document.head.appendChild(s);
      });
    }
    window.Klarna.Payments.init({ client_token: session.clientToken });
    window.Klarna.Payments.load({ container: '#klarna-pay-btn', payment_method_category: 'pay_later' }, {}, (res) => {
      if (res.show_form) {
        window.Klarna.Payments.authorize({ payment_method_category: 'pay_later' }, {}, async (authRes) => {
          if (authRes.approved) {
            try {
              await apiPost('/api/payment/klarna/authorize', { authToken: authRes.authorization_token, type, plan: planKey, videoId, videoTitle, adBudget });
              document.getElementById('norynex-payment-modal')?.remove();
              if (type === 'premium') {
                currentUser.isPremium = true;
                localStorage.setItem('nxd_user', JSON.stringify(currentUser));
                showToast('\uD83C\uDF89 Premium aktiviert!', 'success');
                renderAuthSection(); renderPremiumPage();
              } else { showToast('\u2705 Video beworben!', 'success'); }
            } catch(e) { showToast('Klarna Fehler: ' + e.message, 'error'); }
          } else {
            showToast('Klarna abgebrochen.', 'error');
            if (btn) { btn.disabled = false; btn.innerHTML = 'Klarna bezahlen'; }
          }
        });
      }
    });
  } catch(e) {
    showToast('Klarna Fehler: ' + e.message, 'error');
    if (btn) { btn.disabled = false; btn.innerHTML = 'Klarna bezahlen'; }
  }
}

async function redeemGiftCode() {
  const code = document.getElementById('gift-code-input')?.value.trim().toUpperCase();
  if (!code) { showToast('Bitte Code eingeben', 'error'); return; }
  if (!currentUser) { openAuthModal('login'); return; }
  try {
    // Validate code first (don't activate yet)
    const result = await apiPost('/api/users/premium/giftcode/validate', { code });
    {
      if (result.user) currentUser = result.user;
      currentUser.isPremium = true;
      localStorage.setItem('nxd_user', JSON.stringify(currentUser));
      document.getElementById('norynex-payment-modal')?.remove();
      NXD.play('premium_buy');
      showToast('Premium aktiviert!', 'success');
      renderAuthSection();
    }
  } catch(e) { showToast(e.message, 'error'); }
}

// Kündigung nach § 312k BGB: Button „Verträge hier kündigen“ → Bestätigungsseite mit
// „Jetzt kündigen“ → sofortige Bestätigung auf dem Bildschirm und per E-Mail.
async function cancelSubscription() {
  if (!currentUser) { openAuthModal('login'); return; }
  const u = currentUser;
  const active = !!(u.isPremium && !u.premiumCancelled);
  _nxModal('nx-cancel', `
    <div class="nxm-head"><div class="nxm-head-ico"><i class="fas fa-file-signature"></i></div><div class="nxm-head-text"><h3>${tr({ en: 'Cancel contracts here', de: 'Verträge hier kündigen' })}</h3><p>${tr({ en: 'Norynex Premium', de: 'Norynex Premium' })}</p></div><button class="nxm-x" data-h-click="h_app__nxCloseModal_10095" aria-label="Schließen"><i class="fas fa-xmark"></i></button></div>
    <div class="nxm-body">
      ${active ? `
      <div class="nx-cancel-kv">
        <div><span>${tr({ en: 'Account', de: 'Konto' })}</span><b>@${escHtml(u.username || '')}</b></div>
        <div><span>${tr({ en: 'Contract', de: 'Vertrag' })}</span><b>Norynex Premium${u.premiumPlan ? ' (' + escHtml(u.premiumPlan) + ')' : ''}</b></div>
        <div><span>${tr({ en: 'Type of cancellation', de: 'Art der Kündigung' })}</span><b>${tr({ en: 'Ordinary, at the end of the paid period', de: 'Ordentlich, zum Ende der bezahlten Laufzeit' })}</b></div>
      </div>
      <p style="font-size:13.5px;color:var(--text-secondary);line-height:1.55;margin:0">${tr({ en: 'Premium stays active until the end of the period you already paid for. There will be no further charges. You will receive a confirmation by email.', de: 'Premium bleibt bis zum Ende des bereits bezahlten Zeitraums aktiv. Es erfolgen keine weiteren Abbuchungen. Du erhältst eine Bestätigung per E-Mail.' })}</p>
      <button class="co-btn co-btn--primary co-btn--block" id="nx-cancel-go" style="background:#dc2626">${tr({ en: 'Cancel now', de: 'Jetzt kündigen' })}</button>`
      : `<p style="margin:0;color:var(--text-secondary)">${u.premiumCancelled ? tr({ en: 'Your Premium is already cancelled. It ends on ', de: 'Dein Premium ist bereits gekündigt. Es endet am ' }) + (u.premiumExpiresAt ? new Date(u.premiumExpiresAt).toLocaleDateString(cl() === 'de' ? 'de-DE' : 'en-GB') : '–') + '.' : tr({ en: 'You currently have no active paid contract. Premium plans end automatically and do not renew.', de: 'Du hast aktuell keinen laufenden kostenpflichtigen Vertrag. Premium-Pakete enden automatisch und verlängern sich nicht.' })}</p>
      <p style="margin:12px 0 0;font-size:13px;color:var(--text-muted)">${tr({ en: 'Questions? Contact support@norynex.com', de: 'Fragen? Schreib an support@norynex.com' })}</p>`}
    </div>`);
  const go = document.getElementById('nx-cancel-go');
  if (!go) return;
  go.onclick = async () => {
    go.disabled = true;
    try {
      const result = await apiPost('/api/payment/cancel-subscription', {});
      currentUser.premiumCancelled = true;
      currentUser.premiumExpiresAt = result.premiumExpiresAt;
      currentUser.isPremium = true;
      localStorage.setItem('nxd_user', JSON.stringify(currentUser));
      const until = new Date(result.premiumExpiresAt).toLocaleDateString(cl() === 'de' ? 'de-DE' : 'en-GB');
      document.querySelector('#nx-cancel .nxm-body').innerHTML = `<div class="nx-acct-status is-ok"><i class="fas fa-circle-check"></i><div><b>${tr({ en: 'Cancellation received', de: 'Kündigung eingegangen' })}</b><small>${tr({ en: 'Received on ', de: 'Eingegangen am ' })}${new Date().toLocaleString(cl() === 'de' ? 'de-DE' : 'en-GB')} · ${tr({ en: 'Premium ends on ', de: 'Premium endet am ' })}${until}</small></div></div>
        <p style="font-size:13px;color:var(--text-secondary)">${tr({ en: 'We have sent you a confirmation by email.', de: 'Wir haben dir eine Bestätigung per E-Mail geschickt.' })}</p>
        <button class="co-btn co-btn--sec co-btn--block" data-h-click="h_app__nxCloseModal_10120">OK</button>`;
      renderAuthSection(); if (currentPage === 'premium') renderPremiumPage();
    } catch (e) { showToast(e.message, 'error'); go.disabled = false; }
  };
}
