// ==================== @ERWÄHNUNGEN AUTOCOMPLETE ====================
// Leichtgewichtiges Dropdown, das beim Tippen von "@" im Kommentarfeld
// passende Nutzer vorschlägt. Nutzt /api/users (bereits öffentlich, nur
// id/username/displayName/alias) und cached die Liste kurz im Speicher.
let _mentionUserCache = null;
let _mentionUserCacheTs = 0;
const MENTION_CACHE_TTL = 60000; // 1 Minute

async function getMentionUserList() {
  const now = Date.now();
  if (_mentionUserCache && now - _mentionUserCacheTs < MENTION_CACHE_TTL) return _mentionUserCache;
  try {
    _mentionUserCache = await apiGet('/api/users');
    _mentionUserCacheTs = now;
  } catch { _mentionUserCache = _mentionUserCache || []; }
  return _mentionUserCache;
}

// Findet den @-Suchbegriff direkt vor der Caret-Position, falls vorhanden.
function getActiveMentionQuery(textarea) {
  const pos = textarea.selectionStart;
  const text = textarea.value.slice(0, pos);
  const match = text.match(/(?:^|\s)@([a-zA-Z0-9_]{0,30})$/);
  if (!match) return null;
  return { query: match[1], start: pos - match[1].length - 1 };
}

async function handleMentionInput(textarea) {
  const active = getActiveMentionQuery(textarea);
  if (!active) { closeMentionDropdown(); return; }
  const users = await getMentionUserList();
  const q = active.query.toLowerCase();
  const matches = users.filter(u =>
    (u.username || '').toLowerCase().includes(q) ||
    (u.displayName || '').toLowerCase().includes(q) ||
    (u.alias || '').replace('@','').toLowerCase().includes(q)
  ).slice(0, 6);
  if (!matches.length) { closeMentionDropdown(); return; }
  renderMentionDropdown(textarea, matches, active.start);
}

function handleMentionKeydown(event, textarea) {
  const dropdown = document.getElementById('mention-dropdown');
  if (!dropdown) return;
  const items = dropdown.querySelectorAll('.mention-item');
  if (!items.length) return;
  let idx = [...items].findIndex(i => i.classList.contains('active'));
  if (event.key === 'ArrowDown') {
    event.preventDefault();
    idx = (idx + 1) % items.length;
    items.forEach(i => i.classList.remove('active'));
    items[idx].classList.add('active');
    items[idx].scrollIntoView({ block: 'nearest' });
  } else if (event.key === 'ArrowUp') {
    event.preventDefault();
    idx = idx <= 0 ? items.length - 1 : idx - 1;
    items.forEach(i => i.classList.remove('active'));
    items[idx].classList.add('active');
    items[idx].scrollIntoView({ block: 'nearest' });
  } else if (event.key === 'Enter' || event.key === 'Tab') {
    const target = idx >= 0 ? items[idx] : items[0];
    if (target) { event.preventDefault(); target.click(); }
  } else if (event.key === 'Escape') {
    closeMentionDropdown();
  }
}

function renderMentionDropdown(textarea, matches, mentionStart) {
  closeMentionDropdown();
  const dropdown = document.createElement('div');
  dropdown.id = 'mention-dropdown';
  dropdown.style.cssText = 'position:absolute;z-index:200;background:var(--bg-card);border:1px solid var(--border-light);border-radius:10px;box-shadow:0 8px 24px rgba(0,0,0,0.35);max-height:220px;overflow-y:auto;min-width:200px;padding:4px';
  matches.forEach((u, i) => {
    const handle = (u.username || u.alias?.replace('@','') || u.displayName || '').replace(/\s/g,'');
    const item = document.createElement('div');
    item.className = 'mention-item' + (i === 0 ? ' active' : '');
    item.style.cssText = 'display:flex;align-items:center;gap:8px;padding:7px 10px;border-radius:7px;cursor:pointer;font-size:13px';
    item.innerHTML = `${buildAvatarHtml(u, 24, {})}<span style="font-weight:600">${escHtml(u.displayName || u.username)}</span><span style="color:var(--text-muted);font-size:12px">@${escHtml(handle)}</span>`;
    item.addEventListener('mouseenter', () => { dropdown.querySelectorAll('.mention-item').forEach(el => el.classList.remove('active')); item.classList.add('active'); });
    item.addEventListener('click', () => insertMention(textarea, handle, mentionStart));
    dropdown.appendChild(item);
  });
  const style = document.createElement('style');
  style.textContent = `#mention-dropdown .mention-item.active{background:var(--bg-secondary)}`;
  dropdown.appendChild(style);

  const parent = textarea.parentElement;
  if (parent && getComputedStyle(parent).position === 'static') parent.style.position = 'relative';
  dropdown.style.left = '0';
  dropdown.style.top = (textarea.offsetTop + textarea.offsetHeight + 4) + 'px';
  (parent || document.body).appendChild(dropdown);
}

function insertMention(textarea, handle, mentionStart) {
  const pos = textarea.selectionStart;
  const before = textarea.value.slice(0, mentionStart);
  const after = textarea.value.slice(pos);
  const insertion = '@' + handle + ' ';
  textarea.value = before + insertion + after;
  const newPos = (before + insertion).length;
  textarea.focus();
  textarea.setSelectionRange(newPos, newPos);
  closeMentionDropdown();
}

function closeMentionDropdown() {
  const el = document.getElementById('mention-dropdown');
  if (el) el.remove();
}
// Dropdown schließen, wenn irgendwo anders geklickt wird
document.addEventListener('click', (e) => {
  if (!e.target.closest('#mention-dropdown') && e.target.tagName !== 'TEXTAREA') closeMentionDropdown();
});
// Enter-Taste im Support-Chat-Eingabefeld sendet die Nachricht
document.addEventListener('keydown', (e) => {
  if (e.key === 'Enter' && e.target.id === 'support-chat-input') sendSupportChatMessage();
});

function formatViews(n) {
  if (!n) return '0';
  if (n >= 1e9) return (n/1e9).toFixed(1) + 'Mrd.';
  if (n >= 1e6) return (n/1e6).toFixed(1) + ' Mio.';
  if (n >= 1e3) return (n/1e3).toFixed(1) + 'K';
  return String(n);
}

function formatDuration(sec) {
  if (!sec) return '';
  // Video-Dauer kommt vom Browser/ffprobe oft als Float (z.B. 149.978s). Erst runden,
  // DANN in Minuten/Sekunden aufteilen — sonst rutscht der Nachkommaanteil in die Anzeige
  // durch (Bug: "2:29.97800000000001" statt "2:30").
  const total = Math.round(sec);
  const m = Math.floor(total / 60), s = total % 60;
  return `${m}:${String(s).padStart(2, '0')}`;
}

function timeAgo(dateStr) {
  if (!dateStr) return '';
  const now = new Date(), d = new Date(dateStr);
  const diff = (now - d) / 1000;
  if (diff < 60) return t('time_just_now');
  if (diff < 3600) return `${Math.floor(diff/60)} ${t('time_min')}`;
  if (diff < 86400) return `${Math.floor(diff/3600)} ${t('time_hrs')}`;
  if (diff < 2592000) return `${Math.floor(diff/86400)} ${t('time_days')}`;
  if (diff < 31536000) return `${Math.floor(diff/2592000)} ${t('time_months')}`;
  return `${Math.floor(diff/31536000)} ${t('time_years')}`;
}
// ─── Teil: client/app/410-api-helpers.js ───

// ==================== API HELPERS ====================
// ==================== ECHTES WATCHTIME-TRACKING (Recommendation Engine) ====================
// Sendet alle paar Sekunden die tatsächlich geschaute Zeit (nicht nur "Video geklickt") an den Server,
// damit der Algorithmus lernt: viel Sport geschaut -> mehr Sport vorgeschlagen, auch wenn nur kurz Gaming geklickt wurde.
// Zusätzlich wird die Gesamtlänge des Videos mitgeschickt: ein komplett angesehener 15s-Short ist ein
// genauso starkes Signal wie ein komplett angesehenes 10-Minuten-Video, nicht 40x schwächer.
let _rwtTimer = null;
let _rwtPendingSeconds = 0;
let _rwtVideoId = null;
let _rwtVideoEl = null;

function _rwtFlush(sync) {
  if (_rwtPendingSeconds <= 0 || !_rwtVideoId) return;
  const seconds = _rwtPendingSeconds;
  const videoId = _rwtVideoId;
  const totalDuration = (_rwtVideoEl && isFinite(_rwtVideoEl.duration)) ? _rwtVideoEl.duration : null;
  _rwtPendingSeconds = 0;
  const token = localStorage.getItem('nxd_token');
  if (!token) return; // ohne Login kein persönliches Profil
  if (sync && navigator.sendBeacon) {
    // Beim Verlassen der Seite: sendBeacon kann keine Auth-Header setzen, daher Token im Body mitschicken
    // Cookie wird automatisch mitgeschickt; CSRF-Wert im Body, weil sendBeacon keine Kopfzeilen kann
    const blob = new Blob([JSON.stringify({ seconds, totalDuration, _csrf: nxCsrfToken() })], { type: 'application/json' });
    navigator.sendBeacon(`${API}/api/videos/${videoId}/watchtime`, blob);
  } else {
    apiPost(`/api/videos/${videoId}/watchtime`, { seconds, totalDuration }).catch(() => {});
  }
}

function stopRecommendationWatchTracking() {
  if (_rwtTimer) { clearInterval(_rwtTimer); _rwtTimer = null; }
  _rwtFlush(true);
  _rwtVideoId = null;
  _rwtVideoEl = null;
}

function startRecommendationWatchTracking(vid, videoId) {
  // Vorherigen Tracker (falls Video gewechselt wurde, ohne dass die Watch-Page komplett neu geladen wurde) beenden
  stopRecommendationWatchTracking();
  _rwtVideoId = videoId;
  _rwtVideoEl = vid;
  _rwtPendingSeconds = 0;
  _rwtTimer = setInterval(() => {
    if (!vid.paused && !vid.ended && !vid.seeking) {
      _rwtPendingSeconds += 1;
    }
    if (_rwtPendingSeconds >= 5) _rwtFlush(false); // alle ~5s echte Sekunden senden
  }, 1000);
  // Beim Verlassen/Wechseln der Seite letztes Delta nicht verlieren
  window.addEventListener('beforeunload', () => _rwtFlush(true));
  window.addEventListener('pagehide', () => _rwtFlush(true));
}

async function apiGet(url) {
  const token = localStorage.getItem('nxd_token');
  const headers = {};
  if (token) headers['Authorization'] = `Bearer ${token}`;
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 8000);
  try {
    const res = await fetch(API + url, { headers, signal: controller.signal });
    clearTimeout(timer);
    const data = await res.json();
    if (!res.ok) throw new Error(data.error || 'Fehler');
    return data;
  } catch(e) {
    clearTimeout(timer);
    throw e;
  }
}

async function apiPost(url, body = {}, _totpRetry = 0) {
  const token = localStorage.getItem('nxd_token');
  const headers = { 'Content-Type': 'application/json' };
  if (token) headers['Authorization'] = `Bearer ${token}`;
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 8000);
  try {
    const res = await fetch(API + url, { method: 'POST', headers, body: JSON.stringify(body), signal: controller.signal });
    clearTimeout(timer);
    const data = await res.json();
    // Geld-relevante Aktionen (Auszahlungen) verlangen einen 2FA-Code: nachfragen und erneut senden
    if (!res.ok && data.code === 'TOTP_REQUIRED' && _totpRetry < 2) {
      const code = await nxAskCode(tr({ en: 'Enter the 6-digit code from your authenticator app:', de: 'Gib den 6-stelligen Code aus deiner Authenticator-App ein:' }));
      if (code && code.trim()) return apiPost(url, { ...body, totpToken: code.trim() }, _totpRetry + 1);
    }
    if (!res.ok) throw new Error(data.error || 'Fehler');
    return data;
  } catch(e) { clearTimeout(timer); throw e; }
}

async function apiPatch(url, body) {
  const token = localStorage.getItem('nxd_token');
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 8000);
  try {
    const res = await fetch(url, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json', ...(token ? { 'Authorization': 'Bearer ' + token } : {}) },
      body: JSON.stringify(body),
      signal: controller.signal
    });
    clearTimeout(timer);
    const data = await res.json();
    if (!res.ok) throw new Error(data.error || 'Fehler');
    return data;
  } catch(e) { clearTimeout(timer); throw e; }
}

async function apiPut(url, body = {}) {
  const token = localStorage.getItem('nxd_token');
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 8000);
  try {
    const res = await fetch(url, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json', ...(token ? { Authorization: `Bearer ${token}` } : {}) },
      body: JSON.stringify(body),
      signal: controller.signal
    });
    clearTimeout(timer);
    const data = await res.json();
    if (!res.ok) throw new Error(data.error || 'Fehler');
    return data;
  } catch(e) { clearTimeout(timer); throw e; }
}

async function apiDel(url) {
  const token = localStorage.getItem('nxd_token');
  const headers = {};
  if (token) headers['Authorization'] = `Bearer ${token}`;
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 8000);
  try {
    const res = await fetch(API + url, { method: 'DELETE', headers, signal: controller.signal });
    clearTimeout(timer);
    const data = await res.json();
    if (!res.ok) throw new Error(data.error || 'Fehler');
    return data;
  } catch(e) { clearTimeout(timer); throw e; }
}
