// ==================== WEB PUSH (PWA) ====================
// Funktioniert auf jeder Plattform, deren Browser die Push-API unterstützt
// (Android Chrome/Firefox, Desktop Chrome/Edge/Firefox). iOS Safari unterstützt
// Web Push nur, wenn die Seite bereits zum Homescreen hinzugefügt wurde – dort
// blendet isPushSupported() den Schalter dann automatisch aus statt einen Fehler
// zu zeigen.
function isPushSupported() {
  return 'serviceWorker' in navigator && 'PushManager' in window && window.isSecureContext;
}

function _urlBase64ToUint8Array(base64String) {
  const padding = '='.repeat((4 - base64String.length % 4) % 4);
  const base64 = (base64String + padding).replace(/-/g, '+').replace(/_/g, '/');
  const rawData = atob(base64);
  const outputArray = new Uint8Array(rawData.length);
  for (let i = 0; i < rawData.length; i++) outputArray[i] = rawData.charCodeAt(i);
  return outputArray;
}

async function getPushSubscriptionStatus() {
  if (!isPushSupported()) return 'unsupported';
  if (Notification.permission === 'denied') return 'denied';
  try {
    const reg = await navigator.serviceWorker.ready;
    const sub = await reg.pushManager.getSubscription();
    return sub ? 'subscribed' : 'unsubscribed';
  } catch { return 'unsubscribed'; }
}

// Aktiviert Web Push: fragt Browser-Berechtigung an, abonniert über die Push-API
// und meldet das Abo beim Server an (verknüpft mit dem eingeloggten Nutzer).
async function enablePushNotifications() {
  if (!isPushSupported()) {
    showToast(tr({en:'Push notifications are not supported on this device/browser.',de:'Push-Benachrichtigungen werden auf diesem Gerät/Browser nicht unterstützt.'}), 'error');
    return false;
  }
  if (!currentUser) {
    showToast(tr({en:'Please sign in first.',de:'Bitte melde dich zuerst an.'}), 'error');
    return false;
  }
  try {
    const perm = await Notification.requestPermission();
    if (perm !== 'granted') {
      showToast(tr({en:'Notification permission denied.',de:'Berechtigung für Benachrichtigungen abgelehnt.'}), 'error');
      return false;
    }
    const { publicKey } = await apiGet('/api/push/vapid-public-key');
    const reg = await navigator.serviceWorker.ready;
    let sub = await reg.pushManager.getSubscription();
    if (!sub) {
      sub = await reg.pushManager.subscribe({
        userVisibleOnly: true,
        applicationServerKey: _urlBase64ToUint8Array(publicKey)
      });
    }
    await apiPost('/api/push/subscribe', { subscription: sub.toJSON ? sub.toJSON() : sub });
    localStorage.setItem('nxd_push_enabled', 'true');
    showToast(tr({en:'Push notifications enabled',de:'Push-Benachrichtigungen aktiviert'}), 'success');
    return true;
  } catch(e) {
    showToast(tr({en:'Could not enable push notifications.',de:'Push-Benachrichtigungen konnten nicht aktiviert werden.'}), 'error');
    return false;
  }
}

// Deaktiviert Web Push: hebt das Browser-Abo auf und entfernt es beim Server.
async function disablePushNotifications() {
  try {
    if (isPushSupported()) {
      const reg = await navigator.serviceWorker.ready;
      const sub = await reg.pushManager.getSubscription();
      if (sub) {
        await apiPost('/api/push/unsubscribe', { endpoint: sub.endpoint }).catch(() => {});
        await sub.unsubscribe();
      }
    }
  } catch {}
  localStorage.setItem('nxd_push_enabled', 'false');
  showToast(tr({en:'Push notifications disabled',de:'Push-Benachrichtigungen deaktiviert'}), 'info');
}

// Toggle für die Einstellungsseite: schaltet je nach aktuellem Status um.
async function togglePushNotifications(checkboxEl) {
  if (checkboxEl.checked) {
    const ok = await enablePushNotifications();
    if (!ok) checkboxEl.checked = false;
  } else {
    await disablePushNotifications();
  }
}

// ==================== MEINE MELDUNGEN (Report-Status für Nutzer) ====================
// Zeigt dem Nutzer den Bearbeitungsstatus seiner eigenen Meldungen – bisher war
// das nur intern im Admin-Panel sichtbar. "Deine Meldung wird bearbeitet" statt
// völliger Funkstille nach dem Absenden einer Meldung.
function _nxdEscapeHtml(str) {
  const div = document.createElement('div');
  div.textContent = str == null ? '' : String(str);
  return div.innerHTML;
}

function _reportStatusMeta(status) {
  const en = cl() === 'en';
  switch (status) {
    case 'resolved':
      return { label: en ? 'Completed' : 'Erledigt', color: '#10b981', icon: 'check-circle' };
    case 'dismissed':
      return { label: en ? 'Rejected' : 'Abgelehnt', color: '#6b7280', icon: 'times-circle' };
    case 'takedown':
      return { label: en ? 'Content removed' : 'Inhalt entfernt', color: '#10b981', icon: 'shield-alt' };
    default:
      return { label: en ? 'Being reviewed' : 'Wird bearbeitet', color: '#f59e0b', icon: 'clock' };
  }
}

const _reportTypeLabel = (type, en) => ({
  video: en ? 'Video' : 'Video',
  comment: en ? 'Comment' : 'Kommentar',
  user: en ? 'User' : 'Nutzer'
}[type] || type);

async function openMyReportsModal() {
  if (!currentUser) { openAuthModal('login'); return; }
  document.getElementById('nxd-myreports-modal')?.remove();
  const en = cl() === 'en';
  const overlay = document.createElement('div');
  overlay.id = 'nxd-myreports-modal';
  overlay.style.cssText = 'position:fixed;inset:0;z-index:99999;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,0.88);backdrop-filter:blur(8px);padding:16px;box-sizing:border-box';
  overlay.innerHTML = `
    <div style="background:var(--bg-card);border-radius:20px;max-width:480px;width:100%;max-height:82vh;display:flex;flex-direction:column;border:1px solid rgba(168,59,255,0.35);box-shadow:0 32px 80px rgba(0,0,0,0.7);overflow:hidden">
      <div style="padding:20px 22px 16px;border-bottom:1px solid var(--border-light);display:flex;justify-content:space-between;align-items:center;flex-shrink:0">
        <h2 style="margin:0;color:white;font-size:18px;font-weight:800"><i class="fas fa-flag" style="color:var(--purple-light);margin-right:8px"></i>${en ? 'My Reports' : 'Meine Meldungen'}</h2>
        <button data-h-click="h_app_getElementById_12296" style="background:rgba(255,255,255,0.08);border:none;color:white;width:32px;height:32px;border-radius:50%;cursor:pointer;font-size:18px;flex-shrink:0">&times;</button>
      </div>
      <div id="nxd-myreports-body" style="padding:16px 22px 22px;overflow-y:auto">
        <div style="text-align:center;padding:30px 0;color:var(--text-muted)"><i class="fas fa-spinner fa-spin"></i></div>
      </div>
    </div>`;
  document.body.appendChild(overlay);

  try {
    const myReports = await apiGet('/api/reports/mine');
    const body = document.getElementById('nxd-myreports-body');
    if (!body) return;
    if (!myReports.length) {
      body.innerHTML = `<div style="text-align:center;padding:30px 10px;color:var(--text-muted)">
        <i class="fas fa-flag" style="font-size:28px;opacity:0.4;margin-bottom:10px;display:block"></i>
        ${en ? "You haven't filed any reports yet." : 'Du hast bisher keine Meldungen abgegeben.'}
      </div>`;
      return;
    }
    body.innerHTML = myReports.map(r => {
      const meta = _reportStatusMeta(r.status);
      const date = new Date(r.createdAt).toLocaleDateString(en ? 'en-US' : 'de-DE', { day: '2-digit', month: '2-digit', year: 'numeric' });
      const targetText = r.targetRemoved
        ? (en ? 'Content no longer available' : 'Inhalt nicht mehr verfügbar')
        : (r.targetLabel || (en ? 'Content' : 'Inhalt'));
      return `
        <div style="background:var(--bg-secondary);border-radius:14px;padding:14px 16px;margin-bottom:10px;border:1px solid var(--border-light)">
          <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:10px;margin-bottom:8px">
            <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:var(--text-muted)">${_reportTypeLabel(r.type, en)} · ${date}</div>
            <div style="flex-shrink:0;font-size:11px;font-weight:700;padding:4px 10px;border-radius:50px;background:${meta.color}22;color:${meta.color};white-space:nowrap"><i class="fas fa-${meta.icon}" style="margin-right:5px"></i>${meta.label}</div>
          </div>
          <div style="font-size:14px;font-weight:600;color:var(--text-primary);margin-bottom:4px">${_nxdEscapeHtml(targetText)}</div>
          ${r.reason ? `<div style="font-size:13px;color:var(--text-muted)">${en ? 'Reason' : 'Grund'}: ${_nxdEscapeHtml(r.reason)}</div>` : ''}
        </div>`;
    }).join('');
  } catch(e) {
    const body = document.getElementById('nxd-myreports-body');
    if (body) body.innerHTML = `<div style="text-align:center;padding:30px 10px;color:#ef4444">${en ? 'Could not load your reports.' : 'Deine Meldungen konnten nicht geladen werden.'}</div>`;
  }
}

