// ==================== PRIVACY HELPERS ====================
function _getPrivacySetting(user, key) {
  if (user && user.privacySettings && user.privacySettings[key] === false) return false;
  return true;
}

function updateToggleStyle(input) {
  if (input && input.closest && input.closest('.st-switch')) return; // neue Schalter werden per CSS gestylt
  const checked = input.checked;
  const wrap = input.nextElementSibling;
  if (!wrap) return;
  wrap.style.background = checked ? 'var(--purple-main)' : 'var(--bg-card)';
  const thumb = wrap.querySelector('span');
  if (thumb) thumb.style.left = checked ? '22px' : '2px';
}
