async function sendMessage(userId) { navigateTo('messages', userId); }

const DM = { partnerId: null, convs: [], typingT: null, lastTypingSent: 0 };

function _dmTime(iso) {
  const d = new Date(iso), now = new Date();
  const sameDay = d.toDateString() === now.toDateString();
  if (sameDay) return d.toLocaleTimeString(cl() === 'de' ? 'de-DE' : undefined, { hour: '2-digit', minute: '2-digit' });
  const diffDays = (now - d) / 86400000;
  if (diffDays < 6) return d.toLocaleDateString(cl() === 'de' ? 'de-DE' : undefined, { weekday: 'short' });
  return d.toLocaleDateString(cl() === 'de' ? 'de-DE' : undefined, { day: '2-digit', month: '2-digit', year: '2-digit' });
}
function _dmDayLabel(iso) {
  const d = new Date(iso), now = new Date();
  const y = new Date(now); y.setDate(now.getDate() - 1);
  if (d.toDateString() === now.toDateString()) return tr({en:'Today',de:'Heute'});
  if (d.toDateString() === y.toDateString()) return tr({en:'Yesterday',de:'Gestern'});
  return d.toLocaleDateString(cl() === 'de' ? 'de-DE' : undefined, { weekday: 'long', day: 'numeric', month: 'long' });
}
function nxJoinDmRoom() {
  try { const tk = localStorage.getItem('nxd_token'); if (socket && tk && currentUser) socket.emit('join_dm', tk); } catch {}
}
async function nxRefreshDmBadge() {
  if (!currentUser) { document.querySelectorAll('.dm-badge').forEach(b => b.hidden = true); return; }
  try {
    const { unread } = await apiGet('/api/dm/unread');
    document.querySelectorAll('.dm-badge').forEach(b => { b.textContent = unread > 99 ? '99+' : unread; b.hidden = !unread; });
  } catch {}
}

