function _dmDrawConvs(q = '') {
  const box = document.getElementById('dm-convs');
  if (!box) return;
  const needle = q.trim().toLowerCase();
  const list = DM.convs.filter(c => !needle || (c.partner.displayName || '').toLowerCase().includes(needle) || (c.partner.username || '').toLowerCase().includes(needle));
  if (!list.length) {
    box.innerHTML = `<div class="dm-empty">${needle ? tr({en:'No matches',de:'Keine Treffer'}) : tr({en:'No conversations yet. Open a channel and tap “Message” to start one.',de:'Noch keine Unterhaltungen. Öffne einen Kanal und tippe auf „Nachricht“, um eine zu starten.'})}</div>`;
    return;
  }
  box.innerHTML = list.map(c => `
    <button class="dm-conv${c.partner.id === DM.partnerId ? ' is-active' : ''}${c.unread ? ' is-unread' : ''}" data-action="navigateTo" data-args="${nxA('messages', String(c.partner.id))}">
      <div class="dm-conv-av">${buildAvatarHtml(c.partner, 44, { noVideo: true })}</div>
      <div class="dm-conv-main">
        <div class="dm-conv-top"><span class="dm-conv-name">${escHtml(c.partner.displayName || c.partner.username)}</span><span class="dm-conv-time">${_dmTime(c.last.createdAt)}</span></div>
        <div class="dm-conv-bottom"><span class="dm-conv-last">${c.last.fromMe ? tr({en:'You: ',de:'Du: '}) : ''}${escHtml(c.last.text.slice(0, 80))}</span>${c.unread ? `<span class="dm-conv-unread">${c.unread}</span>` : ''}</div>
      </div>
    </button>`).join('');
}

