// ==================== SPLASH SCREEN (Mobile / TV only) ====================
(function initSplashScreen() {
  const isMobileOrTV = /Android|iPhone|iPad|iPod|Mobile|SmartTV|Tizen|WebOS|HbbTV|SMART-TV/i.test(navigator.userAgent)
    || (window.innerWidth <= 768 && 'ontouchstart' in window);

  // Ein Sofort-Splash wurde bereits inline in index.html gerendert (kein Warten auf
  // dieses Skript nötig -> kein Größen-"Sprung" beim Start auf installierten PWAs).
  // Hier übernehmen wir nur noch die Animation bzw. entfernen ihn auf Desktop sofort.
  const existing = document.getElementById('nxd-splash');

  if (!isMobileOrTV) {
    if (existing) existing.remove();
    return;
  }

  let splash = existing;
  if (!splash) {
    // Fallback, falls das inline Splash-Markup aus irgendeinem Grund fehlt
    splash = document.createElement('div');
    splash.id = 'nxd-splash';
    splash.style.cssText = `
      position:fixed;inset:0;z-index:99999;
      background:var(--bg-card);
      display:flex;flex-direction:column;align-items:center;justify-content:center;
    `;
    splash.innerHTML = `
      <div id="nxd-splash-logo" style="opacity:0;transform:scale(0.7)">
        <div style="position:relative;display:flex;align-items:center;justify-content:center">
          <div id="nxd-splash-ring" style="position:absolute;width:150px;height:150px;border-radius:50%;border:3px solid transparent;border-top-color:#a83bff;border-right-color:#c77dff;opacity:0"></div>
          <img alt="" src="/assets/norynex-logo.png" width="120" height="120" style="box-shadow:none;background:transparent;display:block"
            data-h-error="h_app_getElementById_12900">
          <div id="nxd-splash-fallback" style="display:none;width:120px;height:120px;border-radius:22px;background:linear-gradient(var(--accent),var(--accent));align-items:center;justify-content:center;font-size:44px;font-weight:900;color:white;box-shadow:0 8px 40px rgba(0,0,0,0.25)">N</div>
        </div>
      </div>
      <div id="nxd-splash-text" style="margin-top:24px;opacity:0;transform:translateY(16px)">
        <div style="font-size:28px;font-weight:800;color:white;text-align:center;letter-spacing:-0.5px">Norynex</div>
        <div style="font-size:13px;color:rgba(255,255,255,0.4);text-align:center;margin-top:4px;letter-spacing:2px;text-transform:uppercase">Stream · Entdecken · Teilen</div>
      </div>
      <div id="nxd-splash-dots" style="position:absolute;bottom:48px;opacity:0">
        <div style="display:flex;gap:8px">
          <div style="width:6px;height:6px;border-radius:50%;background:#a83bff"></div>
          <div style="width:6px;height:6px;border-radius:50%;background:#c77dff"></div>
          <div style="width:6px;height:6px;border-radius:50%;background:#c084fc"></div>
        </div>
      </div>
    `;
    document.body.insertBefore(splash, document.body.firstChild);
  }
  // Transitions erst jetzt per JS aktivieren (inline-Version hat bewusst keine
  // CSS-transitions, damit beim allerersten Paint nichts "einschwingt" bevor
  // dieses Skript überhaupt geladen ist).
  splash.style.transition = 'opacity 0.6s ease, transform 0.6s ease';
  const _logoEl = document.getElementById('nxd-splash-logo');
  const _ringEl = document.getElementById('nxd-splash-ring');
  const _textEl = document.getElementById('nxd-splash-text');
  if (_logoEl) _logoEl.style.transition = 'all 0.5s cubic-bezier(0.175,0.885,0.32,1.275)';
  if (_ringEl) _ringEl.style.animation = 'nxd-splash-spin 1.5s linear infinite';
  if (_textEl) _textEl.style.transition = 'all 0.5s ease 0.3s';
  document.querySelectorAll('#nxd-splash-dots > div > div').forEach((dot, i) => {
    dot.style.animation = `nxd-splash-pulse 1.2s ease ${i * 0.2}s infinite`;
    dot.style.transition = 'opacity 0.4s ease 0.6s';
  });
  const _dotsWrap = document.getElementById('nxd-splash-dots');
  if (_dotsWrap) _dotsWrap.style.transition = 'opacity 0.4s ease 0.6s';

  // Keyframes für Ring-Spin & Dot-Pulse (im inline-Splash noch nicht vorhanden)
  if (!document.getElementById('nxd-splash-keyframes')) {
    const style = document.createElement('style');
    style.id = 'nxd-splash-keyframes';
    style.textContent = `
      @keyframes nxd-splash-spin { to { transform: rotate(360deg); } }
      @keyframes nxd-splash-pulse { 0%,100% { opacity:0.3;transform:scale(0.8); } 50% { opacity:1;transform:scale(1.2); } }
    `;
    document.head.appendChild(style);
  }

  // Animate in
  requestAnimationFrame(() => {
    setTimeout(() => {
      const logo = document.getElementById('nxd-splash-logo');
      const ring = document.getElementById('nxd-splash-ring');
      const text = document.getElementById('nxd-splash-text');
      const dots = document.getElementById('nxd-splash-dots');
      if (logo) { logo.style.opacity = '1'; logo.style.transform = 'scale(1)'; }
      if (ring) ring.style.opacity = '0.6';
      if (text) { text.style.opacity = '1'; text.style.transform = 'translateY(0)'; }
      if (dots) dots.style.opacity = '1';


    }, 100);

    // Dismiss after 2s
    setTimeout(() => {
      const s = document.getElementById('nxd-splash');
      if (!s) return;
      s.style.opacity = '0';
      s.style.transform = 'scale(1.05)';
      setTimeout(() => s.remove(), 700);
    }, 2200);
  });
})();

