function renderPartyMembers(members) {
  const el = document.getElementById('party-members-list');
  if (!el) return;
  el.innerHTML = members.map(m => `
    <div style="display:flex;align-items:center;gap:5px;background:rgba(255,255,255,0.06);padding:4px 8px;border-radius:20px;font-size:12px">
      ${m.isHost ? '<i class="fas fa-crown" style="color:#f59e0b;font-size:10px"></i>' : ''}
      <span style="color:white;font-weight:600">${escHtml(m.name)}</span>
    </div>`).join('');
}

function addPartyChatMsg({ userName, message, isSystem }) {
  const el = document.getElementById('party-chat-messages');
  if (!el) return;
  const div = document.createElement('div');
  div.style.cssText = 'font-size:13px;line-height:1.4';
  if (isSystem) {
    div.style.cssText += ';color:rgba(168,59,255,0.7);text-align:center;font-style:italic;font-size:11px';
    div.textContent = message;
  } else {
    div.innerHTML = `<span style="color:#c77dff;font-weight:700">${escHtml(userName)}</span><span style="color:rgba(255,255,255,0.3);margin:0 4px">:</span><span style="color:rgba(255,255,255,0.85)">${escHtml(message)}</span>`;
  }
  el.appendChild(div);
  el.scrollTop = el.scrollHeight;
}

function sendPartyChat() {
  const input = document.getElementById('party-chat-input');
  const msg = input?.value?.trim();
  if (!msg || !_party || !socket || !currentUser) return;
  socket.emit('party_chat', {
    partyId: _party.partyId,
    userId: currentUser.id,
    userName: currentUser.displayName || currentUser.username,
    message: msg
  });
  input.value = '';
}

function partyPlayPause() {
  const vid = document.getElementById('main-video');
  if (!vid || !_party?.isHost) return;
  if (vid.paused) vid.play().catch(()=>{});
  else vid.pause();
  updatePartyPPBtn(!vid.paused);
  socket.emit('party_sync', {
    partyId: _party.partyId,
    currentTime: vid.currentTime,
    playing: !vid.paused,
    hostId: currentUser.id
  });
}

function partySyncNow() {
  const vid = document.getElementById('main-video');
  if (!vid || !_party) return;
  socket.emit('party_sync', {
    partyId: _party.partyId,
    currentTime: vid.currentTime,
    playing: !vid.paused,
    hostId: currentUser.id
  });
  showToast('Alle synchronisiert!', 'success');
}

function updatePartyPPBtn(playing) {
  const btn = document.getElementById('party-pp-btn');
  if (!btn) return;
  btn.innerHTML = playing ? '<i class="fas fa-pause"></i> Pause' : '<i class="fas fa-play"></i> Play';
}

function copyPartyCode() {
  if (!_party) return;
  navigator.clipboard.writeText(_party.partyId).catch(()=>{});
  showToast('Party-Code kopiert!', 'success');
}

function copyPartyLink() {
  if (!_party) return;
  const link = `${location.origin}/watch-party/${_party.partyId}`;
  navigator.clipboard.writeText(link).catch(()=>{});
  showToast('Party-Link kopiert!', 'success');
}

function leaveParty() {
  if (!_party || !socket) return;
  socket.emit('party_leave', { partyId: _party.partyId, userId: currentUser?.id });
  socket.off('party_members');
  socket.off('party_chat_msg');
  socket.off('party_sync');
  socket.off('party_host_changed');
  socket.off('party_state');
  clearInterval(_partySyncInterval);
  _party = null;
  document.getElementById('watch-party-panel')?.remove();
  showToast(tr({en:'Watch Party left',de:'Watch Party verlassen'}), 'success');
}
