// ==================== CLIP FUNCTION ====================
// ==================== VIDEO-DOWNLOAD (nur Premium) ====================
async function downloadVideoPremium(videoId) {
  if (!currentUser) return openAuthModal('login');
  if (!(currentUser.isPremium || currentUser.isAdmin)) {
    // Hinweis passend zur Premium-Funktion anzeigen + zur Premium-Seite führen
    showToast('' + t('download_premium_only') + ' ' + t('prem_feat_download_hint') + '.', 'info');
    setTimeout(() => navigateTo('premium'), 900);
    return;
  }
  try {
    const res = await fetch(API + `/api/videos/${videoId}/download`, {
      headers: { Authorization: `Bearer ${localStorage.getItem('nxd_token')}` }
    });
    if (!res.ok) {
      let msg = 'Fehler';
      try { msg = (await res.json()).error || msg; } catch {}
      throw new Error(msg);
    }
    const cd = res.headers.get('Content-Disposition') || '';
    const m = /filename\*?=(?:UTF-8'')?"?([^";]+)"?/i.exec(cd);
    const filename = m ? decodeURIComponent(m[1]) : 'video.mp4';
    const blob = await res.blob();
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = filename;
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 10000);
    showToast(t('download_started'), 'success');
  } catch (e) { showToast(e.message, 'error'); }
}

// ==================== REMIX ====================
function openRemixModal(videoId, videoTitle, videoPath) {
  document.getElementById('remix-modal-overlay')?.remove();
  const isEN = cl() === 'en';
  const overlay = document.createElement('div');
  overlay.id = 'remix-modal-overlay';
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.7);z-index:10001;display:flex;align-items:center;justify-content:center;padding:16px';
  overlay.innerHTML = `
    <div style="background:var(--bg-secondary);border:1px solid var(--border);border-radius:18px;width:100%;max-width:400px;overflow:hidden;box-shadow:0 20px 60px rgba(0,0,0,0.6)">
      <div style="padding:18px 20px 14px;border-bottom:1px solid var(--border);display:flex;align-items:center;justify-content:space-between">
        <div>
          <div style="font-size:16px;font-weight:800;display:flex;align-items:center;gap:8px"><i class="fas fa-sliders-h" style="color:#f59e0b"></i> Remix</div>
          <div style="font-size:12px;color:var(--text-muted);margin-top:2px">${escHtml(videoTitle)}</div>
        </div>
        <button data-h-click="h_app_getElementById_13340" style="background:rgba(255,255,255,0.07);border:none;color:rgba(255,255,255,0.5);width:32px;height:32px;border-radius:50%;cursor:pointer;font-size:16px;display:flex;align-items:center;justify-content:center">&times;</button>
      </div>
      <div style="padding:20px">
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:20px">
          <!-- Speed Up -->
          <div id="remix-speedup-card" data-h-click="h_app_selectRemixMode_13340" style="border:2px solid var(--border);border-radius:14px;padding:18px 14px;text-align:center;cursor:pointer;transition:all 0.2s;background:transparent">
            <div style="font-size:28px;margin-bottom:8px;color:#f59e0b"><i class="fas fa-bolt"></i></div>
            <div style="font-weight:800;font-size:15px;color:var(--text-primary)">${isEN?'Speed Up':'Speed Up'}</div>
            <div style="font-size:11px;color:var(--text-muted);margin-top:4px">1.25x · ${isEN?'Higher Pitch':'Höherer Ton'}</div>
          </div>
          <!-- Slowed -->
          <div id="remix-slowed-card" data-h-click="h_app_selectRemixMode_13350" style="border:2px solid var(--border);border-radius:14px;padding:18px 14px;text-align:center;cursor:pointer;transition:all 0.2s;background:transparent">
            <div style="font-size:28px;margin-bottom:8px;color:#3b82f6"><i class="fas fa-water"></i></div>
            <div style="font-weight:800;font-size:15px;color:var(--text-primary)">Slowed</div>
            <div style="font-size:11px;color:var(--text-muted);margin-top:4px">0.80x · ${isEN?'Lower Pitch':'Tieferer Ton'}</div>
          </div>
        </div>
        <!-- Preview info -->
        <div id="remix-info" style="background:var(--bg-primary);border-radius:10px;padding:12px 14px;margin-bottom:16px;font-size:13px;color:var(--text-muted);text-align:center">
          ${isEN?'Select a mode to preview':'Wähle einen Modus zur Vorschau'}
        </div>
        <!-- Apply button -->
        <button id="remix-apply-btn" data-h-click="h_app_applyRemix_13361" data-hv-click="${nxHv(String(escJs(videoId)))}" disabled
          style="width:100%;padding:13px;border-radius:12px;border:none;background:var(--purple-main);color:white;font-size:14px;font-weight:700;cursor:pointer;opacity:0.4;transition:opacity 0.2s">
          <i class="fas fa-sliders-h"></i> ${isEN?'Apply Remix':'Remix anwenden'}
        </button>
      </div>
    </div>`;
  overlay.addEventListener('click', e => { if (e.target === overlay) overlay.remove(); });
  document.body.appendChild(overlay);
  window._remixMode = null;
}

function selectRemixMode(mode) {
  window._remixMode = mode;
  const isEN = cl() === 'en';
  const su = document.getElementById('remix-speedup-card');
  const sl = document.getElementById('remix-slowed-card');
  const info = document.getElementById('remix-info');
  const btn = document.getElementById('remix-apply-btn');
  // reset both
  [su, sl].forEach(c => { if(c){ c.style.borderColor='var(--border)'; c.style.background='transparent'; } });
  if (mode === 'speedup') {
    su.style.borderColor = '#f59e0b'; su.style.background = 'rgba(245,158,11,0.08)';
    info.innerHTML = `<i class="fas fa-bolt"></i> <strong>Speed Up</strong> — 1.25x ${isEN?'playback speed':'Wiedergabegeschwindigkeit'} · ${isEN?'higher audio pitch':'höherer Tonhöhe'}`;
    info.style.color = '#f59e0b';
  } else {
    sl.style.borderColor = '#3b82f6'; sl.style.background = 'rgba(59,130,246,0.08)';
    info.innerHTML = `<i class="fas fa-water"></i> <strong>Slowed</strong> — 0.80x ${isEN?'playback speed':'Wiedergabegeschwindigkeit'} · ${isEN?'lower audio pitch':'tieferer Tonhöhe'}`;
    info.style.color = '#3b82f6';
  }
  btn.disabled = false; btn.style.opacity = '1';
}

// ── SoundTouch pitch-shift via AudioWorklet ──────────────────────────────────
// We inline a minimal phase-vocoder worklet so there's no external dependency.
// pitch > 1 = higher, pitch < 1 = lower, speed stays independent.
const _REMIX_WORKLET_CODE = `
// Rauscharmer Pitch-Shifter: zwei gegenläufige Delay-Line-Leseköpfe mit Hann-Crossfade.
// Kein FFT/Phase-Vocoder → keine Phasen-Artefakte, kein Rauschen, konstante Lautstärke
// (die beiden Hann-Fenster summieren sich exakt zu 1).
class PitchShiftProcessor extends AudioWorkletProcessor {
  constructor(opts) {
    super();
    this._pitch = (opts.processorOptions && opts.processorOptions.pitch) || 1.0;
    this._win   = 2048;                       // Fenstergröße in Samples (~43 ms)
    this._size  = 1 << 15;                    // Ringpuffer (Zweierpotenz)
    this._mask  = this._size - 1;
    this._bufs  = [new Float32Array(this._size), new Float32Array(this._size)];
    this._w     = 0;                          // Schreibposition
    this._phase = 0;                          // 0..1 Position im Fenster
    this.port.onmessage = e => { if (e.data.pitch !== undefined) this._pitch = e.data.pitch; };
  }
  _read(buf, pos) {
    const i0 = Math.floor(pos), f = pos - i0;
    const a = buf[i0 & this._mask], b = buf[(i0 + 1) & this._mask];
    return a + (b - a) * f;
  }
  process(inputs, outputs) {
    const input = inputs[0], output = outputs[0];
    if (!output || !output.length) return true;
    const ch = Math.min(output.length, 2);
    const n  = output[0].length;
    const rate = 1 - this._pitch;             // Delay-Drift pro Sample (in Fenstern)
    for (let c = 0; c < ch; c++) {
      const inp = (input && input[c]) || (input && input[0]) || null;
      const buf = this._bufs[c];
      const out = output[c];
      let w = this._w, phase = this._phase;
      for (let i = 0; i < n; i++) {
        buf[w & this._mask] = inp ? inp[i] : 0;
        // zwei Köpfe, um ein halbes Fenster versetzt
        const p1 = phase, p2 = (phase + 0.5) % 1;
        const d1 = p1 * this._win, d2 = p2 * this._win;
        const g1 = 0.5 - 0.5 * Math.cos(2 * Math.PI * p1);
        const g2 = 0.5 - 0.5 * Math.cos(2 * Math.PI * p2);
        out[i] = this._read(buf, w - d1) * g1 + this._read(buf, w - d2) * g2;
        w++;
        phase += rate / this._win;
        if (phase >= 1) phase -= 1; else if (phase < 0) phase += 1;
      }
      if (c === ch - 1) { this._w = w; this._phase = phase; }
    }
    // Mono-Quelle auf zweiten Ausgangskanal spiegeln
    for (let c = ch; c < output.length; c++) output[c].set(output[0]);
    return true;
  }
}
registerProcessor('pitch-shift-processor', PitchShiftProcessor);
`;

async function _loadRemixWorklet(ctx) {
  const blob = new Blob([_REMIX_WORKLET_CODE], { type: 'application/javascript' });
  const url  = URL.createObjectURL(blob);
  await ctx.audioWorklet.addModule(url);
  URL.revokeObjectURL(url);
}

// Effektkette abbauen. reconnectDirect=true → Originalton direkt zum Ausgang (Remix zurücksetzen).
function _remixTeardown(vid, reconnectDirect) {
  try {
    (vid._remixNodes || []).forEach(n => { try { n.disconnect(); } catch(e){} });
    vid._remixNodes = null;
    if (vid._remixSrc) {
      try { vid._remixSrc.disconnect(); } catch(e){}
      if (reconnectDirect && vid._remixCtx) vid._remixSrc.connect(vid._remixCtx.destination);
    }
  } catch(e) { console.warn('Remix teardown', e); }
}

async function applyRemix(videoId) {
  const mode = window._remixMode;
  if (!mode) return;
  const isEN = cl() === 'en';
  const vid  = document.getElementById('main-video');
  if (!vid) { showToast(isEN ? 'No video playing' : 'Kein Video aktiv', 'error'); return; }

  // Alten Effekt-Zweig trennen (Context bleibt offen: ein <video> kann nur EINMAL an einen
  // MediaElementSource gebunden werden und wird nach ctx.close() dauerhaft stumm).
  _remixTeardown(vid);
  document.getElementById('remix-reset-btn')?.remove();

  const speed = mode === 'speedup' ? 1.25 : 0.80;
  // Pitch independent of speed: +3 semitones up or -3 semitones down
  const pitchRatio = mode === 'speedup' ? Math.pow(2, 3/12) : Math.pow(2, -3/12);

  // Keep video at normal speed — pitch node handles the perceptual shift
  vid.playbackRate = speed;

  const applyBtn = document.getElementById('remix-apply-btn');
  if (applyBtn) { applyBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i>'; applyBtn.disabled = true; }

  try {
    let ctx = vid._remixCtx;
    if (!ctx || ctx.state === 'closed') {
      ctx = new (window.AudioContext || window.webkitAudioContext)();
      vid._remixCtx = ctx;
      vid._remixSrc = null;
      vid._remixWorkletLoaded = false;
    }
    window._remixCtx = ctx;
    if (!vid._remixWorkletLoaded) { await _loadRemixWorklet(ctx); vid._remixWorkletLoaded = true; }
    if (!vid._remixSrc) vid._remixSrc = ctx.createMediaElementSource(vid);
    const src   = vid._remixSrc;
    const node  = new AudioWorkletNode(ctx, 'pitch-shift-processor', { processorOptions: { pitch: pitchRatio } });
    // Pegel-Ausgleich: der Pitch-Shifter verliert ~15 % Pegel (Crossfade), das gleichen wir aus.
    // Ein Kompressor/Limiter am Ende verhindert Übersteuern, damit der Song nicht leiser
    // oder verzerrt klingt als das Original.
    const gain  = ctx.createGain();
    gain.gain.value = 1.2;
    const hp = ctx.createBiquadFilter();       // entfernt Gleichanteil/Rumpeln unter 25 Hz
    hp.type = 'highpass'; hp.frequency.value = 25;
    const limiter = ctx.createDynamicsCompressor();
    limiter.threshold.value = -3;  limiter.knee.value = 3;
    limiter.ratio.value = 20;      limiter.attack.value = 0.003; limiter.release.value = 0.15;
    src.disconnect();
    src.connect(node);
    node.connect(hp);
    hp.connect(gain);
    gain.connect(limiter);
    limiter.connect(ctx.destination);
    window._remixNode = node;
    vid._remixNodes = [node, hp, gain, limiter];
    if (ctx.state === 'suspended') await ctx.resume();
  } catch(e) {
    // Fallback: just speed (cross-origin video can't use MediaElementSource)
    console.warn('Remix AudioWorklet failed, falling back:', e);
  }

  document.getElementById('remix-modal-overlay')?.remove();

  showToast(
    mode === 'speedup'
      ? (isEN ? 'Speed Up + higher pitch applied!' : 'Speed Up + höhere Tonlage aktiv!')
      : (isEN ? 'Slowed + lower pitch applied!'    : 'Slowed + tiefere Tonlage aktiv!'),
    'success'
  );

  // Reset button
  const resetBtn = document.createElement('button');
  resetBtn.id = 'remix-reset-btn';
  resetBtn.title = isEN ? 'Reset Remix' : 'Remix zurücksetzen';
  resetBtn.innerHTML = `<i class="fas fa-undo"></i> ${isEN?'Reset Remix':'Remix zurücksetzen'}`;
  resetBtn.style.cssText = 'background:rgba(245,158,11,0.18);border:1px solid #f59e0b;color:#f59e0b;border-radius:8px;padding:5px 12px;cursor:pointer;font-size:12px;font-weight:600;display:flex;align-items:center;gap:6px';
  resetBtn.onclick = () => {
    vid.playbackRate = 1;
    _remixTeardown(vid, true);
    resetBtn.remove();
    showToast(isEN ? 'Remix reset' : 'Remix zurückgesetzt', 'info');
  };
  const actionsArea = document.querySelector('.watch-actions') || document.querySelector('.video-actions');
  if (actionsArea) actionsArea.appendChild(resetBtn);
}

function openClipEditor(videoId, videoTitle) {
  if (!currentUser) return openAuthModal('login');
  const vid = document.getElementById('main-video');
  const duration = vid ? vid.duration : 0;

  const overlay = document.createElement('div');
  overlay.id = 'clip-editor-overlay';
  overlay.style.cssText = 'position:fixed;inset:0;z-index:99999;background:rgba(0,0,0,0.92);backdrop-filter:blur(12px);display:flex;align-items:center;justify-content:center;padding:20px';

  overlay.innerHTML = `
    <div style="background:var(--bg-card);border-radius:20px;max-width:520px;width:100%;border:1px solid rgba(168,59,255,0.35);box-shadow:0 32px 80px rgba(0,0,0,0.7);overflow:hidden">
      <div style="background:linear-gradient(var(--accent),var(--accent));padding:20px 24px;position:relative;display:flex;align-items:center;gap:12px">
        <button data-h-click="h_app_getElementById_13565" style="position:absolute;top:12px;right:14px;background:rgba(0,0,0,0.2);border:none;color:white;width:30px;height:30px;border-radius:50%;cursor:pointer;font-size:16px">&times;</button>
        <i class="fas fa-scissors" style="font-size:22px;color:white"></i>
        <div>
          <h2 style="margin:0;color:white;font-size:18px;font-weight:800">${tr({en:'Create Clip',de:'Clip erstellen'})}</h2>
          <p style="color:rgba(255,255,255,0.7);margin:2px 0 0;font-size:12px">Max. 60 Sekunden</p>
        </div>
      </div>

      <div style="padding:20px 24px;display:flex;flex-direction:column;gap:16px">

        <!-- Preview mini video -->
        <div style="border-radius:12px;overflow:hidden;background:#000;position:relative">
          <video id="clip-preview-vid" src="${vid ? vid.src : ''}" style="width:100%;max-height:180px;display:block;object-fit:contain" preload="metadata"></video>
          <div id="clip-time-display" style="position:absolute;bottom:8px;right:10px;background:rgba(0,0,0,0.7);color:white;font-size:12px;font-family:monospace;padding:3px 8px;border-radius:6px">0:00 – 0:00</div>
        </div>

        <!-- Range slider -->
        <div style="background:rgba(255,255,255,0.05);border-radius:12px;padding:16px">
          <div style="display:flex;justify-content:space-between;margin-bottom:8px">
            <span style="font-size:12px;color:rgba(255,255,255,0.5)">Start</span>
            <span id="clip-duration-display" style="font-size:12px;color:#a83bff;font-weight:700">0s</span>
            <span style="font-size:12px;color:rgba(255,255,255,0.5)">Ende</span>
          </div>

          <!-- Timeline bar -->
          <div id="clip-timeline" style="position:relative;height:48px;border-radius:8px;background:rgba(255,255,255,0.08);cursor:crosshair;user-select:none;overflow:hidden" data-h-mousedown="h_app_clipTimelineDown_13580">
            <!-- filled range -->
            <div id="clip-range-fill" style="position:absolute;top:0;bottom:0;background:linear-gradient(rgba(168,59,255,0.5),rgba(168,59,255,0.5));border:2px solid #a83bff;border-radius:6px;pointer-events:none"></div>
            <!-- waveform visual placeholder -->
            <div style="position:absolute;inset:0;display:flex;align-items:center;padding:0 4px;gap:1px;pointer-events:none;opacity:0.25" id="clip-waveform"></div>
            <!-- handles -->
            <div id="clip-handle-start" style="position:absolute;top:0;bottom:0;width:12px;background:#a83bff;border-radius:4px 0 0 4px;cursor:ew-resize;z-index:2"></div>
            <div id="clip-handle-end" style="position:absolute;top:0;bottom:0;width:12px;background:#a83bff;border-radius:0 4px 4px 0;cursor:ew-resize;z-index:2"></div>
          </div>

          <div style="display:flex;gap:10px;margin-top:12px">
            <div style="flex:1">
              <label style="font-size:11px;color:rgba(255,255,255,0.4);display:block;margin-bottom:4px">START (s)</label>
              <input id="clip-start-input" type="number" min="0" step="0.5" value="0" style="width:100%;padding:8px;background:rgba(255,255,255,0.07);border:1px solid rgba(255,255,255,0.15);border-radius:8px;color:white;font-size:14px;font-family:monospace" data-h-input="h_app_clipInputChanged_13580">
            </div>
            <div style="flex:1">
              <label style="font-size:11px;color:rgba(255,255,255,0.4);display:block;margin-bottom:4px">ENDE (s)</label>
              <input id="clip-end-input" type="number" min="0" step="0.5" value="${Math.min(30, duration).toFixed(1)}" style="width:100%;padding:8px;background:rgba(255,255,255,0.07);border:1px solid rgba(255,255,255,0.15);border-radius:8px;color:white;font-size:14px;font-family:monospace" data-h-input="h_app_clipInputChanged_13610">
            </div>
          </div>
        </div>

        <!-- Clip title -->
        <div>
          <label style="font-size:12px;color:rgba(255,255,255,0.5);display:block;margin-bottom:6px">Clip-Titel</label>
          <input id="clip-title-input" type="text" placeholder="Mein Clip" maxlength="80" value="Clip von ${videoTitle.replace(/'/g, '')}" style="width:100%;padding:10px 14px;background:rgba(255,255,255,0.07);border:1px solid rgba(255,255,255,0.15);border-radius:10px;color:white;font-size:14px;font-family:inherit">
        </div>

        <p id="clip-error" style="color:#ef4444;font-size:13px;display:none;margin:0;text-align:center"></p>

        <button data-h-click="h_app_submitClip_13618" data-hv-click="${nxHv(String(videoId))}" id="clip-submit-btn" style="width:100%;padding:14px;border-radius:12px;background:linear-gradient(var(--accent),var(--accent));border:none;color:white;font-size:15px;font-weight:700;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:8px">
          <i class="fas fa-scissors"></i> ${tr({en:'Create Clip',de:'Clip erstellen'})}
        </button>
      </div>
    </div>`;

  document.body.appendChild(overlay);
  overlay.addEventListener('click', e => { if (e.target === overlay) overlay.remove(); });

  // Init state
  window._clipState = { startTime: 0, endTime: Math.min(30, duration || 30), duration: duration || 0, dragging: null };

  // Draw fake waveform
  const wv = document.getElementById('clip-waveform');
  if (wv) {
    for (let i = 0; i < 80; i++) {
      const bar = document.createElement('div');
      const h = 20 + Math.random() * 60;
      bar.style.cssText = `width:3px;height:${h}%;background:rgba(168,59,255,0.6);border-radius:1px;flex-shrink:0`;
      wv.appendChild(bar);
    }
  }

  // Set preview video time on load
  const pv = document.getElementById('clip-preview-vid');
  if (pv) {
    pv.addEventListener('loadedmetadata', () => {
      window._clipState.duration = pv.duration;
      document.getElementById('clip-end-input').value = Math.min(30, pv.duration).toFixed(1);
      window._clipState.endTime = Math.min(30, pv.duration);
      updateClipUI();
    });
    pv.currentTime = 0;
  }
  updateClipUI();
}

function updateClipUI() {
  const s = window._clipState;
  if (!s) return;
  const dur = s.duration || 1;
  const startPct = (s.startTime / dur) * 100;
  const endPct   = (s.endTime   / dur) * 100;
  const tl = document.getElementById('clip-timeline');
  const tlW = tl ? tl.offsetWidth : 400;

  // Range fill
  const fill = document.getElementById('clip-range-fill');
  if (fill) {
    fill.style.left  = startPct + '%';
    fill.style.width = (endPct - startPct) + '%';
  }

  // Handles (offset by handle width)
  const hs = document.getElementById('clip-handle-start');
  const he = document.getElementById('clip-handle-end');
  if (hs) hs.style.left = `calc(${startPct}% - 6px)`;
  if (he) he.style.left = `calc(${endPct}% - 6px)`;

  // Time display
  const fmt = t => { const m = Math.floor(t/60); const sec = Math.floor(t%60); return `${m}:${sec.toString().padStart(2,'0')}`; };
  const td = document.getElementById('clip-time-display');
  if (td) td.textContent = `${fmt(s.startTime)} – ${fmt(s.endTime)}`;

  const clipDur = s.endTime - s.startTime;
  const dd = document.getElementById('clip-duration-display');
  if (dd) {
    dd.textContent = `${clipDur.toFixed(1)}s`;
    dd.style.color = clipDur > 60 ? '#ef4444' : '#a83bff';
  }

  // Inputs
  const si = document.getElementById('clip-start-input');
  const ei = document.getElementById('clip-end-input');
  if (si && document.activeElement !== si) si.value = s.startTime.toFixed(1);
  if (ei && document.activeElement !== ei) ei.value = s.endTime.toFixed(1);

  // Preview video
  const pv = document.getElementById('clip-preview-vid');
  if (pv && Math.abs(pv.currentTime - s.startTime) > 0.5) pv.currentTime = s.startTime;
}

function clipInputChanged() {
  const s = window._clipState;
  if (!s) return;
  const si = parseFloat(document.getElementById('clip-start-input')?.value || 0);
  const ei = parseFloat(document.getElementById('clip-end-input')?.value || 0);
  s.startTime = Math.max(0, Math.min(si, s.duration - 0.5));
  s.endTime   = Math.max(s.startTime + 0.5, Math.min(ei, s.duration));
  updateClipUI();
}

let _clipDragStartX = 0;
let _clipDragStartVal = 0;
function clipTimelineDown(e) {
  const s = window._clipState;
  if (!s) return;
  const tl = document.getElementById('clip-timeline');
  const rect = tl.getBoundingClientRect();
  const pct  = (e.clientX - rect.left) / rect.width;
  const time = pct * s.duration;

  // Which handle is closer?
  const distStart = Math.abs(time - s.startTime);
  const distEnd   = Math.abs(time - s.endTime);
  s.dragging = distStart < distEnd ? 'start' : 'end';
  _clipDragStartX   = e.clientX;
  _clipDragStartVal = s.dragging === 'start' ? s.startTime : s.endTime;

  const onMove = (ev) => {
    const dx    = ev.clientX - _clipDragStartX;
    const delta = (dx / rect.width) * s.duration;
    if (s.dragging === 'start') {
      s.startTime = Math.max(0, Math.min(_clipDragStartVal + delta, s.endTime - 0.5));
    } else {
      s.endTime = Math.max(s.startTime + 0.5, Math.min(_clipDragStartVal + delta, s.duration));
    }
    updateClipUI();
  };
  const onUp = () => {
    s.dragging = null;
    window.removeEventListener('mousemove', onMove);
    window.removeEventListener('mouseup', onUp);
  };
  window.addEventListener('mousemove', onMove);
  window.addEventListener('mouseup', onUp);
}
