async function submitClip(videoId) {
  const s = window._clipState;
  if (!s) return;
  const title = document.getElementById('clip-title-input')?.value?.trim() || 'Mein Clip';
  const errEl = document.getElementById('clip-error');
  const btn   = document.getElementById('clip-submit-btn');

  if (s.endTime - s.startTime < 1) {
    if (errEl) { errEl.textContent = 'Clip muss mindestens 1 Sekunde lang sein'; errEl.style.display = 'block'; }
    return;
  }
  if (s.endTime - s.startTime > 60) {
    if (errEl) { errEl.textContent = 'Clip darf max. 60 Sekunden lang sein'; errEl.style.display = 'block'; }
    return;
  }

  if (errEl) errEl.style.display = 'none';
  btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Wird erstellt...';
  btn.disabled = true;

  try {
    const res = await apiPost(`/api/videos/${videoId}/clip`, {
      startTime: s.startTime,
      endTime:   s.endTime,
      title
    });
    document.getElementById('clip-editor-overlay')?.remove();
    NXD.play('clip');
    showClipResult(res.clip);
  } catch (err) {
    btn.innerHTML = '<i class="fas fa-scissors"></i> '+(tr({en:'Create Clip',de:'Clip erstellen'}));
    btn.disabled  = false;
    if (errEl) { errEl.textContent = err.message || 'Fehler beim Erstellen'; errEl.style.display = 'block'; }
  }
}

