// ==================== HASHTAGS ====================
// Macht #hashtags in bereits escaptem HTML klickbar (nur im Text, nie in Tags/Links/Entities).
const NX_HASHTAG_RE = /(^|[^&\w#\/])#([\p{L}\p{N}_]{1,50})/gu;
function nxHashtagify(html) {
  if (!html) return '';
  let inLink = 0;
  return String(html).split(/(<[^>]+>)/g).map(part => {
    if (part.startsWith('<')) {
      if (/^<a\b/i.test(part)) inLink++;
      else if (/^<\/a>/i.test(part)) inLink = Math.max(0, inLink - 1);
      return part;
    }
    if (inLink) return part;
    return part.replace(NX_HASHTAG_RE, (m, pre, tag) => `${pre}<a class="nx-hashtag" href="/hashtag/${encodeURIComponent(tag.toLowerCase())}" data-h-click="h_app_preventDefault_13905" data-hv-click="${nxHv(String(tag.toLowerCase().replace(/'/g, '')))}">#${tag}</a>`);
  }).join('');
}
function nxExtractHashtags(text) {
  const out = [];
  String(text || '').replace(/(^|[^&\w#\/])#([\p{L}\p{N}_]{1,50})/gu, (m, pre, tag) => { const t = tag.toLowerCase(); if (!out.includes(t)) out.push(t); return m; });
  return out;
}

async function renderHashtagPage(tag) {
  const el = document.getElementById('page-hashtag');
  if (!el) return;
  tag = String(tag || '').replace(/^#/, '').toLowerCase();
  if (!tag) { navigateTo('home'); return; }
  el.innerHTML = `<div class="ht-head"><div class="ht-icon">#</div><div><h2>#${escHtml(tag)}</h2><p class="ht-sub"><span class="spinner" style="width:14px;height:14px;display:inline-block;vertical-align:middle"></span></p></div></div>`;
  try {
    const data = await apiGet('/api/hashtags/' + encodeURIComponent(tag));
    const vids = (data.videos || []).filter(v => !v.isShort);
    const shorts = (data.videos || []).filter(v => v.isShort);
    const tabs = [['all', tr({en:'All',de:'Alle'}), data.videos || []], ['videos', 'Videos', vids], ['shorts', 'Shorts', shorts]];
    el.innerHTML = `
      <div class="ht-head">
        <div class="ht-icon">#</div>
        <div style="min-width:0">
          <h2>#${escHtml(tag)}</h2>
          <p class="ht-sub">${formatViews(data.total || 0)} ${(data.total === 1) ? 'Video' : 'Videos'} · ${formatViews(data.channels || 0)} ${tr({en:'channels',de:'Kanäle'})} · ${formatViews(data.views || 0)} ${t('view_count')}</p>
        </div>
      </div>
      <div class="ht-tabs">${tabs.map(([id, label, list], i) => `<button class="ht-tab${i === 0 ? ' is-on' : ''}" data-ht="${id}">${label} <span>${list.length}</span></button>`).join('')}</div>
      <div id="ht-grid" class="video-grid"></div>
      ${data.related?.length ? `<div class="ht-related"><h3>${tr({en:'Related hashtags',de:'Ähnliche Hashtags'})}</h3><div>${data.related.map(r => `<button class="ht-chip" data-h-click="h_app_navigateTo_13935" data-hv-click="${nxHv(String(escHtml(r.tag)))}">#${escHtml(r.tag)} <span>${r.count}</span></button>`).join('')}</div></div>` : ''}`;
    const grid = document.getElementById('ht-grid');
    const draw = list => {
      grid.innerHTML = '';
      if (!list.length) { grid.innerHTML = emptyState('fa-hashtag', tr({en:'No videos yet',de:'Noch keine Videos'}), tr({en:`Be the first to use #${tag} in a title or description.`,de:`Sei der Erste, der #${tag} im Titel oder in der Beschreibung verwendet.`})); return; }
      list.forEach(v => grid.appendChild(createVideoCard(v)));
    };
    draw(data.videos || []);
    el.querySelectorAll('.ht-tab').forEach(b => b.addEventListener('click', () => {
      el.querySelectorAll('.ht-tab').forEach(x => x.classList.toggle('is-on', x === b));
      draw(tabs.find(x => x[0] === b.dataset.ht)[2]);
    }));
  } catch(e) { el.innerHTML += `<p style="color:var(--text-muted);padding:20px">${escHtml(e.message)}</p>`; }
}

/** Seek the main video to a time */
function seekVideoTo(secs) {
  const vid = document.getElementById('main-video');
  if (!vid) return;
  vid.currentTime = secs;
  vid.play().catch(() => {});
  // Scroll to player
  document.querySelector('.watch-player-wrapper')?.scrollIntoView({ behavior: 'smooth', block: 'center' });
}

/** Build the visual chapter bar below description */
function buildChapterBar(video) {
  const chapters = parseChapters(video.description);
  if (chapters.length < 2) return '';

  const chapterItems = chapters.map((ch, i) => `
    <div class="chapter-item" data-h-click="h_app_seekVideoTo_13965" data-hv-click="${nxHv(String(ch.time))}" title="${escHtml(ch.label)}">
      <div class="chapter-time">${fmtTime(ch.time)}</div>
      <div class="chapter-label">${escHtml(ch.label)}</div>
    </div>
  `).join('');

  return `
    <div class="chapters-bar" id="chapters-bar">
      <div style="font-size:13px;font-weight:700;color:var(--text-secondary);margin-bottom:10px;display:flex;align-items:center;gap:6px">
        <i class="fas fa-list" style="color:var(--purple-light);font-size:12px"></i> Kapitel
        <span style="font-size:11px;color:var(--text-muted);font-weight:400">(${chapters.length})</span>
      </div>
      <div class="chapter-list">${chapterItems}</div>
    </div>`;
}

/** Update active chapter highlight as video plays */
function initChapterTracking() {
  const vid = document.getElementById('main-video');
  const bar = document.getElementById('chapters-bar');
  if (!vid || !bar) return;

  // Get chapters from current video description
  const descEl = document.getElementById('watch-desc');
  if (!descEl) return;

  // We need chapters — re-parse from the raw text stored on video object
  // Use a data attribute trick: store chapters on the bar
  const rawDesc = vid.dataset.description || '';
  const chapters = parseChapters(rawDesc);
  if (chapters.length < 2) return;

  vid.addEventListener('timeupdate', () => {
    const t = vid.currentTime;
    const items = bar.querySelectorAll('.chapter-item');
    let activeIdx = 0;
    for (let i = 0; i < chapters.length; i++) {
      if (t >= chapters[i].time) activeIdx = i;
    }
    items.forEach((el, i) => {
      el.classList.toggle('active', i === activeIdx);
    });
  });
}

// Hook into renderWatchPage to init chapter tracking after render
const _origRenderWatch = window.renderWatchPage;
// We patch via MutationObserver on chapters-bar appearing
const _chapterObserver = new MutationObserver(() => {
  const bar = document.getElementById('chapters-bar');
  const vid = document.getElementById('main-video');
  if (bar && vid) {
    initChapterTracking();
  }
});
_chapterObserver.observe(document.body, { childList: true, subtree: true });


// ── Hashtag helper in upload form ────────────────────────────
window._uploadHashtags = [];
function addHashtag() {
  const input = document.getElementById('hashtag-input');
  if (!input) return;
  let val = input.value.trim().replace(/^#+/, '').replace(/[,\s]+$/, '').trim();
  if (!val) return;
  // v1.81: nur Zeichen, die auch als Hashtag erkannt werden (Buchstaben, Ziffern, _) – sonst
  // landete z. B. "<img onerror=…>" ungefiltert im HTML der Hashtag-Liste.
  if (!/^[\p{L}\p{N}_]{1,50}$/u.test(val)) { showToast(tr({ en: 'Hashtags may only contain letters, numbers and _ (max. 50).', de: 'Hashtags dürfen nur Buchstaben, Ziffern und _ enthalten (max. 50).' }), 'error'); return; }
  if (window._uploadHashtags.length >= 15) { showToast('Maximal 15 Hashtags erlaubt.'); return; }
  if (window._uploadHashtags.includes(val.toLowerCase())) { input.value = ''; return; }
  window._uploadHashtags.push(val.toLowerCase());
  renderHashtagList();
  appendHashtagToDescription(val);
  input.value = '';
}
function removeHashtag(tag) {
  window._uploadHashtags = window._uploadHashtags.filter(t => t !== tag);
  renderHashtagList();
  // Rebuild description without that hashtag
  const desc = document.getElementById('vid-desc');
  if (desc) {
    const lines = desc.value.split('\n');
    const filtered = lines.map(l => l.split(' ').filter(w => w.toLowerCase() !== '#' + tag).join(' ')).filter(l => l.trim() !== '');
    desc.value = filtered.join('\n').trim();
  }
}
function renderHashtagList() {
  const list = document.getElementById('hashtag-list');
  if (!list) return;
  list.innerHTML = window._uploadHashtags.map(tag =>
    `<span style="display:inline-flex;align-items:center;gap:5px;background:var(--purple-subtle);border:1px solid var(--purple-main);border-radius:20px;padding:3px 10px;font-size:12px;color:var(--purple-light)">
      #${escHtml(tag)}
      <button type="button" data-h-click="h_app_removeHashtag_14057" data-hv-click="${nxHv(String(escHtml(escJs(tag))))}" style="background:none;color:var(--text-muted);font-size:11px;padding:0;cursor:pointer;line-height:1">&times;</button>
    </span>`
  ).join('');
}
function appendHashtagToDescription(tag) {
  const desc = document.getElementById('vid-desc');
  if (!desc) return;
  const cur = desc.value;
  const hashStr = ' #' + tag.toLowerCase().replace(/\s+/g, '_');
  // Find existing hashtag block at the end
  const lines = cur.split('\n');
  const lastLine = lines[lines.length - 1];
  if (lastLine && lastLine.trim().startsWith('#')) {
    lines[lines.length - 1] = lastLine + hashStr;
  } else {
    if (cur.trim()) desc.value = cur.trimEnd() + '\n' + hashStr.trim();
    else desc.value = hashStr.trim();
    return;
  }
  desc.value = lines.join('\n');
}
// ── Upload: Zeichenzähler, erkannte Hashtags & Hashtag-Vorschläge ──
// Hashtags schreibt man direkt in Titel/Beschreibung. Beim Tippen von "#ab" werden
// passende, bereits genutzte Hashtags vorgeschlagen; darunter stehen alle erkannten Hashtags.
(function setupUploadHashtags() {
  let sugTimer = null, lastField = null;
  const wordAtCaret = el => {
    const pos = el.selectionStart ?? el.value.length;
    const before = el.value.slice(0, pos);
    const m = before.match(/(^|[^\w#])#([\p{L}\p{N}_]{0,50})$/u);
    return m ? { start: pos - m[2].length - 1, end: pos, q: m[2] } : null;
  };
  const updateFound = () => {
    const box = document.getElementById('up-hashtag-found');
    if (!box) return;
    const tags = nxExtractHashtags((document.getElementById('vid-title')?.value || '') + ' ' + (document.getElementById('vid-desc')?.value || ''));
    box.hidden = !tags.length;
    box.innerHTML = tags.length ? `<span class="up-tags-label">${tr({en:'Detected',de:'Erkannt'})} (${tags.length}/15)</span>` + tags.slice(0, 30).map(t => `<span class="up-tag${tags.indexOf(t) >= 15 ? ' is-over' : ''}">#${escHtml(t)}</span>`).join('') : '';
  };
  const updateCount = el => {
    const c = document.getElementById(el.id + '-count');
    if (c) { c.textContent = `${el.value.length}/${el.maxLength > 0 ? el.maxLength : ''}`; c.classList.toggle('is-near', el.maxLength > 0 && el.value.length > el.maxLength * 0.9); }
  };
  const showSuggest = async (el) => {
    const box = document.getElementById('up-hashtag-suggest');
    if (!box) return;
    const w = wordAtCaret(el);
    if (!w) { box.hidden = true; return; }
    lastField = el;
    let list = [];
    try { list = await apiGet('/api/hashtags/trending?limit=8&q=' + encodeURIComponent(w.q)); } catch {}
    const cur = wordAtCaret(el);
    if (!cur || cur.q !== w.q) return;
    if (!list.length) { box.hidden = true; return; }
    box.hidden = false;
    box.innerHTML = `<span class="up-tags-label">${tr({en:'Suggestions',de:'Vorschläge'})}</span>` + list.map(x => `<button type="button" class="up-tag up-tag-btn" data-tag="${escHtml(x.tag)}">#${escHtml(x.tag)}</button>`).join('');
  };
  document.addEventListener('input', e => {
    const el = e.target;
    if (!el || (el.id !== 'vid-title' && el.id !== 'vid-desc')) return;
    updateCount(el); updateFound();
    clearTimeout(sugTimer);
    sugTimer = setTimeout(() => showSuggest(el), 180);
  });
  document.addEventListener('click', e => {
    const b = e.target.closest?.('#up-hashtag-suggest .up-tag-btn');
    if (!b || !lastField) return;
    e.preventDefault();
    const el = lastField, w = wordAtCaret(el);
    const tag = '#' + b.dataset.tag + ' ';
    if (w) el.value = el.value.slice(0, w.start) + tag + el.value.slice(w.end);
    else el.value = (el.value.trimEnd() + ' ' + tag).trimStart();
    const pos = w ? w.start + tag.length : el.value.length;
    el.focus(); el.setSelectionRange(pos, pos);
    document.getElementById('up-hashtag-suggest').hidden = true;
    updateCount(el); updateFound();
    if (el.id === 'vid-desc' && typeof previewChapters === 'function') previewChapters(el.value);
  });
  window.nxUploadRefreshHashtags = () => { ['vid-title', 'vid-desc'].forEach(id => { const el = document.getElementById(id); if (el) updateCount(el); }); updateFound(); };
})();

// Reset hashtags when upload form is shown
document.addEventListener('DOMContentLoaded', () => {
  const form = document.getElementById('video-upload-form');
  if (form) {
    const origReset = form.onreset;
    form.addEventListener('reset', () => { window._uploadHashtags = []; renderHashtagList(); });
  }
});

// ── Chapter helper in upload form ────────────────────────────
function previewChapters(desc) {
  const chapters = parseChapters(desc);
  const el = document.getElementById('chapter-preview-list');
  if (!el) return;
  if (chapters.length < 1) { el.style.display = 'none'; return; }
  el.style.display = 'block';
  el.innerHTML = chapters.map((ch, i) => `
    <div style="display:flex;align-items:center;gap:10px;padding:5px 8px;border-radius:6px;${i % 2 === 0 ? 'background:rgba(255,255,255,0.03)' : ''}">
      <span style="font-family:monospace;font-size:12px;color:var(--purple-light);min-width:44px">${fmtTime(ch.time)}</span>
      <span style="font-size:13px;color:var(--text-secondary)">${escHtml(ch.label)}</span>
    </div>`).join('');
}

function addChapterLine() {
  const ta = document.getElementById('vid-desc');
  if (!ta) return;
  const existing = parseChapters(ta.value);
  const lastTime = existing.length > 0 ? existing[existing.length - 1].time + 60 : 0;
  const newLine = `\n${fmtTime(lastTime)} Kapitel ${existing.length + 1}`;
  ta.value += newLine;
  previewChapters(ta.value);
  ta.focus();
  ta.setSelectionRange(ta.value.length, ta.value.length);
}
