// ==================== "ALS NÄCHSTES" QUEUE ====================
let _queue = []; // { id, title, thumbnailPath, author }
let _queueVisible = false;

try { _queue = JSON.parse(sessionStorage.getItem('nxd_queue') || '[]'); if (!Array.isArray(_queue)) _queue = []; } catch { _queue = []; }
function _queueSync() {
  try { sessionStorage.setItem('nxd_queue', JSON.stringify(_queue)); } catch {}
  document.querySelectorAll('.queue-add-btn[data-queue-id]').forEach(b => {
    const on = _queue.some(q => q.id === b.dataset.queueId);
    b.classList.toggle('is-in', on);
    const i = b.querySelector('i'); if (i) i.className = 'fas ' + (on ? 'fa-check' : 'fa-list-ul');
  });
  document.querySelectorAll('[data-watch-queue]').forEach(b => {
    const on = _queue.some(q => q.id === b.dataset.watchQueue);
    b.innerHTML = on ? `<i class="fas fa-check"></i> ${tr({en:'In queue',de:'In der Warteschlange'})}` : `<i class="fas fa-list-ul"></i> ${tr({en:'Add to queue',de:'Zur Warteschlange'})}`;
  });
}
function nxQueueToggleFromCard(id) {
  const v = window._nxCardVideos?.[id];
  if (!v) return;
  if (_queue.some(q => q.id === id)) removeFromQueue(id, true);
  else addToQueue(v);
}
function addToQueue(video) {
  if (_queue.find(v => v.id === video.id)) {
    showToast(tr({en:'Already in your queue',de:'Schon in der Warteschlange'}), 'info'); return;
  }
  _queue.push(video);
  renderQueuePanel();
  _queueSync();
  showToast(tr({en:`Added to queue: „${(video.title||'').slice(0,30)}"`,de:`Zur Warteschlange hinzugefügt: „${(video.title||'').slice(0,30)}"`}), 'success');
  try { NXD.play('click'); } catch {}
  updateQueueBadge();
}

function removeFromQueue(id, withToast) {
  _queue = _queue.filter(v => v.id !== id);
  renderQueuePanel();
  updateQueueBadge();
  _queueSync();
  if (withToast) showToast(tr({en:'Removed from queue',de:'Aus der Warteschlange entfernt'}), 'info');
}

function moveQueueItem(id, dir) {
  const idx = _queue.findIndex(v => v.id === id);
  if (idx < 0) return;
  const newIdx = idx + dir;
  if (newIdx < 0 || newIdx >= _queue.length) return;
  [_queue[idx], _queue[newIdx]] = [_queue[newIdx], _queue[idx]];
  renderQueuePanel();
}

function clearQueue() {
  _queue = [];
  renderQueuePanel();
  updateQueueBadge();
  _queueSync();
}

function updateQueueBadge() {
  const badge = document.getElementById('queue-badge');
  if (!badge) return;
  badge.textContent = _queue.length;
  badge.style.display = _queue.length > 0 ? 'flex' : 'none';
}

function toggleQueuePanel() {
  _queueVisible = !_queueVisible;
  const panel = document.getElementById('queue-panel');
  if (panel) {
    panel.style.display = _queueVisible ? 'flex' : 'none';
  } else if (_queueVisible) {
    createQueuePanel();
  }
}

function createQueuePanel() {
  const panel = document.createElement('div');
  panel.id = 'queue-panel';
  panel.style.cssText = `
    position:fixed;bottom:80px;right:20px;width:320px;max-height:480px;
    background:var(--bg-card);border:1px solid rgba(168,59,255,0.3);
    border-radius:16px;box-shadow:0 16px 48px rgba(0,0,0,0.5);
    z-index:500;display:flex;flex-direction:column;
    animation:slideUp 0.25s cubic-bezier(0.34,1.2,0.64,1);
  `;
  document.body.appendChild(panel);
  renderQueuePanel();
}

function renderQueuePanel() {
  const panel = document.getElementById('queue-panel');
  if (!panel) return;

  panel.innerHTML = `
    <div style="padding:14px 16px;border-bottom:1px solid var(--border);display:flex;align-items:center;justify-content:space-between">
      <div style="font-weight:800;font-size:14px;display:flex;align-items:center;gap:8px">
        <i class="fas fa-list-ol" style="color:var(--purple-light)"></i>
        Als Nächstes <span style="background:var(--purple-subtle);color:var(--purple-light);padding:1px 7px;border-radius:20px;font-size:11px">${_queue.length}</span>
      </div>
      <div style="display:flex;gap:6px">
        ${_queue.length > 0 ? `<button data-h-click="h_app_clearQueue_14276" style="font-size:11px;color:var(--text-muted);background:none;border:none;cursor:pointer;padding:3px 6px">Leeren</button>` : ''}
        <button data-h-click="h_app_toggleQueuePanel_14276" style="width:24px;height:24px;border-radius:50%;background:var(--bg-hover);border:none;color:var(--text-muted);cursor:pointer;font-size:14px">&times;</button>
      </div>
    </div>
    <div style="flex:1;overflow-y:auto;padding:8px">
      ${_queue.length === 0
        ? `<div style="text-align:center;padding:32px 16px;color:var(--text-muted)">
            <i class="fas fa-list-ol" style="font-size:32px;opacity:0.2;display:block;margin-bottom:10px"></i>
            ${tr({en:'Your queue is empty',de:'Deine Warteschlange ist leer'})}<br><span style="font-size:12px;line-height:1.5;display:inline-block;margin-top:6px">${tr({en:'Hover over a video and click <i class="fas fa-list-ul"></i> – or use “More” → “Add to queue” under a video.',de:'Fahr über ein Video und klick auf <i class="fas fa-list-ul"></i> – oder unter einem Video „Mehr“ → „Zur Warteschlange“.'})}</span>
           </div>`
        : _queue.map((v, i) => `
          <div class="queue-item" id="qi-${v.id}">
            <div class="queue-item-thumb">
              ${v.thumbnailPath ? `<img alt="" src="${v.thumbnailPath}" style="width:100%;height:100%;object-fit:cover" data-h-error="h_app_h_14289">` : `<i class="fas fa-film" style="color:rgba(255,255,255,0.2)"></i>`}
            </div>
            <div style="flex:1;min-width:0">
              <div style="font-size:13px;font-weight:600;color:var(--text-primary);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${escHtml(v.title)}</div>
              <div style="font-size:11px;color:var(--text-muted);margin-top:2px">${escHtml(v.author?.displayName || '')}</div>
            </div>
            <div style="display:flex;flex-direction:column;gap:3px;flex-shrink:0">
              ${i > 0 ? `<button data-h-click="h_app_moveQueueItem_14296" data-hv-click="${nxHv(String(v.id))}" class="queue-ctrl-btn" aria-label="Nach oben"><i class="fas fa-chevron-up"></i></button>` : '<div style="width:22px"></div>'}
              ${i < _queue.length-1 ? `<button data-h-click="h_app_moveQueueItem_14297" data-hv-click="${nxHv(String(v.id))}" class="queue-ctrl-btn" aria-label="Nach unten"><i class="fas fa-chevron-down"></i></button>` : '<div style="width:22px"></div>'}
              <button data-h-click="h_app_removeFromQueue_14297" data-hv-click="${nxHv(String(v.id))}" class="queue-ctrl-btn" style="color:#ef4444" aria-label="Schließen"><i class="fas fa-times"></i></button>
            </div>
          </div>`).join('')
      }
    </div>
    ${_queue.length > 0 ? `
    <div style="padding:10px 16px;border-top:1px solid var(--border)">
      <button data-h-click="h_app_playNextInQueue_14303" style="width:100%;padding:10px;border-radius:10px;background:linear-gradient(var(--accent),var(--accent));border:none;color:white;font-size:13px;font-weight:700;cursor:pointer">
        <i class="fas fa-play"></i> Jetzt abspielen
      </button>
    </div>` : ''}
  `;
}

function playNextInQueue() {
  if (_queue.length === 0) return;
  const next = _queue.shift();
  renderQueuePanel();
  updateQueueBadge();
  navigateTo('watch', next.id);
  toggleQueuePanel();
}

function onVideoEnded() {
  if (_queue.length > 0 && localStorage.getItem('nxd_autoplay') !== 'false') {
    // Show countdown overlay then play next
    showQueueNextOverlay(_queue[0]);
  }
}

function showQueueNextOverlay(nextVideo) {
  const existing = document.getElementById('queue-next-overlay');
  if (existing) existing.remove();

  const overlay = document.createElement('div');
  overlay.id = 'queue-next-overlay';
  overlay.style.cssText = `
    position:fixed;bottom:80px;right:20px;width:300px;
    background:var(--bg-card);border:1px solid rgba(168,59,255,0.4);
    border-radius:14px;padding:16px;z-index:600;
    box-shadow:0 8px 32px rgba(0,0,0,0.5);
    animation:slideUp 0.3s cubic-bezier(0.34,1.2,0.64,1);
  `;

  let countdown = 7;
  overlay.innerHTML = `
    <div style="font-size:11px;color:var(--text-muted);margin-bottom:8px;text-transform:uppercase;letter-spacing:0.5px">Als Nächstes in <span id="queue-countdown">${countdown}</span>s</div>
    <div style="display:flex;gap:10px;align-items:center">
      <div style="width:64px;height:36px;border-radius:6px;overflow:hidden;background:var(--bg-secondary);flex-shrink:0">
        ${nextVideo.thumbnailPath ? `<img alt="" src="${nextVideo.thumbnailPath}" style="width:100%;height:100%;object-fit:cover" data-h-error="h_app_h_14347">` : '<i class="fas fa-film" style="color:rgba(255,255,255,0.2);display:block;padding:10px"></i>'}
      </div>
      <div style="flex:1;min-width:0">
        <div style="font-size:13px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${escHtml(nextVideo.title)}</div>
        <div style="font-size:11px;color:var(--text-muted)">${escHtml(nextVideo.author?.displayName || '')}</div>
      </div>
    </div>
    <div style="margin-top:12px;height:3px;background:var(--bg-secondary);border-radius:2px;overflow:hidden">
      <div id="queue-progress-bar" style="height:100%;background:linear-gradient(var(--accent),var(--accent));width:0%;transition:width 1s linear"></div>
    </div>
    <div style="display:flex;gap:8px;margin-top:10px">
      <button data-h-click="h_app_getElementById_14351" style="flex:1;padding:7px;border-radius:8px;background:var(--bg-hover);border:1px solid var(--border);color:var(--text-secondary);font-size:12px;cursor:pointer">Abbrechen</button>
      <button data-h-click="h_app_playNextInQueue_14351" style="flex:1;padding:7px;border-radius:8px;background:linear-gradient(var(--accent),var(--accent));border:none;color:white;font-size:12px;font-weight:700;cursor:pointer"><i class="fas fa-forward"></i> Jetzt</button>
    </div>
  `;
  document.body.appendChild(overlay);

  // Animate progress bar
  setTimeout(() => {
    const bar = document.getElementById('queue-progress-bar');
    if (bar) bar.style.width = '100%';
  }, 50);

  window._queueTimer = setInterval(() => {
    countdown--;
    const el = document.getElementById('queue-countdown');
    if (el) el.textContent = countdown;
    if (countdown <= 0) {
      clearInterval(window._queueTimer);
      overlay.remove();
      playNextInQueue();
    }
  }, 1000);
}

// ── Queue toggle button (injected into header-right) ─────────
(function injectQueueBtn() {
  function tryInject() {
    const headerRight = document.querySelector('.header-right');
    if (!headerRight || document.getElementById('queue-toggle-btn')) return;
    const btn = document.createElement('button');
    btn.id = 'queue-toggle-btn';
    btn.className = 'icon-btn';
    btn.title = 'Warteschlange';
    btn.style.cssText = 'position:relative';
    btn.innerHTML = `
      <i class="fas fa-list-ol"></i>
      <span id="queue-badge" style="display:none;position:absolute;top:3px;right:3px;background:#c77dff;color:white;border-radius:50%;width:16px;height:16px;font-size:10px;font-weight:700;align-items:center;justify-content:center"></span>
    `;
    btn.addEventListener('click', toggleQueuePanel);
    // Insert before the first icon-btn
    const firstBtn = headerRight.querySelector('.icon-btn');
    if (firstBtn) headerRight.insertBefore(btn, firstBtn);
    else headerRight.prepend(btn);
  }
  tryInject();
  new MutationObserver(tryInject).observe(document.body, { childList: true, subtree: true });
})();
// ─── Teil: client/app/500-subtitle-studio-helpers.js ───

// ==================== SUBTITLE STUDIO HELPERS ====================

async function checkWhisperStatusBanner() {
  const banner = document.getElementById('whisper-status-banner');
  if (!banner) return;
  try {
    const st = await apiGet('/api/whisper-status');
    if (st.whisperInstalled) { banner.innerHTML = ''; return; }

    banner.innerHTML = `<div style="background:rgba(239,68,68,0.1);border:1px solid rgba(239,68,68,0.3);border-radius:10px;padding:12px 14px;margin-bottom:16px;font-size:13px;color:#ef4444">
      <i class="fas fa-exclamation-circle"></i> Whisper-Abhängigkeiten fehlen auf dem Server. Bitte einmal <code>npm install</code> ausführen und den Server neu starten.
    </div>`;
  } catch {}
}

function buildSubtitleRow(v) {
  const langs = v.subtitles?.length
    ? v.subtitles.map(s => `
        <span style="display:inline-flex;align-items:center;gap:5px;padding:3px 8px;background:rgba(34,197,94,0.12);border:1px solid rgba(34,197,94,0.25);border-radius:20px;font-size:11px;color:#22c55e">
          <i class="fas fa-${s.auto ? 'robot' : 'user'}" style="font-size:9px"></i> ${escHtml(s.label || s.language)}
          <button data-h-click="h_app_deleteSubtitle_14426" data-hv-click="${nxHv(String(v.id), String(s.language))}" style="background:none;border:none;color:rgba(34,197,94,0.7);cursor:pointer;font-size:11px;padding:0 0 0 2px;line-height:1" title="Entfernen">&times;</button>
        </span>`).join(' ')
    : `<span style="font-size:12px;color:var(--text-muted)">Keine Untertitel</span>`;

  return `
    <div style="background:var(--bg-secondary);border-radius:14px;padding:14px 16px;display:flex;gap:12px;align-items:flex-start" id="sub-row-${v.id}">
      ${v.thumbnailPath
        ? `<img alt="" src="${v.thumbnailPath}" style="width:96px;height:54px;border-radius:8px;object-fit:cover;flex-shrink:0" data-h-error="h_app_h_14434">`
        : `<div style="width:96px;height:54px;border-radius:8px;background:var(--bg-card);flex-shrink:0;display:flex;align-items:center;justify-content:center;color:var(--text-muted)"><i class="fas fa-film"></i></div>`}
      <div style="flex:1;min-width:0">
        <div style="font-weight:600;font-size:13px;margin-bottom:6px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${escHtml(v.title)}</div>
        <div style="display:flex;flex-wrap:wrap;gap:5px;margin-bottom:10px">${langs}</div>
        <div style="display:flex;gap:8px;flex-wrap:wrap">
          <!-- Whisper auto-generate -->
          <div style="display:flex;gap:4px;align-items:center">
            <select id="lang-sel-${v.id}" style="padding:5px 8px;background:var(--bg-card);border:1px solid var(--border);border-radius:7px;color:var(--text-primary);font-size:12px;cursor:pointer">
              <option value="auto">Automatisch erkennen</option>
              <option value="de">Deutsch</option>
              <option value="en">English</option>
              <option value="fr">Français</option>
              <option value="es">Español</option>
              <option value="it">Italiano</option>
              <option value="pt">Português</option>
              <option value="ja">日本語</option>
              <option value="zh">中文</option>
            </select>
            <button data-h-click="h_app_triggerWhisper_14442" data-hv-click="${nxHv(String(v.id))}" id="whisper-btn-${v.id}" style="padding:5px 12px;background:linear-gradient(var(--accent),var(--accent));border:none;border-radius:7px;color:white;font-size:12px;font-weight:700;cursor:pointer;white-space:nowrap">
              <i class="fas fa-robot"></i> Auto-Transkription
            </button>
          </div>
          <!-- Manual upload -->
          <label style="cursor:pointer;display:inline-flex;align-items:center;gap:5px;padding:5px 10px;background:var(--bg-card);border:1px solid var(--border);border-radius:7px;font-size:12px;font-weight:600;white-space:nowrap">
            <i class="fas fa-upload" style="color:var(--text-muted)"></i> .srt / .vtt
            <input type="file" accept=".srt,.vtt" style="display:none" data-h-change="h_app_uploadSubtitleFile_14453" data-hv-change="${nxHv(String(v.id))}">
          </label>
        </div>
        <div id="whisper-status-${v.id}" style="font-size:12px;margin-top:6px;display:none"></div>
      </div>
    </div>`;
}

async function triggerWhisper(videoId) {
  const lang = document.getElementById(`lang-sel-${videoId}`)?.value || 'de';
  const btn = document.getElementById(`whisper-btn-${videoId}`);
  const status = document.getElementById(`whisper-status-${videoId}`);

  btn.disabled = true;
  btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Starte...';
  status.style.display = 'block';
  status.style.color = 'var(--purple-light)';
  status.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Transkription läuft... (kann einige Minuten dauern)';

  try {
    const res = await apiPost(`/api/videos/${videoId}/transcribe`, { language: lang });
    if (res.error) {
      status.style.color = '#ef4444';
      status.innerHTML = `<i class="fas fa-exclamation-circle"></i> ${escHtml(res.error)}`;
      btn.disabled = false; btn.innerHTML = '<i class="fas fa-robot"></i> Auto-Transkription';
      return;
    }
    // Poll for completion
    pollSubtitleStatus(videoId, lang, btn, status);
  } catch(e) {
    status.style.color = '#ef4444';
    status.innerHTML = `<i class="fas fa-exclamation-circle"></i> ${escHtml(e.message)}`;
    btn.disabled = false; btn.innerHTML = '<i class="fas fa-robot"></i> Auto-Transkription';
  }
}

async function pollSubtitleStatus(videoId, lang, btn, status) {
  const interval = setInterval(async () => {
    try {
      const data = await apiGet(`/api/videos/${videoId}/subtitle-status`);
      if (data.status === 'done') {
        clearInterval(interval);
        status.style.color = '#22c55e';
        status.innerHTML = '<i class="fas fa-check-circle"></i> Untertitel fertig! Seite neu laden zum Anzeigen.';
        btn.disabled = false; btn.innerHTML = '<i class="fas fa-robot"></i> Auto-Transkription';
        // Refresh the row
        try {
          const vids = await apiGet(`/api/videos?authorId=${currentUser.id}`);
          const v = vids.find(x => x.id === videoId);
          if (v) {
            const row = document.getElementById(`sub-row-${videoId}`);
            if (row) row.outerHTML = buildSubtitleRow(v);
          }
        } catch {}
      } else if (data.status === 'error') {
        clearInterval(interval);
        status.style.color = '#ef4444';
        status.innerHTML = `<i class="fas fa-times-circle"></i> Fehler: ${escHtml(data.error || 'Unbekannt')}`;
        btn.disabled = false; btn.innerHTML = '<i class="fas fa-robot"></i> Auto-Transkription';
      }
    } catch { clearInterval(interval); }
  }, 3000);
}

async function uploadSubtitleFile(videoId, input) {
  const file = input.files[0];
  if (!file) return;
  const lang = prompt('Sprache (z.B. de, en, fr):', 'de');
  if (!lang) return;
  const label = prompt('Anzeigename:', lang === 'de' ? 'Deutsch' : lang === 'en' ? 'English' : lang);

  const form = new FormData();
  form.append('subtitle', file);
  form.append('language', lang);
  form.append('label', label || lang);

  try {
    const token = localStorage.getItem('nxd_token');
    const res = await fetch(`/api/videos/${videoId}/subtitles/upload`, {
      method: 'POST',
      headers: token ? { Authorization: `Bearer ${token}` } : {},
      body: form
    });
    const data = await res.json();
    if (data.ok) {
      showToast('Untertitel hochgeladen!', 'success');
      const vids = await apiGet(`/api/videos?authorId=${currentUser.id}`);
      const v = vids.find(x => x.id === videoId);
      if (v) {
        const row = document.getElementById(`sub-row-${videoId}`);
        if (row) row.outerHTML = buildSubtitleRow(v);
      }
    } else { showToast(data.error || 'Fehler', 'error'); }
  } catch(e) { showToast(e.message, 'error'); }
}

async function deleteSubtitle(videoId, lang) {
  if (!confirm(`Untertitel (${lang}) löschen?`)) return;
  try {
    await apiDel(`/api/videos/${videoId}/subtitles/${lang}`);
    showToast('Untertitel gelöscht', 'success');
    const vids = await apiGet(`/api/videos?authorId=${currentUser.id}`);
    const v = vids.find(x => x.id === videoId);
    if (v) {
      const row = document.getElementById(`sub-row-${videoId}`);
      if (row) row.outerHTML = buildSubtitleRow(v);
    }
  } catch(e) { showToast(e.message, 'error'); }
}
// ─── Teil: client/app/510-community-polls.js ───

// ==================== COMMUNITY POLLS ====================

function buildPollCard(p) {
  const poll = p.poll;
  if (!poll) return '';
  const totalVotes = poll.options.reduce((s, o) => s + (o.votes?.length || 0), 0);
  const userVote = currentUser ? poll.options.findIndex(o => o.votes?.includes(currentUser.id)) : -1;
  const hasVoted = userVote >= 0;
  const expired = poll.endsAt && new Date(poll.endsAt) < new Date();

  const optionsHtml = poll.options.map((opt, i) => {
    const pct = totalVotes > 0 ? Math.round((opt.votes?.length || 0) / totalVotes * 100) : 0;
    const isChosen = i === userVote;
    return `
      <div class="poll-option ${hasVoted || expired ? 'poll-voted' : ''} ${isChosen ? 'poll-chosen' : ''}"
           ${!hasVoted && !expired ? nxOn('click', () => votePoll(p.id, i)) : ''}>
        <div class="poll-bar" style="width:${hasVoted || expired ? pct : 0}%"></div>
        <div class="poll-option-content">
          <span class="poll-opt-text">${escHtml(opt.text)} ${isChosen ? '<i class="fas fa-check-circle" style="color:#c77dff;font-size:11px"></i>' : ''}</span>
          ${hasVoted || expired ? `<span class="poll-pct">${pct}%</span>` : ''}
        </div>
      </div>`;
  }).join('');

  const expiryText = poll.endsAt
    ? (expired ? '• Abgelaufen' : `• Läuft ab ${timeAgo(poll.endsAt)}`)
    : '';

  return `
    <div class="poll-card" id="poll-${p.id}">
      <div class="poll-question"><i class="fas fa-poll" style="color:var(--purple-light);margin-right:6px"></i>${escHtml(poll.question)}</div>
      <div class="poll-options">${optionsHtml}</div>
      <div class="poll-footer">${totalVotes} Stimmen ${expiryText}</div>
    </div>`;
}

async function votePoll(postId, optionIndex) {
  if (!currentUser) { openAuthModal('login'); return; }
  try {
    const data = await apiPost(`/api/posts/${postId}/poll/vote`, { optionIndex });
    if (data.poll) {
      // Rebuild poll card in-place
      const card = document.getElementById(`poll-${postId}`);
      if (card) {
        const postEl = card.closest('.post-card');
        // Find post data — re-fetch posts to update
        const posts = await apiGet('/api/posts');
        const post = posts.find(p => p.id === postId);
        if (post && postEl) {
          const newCard = document.createElement('div');
          newCard.innerHTML = buildPollCard(post);
          card.replaceWith(newCard.firstElementChild);
        }
      }
      showToast('Stimme abgegeben!', 'success');
      NXD.play('click');
    }
  } catch(e) { showToast(e.message, 'error'); }
}

// Socket.IO: real-time poll updates
// (Registrierung erfolgt in initSocket(), NACHDEM `socket = io()` gesetzt wurde —
// vorher ist `socket` an dieser Stelle im Skript noch null und würde crashen.)
function _registerPollUpdatedListener() {
  if (!socket) return;
  socket.on('poll_updated', ({ postId, poll }) => {
    const card = document.getElementById(`poll-${postId}`);
    if (!card) return;
    // Partial update: just the footer vote count
    const footer = card.querySelector('.poll-footer');
    if (footer) {
      const total = poll.options.reduce((s, o) => s + (o.votes?.length || 0), 0);
      footer.textContent = `${total} Stimmen`;
    }
  });
}


// ==================== KAPITEL-EDITOR IM STUDIO ====================

function buildChapterEditorRow(v) {
  const chapters = parseChapters(v.description || '');
  const chapItems = chapters.map((ch, i) => `
    <div class="chapter-edit-row" data-idx="${i}">
      <span class="chapter-edit-time">${fmtTime(ch.time)}</span>
      <span class="chapter-edit-label">${escHtml(ch.label)}</span>
    </div>`).join('');

  return `
    <div style="background:var(--bg-secondary);border-radius:14px;padding:14px 16px" id="chap-row-${v.id}">
      <div style="display:flex;gap:12px;align-items:center;margin-bottom:12px">
        ${v.thumbnailPath ? `<img alt="" src="${v.thumbnailPath}" style="width:80px;height:45px;border-radius:8px;object-fit:cover;flex-shrink:0" data-h-error="h_app_h_14662">` : `<div style="width:80px;height:45px;border-radius:8px;background:var(--bg-card);flex-shrink:0;display:flex;align-items:center;justify-content:center;color:var(--text-muted)"><i class="fas fa-film"></i></div>`}
        <div style="flex:1;min-width:0">
          <div style="font-weight:700;font-size:14px;margin-bottom:2px">${escHtml(v.title)}</div>
          <div style="font-size:12px;color:var(--text-muted)">${chapters.length} Kapitel</div>
        </div>
        <button data-h-click="h_app_openChapterEditor_14665" data-hv-click="${nxHv(String(v.id), String(escJs(v.title)))}" style="padding:7px 14px;background:linear-gradient(var(--accent),var(--accent));border:none;border-radius:8px;color:white;font-size:12px;font-weight:700;cursor:pointer">
          <i class="fas fa-edit"></i> Bearbeiten
        </button>
      </div>
      ${chapters.length > 0 ? `<div style="display:flex;flex-wrap:wrap;gap:6px">${chapters.slice(0,5).map(ch=>`<span style="background:var(--bg-card);border:1px solid var(--border);border-radius:20px;padding:3px 10px;font-size:11px;color:var(--text-secondary)"><span style="color:var(--purple-light);font-family:monospace">${fmtTime(ch.time)}</span> ${escHtml(ch.label)}</span>`).join('')}${chapters.length > 5 ? `<span style="font-size:11px;color:var(--text-muted);padding:3px 6px">+${chapters.length-5} weitere</span>` : ''}</div>` : `<p style="font-size:12px;color:var(--text-muted);margin:0">Keine Kapitel — Timestamps in der Beschreibung eintragen</p>`}
    </div>`;
}

function openChapterEditor(videoId, videoTitle) {
  // Fetch video description to get current chapters
  apiGet(`/api/videos/${videoId}`).then(video => {
    const chapters = parseChapters(video.description || '');

    const overlay = document.createElement('div');
    overlay.id = 'chapter-editor-overlay';
    overlay.style.cssText = 'position:fixed;inset:0;z-index:99999;background:rgba(0,0,0,0.88);backdrop-filter:blur(12px);display:flex;align-items:center;justify-content:center;padding:20px';

    overlay.innerHTML = `
      <div style="background:var(--bg-card);border-radius:20px;max-width:560px;width:100%;border:1px solid rgba(168,59,255,0.35);overflow:hidden;max-height:90vh;display:flex;flex-direction:column">
        <div style="background:linear-gradient(var(--accent),var(--accent));padding:18px 24px;display:flex;align-items:center;gap:12px;flex-shrink:0">
          <button data-h-click="h_app_getElementById_14684" style="position:absolute;top:14px;right:16px;background:rgba(0,0,0,0.2);border:none;color:white;width:30px;height:30px;border-radius:50%;cursor:pointer;font-size:16px">&times;</button>
          <i class="fas fa-list" style="font-size:20px;color:white"></i>
          <div>
            <h3 style="margin:0;color:white;font-size:16px;font-weight:800">Kapitel bearbeiten</h3>
            <p style="margin:2px 0 0;font-size:12px;color:rgba(255,255,255,0.65)">${escHtml(videoTitle)}</p>
          </div>
        </div>
        <div style="padding:20px 24px;overflow-y:auto;flex:1">
          <div id="chapter-editor-list" style="display:flex;flex-direction:column;gap:8px;margin-bottom:14px">
            ${chapters.length === 0 ? '<p style="color:var(--text-muted);font-size:13px;text-align:center;padding:20px">'+(tr({en:'No chapters yet',de:'Noch keine Kapitel'}))+'</p>' :
              chapters.map((ch, i) => buildChapterEditItem(i, ch.time, ch.label)).join('')}
          </div>
          <button data-h-click="h_app_addChapterEditRow_14697" style="width:100%;padding:10px;border-radius:10px;background:rgba(168,59,255,0.15);border:1px dashed rgba(168,59,255,0.4);color:var(--purple-light);font-size:13px;font-weight:600;cursor:pointer">
            <i class="fas fa-plus"></i> Kapitel hinzufügen
          </button>
          <p style="font-size:11px;color:var(--text-muted);margin-top:10px;text-align:center">Format: 0:00 Intro, 1:30 Teil 2 — das erste Kapitel muss bei 0:00 beginnen</p>
        </div>
        <div style="padding:14px 24px;border-top:1px solid var(--border);display:flex;gap:10px;flex-shrink:0">
          <button data-h-click="h_app_getElementById_14697" style="flex:1;padding:11px;border-radius:10px;background:var(--bg-hover);border:1px solid var(--border);color:var(--text-secondary);font-size:13px;cursor:pointer">Abbrechen</button>
          <button data-h-click="h_app_saveChapters_14697" data-hv-click="${nxHv(String(videoId))}" style="flex:2;padding:11px;border-radius:10px;background:linear-gradient(var(--accent),var(--accent));border:none;color:white;font-size:14px;font-weight:700;cursor:pointer"><i class="fas fa-save"></i> Kapitel speichern</button>
        </div>
      </div>`;

    // Store original description (non-chapter lines) on overlay
    overlay.dataset.origDescription = decodeServerEntities(video.description || '').split('\n')
      .filter(line => !line.trim().match(/^\d{1,2}:\d{2}(?::\d{2})?\s+.+/))
      .join('\n').trim();
    overlay.dataset.videoId = videoId;

    document.body.appendChild(overlay);
    overlay.addEventListener('click', e => { if (e.target === overlay) overlay.remove(); });
  }).catch(() => showToast('Fehler beim Laden', 'error'));
}

function buildChapterEditItem(idx, timeSecs, label) {
  const h = Math.floor(timeSecs / 3600);
  const m = Math.floor((timeSecs % 3600) / 60);
  const s = Math.floor(timeSecs % 60);
  const timeStr = h > 0
    ? `${h}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`
    : `${m}:${String(s).padStart(2,'0')}`;

  return `
    <div class="chapter-edit-item" data-idx="${idx}" style="display:flex;gap:8px;align-items:center;background:var(--bg-secondary);border-radius:10px;padding:10px 12px">
      <input type="text" value="${timeStr}" placeholder="0:00" maxlength="8"
        style="width:72px;flex-shrink:0;padding:6px 8px;background:var(--bg-card);border:1px solid var(--border);border-radius:7px;color:var(--purple-light);font-family:monospace;font-size:13px;font-weight:700;text-align:center"
        class="chapter-time-input">
      <input type="text" value="${escHtml(label)}" placeholder="Kapitelname"
        style="flex:1;padding:6px 10px;background:var(--bg-card);border:1px solid var(--border);border-radius:7px;color:var(--text-primary);font-size:13px"
        class="chapter-label-input">
      <button data-h-click="h_app_closest_14734" style="width:28px;height:28px;border-radius:50%;background:rgba(239,68,68,0.15);border:none;color:#ef4444;cursor:pointer;font-size:14px;flex-shrink:0">&times;</button>
    </div>`;
}

let _chapterEditCount = 10;
function addChapterEditRow() {
  const list = document.getElementById('chapter-editor-list');
  if (!list) return;
  // Remove empty state
  const empty = list.querySelector('p');
  if (empty) empty.remove();
  const items = list.querySelectorAll('.chapter-edit-item');
  let nextTime = 0;
  if (items.length > 0) {
    const lastTimeInput = items[items.length-1].querySelector('.chapter-time-input');
    const parts = (lastTimeInput?.value || '0:00').split(':').map(Number);
    nextTime = parts.length === 3 ? parts[0]*3600+parts[1]*60+parts[2] : parts[0]*60+(parts[1]||0);
    nextTime += 60;
  }
  const idx = _chapterEditCount++;
  const el = document.createElement('div');
  el.innerHTML = buildChapterEditItem(idx, nextTime, '');
  list.appendChild(el.firstElementChild);
}

async function saveChapters(videoId) {
  const overlay = document.getElementById('chapter-editor-overlay');
  const origDesc = overlay?.dataset.origDescription || '';

  const items = document.querySelectorAll('#chapter-editor-list .chapter-edit-item');
  const chapters = [];

  for (const item of items) {
    const timeStr = item.querySelector('.chapter-time-input')?.value?.trim();
    const label = item.querySelector('.chapter-label-input')?.value?.trim();
    if (!timeStr || !label) continue;
    chapters.push(`${timeStr} ${label}`);
  }

  // Rebuild description: original text + chapter lines
  const newDesc = [origDesc, ...chapters].filter(Boolean).join('\n');

  try {
    await apiPut(`/api/videos/${videoId}`, { description: newDesc });
    showToast('Kapitel gespeichert!', 'success');
    overlay?.remove();
    // Refresh studio panel
    switchStudio('content', document.querySelector('[data-studio="content"]'));
  } catch(e) { showToast(e.message || 'Fehler', 'error'); }
}
