// ==================== REALTIME CREATOR DASHBOARD ====================


// ==================== CREATOR-STATISTIKEN (v20) ====================
// Ein Panel: KPI-Kacheln (mit Trend), Aktivität, beste Upload-Zeiten (Heatmap),
// Format-Vergleich, Kategorien, Top-Videos. Alle Zahlen stammen aus echten Daten –
// wo der Server keine Zeitreihen hat (Views), wird bewusst nichts erfunden.
async function renderStudioAnalytics(content, range) {
  window._anRange = range;
  const err = (msg) => { content.innerHTML = `<div class="an-error"><i class="fas fa-triangle-exclamation"></i><p>${escHtml(msg)}</p><button class="btn-primary" data-h-click="h_app_switchStudio_14799">${escHtml(t('an_retry'))}</button></div>`; };
  let d, myVideos;
  try {
    const tz = -new Date().getTimezoneOffset();     // Minuten Offset zu UTC (z.B. +120 im Sommer in DE)
    [d, myVideos] = await Promise.all([
      apiGet(`/api/studio/analytics?range=${encodeURIComponent(range)}&tz=${tz}`),
      apiGet(`/api/videos?authorId=${currentUser.id}`)
    ]);
  } catch (e) { return err(t('an_error')); }
  if (!content.isConnected) return;   // Nutzer hat inzwischen den Tab gewechselt

  if (!myVideos.length) {
    content.innerHTML = `<h3 class="an-h">${escHtml(t('an_title'))}</h3>` + emptyState('fa-chart-line', t('an_no_videos'), '');
    return;
  }

  const num = n => formatViews(n || 0);
  const totalViews = d.totals?.views ?? myVideos.reduce((s, v) => s + (v.views || 0), 0);
  const totalLikes = d.totals?.likes ?? 0;
  const totalComments = d.totals?.comments ?? 0;
  const engagement = totalViews ? ((totalLikes + totalComments) / totalViews * 100) : 0;
  const trend = (cur, prev) => {
    if (prev == null) return '';
    if (prev === 0 && cur === 0) return '';
    const diff = prev === 0 ? 100 : Math.round((cur - prev) / prev * 100);
    const cls = diff > 0 ? 'up' : diff < 0 ? 'down' : 'flat';
    const icon = diff > 0 ? 'fa-arrow-up' : diff < 0 ? 'fa-arrow-down' : 'fa-minus';
    return `<span class="an-trend ${cls}" title="${escHtml(t('an_vs_prev'))}"><i class="fas ${icon}"></i> ${Math.abs(diff)}%</span>`;
  };
  const uploadsInRange = Object.values(d.uploadsByDay || {}).reduce((a, b) => a + b, 0);
  const kpi = (icon, color, val, label, extra = '') => `
    <div class="an-kpi"><div class="an-kpi-ic" style="color:${color};background:${color}22"><i class="fas ${icon}"></i></div>
      <div class="an-kpi-val">${val}</div><div class="an-kpi-lbl">${escHtml(label)}</div>${extra}</div>`;

  // ── Aktivität (Balken je Tag) ──
  const days = [];
  const rangeDays = { '7d': 7, '30d': 30, '90d': 90 }[range] || 30;
  const barCount = range === 'all' ? 0 : rangeDays;
  if (barCount) for (let i = barCount - 1; i >= 0; i--) { const dt = new Date(Date.now() - i * 86400000); days.push(dt.toISOString().slice(0, 10)); }
  const maxAct = Math.max(1, ...days.map(k => (d.uploadsByDay[k] || 0) + (d.commentsByDay[k] || 0)));
  const activityHtml = barCount ? `
    <div class="an-bars" style="--n:${days.length}">${days.map(k => {
      const u = d.uploadsByDay[k] || 0, c = d.commentsByDay[k] || 0;
      const h = Math.round(((u + c) / maxAct) * 100);
      return `<div class="an-bar" title="${k}: ${u} ${escHtml(t('an_uploads'))}, ${c} ${escHtml(t('an_comments'))}"><span style="height:${Math.max(h, (u + c) ? 6 : 2)}%" class="${u ? 'has-upload' : ''}"></span></div>`;
    }).join('')}</div>
    <div class="an-legend"><span><i style="background:var(--purple-main)"></i>${escHtml(t('an_comments'))}</span><span><i style="background:#22c55e"></i>${escHtml(t('an_uploads'))}</span></div>` : '';

  // ── Beste Upload-Zeiten ──
  const bt = d.bestTimes || {};
  const dowName = i => t('dow_' + i), dowShort = i => t('dows_' + i);
  const hh = h => String(h % 24).padStart(2, '0') + ':00';
  let bestHtml;
  if (!bt.bestDay || bt.confidence === 'none') {
    bestHtml = `<p class="an-muted">${escHtml(t('an_need_data'))}</p>`;
  } else {
    const order = [1, 2, 3, 4, 5, 6, 0];                    // Woche beginnt Montag
    const cell = (dow, from) => (bt.heatmap || []).find(c => c.dow === dow && c.from === from) || { level: 0, n: 0, avgViews: 0 };
    const froms = [0, 3, 6, 9, 12, 15, 18, 21];
    const heat = `<div class="an-heat" role="table">
      <div class="an-heat-row an-heat-head"><span></span>${froms.map(f => `<span>${String(f).padStart(2, '0')}</span>`).join('')}</div>
      ${order.map(dw => `<div class="an-heat-row"><span class="an-heat-day">${escHtml(dowShort(dw))}</span>${froms.map(f => {
        const c = cell(dw, f);
        const top = bt.bestDay.dow === dw && bt.bestWindow && bt.bestWindow.from === f;
        return `<span class="an-heat-cell${top ? ' best' : ''}" style="--lv:${c.level}" title="${escHtml(dowName(dw))} ${hh(f)}–${hh(f + 3)}: ${c.n ? c.n + ' ' + escHtml(t('an_videos')) + ', Ø ' + num(c.avgViews) : '–'}"></span>`;
      }).join('')}</div>`).join('')}
      <div class="an-heat-scale"><span>${escHtml(t('an_less'))}</span><i></i><span>${escHtml(t('an_more'))}</span></div></div>`;
    bestHtml = `
      <div class="an-best-top">
        <div class="an-best-pill"><i class="fas fa-calendar-day"></i><div><small>${escHtml(t('an_best_day'))}</small><b>${escHtml(dowName(bt.bestDay.dow))}</b></div></div>
        ${bt.bestWindow ? `<div class="an-best-pill"><i class="fas fa-clock"></i><div><small>${escHtml(t('an_best_hour'))}</small><b>${hh(bt.bestWindow.from)} – ${hh(bt.bestWindow.to)}</b></div></div>` : ''}
        <div class="an-best-pill"><i class="fas fa-eye"></i><div><small>${escHtml(t('an_avg_views'))}</small><b>${num(bt.bestDay.avgViews)}</b></div></div>
      </div>
      ${heat}
      ${bt.confidence === 'low' ? `<p class="an-muted an-warn"><i class="fas fa-circle-info"></i> ${escHtml(t('an_low_data'))}</p>` : ''}`;
  }

  // ── Format-Vergleich ──
  const fb = d.formatBreakdown || { shorts: { count: 0, views: 0 }, longform: { count: 0, views: 0 } };
  const fTotal = Math.max(1, fb.shorts.views + fb.longform.views);
  const fmtRow = (label, o, color) => `<div class="an-row"><div class="an-row-top"><span>${escHtml(label)} <small>(${o.count})</small></span><b>${num(o.views)}</b></div><div class="an-track"><span style="width:${Math.round(o.views / fTotal * 100)}%;background:${color}"></span></div></div>`;

  // ── Kategorien ──
  const cats = (d.categoryBreakdown || []).slice(0, 5);
  const maxCat = Math.max(1, ...cats.map(c => c.totalViews));
  const catHtml = cats.map(c => `<div class="an-row"><div class="an-row-top"><span>${escHtml(c.category)} <small>(${c.videoCount})</small></span><b>${num(c.totalViews)}</b></div><div class="an-track"><span style="width:${Math.round(c.totalViews / maxCat * 100)}%"></span></div></div>`).join('');

  // ── Top-Videos ──
  const top = [...myVideos].sort((a, b) => (b.views || 0) - (a.views || 0)).slice(0, 5);
  const maxV = Math.max(1, top[0]?.views || 1);
  const topHtml = top.map((v, i) => `
    <div class="an-top" data-h-click="h_app_navigateTo_14889" data-hv-click="${nxHv(String(v.id))}">
      <span class="an-rank">${i + 1}</span>
      ${v.thumbnailPath ? `<img src="${v.thumbnailPath}" alt="" loading="lazy" data-h-error="h_app_h_14892">` : `<div class="an-thumb-ph"><i class="fas fa-film"></i></div>`}
      <div class="an-top-main"><div class="an-top-title">${escHtml(v.title)}</div><div class="an-track"><span style="width:${Math.round((v.views || 0) / maxV * 100)}%"></span></div></div>
      <b>${num(v.views)}</b>
    </div>`).join('');

  const ranges = [['7d', 'an_range_7'], ['30d', 'an_range_30'], ['90d', 'an_range_90'], ['all', 'an_range_all']];
  content.innerHTML = `
    <div class="an-head">
      <h3 class="an-h">${escHtml(t('an_title'))}</h3>
      <div class="an-ranges" role="tablist">${ranges.map(([k, key]) => `<button class="${k === range ? 'active' : ''}" data-h-click="h_app_renderStudioAnalytics_14901" data-hv-click="${nxHv(String(k))}">${escHtml(t(key))}</button>`).join('')}</div>
    </div>
    <div class="an-kpis">
      ${kpi('fa-eye', '#22c55e', num(totalViews), t('an_kpi_views'))}
      ${kpi('fa-users', '#a83bff', num(d.currentSubscribers), t('an_kpi_subs'))}
      ${kpi('fa-heart', '#f59e0b', num(totalLikes), t('studio_stat_likes'))}
      ${kpi('fa-bolt', '#06b6d4', engagement.toFixed(1) + '%', t('an_kpi_eng'))}
    </div>
    <div class="an-card">
      <div class="an-card-h"><h4><i class="fas fa-chart-simple"></i> ${escHtml(t('an_activity'))}</h4>
        <div class="an-mini">
          <span>${uploadsInRange} ${escHtml(t('an_uploads'))} ${trend(d.previous?.currentUploads, d.previous?.uploads)}</span>
          <span>${d.commentsInRange} ${escHtml(t('an_comments'))}</span>
        </div></div>
      ${activityHtml}
    </div>
    <div class="an-card">
      <div class="an-card-h"><h4><i class="fas fa-calendar-check"></i> ${escHtml(t('an_best_times'))}</h4></div>
      <p class="an-muted" style="margin:-4px 0 14px">${escHtml(t('an_best_times_sub'))}${bt.videosAnalyzed ? ` · ${bt.videosAnalyzed} ${escHtml(t('an_videos'))}` : ''}</p>
      ${bestHtml}
    </div>
    <div class="an-grid2">
      <div class="an-card"><h4 class="an-card-t"><i class="fas fa-layer-group"></i> ${escHtml(t('an_formats'))}</h4>
        ${fmtRow(t('an_shorts'), fb.shorts, 'var(--pink-accent,#a83bff)')}${fmtRow(t('an_long'), fb.longform, 'var(--purple-main)')}</div>
      <div class="an-card"><h4 class="an-card-t"><i class="fas fa-tags"></i> ${escHtml(t('an_categories'))}</h4>${catHtml || '<p class="an-muted">—</p>'}</div>
    </div>
    <div class="an-card"><h4 class="an-card-t"><i class="fas fa-trophy" style="color:#f59e0b"></i> ${escHtml(t('studio_top_videos'))}</h4>${topHtml}</div>`;
}

