// ==================== HINTERGRUNDWIEDERGABE (Premium) ====================
// (Variablen-Deklarationen befinden sich jetzt oben im Skript, siehe INIT-Bereich)

function _setupBackgroundPlayback(vidEl, videoData) {
  _bgPlayVideoRef = vidEl;
  _bgPlayActive = false;

  // MediaSession API – Steuerung auf dem Sperrbildschirm
  if ('mediaSession' in navigator) {
    navigator.mediaSession.metadata = new MediaMetadata({
      title: videoData.title || 'Norynex',
      artist: videoData.author?.displayName || videoData.authorName || 'Norynex',
      album: 'Norynex',
      artwork: videoData.thumbnailPath ? [{ src: new URL(videoData.thumbnailPath, location.href).href, sizes: '640x360' }] : [{ src: '/assets/icon-512.png', sizes: '512x512', type: 'image/png' }]
    });
    navigator.mediaSession.setActionHandler('play', () => { vidEl.play().catch(() => {}); });
    navigator.mediaSession.setActionHandler('pause', () => { vidEl.pause(); });
    navigator.mediaSession.setActionHandler('seekbackward', () => { vidEl.currentTime = Math.max(0, vidEl.currentTime - 10); });
    navigator.mediaSession.setActionHandler('seekforward', () => { vidEl.currentTime = Math.min(vidEl.duration, vidEl.currentTime + 10); });
  }

  // Update the button state if it exists
  const btn = document.getElementById('bg-play-btn');
  if (btn) btn.title = tr({en:'Enable background play',de:'Hintergrundwiedergabe aktivieren'});
}

function toggleBackgroundPlay() {
  _bgPlayActive = !_bgPlayActive;
  const btn = document.getElementById('bg-play-btn');

  if (_bgPlayActive) {
    // Verhindere Pause beim Tab-Wechsel / Bildschirmsperre
    if (_visibilityHandler) document.removeEventListener('visibilitychange', _visibilityHandler);
    _visibilityHandler = () => {
      if (document.hidden && _bgPlayActive && _bgPlayVideoRef) {
        // Kurz pausiert? Weiterspielen
        setTimeout(() => {
          if (_bgPlayVideoRef && _bgPlayVideoRef.paused && _bgPlayActive) {
            _bgPlayVideoRef.play().catch(() => {});
          }
        }, 300);
      }
    };
    document.addEventListener('visibilitychange', _visibilityHandler);

    // Wake Lock – verhindert Bildschirm-Timeout (wenn verfügbar)
    if ('wakeLock' in navigator) {
      navigator.wakeLock.request('screen').then(lock => {
        _wakeLock = lock;
        _wakeLock.addEventListener('release', () => { _wakeLock = null; });
      }).catch(() => {});
    }

    // Video als audio-only freigeben (playsinline + keine Pause nötig)
    if (_bgPlayVideoRef) {
      _bgPlayVideoRef.setAttribute('playsinline', '');
      _bgPlayVideoRef.setAttribute('webkit-playsinline', '');
    }

    if (btn) {
      btn.style.color = '#f59e0b';
      btn.style.borderColor = 'rgba(245,158,11,0.5)';
      btn.style.background = 'rgba(245,158,11,0.1)';
      btn.innerHTML = '<i class="fas fa-mobile-alt"></i> Hintergrund <i class="fas fa-check-circle" style="color:#22c55e"></i>';
    }
    showToast(tr({en:'Background play active – keeps playing when your screen locks',de:'Hintergrundwiedergabe aktiv – läuft weiter wenn du das Handy sperrst'}), 'success');
  } else {
    // Deaktivieren
    if (_visibilityHandler) {
      document.removeEventListener('visibilitychange', _visibilityHandler);
      _visibilityHandler = null;
    }
    if (_wakeLock) { _wakeLock.release().catch(() => {}); _wakeLock = null; }

    if (btn) {
      btn.style.color = '#f59e0b';
      btn.style.borderColor = 'rgba(245,158,11,0.3)';
      btn.style.background = '';
      btn.innerHTML = '<i class="fas fa-mobile-alt"></i> Hintergrund';
    }
    showToast(tr({en:'Background play disabled',de:'Hintergrundwiedergabe deaktiviert'}), 'info');
  }
}

// Geplante Veröffentlichung - helper: toggle field (already defined above, no-op here)

// ==================== MEHR-MENÜ (Watch Actions) ====================
function toggleWatchMore(videoId) {
  const drop = document.getElementById(`watch-more-drop-${videoId}`);
  const arrow = document.getElementById(`watch-more-arrow-${videoId}`);
  const btn = document.getElementById(`watch-more-btn-${videoId}`);
  if (!drop) return;
  const open = drop.classList.toggle('open');
  if (arrow) arrow.style.transform = open ? 'rotate(180deg)' : 'rotate(0deg)';
  if (btn) btn.classList.toggle('active', open);
  // Auf dem Handy wird das Menü als Bottom-Sheet über der unteren Navigation angezeigt
  // (vorher ragte es unter die Navigationsleiste → "Melden" war nicht antippbar).
  document.body.classList.toggle('nx-sheet-open', open && window.innerWidth <= 768);

  // Close on outside click
  if (open) {
    setTimeout(() => {
      const handler = (e) => {
        if (!document.getElementById(`watch-more-wrap-${videoId}`)?.contains(e.target)) {
          drop.classList.remove('open');
          document.body.classList.remove('nx-sheet-open');
          if (arrow) arrow.style.transform = 'rotate(0deg)';
          if (btn) btn.classList.remove('active');
          document.removeEventListener('click', handler);
        }
      };
      document.addEventListener('click', handler);
    }, 0);
  }
}

// ==================== KANAL-TRAILER ====================
async function saveTrailer() {
  const sel = document.getElementById('trailer-video-select');
  if (!sel) return;
  const videoId = sel.value || null;
  try {
    await apiPut('/api/users/me/trailer', { videoId });
    showToast(videoId ? 'Kanal-Trailer gespeichert!' : 'Trailer entfernt', 'success');
  } catch(e) {
    showToast('Fehler: ' + e.message, 'error');
  }
}

async function deleteVideoAvatar() {
  try {
    await fetch('/api/users/me/video-avatar', { method: 'DELETE', headers: { Authorization: `Bearer ${localStorage.getItem('nxd_token')}` } });
    showToast('Video-Profilbild entfernt', 'success');
    renderChannelPage(currentUser.id);
  } catch { showToast('Fehler beim Entfernen', 'error'); }
}

async function deleteVideoBanner() {
  try {
    await fetch('/api/users/me/video-banner', { method: 'DELETE', headers: { Authorization: `Bearer ${localStorage.getItem('nxd_token')}` } });
    showToast('Video-Kanalbanner entfernt', 'success');
    renderChannelPage(currentUser.id);
  } catch { showToast('Fehler beim Entfernen', 'error'); }
}

async function deleteWatermark() {
  try {
    const result = await fetch('/api/users/me', { method: 'PUT', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${localStorage.getItem('nxd_token')}` }, body: JSON.stringify({ watermark: '' }) });
    const data = await result.json();
    if (!result.ok) throw new Error(data.error);
    currentUser.watermark = '';
    localStorage.setItem('nxd_user', JSON.stringify(currentUser));
    showToast(tr({en:'Watermark removed',de:'Wasserzeichen entfernt'}), 'success');
    switchStudio('channel', document.querySelector('.studio-nav a[data-studio="channel"]'));
  } catch(e) { showToast(e.message || 'Fehler beim Entfernen', 'error'); }
}
// ─── Teil: client/app/540-picture-in-picture.js ───

// ==================== PICTURE-IN-PICTURE ====================
async function togglePictureInPicture() {
  const vid = document.getElementById('main-video');
  if (!vid) { showToast(tr({en:'Video not found',de:'Kein Video gefunden'}), 'error'); return; }

  if (!document.pictureInPictureEnabled) {
    showToast(tr({en:'Your browser does not support Picture-in-Picture',de:'Dein Browser unterstützt kein Picture-in-Picture'}), 'error');
    return;
  }

  try {
    if (document.pictureInPictureElement) {
      await document.exitPictureInPicture();
      const btn = document.getElementById('pip-btn');
      if (btn) { btn.style.background = ''; btn.innerHTML = '<i class="fas fa-compress-alt"></i> Picture-in-Picture'; }
      showToast('Picture-in-Picture beendet', 'info');
    } else {
      await vid.requestPictureInPicture();
      const btn = document.getElementById('pip-btn');
      if (btn) {
        btn.style.background = 'rgba(6,182,212,0.15)';
        btn.innerHTML = '<i class="fas fa-compress-alt"></i> PiP aktiv <i class="fas fa-check-circle" style="color:#22c55e"></i>';
      }
      showToast('Picture-in-Picture aktiv — scrolle frei durch den Feed!', 'success');
      vid.addEventListener('leavepictureinpicture', () => {
        const b = document.getElementById('pip-btn');
        if (b) { b.style.background = ''; b.innerHTML = '<i class="fas fa-compress-alt"></i> Picture-in-Picture'; }
      }, { once: true });
    }
  } catch(e) {
    showToast('PiP nicht möglich: ' + e.message, 'error');
  }
}

