// renderShopPage → siehe public/js/shop-pro.js (Item-Shop v2)



function _shopFillGrid(cat) {
  const grid = document.getElementById('shop-frames-grid');
  if (!grid) return;
  grid.innerHTML = '';

  const { owned, active, premiumFreeIds } = window._shop;
  const frames = cat === 'Alle' ? SHOP_FRAMES : SHOP_FRAMES.filter(f => f.category === cat);
  const initial = currentUser ? (currentUser.displayName || currentUser.username || 'N')[0].toUpperCase() : 'N';

  frames.forEach(f => {
    const isOwned = owned.includes(f.id) || premiumFreeIds.includes(f.id);
    const isActive = active === f.id;
    const isFreeForPremium = premiumFreeIds.includes(f.id) && !owned.includes(f.id);

    const card = document.createElement('div');
    card.className = 'shop-frame-card' + (isActive ? ' shop-frame-active' : '');
    card.id = 'sfc-' + f.id;
    card.onclick = () => isOwned ? activateFrame(f.id) : buyFrame(f.id, f.name);

    // Animated ring — must use .style properties, NOT innerHTML/setAttribute
    const preview = document.createElement('div');
    preview.className = 'shop-frame-preview';

    // 3-layer fix: wrapper (static) -> ring (absolute, rotates) -> inner (absolute, static)
    const ringWrap = document.createElement('div');
    ringWrap.style.cssText = 'position:relative;width:80px;height:80px;border-radius:50%;flex-shrink:0';

    const ring = document.createElement('div');
    ring.style.cssText = 'position:absolute;inset:0;border-radius:50%;background:' + f.css + ';animation:' + (f.anim || 'rotate 3s linear infinite');

    const inner = document.createElement('div');
    inner.style.cssText = 'position:absolute;inset:4px;border-radius:50%;background:var(--bg-secondary);overflow:hidden;display:flex;align-items:center;justify-content:center;font-size:24px;font-weight:700;color:var(--text-primary)';
    // Rang-Vorschau: nur normales Profilbild (kein Video-Avatar)
    if (currentUser && currentUser.avatar) {
      const img = document.createElement('img');
      img.src = currentUser.avatar;
      img.style.cssText = 'width:100%;height:100%;object-fit:cover';
      inner.appendChild(img);
    } else {
      inner.textContent = initial;
    }
    ringWrap.appendChild(ring);
    ringWrap.appendChild(inner);
    preview.appendChild(ringWrap);

    const info = document.createElement('div');
    info.className = 'shop-frame-info';
    const tierEmojis = { bronze:'<i class="fas fa-medal" style="color:#d97706"></i>', silver:'<i class="fas fa-medal" style="color:#cbd5e1"></i>', gold:'<i class="fas fa-medal" style="color:#facc15"></i>', platinum:'<i class="fas fa-shield-halved" style="color:#67e8f9"></i>', diamond:'<i class="fas fa-gem" style="color:#60a5fa"></i>', master:'<i class="fas fa-wand-magic-sparkles" style="color:#c084fc"></i>', grandmaster:'<i class="fas fa-dragon" style="color:#f87171"></i>', challenger:'<i class="fas fa-khanda" style="color:#fbbf24"></i>', immortal:'<i class="fas fa-skull" style="color:#e5e7eb"></i>', radiant:'<i class="fas fa-bolt" style="color:#fde047"></i>' };
    const tierBadge = f.rankTier ? `<span style="font-size:10px;padding:2px 6px;background:rgba(255,255,255,0.1);border-radius:10px;margin-top:3px;display:inline-block">${tierEmojis[f.rankTier]||''} ${f.rankTier.charAt(0).toUpperCase()+f.rankTier.slice(1)}</span>` : '';
    info.innerHTML = '<div class="shop-frame-name">' + escHtml(f.name) + '</div><div class="shop-frame-cat">' + escHtml(f.category) + '</div>' + tierBadge;

    const action = document.createElement('div');
    action.className = 'shop-frame-action';
    if (isActive) {
      action.innerHTML = '<span class="shop-badge-active"><i class="fas fa-check"></i> Aktiv</span>';
    } else if (isOwned) {
      const btn = document.createElement('button');
      btn.className = 'shop-btn-activate';
      btn.innerHTML = '<i class="fas fa-circle"></i> Anlegen';
      btn.onclick = e => { e.stopPropagation(); activateFrame(f.id); };
      action.appendChild(btn);
    } else if (isFreeForPremium) {
      const btn = document.createElement('button');
      btn.className = 'shop-btn-free';
      btn.innerHTML = '<i class="fas fa-crown"></i> Kostenlos für Premium';
      btn.onclick = e => { e.stopPropagation(); activateFrame(f.id); };
      action.appendChild(btn);
    } else {
      const btn = document.createElement('button');
      btn.className = 'shop-btn-buy';
      btn.innerHTML = '<i class="fas fa-shopping-cart"></i> 0,99€';
      btn.onclick = e => { e.stopPropagation(); buyFrame(f.id, f.name); };
      action.appendChild(btn);
    }

    card.appendChild(preview);
    card.appendChild(info);
    card.appendChild(action);
    grid.appendChild(card);
  });
}

function _shopCatClick(idx) {
  var cat = (window._shopCats && window._shopCats[idx]) ? window._shopCats[idx] : 'Alle';
  document.querySelectorAll('.shop-cat-btn').forEach(function(b, i) {
    b.classList.toggle('active', i === idx);
  });
  _shopFillGrid(cat);
}
function _shopFilterCat(cat) {
  var catIdx = (window._shopCats||[]).indexOf(cat);
  document.querySelectorAll('.shop-cat-btn').forEach(function(b, i) {
    b.classList.toggle('active', i === catIdx);
  });
  _shopFillGrid(cat);
}
function filterShopCat(cat) { _shopFilterCat(cat); }

function _renderLockerGrid() {
  const grid = document.getElementById('locker-grid');
  if (!grid) return;
  grid.innerHTML = '';
  const { owned = [], active, premiumFreeIds = [] } = window._shop || {};
  const allOwned = SHOP_FRAMES.filter(function(f) {
    return owned.includes(f.id) || premiumFreeIds.includes(f.id);
  });
  const initial = currentUser ? (currentUser.displayName || currentUser.username || 'N')[0].toUpperCase() : 'N';

  // Empty state
  if (!allOwned.length) {
    grid.innerHTML = '<div style="grid-column:1/-1;text-align:center;padding:32px 16px;color:var(--text-muted)">' +
      '<i class="fas fa-archive" style="font-size:36px;margin-bottom:12px;display:block;opacity:0.4"></i>' +
      '<div style="font-size:14px;font-weight:600;margin-bottom:6px">' + t('spind_empty') + '</div>' +
      '<div style="font-size:13px;opacity:0.7">' + t('spind_empty_hint') + '</div>' +
      '</div>';
    return;
  }

  allOwned.forEach(function(f) {
    const isActive = active === f.id;

    const card = document.createElement('div');
    card.style.cssText = 'background:var(--bg-secondary);border:2px solid ' +
      (isActive ? '#22c55e' : 'var(--border-color)') +
      ';border-radius:16px;padding:16px 10px 12px;display:flex;flex-direction:column;align-items:center;gap:9px;cursor:pointer;transition:transform 0.15s,border-color 0.15s,box-shadow 0.15s;' +
      (isActive ? 'box-shadow:0 0 0 4px rgba(34,197,94,0.15)' : '');
    card.onmouseover = function() { if (!isActive) { this.style.borderColor = 'var(--purple-main)'; this.style.transform = 'translateY(-2px)'; } };
    card.onmouseout  = function() { if (!isActive) { this.style.borderColor = 'var(--border-color)'; this.style.transform = ''; } };
    card.onclick = function() {
      if (!isActive) activateFrame(f.id);
    };

    // 3-layer preview: wrapper -> ring (rotates) -> inner (static)
    const previewWrap = document.createElement('div');
    previewWrap.style.cssText = 'position:relative;width:60px;height:60px;flex-shrink:0';
    const ring = document.createElement('div');
    ring.style.cssText = 'position:absolute;inset:0;border-radius:50%;background:' + f.css + ';animation:' + (f.anim || 'rotate 3s linear infinite');
    const inner = document.createElement('div');
    inner.style.cssText = 'position:absolute;inset:3px;border-radius:50%;background:var(--bg-secondary);overflow:hidden;display:flex;align-items:center;justify-content:center;font-size:18px;font-weight:700;color:var(--text-primary)';
    // Spind-Vorschau: nur normales Profilbild (kein Video-Avatar)
    if (currentUser && currentUser.avatar) {
      const img = document.createElement('img');
      img.src = currentUser.avatar; img.style.cssText = 'width:100%;height:100%;object-fit:cover';
      inner.appendChild(img);
    } else {
      inner.textContent = initial;
    }
    previewWrap.appendChild(ring);
    previewWrap.appendChild(inner);

    // Checkmark overlay when active
    if (isActive) {
      const check = document.createElement('div');
      check.style.cssText = 'position:absolute;bottom:-2px;right:-2px;width:20px;height:20px;border-radius:50%;background:#22c55e;display:flex;align-items:center;justify-content:center;border:2px solid var(--bg-secondary)';
      check.innerHTML = '<i class="fas fa-check" style="font-size:9px;color:white"></i>';
      previewWrap.appendChild(check);
    }

    // Frame name
    const nameEl = document.createElement('div');
    nameEl.style.cssText = 'font-size:11px;font-weight:700;color:var(--text-primary);text-align:center;line-height:1.3;width:100%;overflow:hidden;white-space:nowrap;text-overflow:ellipsis';
    nameEl.textContent = f.name;

    // Status badge
    const badge = document.createElement('div');
    if (isActive) {
      badge.style.cssText = 'font-size:10px;font-weight:700;padding:3px 10px;border-radius:20px;color:#22c55e;background:rgba(34,197,94,0.12);white-space:nowrap;display:flex;align-items:center;gap:4px';
      badge.innerHTML = '<i class="fas fa-check-circle" style="font-size:9px"></i> ' + t('spind_active');
    } else {
      badge.style.cssText = 'font-size:10px;font-weight:600;padding:3px 10px;border-radius:20px;color:var(--purple-light);background:rgba(168,59,255,0.12);white-space:nowrap;cursor:pointer;transition:background 0.15s';
      badge.innerHTML = '<i class="fas fa-circle-dot" style="font-size:9px"></i> ' + t('spind_equip');
      badge.onmouseover = function() { this.style.background = 'rgba(168,59,255,0.25)'; };
      badge.onmouseout  = function() { this.style.background = 'rgba(168,59,255,0.12)'; };
    }

    card.appendChild(previewWrap);
    card.appendChild(nameEl);
    card.appendChild(badge);
    grid.appendChild(card);
  });
}
async function buyFrame(frameId, frameName) {
  if (!currentUser) { openAuthModal('login'); return; }
  openFramePaymentModal(frameId, frameName);
}

