    urlBar.innerHTML = '<div style="flex:1"></div><div style="font-size:13px;color:#444;font-weight:500;letter-spacing:0.01em">pay.google.com</div><div style="flex:1;display:flex;justify-content:flex-end"><div style="width:28px;height:28px;border-radius:50%;background:#f0f0f0;display:flex;align-items:center;justify-content:center;cursor:pointer;font-size:16px;color:#555">&times;</div></div>';
    urlBar.querySelector('div:last-child div').onclick = function(){ overlay.remove(); };

    // Google Pay logo row
    const logoRow = document.createElement('div');
    logoRow.style.cssText = 'display:flex;align-items:center;justify-content:space-between;padding:16px 20px 0';
    logoRow.innerHTML = '<div style="display:flex;align-items:center;gap:4px">'
      + '<svg width="22" height="22" viewBox="0 0 48 48"><path fill="#4285F4" d="M24 9.5c3.5 0 6.6 1.2 9 3.2l6.7-6.7C35.5 2.2 30.1 0 24 0 14.6 0 6.6 5.5 2.7 13.5l7.8 6.1C12.4 13.1 17.7 9.5 24 9.5z"/><path fill="#34A853" d="M46.5 24.5c0-1.6-.1-3.1-.4-4.5H24v8.5h12.7c-.6 3-2.3 5.5-4.8 7.2l7.5 5.8c4.4-4.1 7.1-10.1 7.1-17z"/><path fill="#FBBC05" d="M10.5 28.6A14.8 14.8 0 0 1 9.5 24c0-1.6.3-3.1.8-4.5L2.7 13.5A23.9 23.9 0 0 0 0 24c0 3.8.9 7.4 2.7 10.5l7.8-5.9z"/><path fill="#EA4335" d="M24 48c6.1 0 11.2-2 14.9-5.4l-7.5-5.8c-2 1.4-4.7 2.2-7.4 2.2-6.3 0-11.6-4.2-13.5-9.9l-7.8 6C6.6 42.5 14.6 48 24 48z"/></svg>'
      + '<span style="font-size:17px;font-weight:700;color:#222;letter-spacing:-0.02em">Pay</span></div>'
      + '<div style="width:38px;height:38px;border-radius:50%;background:linear-gradient(var(--accent),var(--accent));display:flex;align-items:center;justify-content:center;overflow:hidden">'
      + '<svg viewBox="0 0 32 32" width="22" height="22" fill="none"><path d="M9 23V9l14 14H15V23z" fill="white"/></svg></div>';

    // Test card
    const cardRow = document.createElement('div');
