    cardRow.innerHTML = '<div style="display:flex;align-items:center;gap:12px">'
      + '<div style="width:44px;height:30px;border-radius:6px;background:#1a1f71;display:flex;align-items:center;justify-content:center"><span style="color:white;font-size:9px;font-weight:900;letter-spacing:0.05em">VISA</span></div>'
      + '<div><div style="font-size:14px;font-weight:600;color:#222">Test Card: Visa</div><div style="font-size:12px;color:#777">Visa ••1111</div></div></div>'
      + '<svg width="20" height="20" viewBox="0 0 24 24" fill="none"><path d="M9 18l6-6-6-6" stroke="#999" stroke-width="2" stroke-linecap="round"/></svg>';

    // Sandbox notice
    const notice = document.createElement('div');
