    sheet.appendChild(urlBar); sheet.appendChild(logoRow); sheet.appendChild(cardRow);
    sheet.appendChild(notice); sheet.appendChild(div1); sheet.appendChild(total);
    sheet.appendChild(payBtn2); sheet.appendChild(encNote);
    overlay.appendChild(sheet);
