// ==================== XP & RANK SYSTEM ====================



function getUserRank(xp) {
  let rank = XP_RANKS[0];
  for (const r of XP_RANKS) { if (xp >= r.minXP) rank = r; }
  return rank;
}
function getNextRank(xp) {
  return XP_RANKS.find(r => r.minXP > xp) || null;
}

