async function activateAufgabenFrame(frameId) {
  if (!currentUser) return openAuthModal('login');
  try {
    await apiPost('/api/shop/frames/' + frameId + '/buy', {}).catch(()=>{});
    await apiPost('/api/shop/frames/' + frameId + '/activate', {});
    currentUser.activeFrame = frameId;
    showToast('Rahmen aktiviert!', 'success');
  } catch { showToast('Fehler beim Aktivieren', 'error'); }
}


// ── Mobile Search Overlay ──────────────────────────────────────────────────
function openMobileSearch() {
  const overlay = document.getElementById('mobile-search-overlay');
  if (!overlay) return;
  overlay.style.display = 'flex';
  setTimeout(() => {
    const inp = document.getElementById('mobile-search-input');
    if (inp) inp.focus();
  }, 80);
}

function closeMobileSearch() {
  const overlay = document.getElementById('mobile-search-overlay');
  if (overlay) overlay.style.display = 'none';
}

document.addEventListener('DOMContentLoaded', function() {
  const mobileInput = document.getElementById('mobile-search-input');
  if (mobileInput) {
    mobileInput.addEventListener('keydown', function(e) {
      if (e.key === 'Enter') {
        const q = this.value.trim();
        if (!q) return;
        closeMobileSearch();
        const mainInput = document.getElementById('search-input');
        if (mainInput) {
          mainInput.value = q;
          const searchBtn = document.getElementById('search-btn');
          if (searchBtn) searchBtn.click();
        } else {
          navigateTo('search', q);
        }
      }
    });
  }
  document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape') closeMobileSearch();
  });
});
// ─── Teil: client/app/565-gemeinsame-helfer.js ───
// ==================== GEMEINSAME HELFER (v1.80) ====================
// Aus admin-pro.js hierher verschoben: admin-pro.js wird seit v1.80 nur noch für Admins geladen,
// diese Helfer brauchen aber auch normale Seiten (Seitenbanner für alle, Diagramme in pages-pro.js).
function axEsc(s) { return typeof escHtml === 'function' ? escHtml(s == null ? '' : String(s)) : String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c])); }
function axNum(n) { n = Number(n) || 0; if (Math.abs(n) >= 1e6) return (n / 1e6).toFixed(1).replace('.0', '') + ' Mio.'; if (Math.abs(n) >= 1e4) return (n / 1e3).toFixed(1).replace('.0', '') + 'k'; return n.toLocaleString('de-DE'); }
function axSpark(data, color) {
  const d = (data || []).length ? data : [0];
  const w = 200, h = 38, max = Math.max(1, ...d), min = Math.min(0, ...d);
  const step = d.length > 1 ? w / (d.length - 1) : w;
  const pts = d.map((v, i) => [i * step, h - 3 - ((v - min) / (max - min || 1)) * (h - 8)]);
  const line = pts.map((p, i) => (i ? 'L' : 'M') + p[0].toFixed(1) + ' ' + p[1].toFixed(1)).join(' ');
  const id = 'sg' + Math.random().toString(36).slice(2, 8);
  return `<svg class="ax-spark" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" aria-hidden="true">
    <defs><linearGradient id="${id}" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="${color}" stop-opacity=".35"/><stop offset="1" stop-color="${color}" stop-opacity="0"/></linearGradient></defs>
    <path d="${line} L${w} ${h} L0 ${h} Z" fill="url(#${id})"/>
    <path d="${line}" fill="none" stroke="${color}" stroke-width="2" vector-effect="non-scaling-stroke" stroke-linejoin="round" stroke-linecap="round"/>
  </svg>`;
}
function axLineChart(host, { labels, series, height = 240, fmt = axNum, bars = false }) {
  if (!host) return;
  const hidden = host._axHidden || (host._axHidden = new Set());
  const draw = () => {
    const W = Math.max(320, host.clientWidth || 600), H = height;
    const pad = { l: 40, r: 12, t: 12, b: 26 };
    const vis = series.filter(s => !hidden.has(s.name));
    const all = vis.flatMap(s => s.data);
    const max = Math.max(1, ...all);
    const niceMax = (() => { const p = Math.pow(10, Math.floor(Math.log10(max))); return Math.ceil(max / p) * p; })();
    const n = labels.length;
    const x = i => pad.l + (n > 1 ? i * (W - pad.l - pad.r) / (n - 1) : 0);
    const y = v => pad.t + (H - pad.t - pad.b) * (1 - v / niceMax);
    const ticks = 4;
    let g = `<g class="grid">`;
    for (let i = 0; i <= ticks; i++) { const yy = pad.t + (H - pad.t - pad.b) * i / ticks; g += `<line x1="${pad.l}" x2="${W - pad.r}" y1="${yy}" y2="${yy}"/>`; }
    g += `</g><g class="axis">`;
    for (let i = 0; i <= ticks; i++) { const v = niceMax * (1 - i / ticks); const yy = pad.t + (H - pad.t - pad.b) * i / ticks; g += `<text x="${pad.l - 8}" y="${yy + 3.5}" text-anchor="end">${fmt(Math.round(v * 100) / 100)}</text>`; }
    const every = Math.max(1, Math.ceil(n / Math.floor((W - pad.l) / 64)));
    labels.forEach((l, i) => { if (i % every === 0 || (i === n - 1 && (n - 1) % every >= every / 2)) g += `<text x="${x(i)}" y="${H - 6}" text-anchor="middle">${axEsc(String(l).slice(5).split('-').reverse().join('.'))}</text>`; });
    g += `</g>`;
    let paths = '';
    vis.forEach((s, si) => {
      const id = 'lc' + si + Math.random().toString(36).slice(2, 6);
      if (bars) {
        const bw = Math.max(2, (W - pad.l - pad.r) / n * 0.6 / vis.length);
        s.data.forEach((v, i) => { const bx = x(i) - (bw * vis.length) / 2 + si * bw; paths += `<rect x="${bx}" y="${y(v)}" width="${bw}" height="${Math.max(0, H - pad.b - y(v))}" rx="2" fill="${s.color}" opacity=".85"/>`; });
        return;
      }
      const pts = s.data.map((v, i) => [x(i), y(v)]);
      // Weiche Kurve (Catmull-Rom → Bézier)
      let d = `M${pts[0][0]} ${pts[0][1]}`;
      for (let i = 0; i < pts.length - 1; i++) {
        const p0 = pts[i - 1] || pts[i], p1 = pts[i], p2 = pts[i + 1], p3 = pts[i + 2] || p2;
        const c1 = [p1[0] + (p2[0] - p0[0]) / 6, p1[1] + (p2[1] - p0[1]) / 6];
        const c2 = [p2[0] - (p3[0] - p1[0]) / 6, p2[1] - (p3[1] - p1[1]) / 6];
        d += ` C${c1[0].toFixed(1)} ${Math.min(y(0), c1[1]).toFixed(1)} ${c2[0].toFixed(1)} ${Math.min(y(0), c2[1]).toFixed(1)} ${p2[0].toFixed(1)} ${p2[1].toFixed(1)}`;
      }
      paths += `<defs><linearGradient id="${id}" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="${s.color}" stop-opacity="${si === 0 ? .28 : .12}"/><stop offset="1" stop-color="${s.color}" stop-opacity="0"/></linearGradient></defs>`;
      paths += `<path d="${d} L${x(n - 1)} ${y(0)} L${x(0)} ${y(0)} Z" fill="url(#${id})"/>`;
      paths += `<path d="${d}" fill="none" stroke="${s.color}" stroke-width="2.2" stroke-linejoin="round" stroke-linecap="round"/>`;
    });
    host.innerHTML = `<svg class="ax-chart" style="height:${H}px" viewBox="0 0 ${W} ${H}" preserveAspectRatio="none">${g}${paths}
      <line class="ax-hover-line" x1="0" x2="0" y1="${pad.t}" y2="${H - pad.b}" stroke="rgba(168,59,255,.55)" stroke-dasharray="3 3" style="display:none"/>
      <g class="ax-hover-dots"></g>
      <rect x="${pad.l}" y="0" width="${W - pad.l - pad.r}" height="${H}" fill="transparent" class="ax-hover-zone"/></svg>`;
    const svg = host.querySelector('svg'), zone = svg.querySelector('.ax-hover-zone'), vline = svg.querySelector('.ax-hover-line'), dots = svg.querySelector('.ax-hover-dots');
    let tip = document.getElementById('ax-tip');
    if (!tip) { tip = document.createElement('div'); tip.id = 'ax-tip'; tip.className = 'ax-tip'; document.body.appendChild(tip); }
    zone.addEventListener('mousemove', e => {
      const r = svg.getBoundingClientRect();
      const px = (e.clientX - r.left) * (W / r.width);
      const i = Math.max(0, Math.min(n - 1, Math.round((px - pad.l) / ((W - pad.l - pad.r) / Math.max(1, n - 1)))));
      vline.setAttribute('x1', x(i)); vline.setAttribute('x2', x(i)); vline.style.display = '';
      dots.innerHTML = bars ? '' : vis.map(s => `<circle cx="${x(i)}" cy="${y(s.data[i])}" r="4" fill="${s.color}" stroke="var(--bg-card)" stroke-width="2"/>`).join('');
      tip.innerHTML = `<b>${axEsc(new Date(labels[i]).toLocaleDateString('de-DE', { weekday: 'short', day: '2-digit', month: 'short' }))}</b>` + vis.map(s => `<div><span><i style="background:${s.color}"></i>${axEsc(s.name)}</span><strong>${fmt(s.data[i])}</strong></div>`).join('');
      tip.style.display = 'block';
      const tx = Math.min(window.innerWidth - tip.offsetWidth - 12, e.clientX + 14);
      tip.style.left = tx + 'px'; tip.style.top = (e.clientY - tip.offsetHeight - 10) + 'px';
    });
    zone.addEventListener('mouseleave', () => { vline.style.display = 'none'; dots.innerHTML = ''; tip.style.display = 'none'; });
  };
  draw();
  host._axRedraw = draw;
  const legend = host.parentElement?.querySelector('[data-ax-legend]');
  if (legend) {
    legend.innerHTML = series.map(s => `<span data-name="${axEsc(s.name)}" class="${hidden.has(s.name) ? 'is-off' : ''}"><i style="background:${s.color}"></i>${axEsc(s.name)}</span>`).join('');
    legend.querySelectorAll('span').forEach(sp => sp.onclick = () => {
      const nm = sp.dataset.name;
      if (hidden.has(nm)) hidden.delete(nm); else if (hidden.size < series.length - 1) hidden.add(nm);
      sp.classList.toggle('is-off', hidden.has(nm)); draw();
    });
  }
}
function nxShowSiteBanner(b) {
  document.getElementById('nx-site-banner')?.remove();
  if (!b || !b.enabled) return;
  try { if (localStorage.getItem('nx_banner_dismissed') === b.id) return; } catch {}
  const icons = { info: 'fa-circle-info', success: 'fa-circle-check', warning: 'fa-triangle-exclamation', critical: 'fa-circle-exclamation' };
  const el = document.createElement('div');
  el.id = 'nx-site-banner'; el.className = b.level || 'info';
  el.innerHTML = `<i class="fas ${icons[b.level] || icons.info}"></i><span>${axEsc(b.text)}</span><button aria-label="Schließen" title="Schließen"><i class="fas fa-xmark"></i></button>`;
  el.querySelector('button').onclick = () => { try { localStorage.setItem('nx_banner_dismissed', b.id); } catch {} el.remove(); };
  document.body.appendChild(el);
}
(function nxInitSiteBanner() {
  const start = () => {
    fetch('/api/site-banner').then(r => r.json()).then(nxShowSiteBanner).catch(() => {});
    let tries = 0;
    const bind = setInterval(() => {
      if (typeof socket !== 'undefined' && socket) { clearInterval(bind); socket.on('site_banner', nxShowSiteBanner); }
      else if (++tries > 40) clearInterval(bind);
    }, 500);
  };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start); else start();
})();
