// ==================== 2FA-CODE-ABFRAGE ALS FENSTER (v1.80) ====================
// Ersetzt prompt() bei der Zwei-Faktor-Abfrage (Google-/Apple-Login, Auszahlungen). prompt() ist
// in installierten PWAs und manchen In-App-Browsern blockiert — die Anmeldung war dort unmöglich.
// nxAskCode(text) → Promise<string|null> (null = abgebrochen)
function nxAskCode(message) {
  return new Promise((resolve) => {
    document.getElementById('nx-code-ask')?.remove();
    const wrap = document.createElement('div');
    wrap.id = 'nx-code-ask';
    wrap.setAttribute('role', 'dialog');
    wrap.setAttribute('aria-modal', 'true');
    wrap.style.cssText = 'position:fixed;inset:0;z-index:100000;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,.65);padding:16px';
    wrap.innerHTML = `<form style="background:var(--bg-card,#1b1b22);color:var(--text-primary,#fff);border:1px solid var(--border,#333);border-radius:16px;padding:22px;width:100%;max-width:360px;box-shadow:0 20px 60px rgba(0,0,0,.5)">
      <h3 style="margin:0 0 8px;font-size:17px"><i class="fas fa-shield-halved" aria-hidden="true"></i> ${escHtml(tr({ en: 'Two-factor authentication', de: 'Zwei-Faktor-Anmeldung' }))}</h3>
      <p style="margin:0 0 14px;font-size:13.5px;color:var(--text-secondary,#bbb)">${escHtml(message || tr({ en: 'Enter the 6-digit code from your authenticator app.', de: 'Gib den 6-stelligen Code aus deiner Authenticator-App ein.' }))}</p>
      <input name="code" inputmode="numeric" autocomplete="one-time-code" maxlength="8" aria-label="${escHtml(tr({ en: 'Code', de: 'Code' }))}" style="width:100%;box-sizing:border-box;font-size:22px;letter-spacing:6px;text-align:center;padding:10px;border-radius:10px;border:1px solid var(--border,#444);background:var(--bg-secondary,#111);color:inherit">
      <div style="display:flex;gap:8px;margin-top:14px">
        <button type="button" data-x style="flex:1;padding:10px;border-radius:10px;border:1px solid var(--border,#444);background:transparent;color:inherit;cursor:pointer">${escHtml(tr({ en: 'Cancel', de: 'Abbrechen' }))}</button>
        <button type="submit" style="flex:1;padding:10px;border-radius:10px;border:0;background:var(--purple-main,#7c3aed);color:#fff;font-weight:600;cursor:pointer">${escHtml(tr({ en: 'Confirm', de: 'Bestätigen' }))}</button>
      </div></form>`;
    const form = wrap.querySelector('form'), input = wrap.querySelector('input');
    const done = (v) => { document.removeEventListener('keydown', onKey, true); wrap.remove(); resolve(v); };
    const onKey = (e) => { if (e.key === 'Escape') { e.preventDefault(); done(null); } };
    form.addEventListener('submit', (e) => { e.preventDefault(); const v = input.value.replace(/\s/g, ''); if (v) done(v); else input.focus(); });
    wrap.querySelector('[data-x]').addEventListener('click', () => done(null));
    wrap.addEventListener('pointerdown', (e) => { if (e.target === wrap) done(null); });
    input.addEventListener('input', () => { input.value = input.value.replace(/\D/g, '').slice(0, 8); if (input.value.length === 6) form.requestSubmit ? form.requestSubmit() : form.dispatchEvent(new Event('submit', { cancelable: true })); });
    document.addEventListener('keydown', onKey, true);
    document.body.appendChild(wrap);
    setTimeout(() => input.focus(), 30);
  });
}

// Freitext-Abfrage im selben Stil (statt prompt()). → Promise<string|null>
function nxAskText(message) {
  return new Promise((resolve) => {
    document.getElementById('nx-text-ask')?.remove();
    const wrap = document.createElement('div');
    wrap.id = 'nx-text-ask'; wrap.setAttribute('role', 'dialog'); wrap.setAttribute('aria-modal', 'true');
    wrap.style.cssText = 'position:fixed;inset:0;z-index:100000;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,.65);padding:16px';
    wrap.innerHTML = `<form style="background:var(--bg-card,#1b1b22);color:var(--text-primary,#fff);border:1px solid var(--border,#333);border-radius:16px;padding:22px;width:100%;max-width:420px">
      <p style="margin:0 0 12px;font-size:14px">${escHtml(message || '')}</p>
      <input name="t" maxlength="200" aria-label="${escHtml(message || '')}" style="width:100%;box-sizing:border-box;padding:10px;border-radius:10px;border:1px solid var(--border,#444);background:var(--bg-secondary,#111);color:inherit">
      <div style="display:flex;gap:8px;margin-top:14px"><button type="button" data-x style="flex:1;padding:10px;border-radius:10px;border:1px solid var(--border,#444);background:transparent;color:inherit">${escHtml(tr({ en: 'Cancel', de: 'Abbrechen' }))}</button>
      <button type="submit" style="flex:1;padding:10px;border-radius:10px;border:0;background:var(--purple-main,#7c3aed);color:#fff;font-weight:600">OK</button></div></form>`;
    const done = (v) => { wrap.remove(); resolve(v); };
    wrap.querySelector('form').addEventListener('submit', (e) => { e.preventDefault(); done(wrap.querySelector('input').value.trim()); });
    wrap.querySelector('[data-x]').addEventListener('click', () => done(null));
    document.body.appendChild(wrap);
    setTimeout(() => wrap.querySelector('input').focus(), 30);
  });
}
